    /**
     * Repo-shipped std scripts root. Honours WYRDSEKAI_SCRIPTS_DIR / wyrdsekai.scripts,
     * then walks cwd, ../, ../../ to locate scripts/std/. Falls back to "scripts" so
     * production .deb installs (with WYRDSEKAI_SCRIPTS_DIR set by systemd) still work.
     * Mirrors ClassifierForge.resolveScriptDir() — gradle test cwd is the subproject,
     * not the repo root, so a literal Path.of("scripts") fails in e2e-test/.
     */
    private static final Path STD_SCRIPTS_ROOT = resolveStdScriptsRoot();

    /** Repo-shipped std scripts root — shared with session-side carried-item execution
     *  (WyrdShellCommand / WyrdWebSocket wire their ItemScriptExecutor resolver from this,
     *  else inherit() is a no-op and template items have no invoke() — second-node 2026-07-09). */
    public static Path stdScriptsRoot() {
        return STD_SCRIPTS_ROOT;
    }

    private static Path resolveStdScriptsRoot() {
        // Probe a canonical script file we know must exist, not just std/ dir —
        // catches cases where std/ exists but is the wrong scripts root.
        var probe = Path.of("std", "zone", "narrative.js");
        var cwd = Path.of("").toAbsolutePath();

        var envDir = WyrdConfig.get().scriptsDir();
        if (envDir != null && !envDir.isBlank()) {
            var p = Path.of(envDir);
            if (Files.isRegularFile(p.resolve(probe))) {
                var abs = p.toAbsolutePath().normalize();
                log.info("STD_SCRIPTS_ROOT resolved via WyrdConfig.scriptsDir: {} (cwd={})", abs, cwd);
                return abs;
            }
        }
        var sysDir = System.getProperty("wyrdsekai.scripts");
        if (sysDir != null && !sysDir.isBlank()) {
            var p = Path.of(sysDir);
            if (Files.isRegularFile(p.resolve(probe))) {
                var abs = p.toAbsolutePath().normalize();
                log.info("STD_SCRIPTS_ROOT resolved via -Dwyrdsekai.scripts: {} (cwd={})", abs, cwd);
                return abs;
            }
        }
        // installRoot() self-locates from the running jar when WYRDSEKAI_HOME is
        // unset, so this resolves <install>/scripts even for a node launched
        // straight from the jpackage Wyrdsekai.exe (Start-menu shortcut, no env,
        // arbitrary cwd) — matching the room-scripts search in Main.java.
        var installRoot = WyrdConfig.get().installRoot();
        var candidateList = new ArrayList<Path>();
        if (installRoot != null && !installRoot.isBlank()) {
            candidateList.add(Path.of(installRoot, "scripts"));
        }
        candidateList.add(Path.of("scripts"));
        candidateList.add(Path.of("..", "scripts"));
        candidateList.add(Path.of("..", "..", "scripts"));
        candidateList.add(Path.of("/opt/wyrdsekai/scripts"));
        candidateList.add(Path.of(System.getProperty("user.home"), ".wyrdsekai", "scripts"));
        var candidates = candidateList.toArray(new Path[0]);
        for (var c : candidates) {
            if (Files.isRegularFile(c.resolve(probe))) {
                var abs = c.toAbsolutePath().normalize();
                log.info("STD_SCRIPTS_ROOT resolved via candidate {}: {} (cwd={})", c, abs, cwd);
                return abs;
            }
        }
        // Last-resort fallback — log loudly so failures downstream are diagnosable.
        var fallback = Path.of("scripts").toAbsolutePath().normalize();
        log.error("STD_SCRIPTS_ROOT FALLBACK: no candidate contained std/zone/narrative.js. cwd={}, fallback={}. "
            + "Set WYRDSEKAI_SCRIPTS_DIR or -Dwyrdsekai.scripts to fix.", cwd, fallback);
        return fallback;
    }

