    private static CfCCell initCfcCell() {
        var cell = new CfCCell();
        // Try to load pre-trained base soul weights (from CfC training pipeline)
        var basePath = SystemPaths.soulsDir().resolve("base_cfc.json");   // #data-dir (2026-07-19)
        if (Files.exists(basePath)) {
            try {
                var loaded = CfCCell.loadJson(basePath);
                cell.loadWeights(loaded.flattenWeights());
                log.info("Loaded pre-trained CfC base soul from {}", basePath);
            } catch (Exception e) {
                log.warn("Failed to load base CfC weights, using Xavier init: {}", e.getMessage());
                cell.initializeXavier(new Random());
            }
        } else {
            cell.initializeXavier(new Random());
        }
        return cell;
    }
