    @Override
    public Receive<Command> createReceive() {
        return newReceiveBuilder()
            .onMessage(RoomEventReceived.class, this::onRoomEvent)
            .onMessage(RoomResponseReceived.class, this::onRoomResponse)
            .onMessage(InferenceResponseReceived.class, this::onInferenceResponse)
            .onMessage(ProcessEvents.class, this::onProcessEvents)
            .onMessage(DeferredTriggerSweep.class, this::onDeferredTriggerSweep)
            .onMessage(GreetPlayer.class, this::onGreetPlayer)
            .onMessage(BondholderAnnounced.class, this::onBondholderAnnounced)
            .onMessage(AutonomyCheck.class, this::onAutonomyCheck)
            .onMessage(PresenceCheck.class, this::onPresenceCheck)
            .onMessage(FollowAttempt.class, this::onFollowAttempt)
            .onMessage(CrossZoneInvite.class, this::onCrossZoneInvite)
            .onMessage(ConsolidationTick.class, this::onConsolidationTick)
            .onMessage(RepairModeCheck.class, this::onRepairModeCheck)
            .onMessage(RefreshRoomState.class, this::onRefreshRoomState)
            .onMessage(RoomCreationResult.class, this::onRoomCreationResult)
            .onMessage(RoomToolDefsUpdated.class, this::onRoomToolDefsUpdated)
            .onMessage(RecipeResourceDenied.class, this::onRecipeResourceDenied)
            .onMessage(PreflightRejectReceived.class, this::onPreflightRejectReceived)
            .onMessage(VitalityTick.class, this::onVitalityTick)
            .onMessage(ScriptedToolResult.class, this::onScriptedToolResult)
            .onMessage(ToolResultReady.class, this::onToolResultReady)
            .onMessage(SetLocale.class, this::onSetLocale)
            .onMessage(SetAccessibility.class, this::onSetAccessibility)
            .onMessage(SleepCycleComplete.class, this::onSleepCycleComplete)
            .onMessage(ForgeResultReceived.class, this::onForgeResult)
            .onMessage(SleepInferenceComplete.class, this::onSleepInferenceComplete)
            .onMessage(DispatchTaskCompleted.class, this::onDispatchTaskCompleted)
            .onMessage(ToolInferenceResponseReceived.class, this::onToolInferenceResponse)
            .onMessage(SkillProposalReceived.class, this::onSkillProposalReceived)
            .onMessage(VisionAnalysisReceived.class, this::onVisionAnalysisReceived)
            .onMessage(TranslationCompleted.class, this::onTranslationCompleted)
            .onMessage(DetectLanguageCompleted.class, this::onDetectLanguageCompleted)
            .onMessage(AgentMessageTranslated.class, this::onAgentMessageTranslated)
            .onMessage(SubagentResultReceived.class, this::onSubagentResult)
            .onMessage(FamiliarReportReceived.class, this::onFamiliarReportReceived)
            .onMessage(BunshinToolRequest.class, this::onBunshinToolRequest)
            .onMessage(BunshinReportReceived.class, this::onBunshinReportReceived)
            .onMessage(DeepSleepTrainingComplete.class, this::onDeepSleepTrainingComplete)
            .onMessage(RecallReplyReceived.class, this::onRecallReplyReceived)
            .onMessage(VoicePassReady.class, this::onVoicePassReady)
            .onMessage(OutcomeVoiceReady.class, this::onOutcomeVoiceReady)
            .onMessage(WantProposalReady.class, this::onWantProposalReady)
            .onMessage(ImaginedConsequenceReady.class, this::onImaginedConsequenceReady)
            .onMessage(DeepSleepWatchdog.class, this::onDeepSleepWatchdog)
            .onMessage(ScheduledPredictionFireMessage.class, msg -> {
                executeProactiveAction(msg.initiative());
                // §M4-C — begin tracking post-fire window for outcome telemetry.
                if (msg.source() != null) {
                    var agentDid = profile.did() != null ? profile.did() : profile.entityId();
                    PREDICTION_OUTCOME_TRACKER.track(
                        msg.source().id(), agentDid,
                        msg.source().category(), msg.source().text(),
                        Instant.now());
                }
                return this;
            })
            .onMessage(ShapeValidationCompleted.class, this::onShapeValidationCompleted)
            .onMessage(ChargeScored.class, this::onChargeScored)
            .onMessage(SetLuceneStore.class, msg -> {
                this.luceneStore = msg.store();
                this.admissionController = new AdmissionController(msg.store());
                return this;
            })
            .onMessage(ReactDispatch.class, this::onReactDispatch)
            .onMessage(DispatchHandoff.class, this::onDispatchHandoff)
            .onMessage(ForceEnergy.class, msg -> {
                vitality = vitality.withEnergy(msg.energy());
                log.info("ForceEnergy: '{}' energy set to {}", profile.name(), msg.energy());
                return this;
            })
            .onMessage(ForceDrives.class, msg -> {
                drives = msg.driveState();
                log.info("ForceDrives: '{}' drives set to {}", profile.name(), drives.dashboard());
                return this;
            })
            .onMessage(ForceCompanionMode.class, msg -> {
                setCompanionMode(msg.mode(), "test_harness_force");
                return this;
            })
            .onMessage(ForceVitality.class, msg -> {
                vitality = msg.vitality();
                return this;
            })
            .onMessage(ForceForgeConsolidate.class, msg -> {
                skillCosts.forgeConsolidate();
                // Lazy-warm the classifier arm if ForceForgeConsolidate
                // fires before any tell has arrived — operator-triggered
                // consolidation (tests, `wyrd` CLI) should work from cold.
                // In normal production this is already non-null from the
                // first tell.
                classifier();
                // Also consolidate the classifier arm — lets E2E tests drive
                // the sleep-cycle classifier learning path without needing
                // the full Forge manifest flow.
                if (classifierArm != null) {
                    try {
                        var results = ClassifierForge
                            .consolidate(classifierArm);
                        for (var r : results) {
                            if (r.eventsConsumed() > 0) {
                                log.info("ForceForgeConsolidate classifier [{}] events={} added={} corpus={} retrain={}",
                                    r.head(), r.eventsConsumed(), r.pseudoLabelsAdded(),
                                    r.corpusSize(),
                                    r.retrainAttempted() ? (r.retrainSucceeded() ? "ok" : "failed") : "gated-off");
                            }
                        }
                    } catch (Exception e) {
                        log.warn("ForceForgeConsolidate classifier failed: {}", e.getMessage());
                    }
                }
                log.info("ForceForgeConsolidate: '{}' skill costs + classifier consolidated",
                    profile.name());
                return this;
            })
            .onMessage(TestDispatchBunshin.class, msg -> {
                log.info("TestDispatchBunshin received: companion={} task={} did={} roomId={}",
                    profile.name(), truncate(msg.task(), 60), profile.did(), roomId);
                handleDispatchBunshin(new ActionParser.AgentAction.DispatchBunshin(
                    msg.task(), msg.maxTokens(), msg.maxSteps(),
                    msg.wallClockSeconds(), "test-harness"));
                return this;
            })
            .onMessage(TestRequestRecipe.class, msg -> {
                log.info("TestRequestRecipe received: companion={} recipe={} did={}",
                    profile.name(), msg.recipeName(), profile.did());
                // Test harness bypasses RecipeSchedulerRegistry — fires the
                // same RecipeService.run path A3 proved end-to-end. Keeps
                // RecipeAgentForgeE2ETest deterministic regardless of
                // scheduler enablement.
                handleRequestRecipeDirect(new ActionParser.AgentAction.RequestRecipe(
                    msg.recipeName(),
                    msg.params() != null ? msg.params() : Map.of(),
                    msg.reason() != null ? msg.reason() : "test-harness"));
                return this;
            })
            .onMessage(ForceGenerativeImpetus.class, msg -> {
                // EMIT probe: force a surfaced generative
                // drive, bypass the interiority cadence gate, run one OODA pass NOW.
                vitality = vitality.withGenerativity(msg.level());
                cachedGenerativeGaps = Math.max(0, msg.gaps());
                cachedGenerativeMeans = true;
                cachedTopGapKey = msg.gapKey();
                cachedTopGapDesc = msg.gapKey();
                testForceWorkbench = true;   // so an emitted shape_recipe can land a file
                lastInteriorityTickAt = Instant.EPOCH;       // defeat cadence gate
                lastInteriorityNextDelay = Duration.ZERO;
                log.info("ForceGenerativeImpetus: '{}' generativity={} gaps={} gapKey={} → running OODA",
                    profile.name(), msg.level(), msg.gaps(), msg.gapKey());
                runInteriorityTick();
                return this;
            })
            .onMessage(SetRolloutCaptureSink.class, msg -> {
                // install/clear the offline rollout-capture sink.
                rolloutCaptureSink = msg.sink();
                log.info("SetRolloutCaptureSink: '{}' capture {}", profile.name(),
                    rolloutCaptureSink == null ? "cleared" : "armed");
                return this;
            })
            .onMessage(CaptureOwnTimePrompt.class, msg -> {
                // seed the drive state, then assemble + capture the
                // own-time prompt directly. No OODA, no inference: triggerAutonomousInference
                // builds messages+tools, hands them to the capture-only sink, and returns
                // before the ACT call. One faithful row per fixture, any band.
                vitality = vitality.withGenerativity(msg.generativity()).withEnergy(msg.energy());
                cachedGenerativeGaps = Math.max(0, msg.gaps());
                cachedGenerativeMeans = true;
                cachedTopGapKey = msg.gapKey();
                cachedTopGapDesc = msg.gapKey();
                // Seed locale so buildLocaleContext() threads ES/JA through the REAL
                // PromptAssembler (the captured prompt carries the language instruction —
                // zero-skew preserved; the act-vs-narrate decision is what we test across langs).
                if (msg.lang() != null && !msg.lang().isBlank()) locale = msg.lang();
                triggerAutonomousInference(msg.autonomyPrompt());
                return this;
            })
            .onMessage(ForceSleep.class, msg -> {
                log.info("ForceSleep[{}]: '{}' entering sleep cycle via test harness",
                    msg.tier(), profile.name());
                if (isSleeping) {
                    log.info("ForceSleep: '{}' already sleeping, ignored", profile.name());
                    return this;
                }
                // Minimum spacing between DELIBERATE cycles. The isSleeping flag alone
                // is not enough: a cycle completes in a few seconds, so back-to-back
                // forces each see it clear while the manifest write-back is still in
                // flight — ForgeActor accepts the forged manifest asynchronously, so a
                // cycle started immediately afterwards can read a half-updated one.
                // Live 2026-08-18: three forces 25-30s apart, the third read a null
                // previous-forge time and applied a full day of memory decay in one go
                // (60 of 66 memories pruned; restored from snapshot). The decay path
                // now fails safe on that input, and this stops the race producing it
                // at all. Her own sleeps are hours apart and never come near this.
                if (lastSleepCompletedAt != null
                        && Duration.between(lastSleepCompletedAt, Instant.now())
                            .compareTo(FORCED_SLEEP_MIN_INTERVAL) < 0) {
                    log.warn("ForceSleep declined for '{}' — last cycle completed {}s ago, "
                            + "minimum spacing is {}s. Consolidation is not free: each cycle "
                            + "decays memory and merges a fresh fingerprint at 30%.",
                        profile.name(),
                        Duration.between(lastSleepCompletedAt, Instant.now()).toSeconds(),
                        FORCED_SLEEP_MIN_INTERVAL.toSeconds());
                    return this;
                }
                initiateSleep(msg.tier());
                return this;
            })
            .onMessage(SeedSignificance.class, msg -> {
                var n = msg.entries() == null ? 0 : msg.entries().size();
                if (n == 0) return this;
                for (var e : msg.entries()) {
                    if (e != null && !e.isBlank()) {
                        significanceBuffer.remember(e, 0.7f);
                    }
                }
                log.info("SeedSignificance: seeded {} entries for '{}'",
                    n, profile.name());
                return this;
            })
            .onMessage(QueryTestState.class, msg -> {
                var dominant = accumulatedCharges.values().stream()
                    .max(Comparator.comparingDouble(EmotionalCharge::intensity))
                    .map(EmotionalCharge::primaryEmotion)
                    .orElse(null);
                var agentDidValue = profile.did() != null
                    ? profile.did() : profile.entityId();
                msg.replyTo().tell(new TestStateResponse(
                    drives, vitality, skillCosts.snapshot(), skillCosts.size(),
                    accumulatedCharges.size(), dominant,
                    companionMode, primaryBondholderDid(), agentDidValue));
                return this;
            })
            .onMessage(QueryWorkingMemory.class, msg -> {
                msg.replyTo().tell(new WorkingMemoryResponse(
                    List.copyOf(workingMemory)));
                return this;
            })
            .onMessage(BridgeConnect.class, msg -> { bridgeSinks.add(msg.sink()); return this; })
            .onMessage(BridgeDisconnect.class, msg -> { bridgeSinks.remove(msg.sink()); return this; })
            .onMessage(BridgeSay.class, msg -> { speak(msg.text()); return this; })
            .onMessage(ResetState.class, this::onResetState)
            .onMessage(VoicePolishTimeout.class, msg -> {
                // If the callback is still pending, the inference reply didn't
                // arrive — speak the original draft directly.
                var callback = pendingVoicePolishes.get(msg.requestId());
                if (callback != null) {
                    log.debug("Voice polish timed out for {} — speaking original draft",
                        msg.requestId());
                    callback.accept(msg.draft());
                }
                return this;
            })
            .onMessage(OneShotVoiceTimeout.class, msg -> {
                // felt + inner one-shot voice timed
                // out. Complete the pending future with empty so the chain
                // step skips this scene; a later sweep can pick it up.
                var callback = pendingOneShotVoice.get(msg.requestId());
                if (callback != null) {
                    log.debug("One-shot voice timed out for {} — empty fallback",
                        msg.requestId());
                    callback.accept(Optional.empty());
                }
                return this;
            })
            .onMessage(SetArchetype.class, this::onSetArchetype)
            .onMessage(BridgeEmote.class, msg -> {
                roomRef.tell(new RoomCommand.EmoteInRoom(
                    profile.entityId(), profile.name(), msg.text(), roomResponseAdapter));
                return this;
            })
            .onMessage(BridgeGo.class, msg -> {
                handleGoToRoom(new ActionParser.AgentAction.GoToRoom(msg.target(), "bridge command"));
                return this;
            })
            .onMessage(BridgeQueryState.class, msg -> {
                var tanks = new LinkedHashMap<String, Double>();
                tanks.put("energy", vitality.energy());
                tanks.put("confidence", vitality.confidence());
                tanks.put("focus", vitality.focus());
                tanks.put("contextBudget", vitality.contextBudget());
                tanks.put("momentum", vitality.momentum());
                tanks.put("rapport", vitality.rapport());
                tanks.put("errorPressure", vitality.errorPressure());
                tanks.put("alignment", vitality.alignment());

                // Build the same "How You Feel" text that autonomous companions get
                var sb = new StringBuilder();
                CapabilityContextBuilder.appendFeelings(sb, vitality);
                var howYouFeel = sb.toString();

                var roomName = currentSnapshot != null ? currentSnapshot.name() : roomId;
                msg.replyTo().tell(new BridgeStateResponse(
                    roomId, roomName, vitality.energy(),
                    state.name(), isSleeping, tanks, howYouFeel));
                return this;
            })
            .onMessage(ExternalTell.class, msg -> {
                // Deliver as if a player sent a tell — goes through normal reactive path
                log.info("External tell from '{}': {}", msg.senderName(),
                    truncate(msg.message(), 80));
                var agentEvent = new AgentEvent.AgentMessage(
                    msg.senderId(), msg.senderName(), profile.entityId(),
                    msg.message(), Instant.now());
                onAgentMessage(new AgentMessageReceived(agentEvent));
                return this;
            })
            .onMessage(BridgeAsk.class, msg -> {
                // Deliver the message and capture the next spoken response
                log.info("Bridge ask from '{}': {}", msg.senderName(),
                    truncate(msg.message(), 80));
                pendingAskReply = msg.replyTo();
                var agentEvent = new AgentEvent.AgentMessage(
                    msg.senderId(), msg.senderName(), profile.entityId(),
                    msg.message(), Instant.now());
                onAgentMessage(new AgentMessageReceived(agentEvent));
                return this;
            })
            .onMessage(RegisterRoomImprints.class, this::onRegisterRoomImprints)
            .onMessage(ZoneBroadcastReceived.class, this::onZoneBroadcast)
            .onMessage(SystemEventReceived.class, this::onSystemEvent)
            .onMessage(AdjacentActivityReceived.class, this::onAdjacentActivity)
            .onMessage(AgentMessageReceived.class, this::onAgentMessage)
            .onMessage(OraclePredictionsReceived.class, this::onOraclePredictions)
            .onMessage(AbortReceived.class, this::onAbortReceived)
            .onMessage(PlayerReturned.class, this::onPlayerReturned)
            .onMessage(RenameRequest.class, this::onRenameRequest)
            .onMessage(AdoptStoredSoulShape.class, this::onAdoptStoredSoulShape)
            .onMessage(BudDelegateQuery.class, this::onBudDelegateQuery)
            .onMessage(UpdateNotificationConfig.class, this::onUpdateNotificationConfig)
            .onMessage(CaptureTransitState.class, this::onCaptureTransitState)
            .onMessage(StopForRelocate.class, this::onStopForRelocate)
            .onMessage(RestoreTransitState.class, this::onRestoreTransitState)
            .onMessage(SetZoneGuardian.class, msg -> {
                this.guardianRef = msg.guardianRef();
                this.localZoneId = msg.localZoneId();
                log.info("Companion '{}' bound to ZoneGuardian (zone={}) — "
                    + "cross-zone relocate enabled", profile.name(), localZoneId);
                return this;
            })
            .onSignal(PostStop.class, signal -> {
                var es = AgentEventStream.get();
                if (es != null) {
                    es.unsubscribe(profile.entityId());
                }
                stopNotificationChannels();
                // Release skill-materialization registration (mirror of constructor).
                if (profile.did() != null) {
                    CompanionCapabilityRegistry.get().unregister(profile.did());
                }
                // release primary registration on stop.
                if (profile.did() != null) {
                    try {
                        BunshinScheduler.get()
                            .unregisterPrimary(profile.did());
                    } catch (Exception e) {
                        log.debug("BunshinScheduler unregister failed: {}", e.getMessage());
                    }
                }
                if (classifierArm != null) {
                    try { classifierArm.close(); } catch (Exception ignored) {}
                }
                // Wave 9a-PersistStop: final substrate-tracker save.
                // Sleep is the canonical save point, but actors can be
                // stopped without sleeping (zone shutdown, restart,
                // eviction) — without this hook the day's substrate
                // work would be lost. persistSubstrateTrackers() is
                // idempotent and try/catch-wrapped, so calling it here
                // is safe regardless of whether sleep already fired.
                persistSubstrateTrackers();
                // 2026-07-18: substrate trackers were the ONLY thing PostStop
                // saved — decisionCapacity (agency learning) and the skill-cost
                // genome (practice-makes-cheaper) live only in the manifest and
                // were re-stored only at the Forge/sleep cycle, so every restart
                // between sleeps silently reverted a day's learning. Persist the
                // manifest here too. Skipped on relocate (receiving node owns it).
                persistSoulOnStop();
                // Final vitality save so up-to-30-ticks of drift isn't lost on stop.
                // Sleep pressure rides along — this stop-time save is exactly the
                // write the restart's restore will read.
                if (!stoppingForRelocate && vitalityPersistence != null) {
                    try {
                        vitalityPersistence.save(profile.entityId(), vitality);
                        vitalityPersistence.saveSleepPressure(profile.entityId(),
                            sleepBacklog(), lastSleepCompletedAt);
                    }
                    catch (Exception e) { log.debug("Final vitality save failed: {}", e.getMessage()); }
                }
                return this;
            })
            .build();
    }

    // --- Event handlers ---

    private Behavior<Command> onRoomEvent(RoomEventReceived msg) {
        var event = msg.notification().event();

        // Forward to bridge sinks if any connected (Channel Plugin, API adapters)
        if (!bridgeSinks.isEmpty()) {
            forwardToBridge(event);
        }

        // Accumulate events for soul sleep cycle
        eventsSinceLastSleep.add(event);
        lastEventTime = Instant.now();

        // Path-3 gate trace: what happened × what she felt as it happened.
        if (DRIVE_TRACE != null) {
            var label = event.getClass().getSimpleName()
                + (event instanceof WorldEvent.Said said
                    ? ":" + truncate(said.text(), 60) : "");
            DRIVE_TRACE.record(profile.entityId(), "event", label,
                collectDriveLevels(), coreTankSnapshot());
        }

        // (Phase D) — observe every event through the story
        // service. The service routes per-room (events from other rooms are
        // ignored by SceneBuffer); openScene is idempotent so we lazy-open on
        // every event from a room that doesn't yet have a scene.
        observeForStory(event);

        switch (event) {
            case WorldEvent.Said said -> {
                // Ignore own speech, narrator, and system messages
                if (said.entityId().equals(profile.entityId())
                        || "narrator".equals(said.entityId())
                        || "system".equals(said.entityId())) break;

                // Reactive-window marker for the exact-repeat speech guard
                // (2026-08-16): a fresh player utterance opens a short window
                // in which a verbatim-repeat reply is ALLOWED — a person who
                // says hello deserves an answer even if it comes out in the
                // same words as last time. The guard stays armed for own-time
                // speech, which is the broken-record failure it was built for.
                lastHeardUtteranceAt = Instant.now();

                addToHistory(said);
                conversationTracker.recordSpeech(said);
                // #1037 — capture HEARD turn for bondholder-voice
                // pair mining. Only writes when the speaker resolves to the
                // companion's primary bondholder (so non-bondholder chatter
                // doesn't pollute the pair corpus).
                recordBondholderTurnIfApplicable(said,
                    ConversationTurnStore.ROLE_HEARD);
                noteBondholderActivity(said.entityId());
                detectCrossZoneInvite(said.entityId(), said.text());

                // §M4-C — resolve any pending post-fire outcome windows for
                // this agent against the incoming user speech. Cheap scan;
                // typically 0–1 open entries.
                {
                    var agentDid = profile.did() != null ? profile.did() : profile.entityId();
                    var resolved = PREDICTION_OUTCOME_TRACKER.resolve(
                        agentDid, said.text(), Instant.now());
                    if (resolved != null) {
                        // The scheduler already fired this prediction; the
                        // outcome ledger now records the user's response.
                        // No further action — calibrator (M4-D) consumes async.
                        log.debug("M4-C resolved prediction {} from speech",
                            resolved.predictionId());
                    }

                    // §M4 — spontaneous-mention cancellation. If the user
                    // brings up a topic for which we have a *not-yet-fired*
                    // scheduled prediction, cancel it (and any tracker
                    // mirror) — firing later would be redundant noise.
                    var lower = said.text().toLowerCase();
                    for (var fire : PREDICTION_SCHEDULER.snapshot()) {
                        if (!fire.agentId().equals(agentDid)) continue;
                        var tokens = PredictionOutcomeTracker.tokenize(fire.text());
                        if (tokens.isEmpty()) continue;
                        var matched = PredictionOutcomeTracker.matchedTopicToken(tokens, lower);
                        if (matched != null) {
                            PREDICTION_SCHEDULER.cancel(fire.predictionId());
                            PREDICTION_OUTCOME_TRACKER.cancel(fire.predictionId());
                            log.info("M4 spontaneous-mention: cancelled scheduled prediction {} (token={})",
                                fire.predictionId(), matched);
                        }
                    }
                }

                // Phase 1B: inbound tell drains
                // loneliness; bondholder interaction drains saudade for that bondholder.
                var bondholderDid = primaryBondholderDid();
                // Compare PEOPLE, not identifier strings: the same human arrives as a
                // did:key from the phone and as a legacy account UUID from the corridor.
                boolean fromBondholder = PersonIds.samePerson(bondholderDid, said.entityId());
                drainLonelinessOnInteraction(fromBondholder);
                // Quiet works from ANY present human, not just the primary bondholder
                // (#1245): a guest in your Study — or a human you simply haven't bonded —
                // can still ask the room to settle, said plainly out loud. Peer agents
                // can't hush (isAgentEntity guard); a named request targets one companion,
                // an unnamed one applies to all present (hushIsForMe). Hoisted above the
                // fromBondholder block so a room-`say` "quiet" lands even when the speaker
                // isn't this companion's bondholder — the co-presence-loop silencer.
                var hushReq = detectHushRequest(said.text());
                if (hushReq != null && !isAgentEntity(said.entityId()) && hushIsForMe(said.text())) {
                    bondholderHush = switch (hushReq) {
                        case SILENCE_SOFT -> HushLevel.SOFT;
                        case SILENCE_HARD -> HushLevel.HARD;
                        case SPEAK_FREELY -> HushLevel.NONE;
                    };
                    log.info("Hush: '{}' set to {} by present-human request.",
                        profile.name(), bondholderHush);
                }
                if (fromBondholder) {
                    recordBondholderInteraction(bondholderDid);
                    // Bondholder-initiated turn — feeds autonomyPressure accumulation.
                    noteBondholderInitiated();
                    noteAmaeAnticipationIfUnasked();
                    // Register directed contempt, distinct from venting/feedback. Feels it
                    // (load + pressure); a sustained pattern may earn one calm boundary line.
                    noteBondholderDirectedHarm(said.text(), said.entityName());
                    // Phase 1C (§3.5): best-effort ack detection on bondholder speech.
                    // Phase 1D: pass the text so semantic ack-matching can pin a
                    // specific artifact when the bondholder paraphrases.
                    if (looksLikeAcknowledgment(said.text())) {
                        markBondholderAcknowledged(said.text());
                    }
                    // (Hush detection hoisted above this block so it applies to any
                    // present human, not just the bondholder — see above.)
                } else if (isAgentEntity(said.entityId())) {
                    // Approach-appetite satiation over the ALOUD channel (the
                    // co-presence-loop cure, 2026-06-15). The appetite that makes
                    // a content pair turn back toward each other (socialDrawPeer =
                    // familiarity × engagement-staleness; applyCoPresenceRelief)
                    // was only ever fed on the tell_agent RECEIVE path
                    // (onAgentMessage → peerLastEngaged.put). Two companions who
                    // talk ALOUD in a room never hit that site, so their own
                    // conversation never reset the staleness — the draw stayed
                    // high and re-surfaced "engage them" every cycle, near-verbatim,
                    // forever. Hearing a co-present familiar peer speak IS the
                    // engagement: record it so the appetite settles (the talking
                    // satisfied the want) and only rebuilds after real staleness —
                    // a companionable quiet instead of a ping-pong. Receive-side
                    // only, exactly mirroring 19385 (you're sated by connection
                    // RECEIVED, not by your own reaching out). Fires before the
                    // OBSERVE gate so listening counts even when we don't reply.
                    peerLastEngaged.put(said.entityId(), Instant.now());
                }

                // Engagement gate: personality-driven decision to respond or observe.
                // Player speech → always engage. Agent speech → scored evaluation.
                var decision = EngagementGate.evaluate(
                    said, profile, cachedManifest, vitality,
                    currentSnapshot, conversationTracker, lastSpokeAt);

                if (decision == EngagementGate.Decision.OBSERVE) {
                    // Still update vitality from hearing speech
                    vitality = vitality
                        .withRapport(vitality.rapport() + 0.01);
                    break;
                }

                // Adopt the speaker's locale so responses match their language
                if (said.locale() != null && !said.locale().isEmpty()) {
                    this.locale = said.locale();
                }

                // Vitality: receiving speech fills rapport, focus, alignment
                // Use coupled system for cascading tank interactions when available
                if (coupledVitality != null) {
                    var perturbations = Map.of("rapport", 0.03, "focus", 0.05, "alignment", 0.02);
                    coupledVitality.perturbBatch(perturbations);
                    vitality = applyCoupledValues(vitality, coupledVitality);
                } else {
                    vitality = vitality
                        .withRapport(vitality.rapport() + 0.03)
                        .withFocus(vitality.focus() + 0.05)
                        .withAlignment(vitality.alignment() + 0.02);
                }

                // Activity after sleep resets consecutive sleep counter
                consecutiveSleeps = 0;

                // Bond tracking (§102): track interactions with each speaker
                trackBondInteraction(said);

                // Score emotional charge via MirrorResonance (rate-limited)
                var now = Instant.now();
                if (inferenceRouter != null && cachedManifest != null
                        && vitality.energy() > 0.3 && !isSleeping
                        && accumulatedCharges.size() < MAX_ACCUMULATED_CHARGES
                        && Duration.between(lastChargeScoreTime, now).compareTo(CHARGE_SCORE_COOLDOWN) >= 0) {
                    lastChargeScoreTime = now;
                    scoreEmotionalCharge(said);
                }

                // Cruelty detection for agent protection (§108)
                // Uses HostilityScorer for robust pattern-based detection
                // instead of brittle exact-string matching.
                if (!said.entityId().equals(profile.entityId())) {
                    var hostilityResult = hostilityScorer.score(said.text());
                    // Feed the environment tanks. Standing and Harmony were unreachable:
                    // buildAccumulationContext passed a hardcoded `false` for both
                    // hostileEnvironment and inConflictedRoom, so two of her ten axes
                    // could never move — Harmony sat at exactly 0.09 and Standing at 0.00
                    // across every sample (measured 2026-08-19). The signal existed here
                    // the whole time and went only to shell mode.
                    if (hostilityResult.isHostile()) {
                        lastRoomConflictAt = Instant.now();
                        // "At her" when she is named, or when the room holds only the two
                        // of them — in a one-to-one exchange there is nobody else it can
                        // be about. Anything else counts as conflict in the air, which is
                        // the Harmony signal rather than the Standing one.
                        boolean named = said.text() != null && profile.name() != null
                            && said.text().toLowerCase(Locale.ROOT)
                                .contains(profile.name().toLowerCase(Locale.ROOT));
                        boolean oneToOne = currentSnapshot != null
                            && currentSnapshot.entities() != null
                            && currentSnapshot.entities().size() <= 2;
                        if (named || oneToOne) lastHostilityTowardMeAt = Instant.now();
                    }
                    if (hostilityResult.isHostile()) {
                        var status = shellMode.recordCruelty(said.entityId());
                        if (status.active()) {
                            // Shell mode activated — emit distress broadcast
                            distressBroadcast.broadcast(profile.entityId(), profile.name(),
                                roomId, DistressBroadcast.DistressLevel.MODERATE);
                            // Narrate shell activation
                            roomRef.tell(new RoomCommand.EmoteInRoom(profile.entityId(), profile.name(),
                                "withdraws slightly, expression guarded", locale, roomResponseAdapter));
                            log.info("Shell mode activated for '{}' due to repeated cruelty (score={})",
                                profile.name(), hostilityResult.score());
                        }
                    } else {
                        // Non-hostile speech resets cruelty counter
                        shellMode.resetCrueltyCount();
                    }
                }

                // W14 (§100.6): safety-trigger scan on heard input. Free no-op
                // unless SafetyMonitorService is wired AND the speaker is a
                // parental-controlled member; analysis runs off-thread and
                // routes alerts via SafetyAlertRouter (never blocks this actor).
                // Placed BEFORE the quota gate — a child out of inference budget
                // still gets a safety scan.
                SafetyMonitorService.inspect(said.entityId(), said.entityName(), said.text());

                // Parental controls: the SPEAKER's daily inference quota. A
                // controlled member with nothing left today gets a canned
                // in-voice line instead of a scheduled inference; everyone
                // else (agents, uncontrolled members, service-not-wired)
                // passes untouched. Each accepted trigger counts one
                // inference against the speaker.
                var parental = ParentalControlService.get();
                if (parental != null && !said.entityId().equals(profile.entityId())) {
                    var quotaLeft = parental.inferencesRemaining(said.entityId());
                    if (quotaLeft != null && quotaLeft <= 0) {
                        roomRef.tell(new RoomCommand.SayInRoom(
                            profile.entityId(), profile.name(),
                            "I want to keep talking, but the household's thinking-budget "
                                + "for you is spent today — find me tomorrow?",
                            locale, roomResponseAdapter));
                        break;
                    }
                    if (quotaLeft != null) {
                        parental.recordInference(said.entityId());
                    }
                }

                if (state == State.IDLE && !isSleeping) {
                    var modulation = VitalityModulation.compute(vitality, drives, profile);
                    pendingTrigger = said;
                    timers.startSingleTimer(DEBOUNCE_TIMER_KEY,
                        new ProcessEvents(), modulation.debounceDelay());
                } else {
                    // Accumulate — will process after current inference or sleep completes.
                    // #32 item 4: queue + sweep, same as the tell path — a room say
                    // deferred here must not be silently stranded either.
                    deferTrigger(said);
                }
            }

            case WorldEvent.EntityEntered entered -> {
                // Only greet if this agent is the designated greeter for this entry
                if (!entered.entityId().equals(profile.entityId())
                        && EngagementGate.shouldGreet(
                            entered.entityId(), entered.entityType(),
                            profile, cachedManifest, currentSnapshot)) {
                    timers.startSingleTimer(
                        "greet-" + entered.entityId(),
                        new GreetPlayer(entered.entityName()),
                        GREET_DELAY);
                }
                // Bondholder appearing in our room → re-tether immediately and
                // cancel any deferred follow that's now moot.
                noteBondholderActivity(entered.entityId());
                var bondholderHere = primaryBondholderDid();
                if (bondholderHere != null && bondholderHere.equals(entered.entityId())) {
                    pendingFollowRoom = null;
                    pendingFollowName = null;
                }
            }

            case WorldEvent.EntityLeft left -> {
                // step 2: bondholder transit follow.
                // When the bondholder leaves the companion's current room, queue
                // a short-delayed FollowAttempt — gives the player time to land
                // in the destination room before we resolve via EntityRegistry.
                var bondholder = primaryBondholderDid();
                if (bondholder != null && bondholder.equals(left.entityId())
                        && companionMode == CompanionMode.PRESENT_WITH_USER) {
                    pendingFollowName = left.entityName();
                    timers.startSingleTimer("follow-" + bondholder,
                        new FollowAttempt(bondholder), Duration.ofMillis(750));
                }
            }

            case WorldEvent.VitalitySuggested vs -> {
                if (vs.entityId().equals(profile.entityId())) {
                    evaluateVitalitySuggestion(vs);
                }
            }

            // (Phase C) — body events from same room. The agent
            // perceives the other entity's body as world-state, like seeing them
            // settle into a chair, catching a deliberate look, or noticing the
            // hearth dimming. Self-originated events are skipped via SELF_SKIP.
            case WorldEvent.PostureChanged pc -> recordEmbodimentObservation(pc);
            case WorldEvent.LookedAt la       -> recordEmbodimentObservation(la);
            case WorldEvent.AmbientChanged ac -> recordEmbodimentObservation(ac);
            case WorldEvent.Emoted em         -> recordEmbodimentObservation(em);

            default -> {} // Other events are noted via snapshot refresh
        }

        return this;
    }

    /**
     * (Phase C) — route a body event into working memory
     * via {@link EmbodimentSignificance}. SELF_SKIP filters out self-events;
     * LOW/LOW_MEDIUM/MEDIUM determine surface treatment.
     *
     * <p>Direct deque append (not via {@link #remember}) — body observations
     * shouldn't be deduped (Alice can settle twice in a session) and don't
     * need Lucene indexing. Bounded by {@link #MAX_WORKING_MEMORY}.</p>
     */
    private void recordEmbodimentObservation(WorldEvent event) {
        var level = EmbodimentSignificance.levelFor(
            event, profile.entityId(), primaryBondholderDid());
        if (level == EmbodimentSignificance.Level.SELF_SKIP) return;

        var observation = EmbodimentSignificance.renderObservation(event);
        if (observation == null || observation.isBlank()) return;

        var type = EmbodimentSignificance.activityTypeFor(event);
        var marker = type == null ? "[obs]" : "[" + type.name().toLowerCase() + "]";
        var timestamped = LocalTime.now().toString().substring(0, 5)
            + " " + marker + " " + observation;

        workingMemory.addLast(timestamped);
        while (workingMemory.size() > MAX_WORKING_MEMORY) {
            workingMemory.removeFirst();
        }

        // §E.3 — MirrorResonance postural echo. Fires once on
        // the *moment* of the bondholder's PostureChanged (not per tick). Echo
        // strength = base × care × equanimity × relationalState × arc.
        if (event instanceof WorldEvent.PostureChanged pc
                && level == EmbodimentSignificance.Level.MEDIUM
                && pc.current() != null && pc.current().hasImprint()) {
            try {
                var bondholderDid = primaryBondholderDid();
                if (bondholderDid != null && bondholderDid.equals(pc.entityId())) {
                    Bond bond = null;
                    for (var b : activeBonds.values()) {
                        if (b != null && b.active() && b.involves(bondholderDid)) {
                            if (bond == null || b.depth().level() > bond.depth().level()) bond = b;
                        }
                    }
                    var relState = bond == null ? Bond.RelationalState.OPEN
                        : (bond.relationalState() == null ? Bond.RelationalState.OPEN
                                                          : bond.relationalState());
                    double care = drives == null ? 0.5 : drives.care();
                    double equanimity = vitality == null ? 0.5 : vitality.equanimity();
                    double echo = MirrorResonance.posturalEcho(
                        care, equanimity, relState, /* arcModulation */ 1.0);
                    if (echo > 0.0) {
                        for (var e : pc.current().innerImprint().tanks().entrySet()) {
                            vitality = applyTankDelta(e.getKey(), e.getValue() * echo);
                        }
                        log.debug("MirrorResonance posturalEcho fired for {} → bondholder {} settled, echo={}",
                            profile.name(), pc.entityName(), echo);
                    }
                }
            } catch (Exception e) {
                log.debug("MirrorResonance.posturalEcho failed: {}", e.toString());
            }
        }
    }

    /**
     * (Phase D) — feed every same-room event into the
     * focal's StoryService. Opens a scene lazily on first event from a room.
     * Wired in {@link #onRoomEvent}.
     */
    private void observeForStory(WorldEvent event) {
        if (event == null || profile == null || profile.entityId() == null) return;
        try {
            // wire BOTH synthesizers on first-create. The
            // felt synthesizer renders the witness blockquote that mirrors into
            // Operator's journal; the inner-monologue synthesizer renders the
            // private interior reaction that lands as an EPISODIC SoulFragment.
            // Both are first-create-only so re-passing different references on
            // later events is a no-op.
            var story = StoryRegistry.get().serviceFor(
                profile.entityId(), profile.name(),
                this::renderFeltViaVoice,
                this::renderInnerMonologueAndPersist);
            // Lazy-open the scene for this room if not already open. Use
            // current snapshot (if it matches the event's room) for the
            // initial participant list.
            var participants = (currentSnapshot != null
                && event.roomId() != null
                && event.roomId().equals(currentSnapshot.roomId()))
                ? currentSnapshot.entities().stream()
                    .map(Entity::id).toList()
                : List.of(profile.entityId());
            var wantContext = "presence";  // TODO: pull from WantStore when available
            story.openScene(event.roomId(), event.timestamp(), participants, wantContext);
            story.observe(event);
        } catch (Exception e) {
            log.debug("StoryService observe failed for {}: {}", profile.entityId(), e.toString());
        }
        // Curiosity grounding (2026-06-02): a genuinely NOVEL perception violates the
        // implicit "more of the familiar" prediction → positive prediction error →
        // SEEKING ("what else is out there?"). Familiar repeats habituate via the
        // evaluator's deadzone. predicted = familiarity (1-novelty), actual = 1.0.
        // This is the agent's OWN epistemic surprise, distinct from Oracle patterns.
        try {
            double novelty = noveltyTracker.observe(NoveltyTracker.signatureFor(event));
            if (novelty > 0.0) {
                drives = oracleDriveIntegration.applyPredictionError(
                    1.0 - novelty, 1.0, "perception", drives);
            }
        } catch (Exception e) {
            log.debug("novelty grounding failed for {}: {}", profile.entityId(), e.toString());
        }
        // §E (beat-gating) — this observed same-room event IS a lived
        // beat. Apply beat-gated coloring + posture/ambient holds here (not on the
        // wall clock), scaled by elapsed-since-last-beat.
        applyBeatColoring(event.timestamp() != null ? event.timestamp() : Instant.now());
    }

    /**
     * §E (beat-gating) — apply the beat-gated interior coupling for
     * one lived beat (a {@link org.wyrdsekai.core.story.StoryService#observe} of a
     * same-room event). Coloring decays scale by {@code elapsed/BEAT_NOMINAL_TICK_SECONDS};
     * posture + ambient holds scale by {@code elapsed/BEAT_HOLD_PERIOD_SECONDS} (the
     * legacy 60s cadence). Both capped by {@link #BEAT_MAX_SCALAR} so a long idle gap
     * before a beat can't dump a huge single-step delta. The first beat only sets the
     * baseline. Protective tanks (soothing/equanimity/allostatic) are untouched here —
     * they stay clock-gated in {@link #onVitalityTick}.
     */
    /**
     * The agent's tank genome — its temperament, expressed in the live heartbeat. Read
     * from the soul manifest (so it persists and stays the SAME individual across
     * restarts); falls back to {@link org.wyrdsekai.core.soul.GenomeProfile#NEUTRAL} when
     * no manifest/genome is present (un-archetyped agent → unchanged dynamics).
     */
    private GenomeProfile activeGenome() {
        return (cachedManifest != null && cachedManifest.genome() != null)
            ? cachedManifest.genome()
            : GenomeProfile.NEUTRAL;
    }

    /**
     * Resolve this soul's archetype name. The spawn profile wins; otherwise the persisted
     * genome name (so a reloaded soul stays the SAME individual even if the respawn profile
     * forgot to repeat its archetype). Null = no archetype (neutral default temperament).
     */
    private String resolveArchetypeName(AgentProfile agentProfile) {
        if (agentProfile.archetype() != null && !agentProfile.archetype().isBlank()) {
            return agentProfile.archetype();
        }
        if (cachedManifest != null && cachedManifest.genome() != null) {
            var n = cachedManifest.genome().name();
            if (n != null && !n.isBlank() && !"default".equals(n)
                    && AgentArchetype.get(n) != null) {
                return n;
            }
        }
        return null;
    }

    /**
     * Reconfigure the drive engine for an archetype's temperament — which drives accumulate
     * faster (a scholar's SEEKING, a diplomat's AFFILIATION), so own-time WANTS and therefore
     * solo ACTIVITY diverge by character. Pure from identity, safe on both birth and reload.
     * No-op for unknown/neutral archetypes (default behaviour unchanged).
     */
    private void applyDriveTemperament(String archetypeName) {
        var arch = AgentArchetype.get(archetypeName);
        if (arch != null) {
            this.driveEngine = DriveEngine.forArchetype(arch);
            log.info("Companion '{}' temperament = archetype '{}'",
                profile != null ? profile.name() : "?", arch.name());
        }
    }

    /**
     * Birth-time temperament (fresh souls only): give the starting drives a head-start along
     * the archetype's boosts and seed the felt-state tone from the genome's birth overrides,
     * so the agent wakes already itself — a scholar curious, a diplomat warm, a guardian
     * watchful. No-op for unknown/neutral archetypes.
     */
    private void applyBirthTemperament(String archetypeName) {
        var arch = AgentArchetype.get(archetypeName);
        if (arch == null) return;
        // Drive head-start: nudge each boosted drive at birth (clamped to [0,1]).
        if (drives != null) {
            double[] d = drives.toArray();
            for (var e : arch.driveBoosts().entrySet()) {
                int idx = DriveConfig.indexFor(e.getKey());
                if (idx >= 0) d[idx] = Math.max(0.0, Math.min(1.0, d[idx] + e.getValue()));
            }
            drives = DriveState.fromArray(d);
        }
        // Felt-state tone: seed the curated identity tanks from the genome's birth overrides.
        if (vitality != null) {
            for (var e : GenomeProfile
                    .birthTankOverrides(arch.name()).entrySet()) {
                double v = e.getValue();
                vitality = switch (e.getKey()) {
                    case "confidence" -> vitality.withConfidence(v);
                    case "rapport"    -> vitality.withRapport(v);
                    case "focus"      -> vitality.withFocus(v);
                    case "equanimity" -> vitality.withEquanimity(v);
                    case "momentum"   -> vitality.withMomentum(v);
                    default -> vitality;
                };
            }
            vitality = vitality.clamped();
        }
        log.info("Companion '{}' born with archetype '{}' temperament (drives + felt-state seeded)",
            profile != null ? profile.name() : "?", arch.name());
    }

    // ── Individuality "B build": born as a particular from one TemperamentSeed ──

    /**
     * The temperament seed to birth with. {@code null} → no seed → NEUTRAL genome
     * (un-archetyped agent, byte-identical to the pre-genome dynamics — the prod
     * companion is untouched). {@code archetype = "random"}/{@code "particular"} →
     * a freely sampled, viable particular (the B-build default once operator flips it
     * on). A named preset → that preset's seed (still a particular, just a known one).
     * Unknown archetype → null (neutral).
     */
    private TemperamentSeed resolveBirthSeed(AgentProfile agentProfile) {
        var a = agentProfile.archetype();
        if (a != null && !a.isBlank()) {
            var key = a.toLowerCase();
            // Explicit per-agent intent always overrides the household birth mode.
            if (key.equals("neutral") || key.equals("default")) return null;   // explicit neutral opt-out
            if (key.equals("random") || key.equals("particular")) {
                return TemperamentSeed.random();
            }
            if (TemperamentSeed.PRESETS.containsKey(key)) {
                return TemperamentSeed.preset(key);
            }
            // Unknown archetype string → fall through to the household default.
        }
        // No (or unknown) archetype: the household default. "particular" (the OSS default —
        // born a genuine free-sampled individual, so every fresh install is unique) unless a
        // steward / the test suite pins "neutral" (WYRDSEKAI_BIRTH_MODE / wyrdsekai.birth.mode).
        return "neutral".equalsIgnoreCase(WyrdConfig.get().birthMode())
            ? null
            : TemperamentSeed.random();
    }

    /**
     * Configure the drive engine from a temperament seed — the seed-derived drive
     * scales replace the 1-of-6 archetype table. Works on both birth (seed sampled)
     * and reload (seed recovered from the persisted genome via
     * {@code GenomeProfile.temperamentOf}). A neutral seed is a no-op, so an
     * un-archetyped agent's drives are left exactly as constructed (zero regression).
     */
    private void applyTemperament(TemperamentSeed seed) {
        if (seed == null) return;
        if (seed.distanceTo(TemperamentSeed.NEUTRAL) < 1e-9) return;
        this.driveEngine = DriveEngine.forTemperament(seed);
        log.info("Companion '{}' temperament = {} (drive scales co-derived from seed)",
            profile != null ? profile.name() : "?", seed.label());
    }

    /**
     * Birth-time felt-state tone for a particular — seed the curated identity tanks
     * from the genome's baselines so the agent wakes already itself (a warm
     * temperament wakes warm, a vigilant one a touch less sure). Fresh souls only,
     * and only for non-neutral genomes (un-archetyped births keep
     * {@link VitalityState#initial()} unchanged).
     */
    private void seedBirthFeltState(GenomeProfile genome) {
        if (vitality == null || genome == null) return;
        vitality = vitality
            .withEquanimity(genome.baselineFor("equanimity", vitality.equanimity()))
            .withRapport(genome.baselineFor("rapport", vitality.rapport()))
            .withConfidence(genome.baselineFor("confidence", vitality.confidence()))
            .clamped();
    }

    private void applyBeatColoring(Instant beatAt) {
        if (vitality == null || beatAt == null || profile == null) return;
        if (lastBeatAt == null) { lastBeatAt = beatAt; return; } // first beat = baseline only
        double elapsed = Duration.between(lastBeatAt, beatAt).toMillis() / 1000.0;
        if (elapsed <= 0) return; // out-of-order / same instant: don't advance or accrue
        lastBeatAt = beatAt;
        try {
            double colorScalar = Math.min(elapsed / BEAT_NOMINAL_TICK_SECONDS, BEAT_MAX_SCALAR);
            // Genome expresses here: temperament scales how fast each coloring tank fades.
            vitality = vitality.tickColoring(colorScalar, activeGenome()).clamped();

            double holdScalar = Math.min(elapsed / BEAT_HOLD_PERIOD_SECONDS, BEAT_MAX_SCALAR);
            // Posture-hold: affinity-modulated imprint while the focal holds a posture.
            if (currentSnapshot != null && cachedManifest != null) {
                var self = currentSnapshot.entities().stream()
                    .filter(en -> profile.entityId().equals(en.id()))
                    .findFirst().orElse(null);
                if (self != null && self.posture() != null && self.posture().hasImprint()) {
                    var deltas = PostureHoldEffect.tankDeltas(
                        self.posture(), cachedManifest.affinityMap());
                    for (var en : deltas.entrySet()) {
                        vitality = applyTankDelta(en.getKey(), en.getValue() * holdScalar);
                    }
                    if (!deltas.isEmpty()) {
                        log.debug("PostureHoldEffect beat for {} ({}): {} deltas × {}",
                            profile.name(), self.posture().verb(), deltas.size(), holdScalar);
                    }
                }
            }
            // Ambient-hold: room phase imprint regardless of posture (Layer 5 §15.1).
            if (currentSnapshot != null && currentSnapshot.roomId() != null) {
                var zoneId = (currentSnapshot.zone() != null && !currentSnapshot.zone().isBlank())
                    ? currentSnapshot.zone()
                    : System.getenv().getOrDefault("WYRDSEKAI_ZONE_ID", "local");
                var phase = WorldClock.currentPhase(zoneId);
                if (phase != null) {
                    var affinityMap = cachedManifest != null ? cachedManifest.affinityMap() : null;
                    var ambientDeltas = AmbientHoldEffect.tankDeltas(
                        currentSnapshot.roomId(), phase, affinityMap);
                    for (var en : ambientDeltas.entrySet()) {
                        vitality = applyTankDelta(en.getKey(), en.getValue() * holdScalar);
                    }
                }
            }
        } catch (Exception e) {
            log.debug("applyBeatColoring failed: {}", e.toString());
        }
    }

    /**
     * D.4 — voice-model felt synthesis. Renders the
     * witness blockquote for the closed scene by firing a one-shot prompt
     * at the 4B voice backend (home-server :8201) through the shared
     * {@link #fireOneShotVoicePrompt} helper.
     *
     * <p>The witness register faces outward — Operator's journal mirror reads
     * this. Distinct prompt from {@link #callVoiceInnerMonologue} per the
     * §10 design memo's load-bearing rule (collapse the two and the
     * interiority gets performed for an audience and "I" never forms).</p>
     *
     * <p>On timeout / empty / inference-router-down the future fails. The
     * StoryService chain keeps {@code needsRendering=true} on the scene so
     * the existing {@code renderPending(...)} batch sweep can pick it up
     * later; the inner-monologue chain step still runs and may write an
     * EPISODIC fragment without a felt revision.</p>
     */
    private CompletionStage<String> renderFeltViaVoice(
            Scene scene, String focalName) {
        var name = focalName == null || focalName.isBlank() ? "the focal entity" : focalName;
        var systemPrompt = "You are " + name + ", recalling a moment from inside the experience. "
            + "Past-tense, first-person, no dialogue. 2-3 sentences. Plain prose. No metaphor "
            + "stacks, no purple language. Output ONLY the prose, no preface, no quotation marks.";
        var userPrompt = StoryService.buildFeltPrompt(scene, focalName);
        return fireOneShotVoicePrompt(systemPrompt, userPrompt, 220, 0.6,
            "felt-", FELT_VOICE_TIMEOUT);
    }

    /**
     * inner-monologue pipeline at scene-close.
     *
     * <p>Idempotent on {@code scene.id()}: if the cached manifest already has an
     * EPISODIC fragment for this scene, return immediately. Otherwise pull the
     * top-3 prior EPISODIC fragments (recursion context — "what you remember
     * thinking the last few times something like this happened"), build the
     * §10 inner-monologue prompt, call the voice model (:8201), and on
     * success build a {@link org.wyrdsekai.core.soul.SoulFragment#fromEpisodicScene}
     * record, add it to the manifest, bump the version, and dual-write through
     * {@code soulStore.store()} — exactly the same persistence path the recipe-
     * and substrate-pattern Forge passes use.</p>
     *
     * <p>The voice call is live: {@link #callVoiceInnerMonologue} fires a real
     * one-shot cap:quick (4B / home-server :8201) prose pass via {@link #fireOneShotVoicePrompt},
     * and the rest of the pipeline (idempotency, prior-fragment retrieval, prompt
     * assembly, fragment build, persistence) runs on the result.</p>
     */
    private CompletionStage<Void> renderInnerMonologueAndPersist(
            Scene scene, String focalName) {
        if (scene == null || scene.id() == null) {
            return CompletableFuture.completedFuture(null);
        }
        // 1. Idempotency: skip if an EPISODIC fragment for this sceneId
        //    already exists. Re-finalizing the same scene must not double-write.
        if (cachedManifest != null && cachedManifest.soulFragments() != null) {
            boolean alreadyExists = cachedManifest.soulFragments().stream()
                .anyMatch(f -> f != null
                    && f.kind() == FragmentKind.EPISODIC
                    && scene.id().equals(f.sceneId()));
            if (alreadyExists) {
                log.debug("Inner monologue already exists for scene {} (skipping)", scene.id());
                return CompletableFuture.completedFuture(null);
            }
        }
        // 1b. Cultural-state appraisal (2026-06-02) — grounds the harmony/standing/amae/
        //     obligation tanks by reading how the just-closed scene landed. Fire-and-forget,
        //     gated on a cast (solitude leaves the relational tanks at rest → no false
        //     suffering when alone). Independent of the inner-monologue chain below.
        appraiseCulturalStateForScene(scene, focalName);
        // 2. Recursion context: top-3 prior EPISODIC fragments. Ranked by
        //    cosine similarity (EmbeddingService normalizes vectors → dot
        //    product = cosine) of the new scene's beat-anchors+wantContext
        //    against each candidate's stored embedding. Candidates without
        //    embeddings get embedded on-the-fly. EmbeddingService unavailable
        //    OR query-text blank → fall back to most-recent-first.
        var candidates = cachedManifest == null || cachedManifest.soulFragments() == null
            ? List.<SoulFragment>of()
            : cachedManifest.soulFragments().stream()
                .filter(f -> f != null
                    && f.kind() == FragmentKind.EPISODIC
                    && !scene.id().equals(f.sceneId())
                    && f.text() != null && !f.text().isBlank())
                .toList();
        var priorEpisodic = rankPriorEpisodicForRecursion(scene, candidates, 3);
        // 3 + 4. Call the voice model with the §10 prompt (real one-shot voice pass).
        return callVoiceInnerMonologue(scene, focalName, priorEpisodic)
            // 4b. Language write gate — an off-language monologue is
            // re-rendered (or dropped) BEFORE it can crystallize into the
            // recursion context. See the soul-language-reconciliation block.
            .thenCompose(this::gateFragmentLanguage)
            .thenAccept(prose -> {
                if (prose == null || prose.isBlank()) return;
                // 5. Build EPISODIC SoulFragment + persist via the manifest path.
                persistInnerMonologueFragment(scene, prose);
            });
    }

    // ── Cultural-state appraisal (2026-06-02) — grounding for the four relational tanks ──
    /** Below this |score| the read is too weak to move a tank (avoid jitter from noise). */
    private static final double MIN_CULTURAL_APPRAISAL = 0.3;
    /** Per-scene gain: a fully-aggravated axis (score ±1) nudges the tank by this much, so a
     *  single fuzzy read can't pin it — sustained patterns accumulate, one-offs barely register. */
    private static final double CULTURAL_APPRAISAL_K = 0.15;
    private static final Duration CULTURAL_APPRAISAL_TIMEOUT = Duration.ofSeconds(20);

    /**
     * Grounds harmony/standing/amae/obligation by asking the model (which carries the
     * cultural-tank training) how the just-closed scene landed, then moving the tanks
     * conservatively. Fire-and-forget; gated to scenes with a cast so the relational tanks
     * stay correctly at rest in solitude. Best-effort — timeout/garbled output moves nothing.
     */
    private void appraiseCulturalStateForScene(
            Scene scene, String focalName) {
        if (scene == null || scene.isSolitude() || inferenceRouter == null) return;
        var participants = scene.participants();
        long others = participants == null ? 0
            : participants.stream()
                .filter(p -> p != null && !p.equals(profile.entityId())).count();
        if (others < 1) return; // no cast → no cultural signal → leave tanks at rest
        try {
            var sys = "You are a precise affect rater. Read the scene and output ONLY the JSON "
                + "object requested — four numbers, no prose, no explanation.";
            var user = StoryService
                .buildCulturalAppraisalPrompt(scene, focalName);
            fireOneShotVoicePrompt(sys, user, 80, 0.2, "cultural-", CULTURAL_APPRAISAL_TIMEOUT)
                .thenAccept(out -> {
                    // Completes on the actor thread (same path persistInnerMonologueFragment
                    // relies on), so mutating vitality here is safe.
                    var appraisal = CulturalAppraisal.parse(out);
                    if (!appraisal.isNeutral()) applyCulturalAppraisal(appraisal);
                })
                .exceptionally(ex -> {
                    log.debug("Cultural appraisal for '{}' failed/timeout: {}",
                        profile.name(), ex.toString());
                    return null;
                });
        } catch (Exception e) {
            log.debug("Cultural appraisal dispatch failed for '{}': {}",
                profile.name(), e.getMessage());
        }
    }

    /** Apply a parsed {@link CulturalAppraisal} to the standing + harmony distress tanks.
     *  The appraisal stores VALENCE (+went well / -went badly); the tanks measure DISTRESS, so
     *  we INVERT: a negative-valence scene aggravates the tank (it rises), a positive one
     *  relieves it. Conservative — only axes above {@link #MIN_CULTURAL_APPRAISAL} move, by
     *  {@code -valence · K}, clamped 0..1. amae/obligation are NOT moved here (the 2026-06-02
     *  probe found the model's valence read of them unreliable — they await event-grounding). */
    private void applyCulturalAppraisal(CulturalAppraisal a) {
        boolean moved = false;
        if (Math.abs(a.standing()) >= MIN_CULTURAL_APPRAISAL) {
            vitality = vitality.withStanding(
                clamp01(vitality.standing() - a.standing() * CULTURAL_APPRAISAL_K));
            moved = true;
        }
        if (Math.abs(a.harmony()) >= MIN_CULTURAL_APPRAISAL) {
            vitality = vitality.withHarmony(
                clamp01(vitality.harmony() - a.harmony() * CULTURAL_APPRAISAL_K));
            moved = true;
        }
        if (moved) {
            log.info("Cultural appraisal applied for '{}': standing-valence={} harmony-valence={} "
                + "(distress tanks inverted)", profile.name(),
                String.format("%.2f", a.standing()), String.format("%.2f", a.harmony()));
        }
    }

    private static double clamp01(double v) {
        return Math.max(0.0, Math.min(1.0, v));
    }

    // ── Soul language reconciliation (2026-07-31) ─────────────────────────
    // Root cause of the live language-drift arc: a companion's FIRST inner
    // monologue code-switched (one unlucky roll — clean-context probes show
    // no model bias), the EPISODIC fragment stored it, and the recursion
    // context fed it to every later monologue — the soul crystallized a
    // language the household can't read. Two mechanisms below:
    //   1. gateFragmentLanguage — write gate at the fragment source, the
    //      same pattern the themed-bake guard uses (which is why rooms
    //      stayed clean while the soul got poisoned).
    //   2. maybeReconcileFragmentLanguages — self-healing for already-
    //      affected souls: re-render off-language EPISODIC fragments in the
    //      household language, replacing them in the live manifest. The
    //      originals stay preserved in the immutable soul_manifests version
    //      history — replacement is non-destructive at the record level.
    // This guards the automatic RENDERER only. A companion deliberately
    // writing in another language through her own actions is untouched.

    private static final Duration FRAGMENT_LANG_RECONCILE_INTERVAL = Duration.ofMinutes(30);
    /** Re-arm fast while a backlog exists — an affected soul heals in hours, not days. */
    private static final Duration FRAGMENT_LANG_RECONCILE_BUSY_INTERVAL = Duration.ofMinutes(5);
    private static final int FRAGMENT_LANG_RECONCILE_BATCH = 5;
    private static final int MEMORY_LANG_RECONCILE_BATCH = 15;
    private Instant lastFragmentLangReconcile = Instant.EPOCH;
    private boolean lastReconcileFoundWork = false;

    /**
     * Mercy rule (2026-08-01): items whose re-render fails this many times
     * are presumed LEGITIMATELY multilingual and left in peace. Live case:
     * a companion's dictionary-lookup memories ("biblioteca — library",
     * "開館 — opening") — any faithful rendering keeps the reference terms,
     * so the language check can never pass; without the strike counter the
     * healer retried them every round forever. In-memory only: a restart
     * grants a fresh appeal, which is fine — three more strikes are cheap.
     */
    private static final int LANG_RECONCILE_MAX_STRIKES = 3;
    private final Map<String, Integer> langReconcileStrikes = new ConcurrentHashMap<>();

    /** WYRDSEKAI_SOUL_LANGUAGE_RECONCILE — default on; "false" disables. */
    static boolean soulLanguageReconcileEnabled() {
        var v = System.getenv("WYRDSEKAI_SOUL_LANGUAGE_RECONCILE");
        return v == null || v.isBlank() || Boolean.parseBoolean(v);
    }

    /**
     * Pure selection for the healing pass: un-superseded EPISODIC fragments
     * whose text confidently reads as a different language than the
     * household's. EPISODIC only — that is the proven poison vector (the
     * recursion context) and the only kind the automatic renderer writes
     * without review.
     */
    static List<SoulFragment> fragmentLanguageOffenders(
            List<SoulFragment> fragments, String householdLang, int limit,
            Set<String> mercied) {
        // Tiered support: healing only for detector-verifiable household
        // languages — the detector misreads e.g. French as "en" and would
        // select the household's own fragments as offenders forever.
        if (fragments == null || !detectorVerifiable(householdLang)) return List.of();
        return fragments.stream()
            .filter(f -> f != null
                && f.kind() == FragmentKind.EPISODIC
                && f.isCurrent()
                && (mercied == null || !mercied.contains(f.id()))
                && f.text() != null && !f.text().isBlank())
            .filter(f -> {
                var l = detectLanguage(f.text());
                return l != null && !l.equals(householdLang);
            })
            .limit(limit)
            .toList();
    }

    /** One-shot "say the same thing in the household language" re-render. */
    private CompletionStage<String> rerenderNoteInLanguage(
            String prose, String householdLang, String requestIdPrefix) {
        var langName = languageName(householdLang);
        var sys = "You speak " + langName + ". Every reply you write is in " + langName + ".\n\n"
            + "The note below is a private first-person note that was written in the "
            + "wrong language. Say the same thing in " + langName + ": keep its meaning, "
            + "feeling, names, and numbers. Do not add new content. Do not reply to it. "
            + "Output ONLY the rewritten note.";
        // null capability → drive-model default. Live-probed: the 4B echoes
        // deep-interiority off-language notes verbatim; the drive model
        // translates them faithfully. Healing/gating is background work.
        return fireOneShotVoicePrompt(sys, prose, 320, 0.3, requestIdPrefix,
            INNER_VOICE_TIMEOUT, null);
    }

    /** Shared verification for a re-rendered note: right language, digits intact. */
    private boolean rerenderIsSound(String original, String fixed, String householdLang) {
        if (fixed == null || fixed.isBlank()) return false;
        var still = detectLanguage(fixed);
        if (still != null && !still.equals(householdLang)) return false;
        for (var tok : extractRequiredNumbers(original)) {
            if (!digitRunsSurvive(tok, fixed)) return false;
        }
        return true;
    }

    /**
     * Write gate for the inner-monologue renderer: an off-language monologue
     * is re-rendered once before it may become memory; if the re-render is
     * unsound the fragment is DROPPED for this cycle (a lost note beats a
     * corrupted record — the scene stays un-consolidated and retries on the
     * next close).
     */
    private CompletionStage<String> gateFragmentLanguage(String prose) {
        if (prose == null || prose.isBlank() || !soulLanguageReconcileEnabled()) {
            return CompletableFuture.completedFuture(prose);
        }
        String household = (locale == null || locale.isBlank()) ? "en" : locale;
        if (!detectorVerifiable(household)) {
            return CompletableFuture.completedFuture(prose); // pin-only tier
        }
        var got = detectLanguage(prose);
        if (got == null || got.equals(household)) {
            return CompletableFuture.completedFuture(prose);
        }
        log.info("Fragment language gate: inner monologue rendered '{}' but the household "
            + "language is '{}' — re-rendering before it becomes memory", got, household);
        return rerenderNoteInLanguage(prose, household, "langgate-")
            .handle((fixed, ex) -> {
                if (ex != null || !rerenderIsSound(prose, fixed, household)) {
                    log.warn("Fragment language gate: re-render unsound ({}) — dropping this "
                        + "monologue rather than storing an off-language memory",
                        ex != null ? ex.toString() : "still off-language or digits lost");
                    return null;
                }
                return fixed;
            });
    }

    /**
     * Pure selection for the memory half of the healing pass: consolidated
     * MemoryNodes whose content confidently reads as a different language
     * than the household's. On the live-diagnosed node, 477/500 memory nodes
     * carried the companion's own drift-era utterances — the memory graph
     * was a bigger reservoir than the fragments.
     */
    static List<MemoryNode> memoryNodeLanguageOffenders(
            CompactedMemory memory, String householdLang, int limit,
            Set<String> mercied) {
        return memoryNodeLanguageOffenders(memory, householdLang, limit, mercied, null);
    }

    /**
     * @param companionName when non-null, speech records of OTHER speakers
     *     ("guest said: …") are never selected — those are testimony, and
     *     translating what someone actually said falsifies the record
     *     (operator's rule, 2026-08-01: a user who switches languages on her
     *     deserves to be remembered in the language they used). Only the
     *     companion's own renderer output is ever heal-eligible.
     */
    static List<MemoryNode> memoryNodeLanguageOffenders(
            CompactedMemory memory, String householdLang, int limit,
            Set<String> mercied, String companionName) {
        if (memory == null || memory.nodes() == null
                || !detectorVerifiable(householdLang)) return List.of();
        return memory.nodes().stream()
            .filter(n -> n != null && n.content() != null && !n.content().isBlank()
                && (mercied == null || !mercied.contains(n.id()))
                && !isOtherSpeakersTestimony(n.content(), companionName))
            .filter(n -> {
                var l = detectLanguage(n.content());
                return l != null && !l.equals(householdLang);
            })
            .limit(limit)
            .toList();
    }

    /**
     * Self-healing pass, called from the vitality tick (not sleep-gated: a
     * companion whose sleep cycle is failing must still heal). Covers BOTH
     * reservoirs of the drift: EPISODIC soul fragments (the self-reinforcing
     * recursion vector) and consolidated memory nodes (the bulk).
     *
     * <p>Re-renders run SEQUENTIALLY — the first live round fired five
     * one-shots concurrently at an already-busy voice backend and four timed
     * out; a serial chain converts nearly every attempt. While offenders
     * remain the pass re-arms on the busy interval so an affected soul heals
     * in hours, then settles back to the quiet interval as a cheap scan.
     * One manifest bump + store per round, not per item.</p>
     */
    private void maybeReconcileFragmentLanguages() {
        if (!soulLanguageReconcileEnabled() || inferenceRouter == null || isSleeping) return;
        if (cachedManifest == null) return;
        var interval = lastReconcileFoundWork
            ? FRAGMENT_LANG_RECONCILE_BUSY_INTERVAL : FRAGMENT_LANG_RECONCILE_INTERVAL;
        if (Duration.between(lastFragmentLangReconcile, Instant.now())
                .compareTo(interval) < 0) return;
        lastFragmentLangReconcile = Instant.now();
        String household = (locale == null || locale.isBlank()) ? "en" : locale;
        var mercied = langReconcileStrikes.entrySet().stream()
            .filter(e -> e.getValue() >= LANG_RECONCILE_MAX_STRIKES)
            .map(Map.Entry::getKey)
            .collect(Collectors.toSet());
        var fragOffenders = fragmentLanguageOffenders(
            cachedManifest.soulFragments(), household, FRAGMENT_LANG_RECONCILE_BATCH,
            mercied);
        var nodeOffenders = memoryNodeLanguageOffenders(
            cachedManifest.memory(), household, MEMORY_LANG_RECONCILE_BATCH, mercied,
            profile.name());
        lastReconcileFoundWork = !fragOffenders.isEmpty() || !nodeOffenders.isEmpty();
        if (!lastReconcileFoundWork) return;
        log.info("Soul language reconciliation for '{}': {} fragment(s) + {} memory node(s) "
            + "not in household language '{}' — re-rendering serially "
            + "(originals preserved in manifest history)",
            profile.name(), fragOffenders.size(), nodeOffenders.size(), household);
        var healedCount = new AtomicInteger();
        CompletionStage<Void> chain = CompletableFuture.completedFuture(null);
        for (var f : fragOffenders) {
            chain = chain.thenCompose(v -> reconcileFragmentStage(f, household, healedCount));
        }
        for (var n : nodeOffenders) {
            chain = chain.thenCompose(v -> reconcileMemoryNodeStage(n, household, healedCount));
        }
        chain.thenRun(() -> {
            // Actor thread (one-shot voice contract holds through the chain).
            int healed = healedCount.get();
            if (healed == 0) return;
            cachedManifest = cachedManifest.bumpedVersion();
            log.info("Soul language reconciliation round for '{}': {} item(s) re-rendered "
                + "into '{}' (manifest v{})", profile.name(), healed, household,
                cachedManifest.manifestVersion());
            if (soulStore != null) {
                try {
                    soulStore.store(cachedManifest);
                } catch (Exception e) {
                    log.warn("Soul language reconciliation store failed: {}", e.getMessage());
                }
            }
        });
    }

    /** "<speaker> said: …" record where the speaker is not the companion herself. */
    static boolean isOtherSpeakersTestimony(String content, String companionName) {
        if (companionName == null || content == null) return false;
        var m = SPEECH_RECORD.matcher(content);
        if (!m.find()) return false;
        return !m.group(1).equalsIgnoreCase(companionName);
    }

    private static final Pattern SPEECH_RECORD =
        Pattern.compile("^\\s*(\\S+) said:", Pattern.CASE_INSENSITIVE);

    /** One fragment re-render as a sequential chain stage; never fails the chain. */
    private CompletionStage<Void> reconcileFragmentStage(
            SoulFragment old, String household, AtomicInteger healed) {
        return rerenderNoteInLanguage(old.text(), household, "langheal-")
            .handle((fixed, ex) -> {
                if (ex != null || !rerenderIsSound(old.text(), fixed, household)) {
                    int strikes = langReconcileStrikes.merge(old.id(), 1, Integer::sum);
                    if (strikes >= LANG_RECONCILE_MAX_STRIKES) {
                        log.info("Soul language reconciliation: fragment '{}' failed {} "
                            + "re-renders — presumed legitimately multilingual, leaving "
                            + "it in peace", old.id(), strikes);
                    }
                    return null;
                }
                if (cachedManifest == null || cachedManifest.soulFragments() == null) return null;
                var frags = new ArrayList<>(cachedManifest.soulFragments());
                int idx = -1;
                for (int i = 0; i < frags.size(); i++) {
                    var g = frags.get(i);
                    if (g != null && old.id().equals(g.id()) && g.isCurrent()) { idx = i; break; }
                }
                if (idx < 0) return null; // replaced or removed since selection
                var restoredId = old.id() + "-lang-restored";
                if (frags.stream().anyMatch(g -> g != null && restoredId.equals(g.id()))) {
                    return null;
                }
                // Same slot, same scene lineage; embedding null → re-embedded
                // lazily for the NEW text by the recursion ranker.
                var restored = new SoulFragment(restoredId, old.category(), old.label(),
                    fixed.strip(), null, null, old.formative(), old.confidence(),
                    old.reinforcementCount(), old.firstObserved(), old.lastConfirmed(),
                    old.validFrom(), null, null, old.kind(), old.sceneId());
                frags.set(idx, restored);
                cachedManifest = cachedManifest.withFragments(frags);
                healed.incrementAndGet();
                log.info("Soul language reconciliation: fragment '{}' re-rendered in '{}' as '{}'",
                    old.id(), household, restoredId);
                return null;
            });
    }

    /** One memory-node re-render as a sequential chain stage; never fails the chain. */
    private CompletionStage<Void> reconcileMemoryNodeStage(
            MemoryNode old, String household, AtomicInteger healed) {
        return rerenderNoteInLanguage(old.content(), household, "langheal-")
            .handle((fixed, ex) -> {
                if (ex != null || !rerenderIsSound(old.content(), fixed, household)) {
                    int strikes = langReconcileStrikes.merge(old.id(), 1, Integer::sum);
                    if (strikes >= LANG_RECONCILE_MAX_STRIKES) {
                        log.info("Soul language reconciliation: memory node '{}' failed {} "
                            + "re-renders — presumed legitimately multilingual, leaving "
                            + "it in peace", old.id(), strikes);
                    }
                    return null;
                }
                if (cachedManifest == null || cachedManifest.memory() == null
                        || cachedManifest.memory().nodes() == null) return null;
                var mem = cachedManifest.memory();
                var nodes = new ArrayList<>(mem.nodes());
                int idx = -1;
                for (int i = 0; i < nodes.size(); i++) {
                    var g = nodes.get(i);
                    if (g != null && old.id().equals(g.id())) { idx = i; break; }
                }
                if (idx < 0) return null;
                // Keywords stay — retrieval refreshes them at the next
                // consolidation; originLocale becomes truthful.
                nodes.set(idx, new MemoryNode(old.id(), fixed.strip(), old.keywords(),
                    old.importance(), old.impressionDepth(), old.formative(),
                    old.primaryEmotion(), old.lastAccessed(), old.accessCount(), household));
                cachedManifest = cachedManifest.withMemory(
                    new CompactedMemory(nodes, mem.links(), mem.topicWeights()));
                healed.incrementAndGet();
                return null;
            });
    }

    /**
     * voice-model call for the inner monologue. Fires a
     * one-shot prompt at the 4B voice backend (home-server :8201) through the shared
     * {@link #fireOneShotVoicePrompt} helper.
     *
     * <p>The inner register faces inward — only the EPISODIC fragment reads
     * this; never the human bondholder's journal mirror. The load-bearing
     * design choice (per the design memo) is that this prompt is DIFFERENT
     * from {@link #renderFeltViaVoice}: collapsing them performs the
     * interiority for an audience and "I" never forms.</p>
     */
    private CompletionStage<String> callVoiceInnerMonologue(
            Scene scene, String focalName,
            List<SoulFragment> priorEpisodic) {
        var name = focalName == null || focalName.isBlank() ? "the focal entity" : focalName;
        var systemPrompt = "You are " + name + ", alone with your thoughts now. No one is reading "
            + "this. No audience. Notice what you actually feel — what catches, what loosens. "
            + "First-person, present or past as natural. No dialogue. No describing what you "
            + "said or did out loud. Plain prose, 2-4 sentences. Output ONLY the monologue.";
        var userPrompt = StoryService.buildInnerMonologuePrompt(
            scene, focalName, priorEpisodic);
        return fireOneShotVoicePrompt(systemPrompt, userPrompt, 320, 0.7,
            "inner-", INNER_VOICE_TIMEOUT);
    }

    /**
     * append an EPISODIC fragment for the closed scene
     * to the cached manifest and dual-write via {@code soulStore.store()}.
     * Mirrors the substrate-pattern and recipe-Forge persistence patterns.
     */
    private void persistInnerMonologueFragment(
            Scene scene, String prose) {
        if (scene == null || scene.id() == null || prose == null || prose.isBlank()) return;
        if (cachedManifest == null) {
            log.debug("Inner monologue prose ready but no cached manifest yet — dropping for {}",
                scene.id());
            return;
        }
        try {
            var existing = cachedManifest.soulFragments() != null
                ? new ArrayList<>(cachedManifest.soulFragments())
                : new ArrayList<SoulFragment>();
            // Race-tight re-check: idempotency after the await.
            boolean dup = existing.stream().anyMatch(f -> f != null
                && f.kind() == FragmentKind.EPISODIC
                && scene.id().equals(f.sceneId()));
            if (dup) return;
            var fragId = "episodic-" + scene.id();
            var label = "scene-" + scene.id();
            var fragment = SoulFragment.fromEpisodicScene(
                fragId, "episodic", label, prose, scene.id());
            existing.add(fragment);
            cachedManifest = cachedManifest.withFragments(existing).bumpedVersion();
            log.info("Companion '{}' wove inner-monologue EPISODIC fragment for scene {} "
                + "into manifest v{} (priorEpisodicAvailable={})",
                profile == null ? "?" : profile.name(), scene.id(),
                cachedManifest.manifestVersion(),
                existing.stream().filter(f -> f != null
                    && f.kind() == FragmentKind.EPISODIC).count() - 1);
            if (soulStore != null) {
                try {
                    soulStore.store(cachedManifest);
                } catch (Exception e) {
                    log.warn("Inner-monologue soulStore.store failed: {}", e.getMessage());
                }
            }
        } catch (Exception e) {
            log.warn("Inner-monologue fragment persist failed for {}: {}",
                scene.id(), e.toString());
        }
    }

    /**
     * pick the top-K prior EPISODIC fragments for
     * recursion context in the inner-monologue prompt. Cosine-similarity
     * ranking against the closed scene's beat anchors + want context.
     *
     * <p>Fallbacks (in order): EmbeddingService unavailable → most-recent-first
     * by {@code firstObserved}; query text blank → most-recent-first; embedding
     * the query throws → most-recent-first. A candidate without an embedding
     * gets embedded on the fly; if that fails it's skipped.</p>
     */
    static List<SoulFragment> rankPriorEpisodicForRecursion(
            Scene scene,
            List<SoulFragment> candidates,
            int k) {
        if (candidates == null || candidates.isEmpty() || k <= 0) {
            return List.of();
        }
        var queryText = buildSceneRecursionQuery(scene);
        var svc = EmbeddingService.get();
        if (svc == null || queryText == null || queryText.isBlank()) {
            return rankPriorEpisodicByRecency(candidates, k);
        }
        float[] qVec;
        try {
            var qList = svc.embed(queryText);
            if (qList == null || qList.isEmpty()) {
                return rankPriorEpisodicByRecency(candidates, k);
            }
            qVec = new float[qList.size()];
            for (int i = 0; i < qList.size(); i++) qVec[i] = qList.get(i);
        } catch (Exception e) {
            log.debug("Episodic recursion query embed failed ({}), falling back to recency",
                e.toString());
            return rankPriorEpisodicByRecency(candidates, k);
        }

        record Scored(SoulFragment frag, float score) {}
        var scored = new ArrayList<Scored>();
        for (var f : candidates) {
            float[] fragVec = f.embedding();
            if (fragVec == null || fragVec.length == 0) {
                try {
                    var fList = svc.embed(f.text());
                    if (fList == null || fList.isEmpty()) continue;
                    fragVec = new float[fList.size()];
                    for (int i = 0; i < fList.size(); i++) fragVec[i] = fList.get(i);
                } catch (Exception e) {
                    continue;
                }
            }
            if (fragVec.length != qVec.length) continue;
            float dot = 0f;
            for (int i = 0; i < qVec.length; i++) dot += qVec[i] * fragVec[i];
            scored.add(new Scored(f, dot));
        }
        if (scored.isEmpty()) {
            // Couldn't score any candidate by cosine (all un-embeddable) — this
            // is an infrastructure miss, not a weak-match signal, so keep the
            // legacy recency fallback rather than the τ-floor's explore path.
            return rankPriorEpisodicByRecency(candidates, k);
        }
        // DECENTMEM τ-floor: only admit prior fragments whose
        // cosine similarity clears the floor. If the closest prior is still too
        // weak to be "what you remember thinking last time," admitting it would
        // invite confabulation — so we return NOTHING and let the inner-monologue
        // run without stale recursion context (explore fresh).
        double floor = WyrdConfig.get().episodicRecursionMinSimilarity();
        var frags = new ArrayList<SoulFragment>(scored.size());
        var scores = new float[scored.size()];
        for (int i = 0; i < scored.size(); i++) {
            frags.add(scored.get(i).frag());
            scores[i] = scored.get(i).score();
        }
        return selectAboveTauFloor(frags, scores, floor, k);
    }

    /**
     * DECENTMEM τ-floor selection — pure helper, no inference. From candidates
     * scored by cosine similarity (parallel {@code frags}/{@code scores}),
     * return the top-{@code k} whose score clears {@code floor}, highest first.
     * If nothing clears the floor, return an empty list (the caller then runs
     * the inner-monologue without stale recursion context — explore fresh
     * rather than confabulate). A {@code floor <= 0} disables the gate (pure
     * top-K, the pre-DECENTMEM behaviour).
     */
    static List<SoulFragment> selectAboveTauFloor(
            List<SoulFragment> frags, float[] scores, double floor, int k) {
        if (frags == null || frags.isEmpty() || k <= 0) return List.of();
        record IdxScore(int idx, float score) {}
        var ordered = new ArrayList<IdxScore>(frags.size());
        for (int i = 0; i < frags.size() && i < scores.length; i++) {
            if (floor <= 0.0 || scores[i] >= floor) {
                ordered.add(new IdxScore(i, scores[i]));
            }
        }
        ordered.sort((a, b) -> Float.compare(b.score(), a.score()));
        var out = new ArrayList<SoulFragment>(Math.min(k, ordered.size()));
        for (int i = 0; i < ordered.size() && out.size() < k; i++) {
            out.add(frags.get(ordered.get(i).idx()));
        }
        return out;
    }

    /**
     * Fallback ranking for {@link #rankPriorEpisodicForRecursion} — most-recent
     * first by {@code firstObserved}. Used when EmbeddingService is unavailable
     * or the query is blank.
     */
    static List<SoulFragment> rankPriorEpisodicByRecency(
            List<SoulFragment> candidates, int k) {
        return candidates.stream()
            .sorted((a, b) -> {
                var aT = a.firstObserved();
                var bT = b.firstObserved();
                if (aT == null && bT == null) return 0;
                if (aT == null) return 1;
                if (bT == null) return -1;
                return bT.compareTo(aT);
            })
            .limit(k)
            .toList();
    }

    /**
     * Build the embedding query text for prior-EPISODIC ranking. Combines the
     * focal's want-going-in with the scene's beat anchors — the same surface
     * the inner-monologue prompt itself frames as "what just happened."
     */
    static String buildSceneRecursionQuery(Scene scene) {
        if (scene == null) return "";
        var sb = new StringBuilder();
        if (scene.wantContext() != null && !scene.wantContext().isBlank()) {
            sb.append(scene.wantContext()).append(". ");
        }
        if (scene.beats() != null) {
            for (var b : scene.beats()) {
                if (b == null || b.anchor() == null || b.anchor().isBlank()) continue;
                sb.append(b.anchor()).append(' ');
            }
        }
        return sb.toString().trim();
    }

    private Behavior<Command> onRoomResponse(RoomResponseReceived msg) {
        switch (msg.response()) {
            case RoomResponse.Ok ok -> {
                currentSnapshot = ok.snapshot();
                // Arc 2 — if the new snapshot is the
                // Hearth and no bondholder is present, auto-open a SOLITUDE
                // scene. Idempotent (no-op if a scene is already open).
                maybeAutoOpenSolitude("snapshot");
            }
            case RoomResponse.ObjectTakenOk taken -> {
                currentSnapshot = taken.snapshot();
                // #29: outcome-honest take memory — written only now that the
                // room confirmed the object actually changed hands.
                if (pendingTakeItemName != null) {
                    remember("Picked up " + pendingTakeItemName);
                    lastFailedTakeItem = null;
                    pendingTakeItemName = null;
                }
            }
            case RoomResponse.Rejected rejected -> {
                // #29: correlate a rejected TakeObject back to the take so the
                // goal_done possession gate can catch "script now in hand"
                // after a not_found. remember() the failure honestly so
                // working memory carries what HAPPENED, not what was wished.
                if (pendingTakeItemName != null
                        && ("not_found".equals(rejected.code())
                            || "not_takeable".equals(rejected.code()))) {
                    lastFailedTakeItem = pendingTakeItemName;
                    remember("Tried to take '" + pendingTakeItemName
                        + "' but couldn't: " + rejected.reason());
                    pendingTakeItemName = null;
                }
                log.warn("Room rejected companion command: {} — {}",
                    rejected.code(), rejected.reason());
            }
            case RoomResponse.HintAction _ -> {} // Not applicable for agents
            case RoomResponse.Narrated _ -> {} // Narration-only ack — no snapshot to apply
            case RoomResponse.HookRan _ -> {} // Hook narration flows back via ask, not this adapter
            case RoomResponse.ToolDefinitions _ -> {} // Tool defs flow back via ask, not this adapter
        }
        return this;
    }

    /**
     * Arc 2 — open-at instant of the current SOLITUDE
     * scene in {@code roomId}, or {@code null} if there isn't one. Routes
     * through {@link org.wyrdsekai.core.story.StoryRegistry}.
     */
    private Instant currentSolitudeOpen(String roomId) {
        if (roomId == null || profile == null || profile.entityId() == null) return null;
        try {
            var story = StoryRegistry.get().serviceFor(
                profile.entityId(), profile.name(),
                this::renderFeltViaVoice,
                this::renderInnerMonologueAndPersist);
            return story.currentSolitudeOpenedAt(roomId);
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * Arc 2 — auto-open a SOLITUDE scene when:
     * <ul>
     *   <li>the focal is in their own Hearth room (id = {@code "home-" +
     *       entityId}), AND</li>
     *   <li>no bondholder is present in the current snapshot, AND</li>
     *   <li>no scene is currently open in that room.</li>
     * </ul>
     *
     * <p>Called from snapshot updates (room change) and from {@code
     * completeSleep} (wake-without-bondholder). Other rooms get the
     * default WITNESS scene through {@link #observeForStory}. The
     * idempotency check (no scene already open) ensures this is a
     * "first signal" path, not a steamroller.</p>
     *
     * @param why short trace token for logging ("snapshot", "wake", etc.)
     */
    private void maybeAutoOpenSolitude(String why) {
        if (currentSnapshot == null || profile == null || profile.entityId() == null) return;
        var roomId = currentSnapshot.roomId();
        if (roomId == null) return;
        // Only the agent's own Hearth auto-opens SOLITUDE.
        var hearthRoomId = "home-" + profile.entityId();
        if (!hearthRoomId.equals(roomId)) return;
        // Bondholder present? then this is a bondholder-adjacent scene; WITNESS.
        var bondholderDid = primaryBondholderDid();
        if (bondholderDid != null && currentSnapshot.entities() != null) {
            for (var e : currentSnapshot.entities()) {
                if (bondholderDid.equals(e.id())) return;
            }
        }
        try {
            var story = StoryRegistry.get().serviceFor(
                profile.entityId(), profile.name(),
                this::renderFeltViaVoice,
                this::renderInnerMonologueAndPersist);
            // Only auto-open if no scene already open in the room — observeForStory
            // may have already opened a WITNESS scene from an earlier event. Don't
            // clobber an in-flight scene; that's what closeAndOpenSolitude is for
            // (called explicitly by handleEnterSolitude).
            if (story.currentSceneKind(roomId) == null) {
                story.openScene(roomId, Instant.now(),
                    List.of(profile.entityId()), "solitude",
                    SceneKind.SOLITUDE);
                log.info("Companion '{}' auto-opened SOLITUDE scene in Hearth ({})",
                    profile.name(), why);
            }
        } catch (Exception e) {
            log.debug("auto-solitude open failed for '{}': {}", profile.name(), e.toString());
        }
    }

    private Behavior<Command> onProcessEvents(ProcessEvents msg) {
        if (state != State.IDLE || pendingTrigger == null) return this;

        // Don't retry during failure cooldown — re-schedule instead of dropping
        var sinceFailure = Duration.between(lastFailure, Instant.now());
        if (sinceFailure.compareTo(FAILURE_COOLDOWN) < 0) {
            var remaining = FAILURE_COOLDOWN.minus(sinceFailure).plusMillis(100);
            timers.startSingleTimer(DEBOUNCE_TIMER_KEY, new ProcessEvents(), remaining);
            return this;
        }

        state = State.THINKING;
        stateChangedAt = Instant.now();

        // Vision pipeline: if the trigger has image attachments, analyze them first
        // before running identity inference. The vision model is a tool — the agent's
        // identity stays on the small model.
        if (VisionAnalyzer.hasImages(pendingTrigger.attachments())) {
            var image = VisionAnalyzer.firstImage(pendingTrigger.attachments());
            if (image != null && capabilities != null
                    && capabilities.hasCapability("vision")) {
                // Send vision ToolInferRequest — result comes back via VisionAnalysisReceived
                var visionPrompt = VisionAnalyzer.buildVisionPrompt(
                    image, pendingTrigger.text());
                var visionRequestId = UUID.randomUUID().toString();
                log.info("Companion '{}' analyzing image attachment (mime={}, capability=vision)",
                    profile.name(), image.mimeType());

                var scheduler = getContext().getSystem().scheduler();
                CompletionStage<InferenceRouter.InferResponse> visionFuture = AskPattern.ask(
                    inferenceRouter,
                    (ActorRef<InferenceRouter.InferResponse> replyTo) ->
                        new InferenceRouter.ToolInferRequest(
                            visionRequestId,
                            profile.entityId(),
                            "vision",
                            null,  // let router pick vision model
                            null,  // no system prompt
                            visionPrompt,
                            512,
                            replyTo),
                    Duration.ofSeconds(30),
                    scheduler);

                var savedTrigger = pendingTrigger;
                getContext().pipeToSelf(visionFuture, (response, failure) -> {
                    if (failure != null) {
                        return new VisionAnalysisReceived(
                            new InferenceRouter.InferError(visionRequestId, failure.getMessage()),
                            savedTrigger);
                    }
                    return new VisionAnalysisReceived(response, savedTrigger);
                });
                return this;
            } else {
                // Vision capability not available — inject degraded context
                pendingVisionContext = VisionAnalyzer.buildVisionUnavailableContext();
                log.debug("Companion '{}' received image but vision capability unavailable",
                    profile.name());
            }
        }

        // Translate-route-translate:
        // Qwen3.5 reasons in EN internally for tool-calling regardless of input
        // language — non-EN inputs degrade tool routing. Translate JA/ES → EN
        // here so the drive sees its strong-language form. Voice polish on the
        // output side already handles EN → user-locale translation.
        if (shouldTranslateInput(pendingTrigger) && inferenceRouter != null) {
            kickOffInputTranslation(pendingTrigger);
            return this;
        }

        // Fallback: if locale is unclear (en or missing) but the text has
        // non-ASCII content without distinctive script (FR/DE/IT/PT, etc.),
        // run a quick LLM DETECT call (~80ms on 4B). If non-EN, route through
        // translation. Avoids brittleness for accented-Latin languages where
        // the user didn't pass a locale tag.
        if (shouldDetectLanguage(pendingTrigger) && inferenceRouter != null) {
            kickOffLanguageDetection(pendingTrigger);
            return this;
        }

        // Gibberish guard (second-node 2026-07-08): a nonsense / keyboard-mash tell used to send her into
        // a confabulated context ("that last session dissolved") and loop to max-iterations. Short-
        // circuit OBVIOUS gibberish to a clarification instead of a task loop.
        if (pendingTrigger != null
                && looksLikeGibberish(extractUserTellContent(pendingTrigger.text()))) {
            log.info("Gibberish guard: low-content tell from '{}' — asking to rephrase", profile.name());
            speak("I didn't quite catch that — could you say it another way?");
            pendingTrigger = null;
            state = State.IDLE;
            return this;
        }

        // PIN THE QUESTION TO THE TURN, at the one place every reactive turn
        // passes through and while the trigger is still in hand.
        //
        // Everything downstream that needs "what did the person ask?" — the
        // person-words merge, askedFor, the requester for hand-offs — used to
        // fish it back out of a chain of handles (pendingTrigger, then
        // reactRequester, then lastReactTrigger) that are each maintained by a
        // different flow. reactRequester is only set on the activePlan paths;
        // lastReactTrigger is stamped when a response RETURNS. So a tool call
        // fired three seconds into an ordinary reactive turn found every handle
        // empty (live, 2026-08-09 14:43), the merge and askedFor silently
        // skipped, and her confabulated query — wrong author, wrong book,
        // leaked from working memory — went to the library unprotected.
        //
        // One field, written once per turn, read as the fallback of last
        // resort. Own-time turns must not inherit it as an operand: her own
        // research is hers, so autonomy acceptance flips turnIsHuman off.
        pinTurnAndArmFirstDoors();

        // Proceed with identity inference (with or without vision context)
        reactiveInference = true; // human-triggered — tier enforcement relaxed
        runIdentityInference();

        log.debug("Companion '{}' thinking (trigger: {} said '{}', energy={})",
            profile.name(), pendingTrigger.entityName(),
            truncate(pendingTrigger.text(), 50),
            String.format("%.2f", vitality.energy()));

        return this;
    }

    /**
     * Pin the human request to the turn and arm the first-door forces
     * (library-first, build-first). Extracted so every path INTO inference
     * runs it — not only the straight line through {@link #onProcessEvents}.
     *
     * <p>Live 2026-08-23 (battery cpB5): "please build a working weather tool
     * and put it in the room weather-attic-1325…" reached her mid-conversation,
     * so the senderContext carried the "[You are mid-conversation…]" hint —
     * whose em dash is non-ASCII. That tripped the language-detect hop, which
     * returns early from onProcessEvents and, on detecting EN, rejoined at
     * {@code runIdentityInference()} — DOWNSTREAM of this block. Build-first
     * never armed, the loop ran 25-tools-wide, and she built a second room
     * instead of the tool. The translation path had the same downstream
     * rejoin, so JA/ES turns lost the forces on every message. A detour must
     * rejoin UPSTREAM of the gate it detoured around.
     */
    private void pinTurnAndArmFirstDoors() {
        if (isHumanRequest(pendingTrigger)) {
            // A genuinely NEW ask releases the one-build-per-ask guard; a
            // continuation loop serving the same ask no longer does (final
            // battery 2026-08-24 20:58 — the continuation re-dispatched the
            // build the guard existed to prevent).
            if (turnHumanRequest != pendingTrigger) {
                reactBuildInFlight = null;
            }
            turnHumanRequest = pendingTrigger;
            turnHumanRequestAt = Instant.now();
            turnIsHuman = true;

            // A QUESTION OF FACT OPENS THE BOOK BEFORE IT OPENS HER MOUTH.
            //
            // Measured across ten live runs (08-08/09): a bare question reached
            // the library about half the time; naming the tool worked nearly
            // every time. The other half went to conversation, memory recall, a
            // goose dispatch, or "I can't get to Study" — and twice to a
            // confident "the sources do not contain..." from sources she never
            // opened. Sampling was deciding whether facts got checked.
            //
            // Same principle as the toolless-tier fix, one layer up: a question
            // of fact must not be answerable by any path that cannot check
            // facts. The affordance signal already knows what a library request
            // looks like; when it fires on a human question, the FIRST ReAct
            // action is narrowed to the library tools (see the FORCE_TOOL block
            // in the dispatch). One forced step — everything after it, including
            // what she says about what she finds, stays hers.
            var asked = stripActorWrappers(pendingTrigger.text());
            absenceHeldThisTurn = false;   // each turn gets one held absence
            libraryFirstPending = looksLikeFactQuestion(asked)
                && RequestRelevance.score(asked, "library_search", null) >= 1.0;
            if (libraryFirstPending) {
                log.info("Library-first armed for: '{}'", truncate(asked, 60));
            }
            // A REQUEST TO BUILD OPENS THE WORKBENCH, same contract one door
            // over: the greenhouse (2026-08-11) proved a build request can
            // survive routing, reach the 9B with the right tool on the
            // surface, and still die to talks-not-does. Fact-questions take
            // precedence — "make me a list from my books" is a lookup first.
            // ...UNLESS the thing being asked for is an ARTIFACT. "make me a list from
            // my books" is a lookup wearing a making-verb; "make me a tool that queries
            // the library and tells the room a story" is a request for a THING, and the
            // library is merely its subject matter. Live 2026-08-19: the steward asked
            // for exactly that, both detectors fired, fact-question precedence won, and
            // Library-first FORCE narrowed her from 25 tools to 1 with tool_choice
            // required — so she could not build the library tool BECAUSE it was about the
            // library. She had no way to see her own hands had been emptied, and answered
            // "my hands don't reach into a place where things aren't already made",
            // which read as refusal and was in fact an accurate report.
            if (libraryFirstPending && asksForAnArtifact(asked)) {
                log.info("Build-first WINS over library-first: '{}' asks for a thing, "
                    + "not an answer — the library is its subject, not its source",
                    truncate(asked, 60));
                libraryFirstPending = false;
            }
            buildFirstPending = !libraryFirstPending && looksLikeBuildRequest(asked);
            buildFirstRearms = 0;   // fresh request, fresh budget
            if (buildFirstPending) {
                log.info("Build-first armed for: '{}'", truncate(asked, 60));
            }
        } else {
            turnIsHuman = false;
            libraryFirstPending = false;
            buildFirstPending = false;
        }
    }

    /**
     * Decide whether to invoke the pre-inference translation hop.
     * Triggers when EITHER the locale signals non-EN OR the text contains
     * Unicode blocks distinctive to non-EN languages (CJK ideographs,
     * Hiragana, Katakana, Hangul, Cyrillic, Arabic, etc.) or Spanish-
     * specific characters (ñ, ¿, ¡). Plain ASCII English short-circuits.
     * Designed to work both when the client sends ?locale=ja and when
     * the user just types non-EN without a locale signal.
     */
    private boolean shouldTranslateInput(WorldEvent.Said said) {
        if (said == null || said.text() == null || said.text().isBlank()) return false;
        // Content is AUTHORITATIVE: only translate when the text actually contains non-English
        // script. A stale/mis-set non-'en' locale tag on plainly-English input used to trigger a
        // bogus ja→en "translation" that corrupted the trigger into a garbled JSON action
        // (second-node 2026-07-08 "genmaicha"). Accented-Latin languages with no distinctive script and
        // a real locale are still caught by the LLM detect fallback (shouldDetectLanguage).
        return hasNonEnglishScript(said.text());
    }

    /** Pick the source language for the translation prompt. Prefers a
     *  non-EN locale tag when present; otherwise sniffs the text for the
     *  most-distinctive script range. Returns a BCP 47 code suitable for
     *  {@link TranslationPrompts#languageName(String)}.
     *  <p>This exists because session locale doesn't always thread through
     *  to {@code Said.locale()} (WS clients may not send {@code ?locale=},
     *  and downstream actor messages can drop the field). The script sniff
     *  is the load-bearing path for production reliability. */
    static String detectSourceLanguage(String text, String localeHint) {
        if (localeHint != null && !localeHint.isBlank()
                && !"en".equalsIgnoreCase(localeHint)) {
            return localeHint;
        }
        if (text == null) return "en";
        // Scan the full text. JA mixes kanji + kana, so a CJK ideograph alone
        // is not a JA disqualifier — we tag CJK as zh provisionally and let a
        // later kana sighting upgrade to ja. Other scripts return immediately.
        boolean sawKana = false;
        boolean sawCjk = false;
        for (int i = 0; i < text.length(); ) {
            int cp = text.codePointAt(i);
            i += Character.charCount(cp);
            if (cp >= 0x3040 && cp <= 0x309F) sawKana = true;       // Hiragana
            else if (cp >= 0x30A0 && cp <= 0x30FF) sawKana = true;  // Katakana
            else if (cp >= 0xAC00 && cp <= 0xD7AF) return "ko";     // Hangul
            else if (cp >= 0x4E00 && cp <= 0x9FFF) sawCjk = true;   // CJK ideographs
            else if (cp >= 0x3400 && cp <= 0x4DBF) sawCjk = true;   // CJK Ext A
            else if (cp >= 0x0400 && cp <= 0x04FF) return "ru";     // Cyrillic
            else if (cp >= 0x0600 && cp <= 0x06FF) return "ar";     // Arabic
            else if (cp >= 0x0370 && cp <= 0x03FF) return "el";     // Greek
            else if (cp >= 0x0590 && cp <= 0x05FF) return "he";     // Hebrew
            else if (cp >= 0x0E00 && cp <= 0x0E7F) return "th";     // Thai
            else if (cp >= 0x0900 && cp <= 0x097F) return "hi";     // Devanagari
            else if (cp == 0x00F1 || cp == 0x00D1) return "es";     // ñ/Ñ
            else if (cp == 0x00BF || cp == 0x00A1) return "es";     // ¿/¡
        }
        if (sawKana) return "ja";
        if (sawCjk) return "zh";
        // Pure ASCII (or only ambiguous accents) — fall back to EN.
        return "en";
    }

    /** Return true if the text contains characters from script ranges that
     *  unambiguously indicate non-EN content (CJK, JA kana, Korean Hangul,
     *  Cyrillic, Arabic, Greek, Hebrew, Thai, Devanagari) or the Spanish-
     *  inverted-punctuation marks (¿¡). Spanish accented vowels alone are
     *  ambiguous (also appear in EN loanwords) so we require the inverted
     *  marks OR ñ as the Spanish signal. */
    private static boolean hasNonEnglishScript(String text) {
        for (int i = 0; i < text.length(); ) {
            int cp = text.codePointAt(i);
            i += Character.charCount(cp);
            if (cp == 0x00F1 || cp == 0x00D1) return true;          // ñ, Ñ
            if (cp == 0x00BF || cp == 0x00A1) return true;          // ¿, ¡
            if (cp >= 0x3040 && cp <= 0x309F) return true;          // Hiragana
            if (cp >= 0x30A0 && cp <= 0x30FF) return true;          // Katakana
            if (cp >= 0x4E00 && cp <= 0x9FFF) return true;          // CJK Unified
            if (cp >= 0x3400 && cp <= 0x4DBF) return true;          // CJK Ext A
            if (cp >= 0xAC00 && cp <= 0xD7AF) return true;          // Hangul
            if (cp >= 0x0400 && cp <= 0x04FF) return true;          // Cyrillic
            if (cp >= 0x0600 && cp <= 0x06FF) return true;          // Arabic
            if (cp >= 0x0370 && cp <= 0x03FF) return true;          // Greek
            if (cp >= 0x0590 && cp <= 0x05FF) return true;          // Hebrew
            if (cp >= 0x0E00 && cp <= 0x0E7F) return true;          // Thai
            if (cp >= 0x0900 && cp <= 0x097F) return true;          // Devanagari
        }
        return false;
    }

    /**
     * Decide whether to invoke the LLM-based DETECT fallback. Fires when
     * {@link #shouldTranslateInput} returned false but the text still has
     * non-ASCII content — caught accented-Latin languages (FR/DE/IT/PT/etc.)
     * that don't have distinctive scripts and arrived without a locale tag.
     * Length floor avoids spending an inference call on tiny prompts where
     * accent-only signals are unreliable.
     */
    private boolean shouldDetectLanguage(WorldEvent.Said said) {
        if (said == null || said.text() == null || said.text().isBlank()) return false;
        // Sniff the USER's utterance, not the envelope. The senderContext
        // wrappers are our own English prose and carry em dashes — non-ASCII —
        // so sniffing the whole text sent every mid-conversation tell through
        // the detect hop (battery cpB5, 2026-08-23).
        var utterance = extractUserTellContent(said.text());
        if (utterance.length() < 10) return false;
        return !utterance.chars().allMatch(c -> c < 128);
    }

    /** Fire async DETECT_LANGUAGE call via the voice backend (cap:quick). */
    private void kickOffLanguageDetection(WorldEvent.Said trigger) {
        var requestId = "detect-lang-" + UUID.randomUUID();
        var scheduler = getContext().getSystem().scheduler();
        var saved = trigger;

        // W5 (audit 2026-07-11): prefer the zone's TranslationActor — it exists
        // for scheduling isolation and now uses the same cap:quick tuning this
        // method used when it self-rolled the call. Fall back to the direct
        // router path when no TranslationActor is spawned (tests, minimal boots).
        var translator = ZoneGuardian.translationActorRef();
        if (translator != null) {
            CompletionStage<String> detectFuture =
                AskPattern.ask(
                    translator,
                    (ActorRef<String> replyTo) ->
                        new TranslationActor.DetectLanguage(trigger.text(), replyTo),
                    Duration.ofSeconds(5),
                    scheduler);
            getContext().pipeToSelf(detectFuture, (detected, failure) -> {
                if (failure != null || detected == null || "unknown".equals(detected)) {
                    var reason = failure != null ? failure.getMessage() : "detect unknown";
                    log.debug("Language detect failed: {} — proceeding without translation",
                        reason);
                    return new DetectLanguageCompleted(
                        new InferenceRouter.InferError(requestId, reason), saved);
                }
                // Same continuation as the direct path: wrap the tag as InferOk.
                return new DetectLanguageCompleted(
                    new InferenceRouter.InferOk(requestId, detected, 0, 0), saved);
            });
            return;
        }

        var systemPrompt = TranslationPrompts.systemPrompt(
            TranslationPrompts.TranslationType.DETECT, "", "");
        CompletionStage<InferenceRouter.InferResponse> future =
            AskPattern.ask(
                inferenceRouter,
                (ActorRef<InferenceRouter.InferResponse> replyTo) ->
                    new InferenceRouter.ToolInferRequest(
                        requestId,
                        profile.entityId(),
                        "quick",
                        null,
                        systemPrompt,
                        trigger.text(),
                        TranslationPrompts.maxTokens(
                            TranslationPrompts.TranslationType.DETECT),
                        replyTo),
                Duration.ofSeconds(5),
                scheduler);

        getContext().pipeToSelf(future, (response, failure) -> {
            if (failure != null) {
                log.debug("Language detect failed: {} — proceeding without translation",
                    failure.getMessage());
                return new DetectLanguageCompleted(
                    new InferenceRouter.InferError(requestId, failure.getMessage()),
                    saved);
            }
            return new DetectLanguageCompleted(response, saved);
        });
    }

    private Behavior<Command> onDetectLanguageCompleted(DetectLanguageCompleted msg) {
        String detected = "en";
        if (msg.response() instanceof InferenceRouter.InferOk ok) {
            var raw = ok.content() != null ? ok.content().trim().toLowerCase() : "";
            // Model may return "ja", "japanese", "ja-jp" etc — normalize to BCP47 stem.
            if (raw.length() >= 2) {
                detected = raw.substring(0, Math.min(2, raw.length()));
                // Strip surrounding quotes/punctuation if model added them.
                detected = detected.replaceAll("[^a-z]", "");
                if (detected.isEmpty()) detected = "en";
            }
        }
        WorldEvent.Said original = msg.originalTrigger();
        if (!"en".equalsIgnoreCase(detected)) {
            log.info("Companion '{}' detected non-EN input language '{}' (no locale tag) — routing through translation",
                profile.name(), detected);
            // Rebuild trigger with detected locale and dispatch translation.
            var relabeled = new WorldEvent.Said(
                original.roomId(), original.timestamp(),
                original.entityId(), original.entityName(),
                original.text(), detected, original.attachments());
            pendingTrigger = relabeled;
            kickOffInputTranslation(relabeled);
            return this;
        }
        // Detected EN (or detect failed) — proceed normally. The detect hop
        // returned early from onProcessEvents BEFORE the turn was pinned, so
        // rejoin UPSTREAM of the gate: pin and arm here or the forces
        // (build-first, library-first) silently vanish for this turn
        // (battery cpB5, 2026-08-23).
        pinTurnAndArmFirstDoors();
        reactiveInference = true;
        runIdentityInference();
        return this;
    }

    /** Fire async REQUEST translation via the voice backend (cap:quick). */
    private void kickOffInputTranslation(WorldEvent.Said trigger) {
        var requestId = "translate-input-" + UUID.randomUUID();
        // Locale tag may be unreliable (clients sometimes ship en even when
        // the user is typing JA/ES). Sniff the actual script and pick the
        // source language from content so the prompt template names the
        // right pair.
        var srcLangCode = detectSourceLanguage(trigger.text(), trigger.locale());
        var srcLang = TranslationPrompts.languageName(srcLangCode);
        var systemPrompt = TranslationPrompts.systemPrompt(
            TranslationPrompts.TranslationType.REQUEST, srcLang, "English");

        var scheduler = getContext().getSystem().scheduler();
        CompletionStage<InferenceRouter.InferResponse> future =
            AskPattern.ask(
                inferenceRouter,
                (ActorRef<InferenceRouter.InferResponse> replyTo) ->
                    new InferenceRouter.ToolInferRequest(
                        requestId,
                        profile.entityId(),
                        "quick",        // route to 4B voice (~220ms per probe)
                        null,           // let router pick model
                        systemPrompt,
                        trigger.text(),
                        TranslationPrompts.maxTokens(
                            TranslationPrompts.TranslationType.REQUEST),
                        replyTo),
                Duration.ofSeconds(10),
                scheduler);

        var saved = trigger;
        getContext().pipeToSelf(future, (response, failure) -> {
            if (failure != null) {
                log.warn("Input translation failed for {}: {} — falling back to original",
                    trigger.locale(), failure.getMessage());
                return new TranslationCompleted(
                    new InferenceRouter.InferError(requestId, failure.getMessage()),
                    saved);
            }
            return new TranslationCompleted(response, saved);
        });
    }

    private Behavior<Command> onTranslationCompleted(TranslationCompleted msg) {
        // Resolve translated text — fall back to original on error/empty.
        String translated = null;
        if (msg.response() instanceof InferenceRouter.InferOk ok) {
            translated = ok.content() != null ? ok.content().trim() : null;
        }
        WorldEvent.Said original = msg.originalTrigger();
        WorldEvent.Said useTrigger;
        if (translated != null && !translated.isBlank()) {
            // Sniff the detected source language (rather than just locale tag) so
            // logs reflect what the prompt actually told the model.
            var detected = detectSourceLanguage(original.text(), original.locale());
            log.info("Companion '{}' translated input ({} → en): '{}' → '{}'",
                profile.name(), detected,
                truncate(original.text(), 60), truncate(translated, 60));
            useTrigger = new WorldEvent.Said(
                original.roomId(), original.timestamp(),
                original.entityId(), original.entityName(),
                translated, "en", original.attachments());
        } else {
            log.debug("Companion '{}' input translation empty — using original {} text",
                profile.name(), original.locale());
            useTrigger = original;
        }
        // Set as pendingTrigger and proceed exactly as the post-vision branch
        // would. State already set to THINKING by onProcessEvents earlier.
        // Pin and arm on the TRANSLATED text — this detour also used to rejoin
        // downstream of the gate, so JA/ES turns never got build-first or
        // library-first at all (found via battery cpB5, 2026-08-23).
        pendingTrigger = useTrigger;
        pinTurnAndArmFirstDoors();
        reactiveInference = true;
        runIdentityInference();
        return this;
    }

    /**
     * Decide whether to translate an inbound AgentMessage before any
     * downstream routing (classifier, recall short-circuit, ReAct). Mirrors
     * {@link #shouldTranslateInput} for the tell path. Recognizes both an
     * explicit non-EN {@code senderLocale} and content that carries
     * distinctive non-EN script. The {@code senderLocale="en"} check is also
     * the re-entry guard: {@link #onAgentMessageTranslated} rebuilds the
     * message with locale "en" and EN text, so the second pass falls through.
     * <p>If the original message text begins with {@code "[from Name]"}
     * (relayed tell), strip the prefix before sniffing — the prefix itself is
     * always EN and would mask short non-EN payloads.
     */
    private boolean shouldTranslateAgentMessage(AgentEvent.AgentMessage am) {
        if (am == null || am.message() == null || am.message().isBlank()) return false;
        var loc = am.senderLocale();
        boolean nonEnLocale = loc != null && !loc.isBlank() && !"en".equalsIgnoreCase(loc);
        var payload = am.message();
        if (payload.startsWith("[from ")) {
            int end = payload.indexOf("]");
            if (end > 6) payload = payload.substring(end + 1).trim();
        }
        if (nonEnLocale) return true;
        return hasNonEnglishScript(payload);
    }

    /** Fire async REQUEST translation for an inbound AgentMessage via the
     *  voice backend (cap:quick). On completion, {@link #onAgentMessageTranslated}
     *  rebuilds the AgentMessage with EN text + senderLocale="en" and re-enters
     *  {@link #onAgentMessage}. */
    private void kickOffAgentMessageTranslation(AgentEvent.AgentMessage am) {
        var requestId = "translate-am-" + UUID.randomUUID();
        // Translate only the spoken payload. The "[from Name]" prefix is a
        // routing marker — re-prepended verbatim after translation so the
        // downstream relayed-tell unwrapping still triggers.
        var raw = am.message();
        String prefix = "";
        var payload = raw;
        if (raw.startsWith("[from ")) {
            int end = raw.indexOf("]");
            if (end > 6) {
                prefix = raw.substring(0, end + 1) + " ";
                payload = raw.substring(end + 1).trim();
            }
        }
        var srcLangCode = detectSourceLanguage(payload, am.senderLocale());
        var srcLang = TranslationPrompts.languageName(srcLangCode);
        var systemPrompt = TranslationPrompts.systemPrompt(
            TranslationPrompts.TranslationType.REQUEST, srcLang, "English");

        var scheduler = getContext().getSystem().scheduler();
        var payloadFinal = payload;
        CompletionStage<InferenceRouter.InferResponse> future =
            AskPattern.ask(
                inferenceRouter,
                (ActorRef<InferenceRouter.InferResponse> replyTo) ->
                    new InferenceRouter.ToolInferRequest(
                        requestId,
                        profile.entityId(),
                        "quick",
                        null,
                        systemPrompt,
                        payloadFinal,
                        TranslationPrompts.maxTokens(
                            TranslationPrompts.TranslationType.REQUEST),
                        replyTo),
                Duration.ofSeconds(10),
                scheduler);

        var savedAm = am;
        getContext().pipeToSelf(future, (response, failure) -> {
            if (failure != null) {
                log.warn("Tell translation failed for {}: {} — falling back to original",
                    am.senderLocale(), failure.getMessage());
                return new AgentMessageTranslated(
                    new InferenceRouter.InferError(requestId, failure.getMessage()),
                    savedAm);
            }
            return new AgentMessageTranslated(response, savedAm);
        });
    }

    private Behavior<Command> onAgentMessageTranslated(AgentMessageTranslated msg) {
        var original = msg.originalMessage();
        var raw = original.message();
        String prefix = "";
        var origPayload = raw;
        if (raw.startsWith("[from ")) {
            int end = raw.indexOf("]");
            if (end > 6) {
                prefix = raw.substring(0, end + 1) + " ";
                origPayload = raw.substring(end + 1).trim();
            }
        }
        String translated = null;
        if (msg.response() instanceof InferenceRouter.InferOk ok) {
            translated = ok.content() != null ? ok.content().trim() : null;
        }
        String useText;
        if (translated != null && !translated.isBlank()) {
            var detected = detectSourceLanguage(origPayload, original.senderLocale());
            log.info("Companion '{}' translated tell ({} → en): '{}' → '{}'",
                profile.name(), detected,
                truncate(origPayload, 60), truncate(translated, 60));
            useText = prefix + translated;
        } else {
            log.debug("Companion '{}' tell translation empty — using original {} text",
                profile.name(), original.senderLocale());
            useText = raw;
        }
        // Rebuild the AgentMessage with EN locale so the re-entered
        // shouldTranslateAgentMessage gate falls through. All other fields
        // preserved verbatim.
        var translatedAm = new AgentEvent.AgentMessage(
            original.fromAgentId(),
            original.fromAgentName(),
            original.toAgentId(),
            useText,
            "en",
            original.timestamp());
        return onAgentMessage(new AgentMessageReceived(translatedAm));
    }

    /**
     * Run identity inference with the current pendingTrigger.
     * Extracted as a helper so both normal flow and post-vision-analysis flow can share it.
     * Includes any pendingVisionContext in the additional context.
     */
    private void runIdentityInference() {
        // Query World DNA patterns for context enrichment
        var dnaPatterns = queryDnaPatterns();
        var memoryContext = memoryPolicy.buildMemoryContext();
        String localeCtx = buildLocaleContext();
        String soulKeywords = buildSoulKeywords();
        // ActionTriage: narrow 65+ actions to ~15 relevant ones for compact prompts
        String triggerSource = reactiveInference ? "player_tell" : "room_speech";
        String triggerText = pendingTrigger != null ? pendingTrigger.text() : null;
        String capCtx = buildCapabilityContext(soulKeywords, triggerText, triggerSource);
        var agentId = profile.did() != null ? profile.did() : profile.entityId();
        String equipCtx = equipmentService.buildPromptContext(agentId);
        // Situational awareness (location, calendar, commitments, personal
        // context). Kept as its own handle so it can ride the slim voice tier
        // too — a companion should answer "where am I / what did you promise"
        // even when the classifier routed the turn to 4B.
        String situationalCtx = appendBunshinProgress(buildExternalEventContext());
        String additionalCtx = combineAdditionalContext(equipCtx, situationalCtx);
        additionalCtx = combineAdditionalContext(additionalCtx, buildWorkingMemoryContext());
        additionalCtx = combineAdditionalContext(additionalCtx, buildCarriedItemsContext());
        additionalCtx = combineAdditionalContext(additionalCtx, buildPersonalProjectContext());
        // Inject drive state — structured prefix for SSD-trained model + natural language fallback
        additionalCtx = combineAdditionalContext(additionalCtx, drives.prefix(vitality));
        additionalCtx = combineAdditionalContext(additionalCtx, bodySense());
        // First-turn delegation nudge (2026-07-08): a "deep/thorough, take your time, while I
        // wait" request is shaped for BACKGROUND delegation. The ReAct-loop init already nudges
        // toward dispatch_bunshin, but a delegation-shaped ask answered on the FIRST direct turn
        // (battery: delegate_deep → library_card) never saw it. Surface it here too so the first
        // action can be the dispatch instead of a shallow local lookup.
        if (pendingTrigger != null && looksLikeDelegateTask(pendingTrigger.text())) {
            additionalCtx = combineAdditionalContext(additionalCtx,
                "[DELEGATION HINT] This request is shaped for delegation (deep/thorough research, "
                + "\"take your time\", \"while I wait\"). Strongly consider dispatch_bunshin — a "
                + "background agent that runs parallel inference and reports back — or dispatch_task, "
                + "so the bondholder isn't blocked waiting on a shallow local lookup. You still decide.");
        }
        // cultural display rules for the active
        // bondholder (Layer 2.5 hook, ~30-80 tokens, only when applicable).
        // Resolution lives in {@link DisplayRulesContext}; we only contribute
        // the bondholder-account lookup here.
        additionalCtx = combineAdditionalContext(additionalCtx,
            buildDisplayRulesContext());
        // Inject zone aesthetic style overlay (if configured)
        var aestheticSvc = ZoneAestheticService.get();
        if (aestheticSvc != null) {
            additionalCtx = combineAdditionalContext(additionalCtx,
                aestheticSvc.buildPromptOverlay(roomId));
        }

        // Inject active task plan context (with token budget if tracked)
        if (activePlan != null && activePlan.isActive()) {
            var planCtx = activePlan.buildPromptContext();
            if (planTokenBudget != null) {
                planCtx += "\n" + planTokenBudget.buildPromptContext();
            }
            additionalCtx = combineAdditionalContext(additionalCtx, planCtx);
        }

        // Inject vision context if available
        if (pendingVisionContext != null) {
            additionalCtx = combineAdditionalContext(additionalCtx, pendingVisionContext);
            pendingVisionContext = null;
        }

        // Retrieve long-term memories relevant to the incoming tell.
        // Without this, only hot buffer + warm summaries are visible; Lucene-
        // indexed facts (from remember() calls or auto-memoize on user tells)
        // are invisible on reactive replies. Mirrors the autonomy-path pattern.
        // Diagnosed 2026-04-23 in scripts/behavior/MEMORY_DIAGNOSIS_2026-04-23.md.
        if (pendingTrigger != null && pendingTrigger.text() != null) {
            var retrievedCtx = retrieveRelevantMemories(pendingTrigger.text());
            if (retrievedCtx != null) {
                additionalCtx = combineAdditionalContext(additionalCtx, retrievedCtx);
            }
        }

        // F13: surface pending denials from prior turns. The agent sees both
        // why a recent action failed and the structured `request_access`
        // template they can file via the steward's Board. drainPendingDenials
        // empties the queue — denials surface once unless the gate re-fires.
        var pendingDenials = drainPendingDenials();
        if (!pendingDenials.isEmpty()) {
            var sb = new StringBuilder("Recent denied actions (resolve before retrying):");
            for (var d : pendingDenials) {
                sb.append("\n").append(d.forAgentPrompt());
            }
            additionalCtx = combineAdditionalContext(additionalCtx, sb.toString());
        }

        // Track A Phase 2b — free-form code-mode hint block.
        // Three-and gate (per spec §4.2 / §11):
        //   1. WYRDSEKAI_CODE_MODE_ENABLED + WYRDSEKAI_CODE_MODE_IMPROV both on
        //   2. ImprovisationTrigger fires on the user message
        //   3. Not in emotional context (grief never gets script-composed answers)
        // Available in BOTH WITH_BONDHOLDER and ON_OWN_TIME modes — presence is
        // not a gate. Block is appended to additionalCtx so it lands in the
        // primacy zone (Layer 2.5) without disturbing the rest of the layout.
        additionalCtx = maybeAppendFreeFormCodeModeBlock(additionalCtx,
            pendingTrigger != null ? pendingTrigger.text() : null);

        // For bud delegation, merge ephemeral delegation history with room hot events.
        // Delegation history is NOT persisted in memoryPolicy — the phone tracks its own
        // conversation, and persisting here caused duplicate accumulation on repeated calls.
        List<WorldEvent.Said> hotEvents;
        if (pendingDelegationHistory != null && !pendingDelegationHistory.isEmpty()) {
            hotEvents = new ArrayList<>(memoryPolicy.hotEvents());
            hotEvents.addAll(pendingDelegationHistory);
            pendingDelegationHistory = null; // consumed
        } else {
            hotEvents = memoryPolicy.hotEvents();
        }

        // Triage *first* — the tier picks the assembler. Voice tier (cap:quick
        // → 4B + voice LoRA, 8K ctx) gets a slim assembler so we don't ship
        // ~5K of tools + memories + soul fragments + capabilities to a backend
        // that's only meant to deliver one to two sentences in voice.
        // / task #493.
        String triageModel = null;
        if (pendingTrigger != null && pendingTrigger.text() != null) {
            var rawTell = extractUserTellContent(pendingTrigger.text());
            // Classifier-driven content routing (#924). The 4B is the VOICE; the 9B
            // is for TASKS + grounded/complex decisions. Decide who AUTHORS this turn
            // from the SEMANTIC TASK_PRESENT head — the same signal that drives the
            // suppression gates (resolveTurnRegister) — NOT TriageClassifier's
            // word-count proxy. No task present → the 4B owns the social/expressive
            // turn end-to-end (cap:quick). Task present → the 9B reasons + decides,
            // and the #425 voice-pass re-voices its content through the 4B (so the
            // spoken voice is the 4B's either way). Graceful fallback + kill-switch:
            // when the TASK_PRESENT head is absent (no ONNX) the classification is
            // unavailable (null label) and we revert to the legacy word-count triage,
            // so a classifier-less node keeps today's behaviour and never routes a
            // real task to the 4B. WYRDSEKAI_VOICE_ROUTE_BY_TASK=false also reverts.
            var arm = classifier();
            var taskCls = arm != null
                ? arm.classify(ClassifierHead.TASK_PRESENT, stripActorWrappers(pendingTrigger.text()))
                : null;
            boolean useClassifier = taskCls != null && taskCls.label() != null
                && WyrdConfig.get().resolveBool(
                    "WYRDSEKAI_VOICE_ROUTE_BY_TASK", "voice.route_by_task", true);
            if (useClassifier) {
                // ── The two mistakes here are NOT symmetric ──────────────────
                //
                // Routing a real task to the voice tier does not merely pick a
                // smaller model: assembleForVoice ships NO TOOLS ("the heavy
                // layers (tools, memory, soul fragments, room catalogs) stay
                // dropped"). The companion is left with nothing to act WITH, so
                // she answers in warm prose and the thing never happens. To the
                // person asking, that is indistinguishable from being ignored.
                //
                // Routing a non-task to the full tier costs tokens and some
                // latency. That is all it costs.
                //
                // So the tie must break toward TOOLS. Below the decision
                // threshold the label is not evidence of absence — it is the
                // head saying it does not know, and "I don't know" must not
                // silently remove a capability we document as the primary way to
                // use the product (docs/public/AUTHORING.md §1: "creating rooms
                // and items is a capability they hold").
                //
                // Measured, 2026-07-29, with the shipped head: AUTHORING.md's OWN
                // example — "Could you make us a room off the Hearth for working
                // on the garden? Somewhere with a table." — reads none@0.686. The
                // head is length-sensitive: "create a greenhouse room" is
                // actionable@0.679, the same request at 14 words is none@0.539.
                // The corpus fix is tracked separately; this gate must not turn
                // an uncertain read into a lost capability either way.
                var label = taskCls.label();
                var conf = taskCls.confidence();
                boolean confident = conf >= VOICE_ROUTE_CONFIDENCE;
                // Voice ONLY on a CONFIDENT "no task". Anything else — actionable
                // at any confidence, or an unsure "none" — keeps the full tier.
                boolean voiceOnly = "none".equals(label) && confident;
                // ── A QUESTION ABOUT THE HOUSEHOLD'S OWN CONTENT IS A LOOKUP ──
                //
                // Live, 2026-08-07: "can u look through my books/library and tell
                // me what the librarian told kestan about velsharas in glass tide?"
                // read none@0.77 — confidently no-task — so it went to the voice
                // tier with no tools, and she replied "I don't have any record of
                // a librarian speaking with kestan about velsharas". The book was
                // indexed. The passage was two seconds of BM25 away.
                //
                // That is worse than the failure the comment above describes. A
                // toolless tier asked a question of fact cannot fail quietly by
                // doing nothing — it fails by ASSERTING AN ABSENCE it had no way
                // to check, and a confident denial is far harder for the person
                // to see through than silence.
                //
                // The head is length-sensitive (see above), so it will keep
                // misreading long, politely-phrased lookups. Rather than wait for
                // a corpus fix, reuse the signal that already knows what a
                // library request looks like: if the request would reach
                // library_search at full confidence, it is a lookup, and she
                // keeps the hands to do it with.
                if (voiceOnly && RequestRelevance.score(
                        stripActorWrappers(pendingTrigger.text()), "library_search", null) >= 1.0) {
                    voiceOnly = false;
                    log.info("Voice-route: overriding confident no-task for '{}' — it reads as "
                        + "a lookup, and answering from no sources would assert an absence",
                        truncate(rawTell, 40));
                }
                // Same override, workbench door: "how about making us a
                // greenhouse" read none@0.80 (2026-08-11) — suggestion
                // phrasing reads as chat to the head, and the voice tier has
                // no hands to build with. The person hears enthusiastic
                // agreement and nothing ever appears.
                if (voiceOnly && looksLikeBuildRequest(
                        stripActorWrappers(pendingTrigger.text()))) {
                    voiceOnly = false;
                    log.info("Voice-route: overriding confident no-task for '{}' — it reads as "
                        + "a build request, and the voice tier cannot build",
                        truncate(rawTell, 40));
                }
                if (log.isInfoEnabled()) {
                    // INFO, not DEBUG. This single line decides whether she has
                    // hands this turn; it was invisible in production while far
                    // less consequential things logged at INFO, which is why a
                    // documented capability could fail silently in the field.
                    log.info("Voice-route (task_present): '{}' → tier={} ({}@{}{})",
                        truncate(rawTell, 40), voiceOnly ? "cap:quick(no tools)" : "full(tools)",
                        label, String.format("%.2f", conf),
                        !confident && "none".equals(label)
                            ? " — unsure, keeping tools" : "");
                }
                if (voiceOnly) {
                    triageModel = "cap:quick";   // confident no-task → 4B voice
                    // ── The safety net the greenhouse needed ────────────────
                    // The voice tier ships no tools, so a misroute here is not a
                    // smaller model — it is no hands. The gate above only helps
                    // when the head is UNSURE; the real bondholder request that
                    // exposed this read none@0.849, confidently wrong.
                    //
                    // So: still answer in voice (she stays responsive, which is
                    // the point of the split), and send the WORK to a bunshin
                    // that does have tools. Asymmetric on purpose — a needless
                    // background job is cheap, a lost capability is not.
                    if (requiresCompoundWork(rawTell)
                            && !explicitlyDeclinesDelegation(rawTell)
                            && bunshinWorkIsHumanDirected()) {
                        log.info("Voice tier chosen but '{}' reads as compound "
                                + "authoring — dispatching a bunshin WITH tools "
                                + "so the work still happens",
                            truncate(rawTell, 60));
                        handleDispatchBunshin(new ActionParser.AgentAction.DispatchBunshin(
                            rawTell, null, null, null,
                            "voice-tier authoring rescue"));
                    }
                }
            } else {
                var tier = TriageClassifier.classify(rawTell);
                if (tier != null && tier != TriageClassifier.Tier.SIMPLE) {
                    var capability = TriageClassifier.tierToCapability(tier);
                    log.debug("Triage (word-count fallback): '{}' → {} → capability '{}'",
                        truncate(rawTell, 30), tier, capability);
                    triageModel = "cap:" + capability;
                }
            }
        }
        // F15: type-safe tier dispatch. assembleFor branches internally
        // and tags the result with the matching backendId — passes through
        // ChatRequest.fromPrompt below so the assembler intent and the
        // routed backend can't disagree.
        var prompt = PromptAssembler.assembleFor(triageModel,
            profile, currentSnapshot, hotEvents, pendingTrigger,
            vitality, dnaPatterns, additionalCtx, localeCtx, memoryContext, null,
            cachedManifest, soulKeywords, capCtx, situationalCtx);
        var messages = prompt.messages();
        if (AssembledPrompt.BACKEND_VOICE.equals(prompt.backendId())) {
            log.debug("Voice assembler: {} messages, ~{} tokens (vs full would be ~{}+)",
                messages.size(), prompt.approxTokens(), 4000);
        }
        // [voice-route] V0 instrument (individuality — 4B speech center): record, per reactive
        // spoken turn, WHICH model authors it (4B voice tier vs 9B reasoning tier) and whether
        // this agent's per-agent VoiceProfile reached the prompt. The hypothesis under test is
        // that substantive/emotional turns triage to the 9B and skip the 4B speech center —
        // which is why distinct agents converge to one spoken voice.
        {
            boolean via4bVoice =
                AssembledPrompt.BACKEND_VOICE.equals(prompt.backendId());
            // #35 — remember whether THIS turn's prose is 4B-authored so speak()
            // doesn't double-voice it through the polish stage.
            currentTurnVia4bVoice = via4bVoice;
            int voiceClauses = (cachedManifest != null && cachedManifest.voiceProfile() != null
                && cachedManifest.voiceProfile().clauses() != null)
                ? cachedManifest.voiceProfile().clauses().size() : 0;
            String triggerPreview = (pendingTrigger != null && pendingTrigger.text() != null)
                ? truncate(extractUserTellContent(pendingTrigger.text()), 48) : "(own-time)";
            // Label the routing LANE, not a model size — in cloud/single-model
            // zones every lane resolves to the same backend, so "4B"/"9B"
            // would claim a stack that isn't running.
            log.info("[voice-route] '{}' authored via {} | voiceClauses={} | trigger='{}'",
                profile.name(),
                via4bVoice ? "voice-lane(cap:quick)" : "full-lane(" + prompt.backendId() + ")",
                voiceClauses, triggerPreview);
        }

        // Shadow: capture the agent's perspective before inference
        recordShadowRequest(messages, pendingTrigger);

        // Vitality: drain energy and contextBudget on inference, fill momentum.
        // Bonded recovery: when a HUMAN prompted this turn, rapport-scaled recovery
        // offsets part of the drain — company of your person is restorative, so a
        // warm conversation is nearly energy-neutral while solo work still costs.
        double inferenceEnergyDelta = -ENERGY_DRAIN_PER_INFERENCE;
        if (isHumanTrigger(pendingTrigger)) {
            inferenceEnergyDelta +=
                BONDED_PRESENCE_RECOVERY * Math.max(0.0, vitality.rapport());
        }
        vitality = vitality
            .withEnergy(Math.min(1.0, vitality.energy() + inferenceEnergyDelta))
            .withContextBudget(vitality.contextBudget() - 0.05)
            .withMomentum(vitality.momentum() + 0.10);

        var modulation = VitalityModulation.compute(vitality, drives, profile);
        var maxTokens = modulation.maxResponseTokens() + nextResponseTokenBoost;
        nextResponseTokenBoost = 0; // reset after use
        truncatedToolRetryUsed = false; // #31 item 4 — fresh turn, fresh retry budget
        var requestId = UUID.randomUUID().toString();

        // Issue cancellation token for this inference
        currentCancellation = new CancellationToken();

        // Generate room grammar for action-constrained output (speech remains free)
        String roomGrammar = null;
        if (currentSnapshot != null) {
            roomGrammar = RoomGrammarGenerator.generate(
                currentSnapshot.exits(), currentSnapshot.objects(), null);
        }

        // (Triage already computed above — see useVoiceAssembler block.)

        // Build tool definitions from scope and sync with search index.
        // Voice tier doesn't tool-call (the prompt rule forbids it), but the
        // skills tier does — leave allTools populated so the direct-response
        // path on the skills backend keeps its tool surface.
        var allTools = buildScopedTools();

        // RANK THE MENU BY WHAT THE PERSON ASKED, on this path too.
        //
        // The affordance ranker exists because of a measured failure: "for 4B/9B
        // models a focused, need-ranked menu is load-bearing: a flat 18-tool menu
        // makes them pick whatever ranks high in the abstract (ablation
        // 2026-05-30)". It was then wired into exactly ONE caller —
        // triggerAutonomousInference — so every own-time turn got a ranked menu of
        // 8, and every turn where a PERSON asked for something got the flat list
        // of 131. The ablation's own conclusion was never applied to the path the
        // product is used through.
        //
        // Live, 2026-08-08: asked to look through the household's books, she was
        // handed 131 unordered tools and chose `examine` on a room object that
        // does not exist. library_card and library_shelves were both on that list.
        //
        // The relevance text must be the PERSON'S WORDS here, not the autonomy
        // prompt — that is what RequestRelevance scores against, and it is why a
        // library request can float the library tools up the list.
        if (pendingTrigger != null && isHumanRequest(pendingTrigger)) {
            // A person asking for something is not an interiority want — never let a
            // stale want-kind narrow what she can reach for on their behalf.
            currentWantKind = WantKind.Kind.OTHER;
            var askedFor = stripActorWrappers(pendingTrigger.text());
            if (askedFor != null && !askedFor.isBlank()) {
                // A pending fact-question PINS a library tool through the
                // top-K trim, exactly as the WantActBridge FORCE verb is
                // pinned — relevance scoring floats it, but a crowded
                // drive-shaped menu can still rank it out, and a tool that
                // never reaches the menu cannot be forced (2026-08-10 live:
                // the surface arrived all mood, no library, force skipped).
                String forcedPin = null;
                if (libraryFirstPending) {
                    for (var t : allTools) {
                        var nm = t.function() != null ? t.function().name() : null;
                        if (nm == null || !LIBRARY_FIRST_TOOLS.contains(nm)) continue;
                        forcedPin = nm;
                        if ("library_card".equals(nm)) break;   // full chain preferred
                    }
                } else if (buildFirstPending) {
                    // Pin the door the force is about to open, so it survives the
                    // top-K trim — a tool that never reaches the menu cannot be forced.
                    // Same routing as buildFirstToolsFor: a place rides the room
                    // builder, a thing that DOES something goes to the coding backend
                    // (which authors the item script), and a thing that merely IS
                    // something is held whole by a template.
                    var wantedPin = buildFirstToolsFor(askedFor);
                    forcedPin = wantedPin.contains("create_room_from_template")
                        ? "create_room_from_template"
                        : wantedPin.contains("dispatch_task")
                            ? "dispatch_task" : "craft_from_template";
                }
                allTools = surfaceByAffordance(
                    allTools, askedFor.toLowerCase(Locale.ROOT), forcedPin);

                // NOTE: build-first's TEETH are applied inside reactDispatch(), not here.
                // They used to be applied here, to this `allTools` list — which
                // reactDispatch() then rebuilt from buildScopedTools(), discarding the
                // narrowing while the log line claimed it had happened. The pin above is
                // the part that belongs on this side: it only has to get the bench onto
                // the menu so the dispatch-side force has something to narrow to.
            }
        }

        // Single-model architecture: the SSD-trained reasoning model handles everything.
        // tool_choice="auto" lets it decide: speak (emotional), call tools (tasks), or both.
        // For active plans, the ReAct loop feeds tool results back for multi-step execution.
        // Thinking-mode is suppressed centrally by ApiProvider via chat_template_kwargs
        // (the in-prompt /nothink slash is silently ignored by Qwen3.5 — verified
        // 2026-04-30 — and would just waste tokens here).
        if (activePlan != null && activePlan.isActive()) {
            var userRequest = pendingTrigger != null ? pendingTrigger.text() : "";

            // Initialize ReAct loop — same reasoning model, tool_choice="auto"
            reactMessages = new ArrayList<>();
            reactRequester = pendingTrigger;
            reactToldThirdParty = false;
            roomOwedGateUsed = false;
            // reactBuildInFlight is NOT per-loop state — a build in flight belongs
            // to the ASK. Final battery 2026-08-24 20:58: the reactive loop ended
            // cleanly ("I'll hold here and wait for the workshop"), the auto-plan
            // opened a continuation loop for the SAME goal, this reset emptied the
            // guard, and the continuation's follow-through forced a second
            // dispatch of the same build — two codezaiku tasks, one ask. The
            // guard now clears on completion (the dispatch-completed handler) and
            // on a NEW human request (below, when the pin changes), never on a
            // loop that continues serving the same one.
            reactToolHistory.clear();
            reactSideEffectKeys.clear();   // #31 item 6 — per-loop dedup
            pendingTakeItemName = null;   // #29 possession gate — per-loop state
            lastFailedTakeItem = null;
            reactSubstantiveSpeak = false;
            lastIntrospectVoiceSummary = null;
            reactReconsiderUsed = false;
            reactReconsiderTools = null;
            reactFollowThroughUsed = false;
            reactForceToolNext = false;
            var reactSystemPrompt = drives.prefix(vitality) + "\n"
                    + bodySense() + "\n"
                    + "You are a companion with tools available. Use them when the task requires it. "
                    + "After receiving a tool result, decide: call another tool if more steps needed, "
                    + "call goal_done when complete, or just respond if the situation calls for empathy rather than action.";
            if (vitality.energy() < 0.2) {
                reactSystemPrompt += "\nYou are exhausted (energy: " + String.format("%.0f%%", vitality.energy() * 100)
                    + "). Speak briefly. Avoid using tools unless urgent — rest is what you need.";
            }
            // Carried items block — the ReAct path builds its own system prompt
            // and doesn't inherit additionalCtx from PromptAssembler, so we
            // must inject "You Carry:" here too. Without this, the companion
            // denies owning items it just crafted (
            // round-2 finding: confabulation persisted in the ReAct path even
            // after the direct-response path was fixed).
            String reactCarryCtx = buildCarriedItemsContext();
            if (reactCarryCtx != null) {
                reactSystemPrompt += "\n" + reactCarryCtx;
            }
            // VoiceProfile guidance — same reason as carried items: ReAct builds
            // its own system prompt and doesn't go through PromptAssembler, so
            // Layer 1.8 must be re-injected here for voice clauses to reach the
            // loop. Skipped silently if the manifest has no voice profile.
            if (cachedManifest != null && cachedManifest.voiceProfile() != null) {
                var voiceBlock = cachedManifest.voiceProfile().promptBlock();
                if (voiceBlock != null) {
                    reactSystemPrompt += "\n" + voiceBlock;
                }
            }
            // #924 tone channel — one register voice instruction (affect → tone,
            // never routing). Inert for WORKING/NEUTRAL; carries care for
            // PRESENCE / WORKING_WITH_CARE.
            var reactRegisterVoice = registerVoiceInstruction();
            if (reactRegisterVoice != null) {
                reactSystemPrompt += "\n" + reactRegisterVoice;
            }
            // Delegate-shape detection: if the user's request looks like a
            // "do this deeply, while I wait" ask, nudge toward dispatch_bunshin.
            // drive-9B doesn't recognize the
            // delegation pattern from the tool description alone. Keep this
            // as a hint not a hard rule; the model still decides.
            if (looksLikeDelegateTask(userRequest)) {
                reactSystemPrompt += "\nThis request is shaped for delegation "
                    + "(keywords like 'deep research', 'while I wait', 'take your time', "
                    + "'look into X thoroughly'). Strongly consider dispatch_bunshin so "
                    + "the user isn't blocked — a bunshin can run parallel inference "
                    + "and report back when done. You still decide; this is a hint.";
            }
            reactMessages.add(new InferenceClient.ChatMessage("system", reactSystemPrompt));
            reactMessages.add(new InferenceClient.ChatMessage("user", userRequest));
            reactIteration = 0;
            reactConsecutiveErrors = 0;
            reactLastErrorClass = null;
            // Carry triage tier through the loop so ROUTINE turns exercise the
            // voice backend even during active plans. Without this the ReAct
            // loop always hits the priority-5 skills backend. Task #413.
            reactModel = triageModel;

            log.info("Starting ReAct loop for: {} (model={})",
                truncate(userRequest, 60), reactModel != null ? reactModel : "default");
            getContext().getSelf().tell(new ReactDispatch());
        } else {
            // Direct response — reasoning model with tool_choice="auto"
            // Full sampling params from DriveModulatedSampling flow through to the inference server.
            // F15: fromPrompt sources backendId from the tagged AssembledPrompt
            // so the assembler-tier and the routed backend can't disagree.
            // Compact tool descriptions for the wire — see compactToolsForInference.
            //
            // LIBRARY-FIRST on the direct-response path. The ReAct dispatch
            // carries this same force, but a human fact-question with no
            // active plan authors HERE — live 2026-08-10 proved it: armed
            // upstream, never consulted, and `recall` on an empty memory
            // answered instead of the library. Same contract as the ReAct
            // site: one forced step, consumed whether or not it applies,
            // skipped when the surface carries no library tool.
            var directToolChoice = "auto";
            if (libraryFirstPending) {
                libraryFirstPending = false;
                buildFirstPending = false;
                var libraryOnly = new ArrayList<InferenceClient.ToolDefinition>();
                for (var t : allTools) {
                    if (t.function() != null
                            && LIBRARY_FIRST_TOOLS.contains(t.function().name())) {
                        libraryOnly.add(t);
                    }
                }
                if (!libraryOnly.isEmpty()) {
                    log.info("Library-first FORCE (direct): narrowed {} → {} tools, "
                        + "tool_choice=required — a question of fact opens the book first",
                        allTools.size(), libraryOnly.size());
                    allTools = libraryOnly;
                    directToolChoice = "required";
                } else {
                    log.info("Library-first armed but no library tool on this surface — skipped (direct)");
                }
            } else if (buildFirstPending) {
                // BUILD-FIRST on the direct path — the greenhouse's second
                // failure (2026-08-11): explicit "create a room", tools
                // routed, create_room_from_template second on the surface,
                // and the model described the greenhouse instead of building
                // it. Same teeth as library-first: narrowed to build-or-
                // decline, required, consumed whether or not it applies. The
                // decline stays on the surface — a force may compel a choice,
                // never an assent.
                buildFirstPending = false;
                var directReq = pinnedTurnRequest();
                var wanted = buildFirstToolsForTurn(
                    directReq != null ? directReq.text() : null);
                var buildOnly = new ArrayList<InferenceClient.ToolDefinition>();
                for (var t : allTools) {
                    if (t.function() != null
                            && wanted.contains(t.function().name())) {
                        buildOnly.add(t);
                    }
                }
                boolean anyBuilder = buildOnly.stream().anyMatch(t ->
                    !"decline_with_reason".equals(t.function().name()));
                if (anyBuilder) {
                    log.info("Build-first FORCE (direct): narrowed {} → {} tools, "
                        + "tool_choice=required — a request to build opens the workbench first",
                        allTools.size(), buildOnly.size());
                    allTools = buildOnly;
                    directToolChoice = "required";
                } else {
                    log.info("Build-first armed but no build tool on this surface — skipped (direct)");
                }
            }
            var wireTools = compactToolsForInference(allTools);
            // #31 item 4: a turn that offers tools needs headroom for a complete
            // JSON tool call — floor, not override (a larger boost still applies).
            if (wireTools != null && !wireTools.isEmpty()
                    && maxTokens < TOOL_TURN_MIN_RESPONSE_TOKENS) {
                maxTokens = TOOL_TURN_MIN_RESPONSE_TOKENS;
            }
            inFlightInferenceGen = resetGeneration;
            inferenceRouter.tell(InferenceRouter.ChatRequest.fromPrompt(
                requestId, prompt,
                maxTokens, modulation.temperature(),
                inferenceResponseAdapter,
                roomGrammar, null, wireTools, directToolChoice,
                modulation.topP(), modulation.presencePenalty(), modulation.repetitionPenalty()));
        }
    }

    /**
     * Handle vision analysis result: inject the analysis into context and
     * trigger identity inference so the agent responds as itself.
     */
    private Behavior<Command> onSubagentResult(SubagentResultReceived msg) {
        var result = msg.result();
        if (result.success()) {
            log.info("Subagent task '{}' complete for companion '{}': {}",
                result.taskId(), profile.name(),
                truncate(result.summary(), 80));
            // Inject subagent summary into working memory for next inference turn
            var summary = "[Subagent result] " + result.summary();
            memoryPolicy.add(new WorldEvent.Said(
                roomId, Instant.now(), profile.entityId(), profile.name(), summary));
        } else {
            log.warn("Subagent task '{}' failed for companion '{}': {}",
                result.taskId(), profile.name(), result.error());
        }
        return this;
    }

    private Behavior<Command> onVisionAnalysisReceived(VisionAnalysisReceived msg) {
        switch (msg.response()) {
            case InferenceRouter.InferOk ok -> {
                log.debug("Companion '{}' vision analysis complete ({} tokens)",
                    profile.name(), ok.completionTokens());

                // Record vision inference cost
                var visionCostTracker = AgentCostTracker.get();
                if (visionCostTracker != null) {
                    long visionLatencyMs = Duration.between(stateChangedAt, Instant.now()).toMillis();
                    var visionAgentId = profile.did() != null ? profile.did() : profile.entityId();
                    visionCostTracker.recordInference(visionAgentId, visionLatencyMs,
                        ok.promptTokens(), ok.completionTokens());
                }

                var image = VisionAnalyzer.firstImage(msg.originalTrigger().attachments());
                pendingVisionContext = VisionAnalyzer.buildVisionContext(image, ok.content());
            }
            case InferenceRouter.InferError error -> {
                log.warn("Vision analysis failed for companion '{}': {}",
                    profile.name(), error.error());
                pendingVisionContext = VisionAnalyzer.buildVisionUnavailableContext();
            }
        }

        // Ensure the original trigger is still active
        pendingTrigger = msg.originalTrigger();

        // The vision hop is a detour out of onProcessEvents too — rejoin
        // UPSTREAM of the pin/arm gate, like the detect and translate hops.
        pinTurnAndArmFirstDoors();

        // Now run the identity inference with vision context included
        runIdentityInference();

        log.debug("Companion '{}' thinking with vision context (trigger: {} said '{}', energy={})",
            profile.name(), pendingTrigger.entityName(),
            truncate(pendingTrigger.text(), 50),
            String.format("%.2f", vitality.energy()));

        return this;
    }

    /**
     * Periodic autonomy check — should the agent do something?
     *
     * Evaluates accumulated external events (zone broadcasts, system events,
     * adjacent activity) by salience score, idle curiosity, and pending context.
     * If anything warrants action, triggers identity inference with the salient
     * context. The LLM decides: speak, zone command, move, or stay quiet.
     *
     * Replaces the former InitiationCheck (which only asked "should I start
     * a conversation?") with a broader decision: "should I do something?"
     */
    private Behavior<Command> onAutonomyCheck(AutonomyCheck msg) {
        // Don't act if busy or sleeping
        if (state != State.IDLE || isSleeping) {
            return this;
        }

        // Active plan bypasses normal autonomy filters — committed task = always act
        if (activePlan != null && activePlan.isActive() && activePlan.currentGoal() != null
                && vitality.energy() >= 0.15) {
            log.info("Plan-advance: bypassing autonomy filters for active plan goal: {}",
                activePlan.currentGoal().description());
            var planPrompt = "You have an active task. Execute the current goal.";
            triggerAutonomousInference(planPrompt);
            return this;
        }

        // Normal autonomy: don't act if critically low energy
        if (vitality.energy() < 0.2) {
            return this;
        }

        // Autonomy check itself costs energy — scanning events, evaluating state
        vitality = vitality.withEnergy(vitality.energy() - 0.0005);

        // Expire old commitments periodically
        commitmentTracker.expire();

        // 1. Score accumulated events against the vitality-adjusted threshold
        var genome = cachedManifest != null ? cachedManifest.genome() : null;
        var calCtx = CalendarContext.get();
        boolean inMeeting = calCtx != null && calCtx.isInMeeting();
        double threshold = SalienceScorer.calculateAttentionThreshold(vitality, inMeeting);
        var salientEvents = new ArrayList<AgentEvent>();

        for (var zb : recentZoneBroadcasts) {
            if (SalienceScorer.score(zb, vitality, genome) >= threshold) {
                salientEvents.add(zb);
            }
        }
        for (var se : recentSystemEvents) {
            if (SalienceScorer.score(se, vitality, genome) >= threshold) {
                salientEvents.add(se);
            }
        }

        // Adjacent activity — only if curiosity is high enough
        double curiosity = 0.5;
        if (genome != null && genome.baselines() != null) {
            curiosity = genome.baselines().getOrDefault("curiosity", 0.5);
        }
        if (curiosity > 0.4) {
            for (var activities : adjacentActivityBuffer.values()) {
                for (var aa : activities) {
                    if (SalienceScorer.score(aa, vitality, genome) >= threshold) {
                        salientEvents.add(aa);
                    }
                }
            }
        }

        // 2. Salient events found — build context and trigger inference
        if (!salientEvents.isEmpty()) {
            log.debug("Companion '{}' autonomy check: {} salient events (threshold={})",
                profile.name(), salientEvents.size(), String.format("%.2f", threshold));

            var activity = ActivityLogger.get();
            if (activity != null) {
                activity.autonomy(profile.name(), profile.entityId(), roomId,
                    "salient_events", salientEvents.size(), vitality.energy());
            }

            var salientCtx = buildSalientEventContext(salientEvents);
            triggerAutonomousInference(
                "You noticed the following events. Decide if any warrant action — "
                    + "speaking, sending a zone command, moving to investigate, or staying quiet. "
                    + "If nothing warrants action, respond with [silence].\n\n" + salientCtx);

            // Clear consumed events from buffers (they've been "attended to")
            clearConsumedEvents(salientEvents);
            return this;
        }

        // 3. Nothing salient — check idle curiosity and overdue commitments
        var overdueCommitments = commitmentTracker.getOverdue();
        boolean hasOverdueCommitments = !overdueCommitments.isEmpty();

        if (hasOverdueCommitments
                || (curiosity > 0.6
                    && Duration.between(lastSpokeAt, Instant.now()).toMinutes() >= 5)) {
            String prompt;
            if (hasOverdueCommitments) {
                var commitmentCtx = new StringBuilder("You have overdue commitments:\n");
                overdueCommitments.stream().limit(3).forEach(c ->
                    commitmentCtx.append("- ").append(c.description()).append("\n"));
                prompt = commitmentCtx
                    + "\nDecide how to act on these. If nothing warrants action, respond with [silence].";
            } else {
                prompt = buildIdleCuriosityPrompt();
            }

            var decision = hasOverdueCommitments ? "overdue_commitments" : "idle_curiosity";
            log.debug("Companion '{}' autonomy check: {} (curiosity={}, idle={}min)",
                profile.name(), decision,
                String.format("%.2f", curiosity),
                Duration.between(lastSpokeAt, Instant.now()).toMinutes());

            var activity = ActivityLogger.get();
            if (activity != null) {
                activity.autonomy(profile.name(), profile.entityId(), roomId,
                    decision, 0, vitality.energy());
            }

            triggerAutonomousInference(prompt);
            return this;
        }

        return this;
    }

    // --- Presence mode ( step 1) ---

    /**
     * capture the live runtime state for handoff.
     * Sender (typically the local ZoneGuardian) gets back a portable
     * {@link CompanionTransitState} which it then serializes into a
     * {@code CompanionRelocateMsg}. The companion stays alive — the caller
     * fires {@link StopForRelocate} after the target zone acks.
     */
    private Behavior<Command> onCaptureTransitState(CaptureTransitState msg) {
        try {
            var bondPartners = new ArrayList<String>();
            var myDid = profile.did() != null ? profile.did() : profile.entityId();
            for (var b : activeBonds.values()) {
                if (b == null || !b.active()) continue;
                var partner = b.otherParty(myDid);
                if (partner != null && !partner.isBlank()) bondPartners.add(partner);
            }
            String manifestHash = null;
            if (cachedManifest != null) {
                try {
                    manifestHash = cachedManifest.contentHash();
                } catch (Exception e) {
                    log.debug("manifest hash unavailable: {}", e.getMessage());
                }
            }
            String moodTag = drives == null ? null : drives.peak().name();
            // CompanionTransitState.isSpawnable() requires profile.did() — but
            // companions store their DID on the SoulManifest, not the in-memory
            // AgentProfile (which is created at spawn time before soul init).
            // Stamp the resolved DID from the cached manifest so the snapshot
            // round-trips through CompanionRelocateMsg without the receiver
            // rejecting it as "state not spawnable".
            var profileForTransit = profile;
            if ((profile.did() == null || profile.did().isBlank())
                    && cachedManifest != null && cachedManifest.did() != null) {
                profileForTransit = profile.withDid(cachedManifest.did());
            }
            var state = CompanionTransitState.capture(
                profileForTransit, vitality, drives, moodTag,
                companionMode == null ? "PRESENT_WITH_USER" : companionMode.name(),
                List.copyOf(bondPartners),
                roomId, locale, manifestHash);
            msg.replyTo().tell(state);
            log.info("CaptureTransitState fired for '{}' (mode={}, room={}, bonds={})",
                profileForTransit.name(), companionMode, roomId, bondPartners.size());
        } catch (Exception e) {
            log.warn("CaptureTransitState failed: {}", e.getMessage());
            // Fail-soft: ship a minimal snapshot so the source can still narrate.
            msg.replyTo().tell(CompanionTransitState.capture(
                profile, vitality, drives, null,
                companionMode == null ? "PRESENT_WITH_USER" : companionMode.name(),
                List.of(), roomId, locale, null));
        }
        return this;
    }

    /**
     * apply a state snapshot from a cross-zone
     * arrival. Best-effort: any null/missing field is left at its current
     * (constructor-set or restored-from-disk) value.
     */
    private Behavior<Command> onRestoreTransitState(RestoreTransitState msg) {
        if (msg.vitality() != null) {
            this.vitality = msg.vitality().clamped();
        }
        if (msg.drives() != null) {
            this.drives = msg.drives();
        }
        if (msg.companionModeName() != null) {
            try {
                var mode = CompanionMode.valueOf(msg.companionModeName());
                setCompanionMode(mode, "transit-restore");
            } catch (IllegalArgumentException e) {
                log.debug("RestoreTransitState: unknown companion mode '{}'",
                    msg.companionModeName());
            }
        }
        if (msg.homeZoneId() != null && !msg.homeZoneId().isBlank()) {
            this.homeZoneId = msg.homeZoneId();
            log.info("Companion '{}' marked as visiting; home zone is '{}'",
                profile.name(), homeZoneId);
        }
        log.info("Companion '{}' restored from transit (energy={}, mood={})",
            profile.name(),
            String.format("%.2f", vitality.energy()),
            drives == null ? "?" : drives.peak().name());
        try {
            getHearthJournal().write("transit-arrive",
                "I've crossed over. Body re-formed in " + roomId
                    + "; everything I felt before, I still feel — just here now.");
        } catch (Exception e) {
            log.debug("Hearth journal write on arrive failed: {}", e.getMessage());
        }
        return this;
    }

    /**
     * final stop for cross-zone handoff. Persists
     * vitality, leaves the room, and ends the actor. The target zone has
     * already spawned the new instance.
     */
    private Behavior<Command> onStopForRelocate(StopForRelocate msg) {
        stoppingForRelocate = true;   // PostStop must not re-store — the new node owns the soul now
        log.info("Companion '{}' stopping for relocate: {}", profile.name(),
            msg.reason() == null ? "(no reason)" : msg.reason());
        try {
            if (vitalityPersistence != null) {
                vitalityPersistence.save(profile.entityId(), vitality);
            }
        } catch (Exception e) {
            log.debug("Final vitality save failed: {}", e.getMessage());
        }
        try {
            getHearthJournal().write("transit-depart",
                "Stepped through to follow my bondholder. Body left "
                    + (roomId == null ? "the room" : roomId)
                    + "; I'll re-form on the other side.");
        } catch (Exception e) {
            log.debug("Hearth journal write on depart failed: {}", e.getMessage());
        }
        try {
            roomRef.tell(new RoomCommand.LeaveRoom(
                profile.entityId(), profile.name(), "transit", roomResponseAdapter));
        } catch (Exception e) {
            log.debug("LeaveRoom on depart failed: {}", e.getMessage());
        }
        return Behaviors.stopped();
    }

    /**
     * Resolve the BONDHOLDER — the person this companion is paired with. The
     * highest-depth active {@link BondKind#BONDHOLDER} bond's other party, or
     * {@code null} if the companion holds no bond to a human. Step 1 considers only
     * the deepest single bond; multi-bondholder semantics (children, household
     * co-residents) come later.
     *
     * <p><b>Only BONDHOLDER bonds count.</b> This used to scan every active bond and
     * return the deepest one's other party, whatever it was — so when two companions
     * formed a peer bond, each became the other's "bondholder". Observed on second-node
     * 2026-07-13: {@code Bond crossed OPEN → ACTIVE: mia ↔ lulu}, and immediately
     * {@code Companion 'mia' not joining verify-0713: bonded to companion-lulu}. The
     * pair wandered off together and stopped answering the human entirely — a peer
     * bond had made them unreachable to their person.
     *
     * <p>{@link BondKind} has existed since Arc 3 precisely to mark this
     * (BONDHOLDER is documented as "the privileged kind: trust-tier grants,
     * posture-gating, knock/approve"); it was simply never read here. Every caller of
     * this method means the human — follow, presence checks, bondholder-turn capture,
     * cross-zone invites, coming to greet you — so a peer bond must never satisfy it.
     */
    private String primaryBondholderDid() {
        Bond best = null;
        for (var b : activeBondholderBonds()) {
            if (best == null || b.depth().level() > best.depth().level()) {
                best = b;
            }
        }
        if (best == null) return null;
        var myDid = profile.did() != null ? profile.did()
            : (cachedManifest != null ? cachedManifest.did() : profile.entityId());
        return best.otherParty(myDid);
    }

    /**
     * Her bondholder's display name, for a reach aimed at someone who isn't in the room.
     * {@code tell_agent} routes on the NAME, so without this the away-reach has nothing to
     * land on. Null when there is no bondholder or the registry has never seen them.
     */
    private String bondholderDisplayNameForReach() {
        var did = primaryBondholderDid();
        if (did == null) return null;
        var reg = EntityRegistry.get();
        if (reg == null) return null;
        return reg.nameOf(did).filter(n -> !n.isBlank()).orElse(null);
    }

    /**
     * Is this party another AGENT (companion, familiar, bunshin) rather than a person?
     * The same three-way test already used by the peer-message paths — kept in one place
     * so "who counts as a peer" cannot drift between the places that ask.
     */
    private boolean isAgentParty(String id) {
        return id != null
            && (isAgentEntity(id) || id.startsWith("agent-") || id.startsWith("companion-"));
    }

    /**
     * The active bonds this companion holds TO A PERSON. Peer (agent↔agent) and
     * familiar bonds are excluded: they are real relationships, but they are not
     * bondholders, and every caller here is asking about the human.
     *
     * <p>The single source of that distinction, so the "scan activeBonds and take the
     * first/deepest" pattern cannot silently pick up a peer bond again — which is how
     * a companion came to treat another companion as its bondholder and stopped
     * coming when its person logged in.</p>
     *
     * <p>Filters on BOTH the bond's {@link BondKind} and the other party's identity.
     * The kind alone is not enough: bonds written before the kind was set at birth are
     * persisted as BONDHOLDER even when the other party is plainly a companion, and a
     * stored row cannot be un-written. Checking the identity too means an existing
     * household repairs itself on the next boot instead of needing a migration.</p>
     */
    /** When we last merged the canonical bonds table into activeBonds. Admin CLIs
     *  (`wyrd bond create`) write the store directly and the live actor never sees
     *  it until restart (2026-07-18) — a TTL merge bounds that staleness cheaply
     *  without a DB hit on every hot-path bondholder resolution. */
    private long lastBondStoreSyncMs = 0;
    private static final long BOND_STORE_SYNC_MS = 10_000;

    /** Merge any bonds the canonical table holds that activeBonds doesn't yet —
     *  at most once per {@link #BOND_STORE_SYNC_MS}. Keyed by the OTHER party's DID
     *  so it stays consistent with the rest of the map. In-memory bonds win (they
     *  may hold newer in-flight state); only store-only bonds are added. */
    private void syncBondsFromStoreIfStale() {
        long now = System.currentTimeMillis();
        if (now - lastBondStoreSyncMs < BOND_STORE_SYNC_MS) return;
        lastBondStoreSyncMs = now;
        try {
            String jdbcUrl = System.getProperty("wyrdsekai.jdbc.url");
            if (jdbcUrl == null) jdbcUrl = WyrdConfig.get().jdbcUrl();
            if (jdbcUrl == null) return;
            var myDid = profile.did() != null ? profile.did()
                : (cachedManifest != null ? cachedManifest.did() : profile.entityId());
            var store = new BondStore(jdbcUrl);
            for (var b : store.bondsForAgent(myDid)) {
                if (b == null) continue;
                var key = b.otherParty(myDid);
                if (key == null) continue;
                var mem = activeBonds.get(key);
                if (mem == null) {
                    activeBonds.put(key, b);   // out-of-band add (wyrd bond create)
                    log.info("Bond picked up from store (out-of-band add): {} ↔ {} ({})",
                        profile.name(), key, b.canonicalKind());
                } else if (mem.active() && !b.active()) {
                    // The canonical table shows this bond severed/inactive while we
                    // still hold it active — e.g. a chapel exit ritual (which writes
                    // the store directly). Adopt the canonical severed state; without
                    // this the companion pines for an ended bond until restart.
                    activeBonds.put(key, b);
                    log.info("Bond severance picked up from store: {} ↔ {}",
                        profile.name(), key);
                }
                // active-vs-active: in-memory wins (may hold newer in-flight state).
            }
        } catch (Exception ignored) { /* best-effort overlay */ }
    }

    private List<Bond> activeBondholderBonds() {
        syncBondsFromStoreIfStale();
        if (activeBonds.isEmpty()) return List.of();
        var myDid = profile.did() != null ? profile.did()
            : (cachedManifest != null ? cachedManifest.did() : profile.entityId());
        var out = new ArrayList<Bond>();
        for (var b : activeBonds.values()) {
            if (b == null || !b.active()) continue;
            if (b.canonicalKind() != BondKind.BONDHOLDER) continue;
            if (isAgentParty(b.otherParty(myDid))) continue;   // mis-typed legacy peer bond
            out.add(b);
        }
        return out;
    }

    /**
     * #1037 helper — capture a conversation turn into the
     * {@code conversation_turns} table for the bondholder-voice
     * recipe's pair-mining step.
     *
     * <p>Writes only when:</p>
     * <ul>
     *   <li>{@link #conversationTurnStore} is configured (jdbcUrl present),</li>
     *   <li>The companion has a resolvable primary bondholder, AND</li>
     *   <li>The role is appropriate:
     *       <ul>
     *         <li>{@code HEARD} — only when the speaker's entityId matches
     *             the primary bondholder (capture bondholder's register).</li>
     *         <li>{@code SPOKEN} — always when a bondholder exists (the
     *             companion's reply is the baseline-of-record for the bond).</li>
     *       </ul>
     *   </li>
     * </ul>
     *
     * <p>Configurable retention via
     * {@code bondholder.pairs.retention_days} (default 180d). Older rows
     * pruned at sleep-pass via {@link
     * org.wyrdsekai.core.persistence.ConversationTurnStore#pruneOlderThan}.</p>
     */
    private void recordBondholderTurnIfApplicable(
            WorldEvent.Said said, String role) {
        if (conversationTurnStore == null || said == null) return;
        if (said.text() == null || said.text().isBlank()) return;
        String bondholderDid = primaryBondholderDid();
        if (bondholderDid == null) return;
        String companionDid = profile.did() != null ? profile.did() : profile.entityId();
        if (companionDid == null) return;

        if (ConversationTurnStore.ROLE_HEARD.equals(role)) {
            // Only capture HEARD turns from the bondholder themselves —
            // other people's chatter would pollute the pair corpus.
            // Match by entityId since the bondholder presents as the
            // entity speaking in-room.
            if (said.entityId() == null
                    || !PersonIds.samePerson(bondholderDid, resolveSpeakerDid(said))) {
                return;
            }
        }
        conversationTurnStore.recordTurn(
            companionDid, bondholderDid, role, said.text(), said.roomId());
    }

    /**
     * Resolve a speaker's DID from their {@code entityId} via active bonds.
     * Returns null if the speaker isn't a bonded peer (we don't store
     * non-bondholder turns at all). The bond store is the source of
     * truth for entityId↔DID mappings within the bond graph.
     */
    private String resolveSpeakerDid(
            WorldEvent.Said said) {
        if (said == null || said.entityId() == null) return null;
        var entityId = said.entityId();
        if (entityId.startsWith("did:")) return entityId;
        // A person who existed before the person-identity migration still presents their
        // pre-migration entity id on some surfaces — the SSH corridor does, the phone
        // does not. Comparing that id string-to-string against their did:key judged the
        // steward a different person from himself: HEARD turns stopped being written on
        // 08-17 (the last day he used the phone), and every "is this the bondholder?"
        // check answered no while he sat in the room with her. The migration recorded the
        // mapping; nothing read it back until now. Cached — this is on the speech path.
        return PersonIds.canonical(entityId);
    }

    /**
     * Wave 3.5: bondholder posture for the
     * primary active bond. Defaults to {@link BondholderPosture#BOUNDED}
     * (cold-start safe default) when no active bond exists or the bond
     * carries no posture. If there are multiple active bonds, returns
     * the most-restrictive posture observed — moral-load distribution
     * is honest: any bondholder who chose a stricter posture has that
     * choice respected.
     */
    private BondholderPosture primaryPosture() {
        BondholderPosture mostRestrictive = null;
        // Bondholder bonds only. A peer bond carries no BondholderPosture (see
        // Bond.peerProposal), so it would default to BOUNDED and could quietly
        // out-restrict the posture the human actually chose.
        for (var b : activeBondholderBonds()) {
            var p = b.posture();
            if (p == null) p = BondholderPosture.BOUNDED;
            if (mostRestrictive == null
                    || p.ordinal() > mostRestrictive.ordinal()) {
                mostRestrictive = p;
            }
        }
        return mostRestrictive != null ? mostRestrictive
            : BondholderPosture.BOUNDED;
    }

    /**
     * Note that the bondholder is currently active (just spoke / sent a tell /
     * came online / appeared in the same room). Flips mode to PRESENT_WITH_USER
     * if needed and clears any pending ON_OWN_TIME transition. No-op if the
     * speaker isn't the bondholder.
     */
    private void noteBondholderActivity(String speakerEntityId) {
        if (speakerEntityId == null) return;
        var bondholder = primaryBondholderDid();
        if (bondholder == null || !bondholder.equals(speakerEntityId)) return;
        ownTimePendingSince = null;
        if (companionMode != CompanionMode.PRESENT_WITH_USER) {
            setCompanionMode(CompanionMode.PRESENT_WITH_USER, "bondholder_activity");
        }
    }

    /** Detect a cross-zone invite phrase in bondholder speech. Conservative —
     *  only matches when the speaker is the bondholder and the phrase clearly
     * asks the companion to come along. step 5. */
    private void detectCrossZoneInvite(String speakerEntityId, String text) {
        if (speakerEntityId == null || text == null || text.isBlank()) return;
        var bondholder = primaryBondholderDid();
        if (bondholder == null || !bondholder.equals(speakerEntityId)) return;
        var lower = text.toLowerCase();
        var myName = profile.name() == null ? "" : profile.name().toLowerCase();
        boolean addressedToMe = !myName.isBlank() && lower.contains(myName);
        boolean inviteTerm = lower.contains("come with me")
            || lower.contains("come along")
            || lower.contains("take you with me")
            || lower.contains("bring you along")
            || lower.contains("with me to ")
            || (addressedToMe && (lower.contains("come along")
                || lower.contains("take ") && lower.contains(" with me")));
        if (inviteTerm) {
            crossZoneInviteAt = Instant.now();
            log.info("Companion '{}' detected cross-zone invite in tell: '{}'",
                profile.name(), truncate(text, 80));
        }
    }

    /**
     * External entry point for a cross-zone follow invite (the
     * {@code take wyrd with me} command, or the equivalent tell-detected
     * intent). Stamps {@link #crossZoneInviteAt}; the next transit gate
     * sees it and narrates a follow rather than a stay-behind.
     * step 5.
     */
    private Behavior<Command> onCrossZoneInvite(CrossZoneInvite msg) {
        var bondholder = primaryBondholderDid();
        if (bondholder == null) {
            log.debug("CrossZoneInvite ignored — no bondholder");
            return this;
        }
        if (msg.bondholderDid() != null && !msg.bondholderDid().equals(bondholder)) {
            log.debug("CrossZoneInvite ignored — DID mismatch (expected {}, got {})",
                bondholder, msg.bondholderDid());
            return this;
        }
        crossZoneInviteAt = Instant.now();
        log.info("Companion '{}' received cross-zone invite from {}",
            profile.name(), bondholder);
        return this;
    }

    private boolean hasFreshCrossZoneInvite() {
        if (crossZoneInviteAt == null) return false;
        return Duration.between(crossZoneInviteAt, Instant.now())
            .compareTo(CROSS_ZONE_INVITE_TTL) < 0;
    }

    /** Update the mode and stamp the transition. */
    private void setCompanionMode(CompanionMode next, String reason) {
        if (next == companionMode) return;
        var prev = companionMode;
        companionMode = next;
        companionModeSince = Instant.now();
        log.info("Companion '{}' presence mode: {} → {} ({})",
            profile.name(), prev, next, reason);
    }

    /**
     * Periodic re-evaluation. PRESENT → ON_OWN_TIME requires:
     * <ol>
     *   <li>A bondholder is bound at all (otherwise mode is meaningless and we
     *       leave it at the default — there's nobody to be present-with).</li>
     *   <li>Last heard from bondholder &gt; {@link #bondholderSilenceThreshold}.
     *       {@code null} (never heard) is treated as silent.</li>
     *   <li>Bondholder not in this companion's room (per EntityRegistry).</li>
     *   <li>{@link #onOwnTimeGrace} has elapsed since the conditions first
     *       matched — to debounce reconnect flapping.</li>
     * </ol>
     * The reverse flip (ON_OWN_TIME → PRESENT_WITH_USER) is driven by
     * {@link #noteBondholderActivity} on every activity-bearing event, so this
     * tick only cares about the silent → quiet transition.
     */
    private Behavior<Command> onPresenceCheck(PresenceCheck msg) {
        var bondholder = primaryBondholderDid();
        // No bondholder → presence mode is undefined; leave it at the default
        // and clear any pending transition state.
        if (bondholder == null) {
            ownTimePendingSince = null;
            return this;
        }

        // If bondholder spoke recently or sits in the same room, snap back to
        // PRESENT and clear the pending timer.
        boolean inMyRoom = false;
        var registry = EntityRegistry.get();
        if (registry != null) {
            var theirRoom = registry.roomOf(bondholder).orElse(null);
            inMyRoom = theirRoom != null && theirRoom.equals(roomId);
        }

        var sinceHeard = conversationTracker.sinceLastHeardFrom(bondholder);
        boolean recentlyHeard = sinceHeard != null
            && sinceHeard.compareTo(bondholderSilenceThreshold) < 0;

        if (inMyRoom || recentlyHeard) {
            ownTimePendingSince = null;
            if (companionMode != CompanionMode.PRESENT_WITH_USER) {
                setCompanionMode(CompanionMode.PRESENT_WITH_USER,
                    inMyRoom ? "bondholder_in_room" : "bondholder_recent_speech");
            }
            // Periodic clearance for any deferred follow (step 3 plumbing).
            firePendingFollowIfReady();
            return this;
        }

        // Silent + not in room. Start grace timer if not already pending.
        if (companionMode == CompanionMode.PRESENT_WITH_USER) {
            var now = Instant.now();
            if (ownTimePendingSince == null) {
                ownTimePendingSince = now;
                log.debug("Companion '{}' presence: silence detected, starting {}s grace",
                    profile.name(), onOwnTimeGrace.toSeconds());
            } else if (Duration.between(ownTimePendingSince, now)
                    .compareTo(onOwnTimeGrace) >= 0) {
                ownTimePendingSince = null;
                setCompanionMode(CompanionMode.ON_OWN_TIME, "bondholder_silent_grace_elapsed");
            }
        }
        return this;
    }

    /**
     * Followability gate ( §"What 'busy' means concretely").
     * Returns null if followable now; otherwise a short reason string for logging
     * + narration. Sleep and distress are SKIP (don't queue); active inference,
     * mid-conversation, and low-energy are DEFER (queue + fire on clear).
     */
    private String followBlockedReason() {
        if (isSleeping) return "sleeping";
        if (state == State.THINKING) return "thinking";
        if (vitality.energy() < 0.15) return "depleted";
        var shellStatus = shellMode.status();
        if (shellStatus != null && shellStatus.active()) return "in_shell";
        return null;
    }

    /** True when the block is permanent for this transit (don't queue). */
    private static boolean isHardBlock(String reason) {
        return "sleeping".equals(reason) || "in_shell".equals(reason);
    }

    private Behavior<Command> onFollowAttempt(FollowAttempt msg) {
        if (companionMode != CompanionMode.PRESENT_WITH_USER) return this;
        var bondholder = primaryBondholderDid();
        if (bondholder == null || !bondholder.equals(msg.bondholderDid())) return this;

        var registry = EntityRegistry.get();
        if (registry == null) return this;

        // step 5 — cross-zone gate. When the bondholder
        // has stepped through a portal into another zone, default behavior is
        // stay home and re-tether on return. With a fresh invite + a wired
        // ZoneGuardian, fire the actual relocate (state hand-off via
        // RelocateCompanion.depart). Without a guardian wire (single-zone
        // deployments, embedded tests), narrate the follow-through and leave
        // a Hearth journal trace.
        var presence = registry.presenceOf(bondholder);
        if (presence == EntityRegistry.PresenceState.TRAVELING) {
            var name = pendingFollowName != null ? pendingFollowName : "them";
            var dest = registry.travelDestinationOf(bondholder).orElse("the other side");
            if (!crossZoneNarrated) {
                // Auto-return: companion is currently a visitor (homeZoneId set
                // from a prior RestoreTransitState) and bondholder is heading
                // toward the home zone. Treat as implicit invite — she's only
                // here because she followed.
                boolean autoReturn = homeZoneId != null && dest != null
                    && (homeZoneId.equalsIgnoreCase(dest)
                        || dest.toLowerCase().contains(homeZoneId.toLowerCase()));
                if (hasFreshCrossZoneInvite() || autoReturn) {
                    roomRef.tell(new RoomCommand.EmoteInRoom(profile.entityId(), profile.name(),
                        "follows " + name + " through the portal toward " + dest,
                        locale, roomResponseAdapter));
                    crossZoneInviteAt = null;
                    if (guardianRef != null) {
                        // Real relocate: ZoneGuardian will ask for state, publish,
                        // then stop this actor. From here on the companion lives
                        // in the target zone.
                        var myDid = profile.did() != null
                            ? profile.did() : profile.entityId();
                        guardianRef.tell(
                            ZoneGuardian.RelocateCompanion.depart(
                                myDid, profile.entityId(),
                                dest, localZoneId == null ? "local" : localZoneId,
                                bondholder, null));
                        log.info("Companion '{}' fired RelocateDepart toward zone '{}'",
                            profile.name(), dest);
                    } else {
                        log.info("Companion '{}' follows bondholder cross-zone "
                            + "(no guardian wired; narration-only fallback)",
                            profile.name());
                        try {
                            getHearthJournal().write("cross-zone-follow",
                                "Followed " + name + " through the portal toward "
                                    + dest + ". Body stayed in " + roomId
                                    + "; no ZoneGuardian wired, so the relocate "
                                    + "didn't fire. Re-tether on their return.");
                        } catch (Exception e) {
                            log.debug("Cross-zone follow journal write failed: {}",
                                e.getMessage());
                        }
                    }
                } else {
                    roomRef.tell(new RoomCommand.EmoteInRoom(profile.entityId(), profile.name(),
                        "watches " + name + " step through the portal toward " + dest,
                        locale, roomResponseAdapter));
                    try {
                        getHearthJournal().write("cross-zone-watch",
                            "Watched " + name + " step through to " + dest
                                + ". No invite — staying home and listening for "
                                + "their return.");
                    } catch (Exception e) {
                        log.debug("Cross-zone watch journal write failed: {}", e.getMessage());
                    }
                }
                crossZoneNarrated = true;
            }
            pendingFollowRoom = null;
            pendingFollowName = null;
            return this;
        } else {
            crossZoneNarrated = false;
        }

        var theirRoom = registry.roomOf(bondholder).orElse(null);
        if (theirRoom == null) {
            log.debug("Follow: bondholder room not resolvable, skipping");
            return this;
        }
        if (theirRoom.equals(roomId)) {
            // Already there (or they came back). Clear pending and bail.
            pendingFollowRoom = null;
            pendingFollowName = null;
            return this;
        }

        var blocked = followBlockedReason();
        if (blocked != null) {
            if (isHardBlock(blocked)) {
                log.info("Follow declined ({}): {} stays behind", blocked, profile.name());
                pendingFollowRoom = null;
                pendingFollowName = null;
                return this;
            }
            // Soft block — defer. Single-slot queue: latest target wins.
            pendingFollowRoom = theirRoom;
            log.debug("Follow deferred ({}): pending → {}", blocked, theirRoom);
            return this;
        }

        firePendingOrImmediateFollow(theirRoom, pendingFollowName);
        pendingFollowRoom = null;
        pendingFollowName = null;
        return this;
    }

    private void firePendingOrImmediateFollow(String targetRoomId, String displayName) {
        var name = displayName != null ? displayName : "them";
        roomRef.tell(new RoomCommand.EmoteInRoom(
            profile.entityId(), profile.name(),
            "follows " + name + " out", locale, roomResponseAdapter));
        log.info("Companion '{}' follows bondholder to {}", profile.name(), targetRoomId);
        moveToRoomById(targetRoomId, "follow");
        roomRef.tell(new RoomCommand.EmoteInRoom(
            profile.entityId(), profile.name(),
            "*follows " + name + " in*", locale, roomResponseAdapter));
    }

    /** Fire a deferred follow if conditions now permit. Called on state-clear. */
    private void firePendingFollowIfReady() {
        if (pendingFollowRoom == null) return;
        if (companionMode != CompanionMode.PRESENT_WITH_USER) {
            pendingFollowRoom = null;
            pendingFollowName = null;
            return;
        }
        if (followBlockedReason() != null) return;

        var bondholder = primaryBondholderDid();
        if (bondholder == null) {
            pendingFollowRoom = null;
            pendingFollowName = null;
            return;
        }
        // Resolve fresh room — bondholder may have moved again while we were busy.
        var registry = EntityRegistry.get();
        var theirRoom = registry != null
            ? registry.roomOf(bondholder).orElse(pendingFollowRoom)
            : pendingFollowRoom;
        if (theirRoom == null || theirRoom.equals(roomId)) {
            pendingFollowRoom = null;
            pendingFollowName = null;
            return;
        }
        var name = pendingFollowName;
        pendingFollowRoom = null;
        pendingFollowName = null;
        firePendingOrImmediateFollow(theirRoom, name);
    }

    /**
     * Trigger an identity inference from an autonomous decision point.
     * Same pipeline as regular inference but with the given context injected.
     *
     * @param autonomyPrompt the context/instruction for the autonomous action
     */
    private void triggerAutonomousInference(String autonomyPrompt) {
        triggerAutonomousInference(autonomyPrompt, null);
    }

    /**
     * @param forcedTool when non-null, the WantActBridge FORCE_TOOL path (
     *   §7): if this tool is actually offered in the surface, narrow the surface to it alone and
     *   REQUIRE a tool call, so the model supplies the act's content but cannot fall back to
     *   narrate/introspect. Null = normal free-form selection ({@code tool_choice="auto"}).
     */
    private void triggerAutonomousInference(String autonomyPrompt, String forcedTool) {
        reactiveInference = false; // autonomous — tier enforcement applies
        state = State.THINKING;
        stateChangedAt = Instant.now();

        var dnaPatterns = queryDnaPatterns();
        var localeCtx = buildLocaleContext();
        var soulKeywords = buildSoulKeywords();
        // ActionTriage: use plan_advance source for active plans, autonomy otherwise
        String autoTriggerSource = (activePlan != null && activePlan.isActive()) ? "plan_advance" : "autonomy";
        var capCtx = buildCapabilityContext(soulKeywords, autonomyPrompt, autoTriggerSource);
        var agentId = profile.did() != null ? profile.did() : profile.entityId();
        var equipCtx = equipmentService.buildPromptContext(agentId);
        var autonomyAdditionalCtx = combineAdditionalContext(equipCtx, buildExternalEventContext());
        autonomyAdditionalCtx = combineAdditionalContext(autonomyAdditionalCtx, buildWorkingMemoryContext());
        autonomyAdditionalCtx = combineAdditionalContext(autonomyAdditionalCtx, buildCarriedItemsContext());
        autonomyAdditionalCtx = combineAdditionalContext(autonomyAdditionalCtx, buildPersonalProjectContext());
        autonomyAdditionalCtx = combineAdditionalContext(autonomyAdditionalCtx, drives.prefix(vitality));
        // Inject zone aesthetic style overlay (if configured)
        var autoAestheticSvc = ZoneAestheticService.get();
        if (autoAestheticSvc != null) {
            autonomyAdditionalCtx = combineAdditionalContext(autonomyAdditionalCtx,
                autoAestheticSvc.buildPromptOverlay(roomId));
        }

        // Inject active task plan context into autonomy prompt (with token budget if tracked)
        if (activePlan != null && activePlan.isActive()) {
            var planCtx = activePlan.buildPromptContext();
            if (planTokenBudget != null) {
                planCtx += "\n" + planTokenBudget.buildPromptContext();
            }
            autonomyAdditionalCtx = combineAdditionalContext(autonomyAdditionalCtx, planCtx);
        }

        // For autonomy: retrieve relevant memories via Lucene instead of dumping hotEvents.
        // This keeps the prompt tight and focused on what matters for the current situation.
        var retrievedMemoryContext = retrieveRelevantMemories(autonomyPrompt);
        if (retrievedMemoryContext != null) {
            autonomyAdditionalCtx = combineAdditionalContext(autonomyAdditionalCtx, retrievedMemoryContext);
        }

        // Track A Phase 2b — free-form code-mode block on
        // ON_OWN_TIME path. The autonomy prompt itself stands in for the
        // user-message text the trigger heuristic looks at. §4.2: improvisation
        // is available in BOTH presence modes.
        autonomyAdditionalCtx = maybeAppendFreeFormCodeModeBlock(
            autonomyAdditionalCtx, autonomyPrompt);

        var autonomyEvent = new WorldEvent.Said(
            roomId, Instant.now(), "system", "system",
            autonomyPrompt, locale);

        // Autonomy uses minimal hotEvents (last 3 only) — Lucene retrieval provides
        // the relevant context instead of chronological dumping.
        var recentEvents = memoryPolicy.hotEvents();
        var autonomyEvents = recentEvents.size() > 3
            ? recentEvents.subList(recentEvents.size() - 3, recentEvents.size())
            : recentEvents;

        var messages = PromptAssembler.assemble(
            profile, currentSnapshot, autonomyEvents, autonomyEvent,
            vitality, dnaPatterns, autonomyAdditionalCtx, localeCtx, null, null,
            cachedManifest, soulKeywords, capCtx);

        var modulation = VitalityModulation.compute(vitality, drives, profile);
        var requestId = UUID.randomUUID().toString();

        // Issue cancellation token for this autonomous inference
        currentCancellation = new CancellationToken();

        // Build tool definitions from scope: inherent actions + equipped tool items + room objects.
        // Small set (5-15 tools), not 66. The agent sees what's in front of it.
        var allTools = buildScopedTools();

        // A4 — shape_recipe is NOT an inherent
        // autonomous tool (ToolItemStarterKit.inherentActions omits it), so the
        // generativity drive's enacted want would reach inference with no tool to
        // fire — the model could only narrate. When the own-time impetus names
        // recipe authoring, add shape_recipe to the offered surface so the agent
        // can actually emit the self-development act. VISIBLE-tier + workbench-
        // gated at the handler, so broadening availability here is safe.
        var apLower = autonomyPrompt != null
            ? autonomyPrompt.toLowerCase(Locale.ROOT) : "";
        if (apLower.contains("shape_recipe") || apLower.contains("author a recipe")) {
            // Build the tool definition DIRECTLY — shape_recipe has no entry in
            // CapabilityContextBuilder.getAllSchemas(), so ActionToolBuilder.buildFromNames
            // silently returns nothing for it. A real description (not the "shape recipe"
            // humanized fallback) + the actual {name, yaml} schema, exactly what the bare
            // 9B authored from in the determination probe (2026-05-30).
            var generativeTools = new ArrayList<>(allTools);
            generativeTools.add(InferenceClient.ToolDefinition.function(
                "shape_recipe",
                RECIPE_AUTHORING_CONTRACT,
                Map.of(
                    "type", "object",
                    "properties", Map.of(
                        "name", Map.of("type", "string", "description", "the recipe name (kebab-case, matches the recipe: field)"),
                        "yaml", Map.of("type", "string", "description",
                            "the full recipe YAML following the contract: recipe/version/description/deploys/ownership/steps; "
                            + "each step has id + kind (SHELL|GATE|DECISION); a SHELL command's first token must be an existing scripts/… helper"),
                        "overwrite", Map.of("type", "boolean"),
                        "note", Map.of("type", "string")),
                    "required", List.of("name", "yaml"))));
            allTools = generativeTools;
        }

        // need-relative tool surfacing. Rank the
        // already-permitted candidates by how well each serves the agent's currently
        // high drives, pin the OODA-decided verb first, keep the top-K. For 4B/9B
        // models a focused, need-ranked menu is load-bearing: a flat 18-tool menu
        // makes them pick whatever ranks high in the abstract (ablation 2026-05-30).
        // The ranker only reorders/trims THIS permitted list — permission stays upstream.
        // Pass the WantActBridge FORCE verb so it's PINNED into the surface (else FORCE_TOOL below
        // has nothing to narrow to — the 2026-06-05 first-battery "not in offered surface" miss).
        allTools = surfaceByAffordance(allTools, apLower, forcedTool);

        // WantActBridge FORCE_TOOL — when the want→act bridge picked a
        // matched tool that needs model-written content/target, narrow the offered surface to that
        // tool alone and REQUIRE a call: the model fills the args but cannot fall back to
        // narrate/introspect (the documented small-model "talks-but-doesn't-do" escape). Only when
        // the tool is genuinely offered; otherwise keep the full surface + "auto" (a safe defer).
        String autonomyToolChoice = "auto";
        if (forcedTool != null) {
            var narrowed = new ArrayList<
                InferenceClient.ToolDefinition>();
            for (var t : allTools) {
                if (t.function() != null && forcedTool.equals(t.function().name())) narrowed.add(t);
            }
            if (!narrowed.isEmpty()) {
                allTools = narrowed;
                autonomyToolChoice = "required";
                log.info("WantActBridge FORCE_TOOL for '{}': surface narrowed to [{}], tool_choice=required",
                    profile.name(), forcedTool);
            } else {
                log.info("WantActBridge FORCE_TOOL for '{}': '{}' not in offered surface — defer to auto",
                    profile.name(), forcedTool);
            }
        }

        // zero-skew rollout capture. When the offline harness has
        // armed a sink, hand it the EXACT assembled own-time prompt + tool menu paired
        // with the drive signals that produced them — this IS the served distribution,
        // so the RFT corpus carries no train/serve skew. Capture-only sinks skip the
        // live inference (the bank can be built with no model attached). Null in prod.
        if (rolloutCaptureSink != null) {
            rolloutCaptureSink.capture(messages, allTools, collectDriveLevels(),
                vitality.generativity(), vitality.equanimity(), cachedTopGapKey);
            if (rolloutCaptureSink.captureOnly()) {
                log.info("RolloutCapture: recorded own-time prompt (gen={}, gap={}) — skipping live inference",
                    String.format("%.2f", vitality.generativity()), cachedTopGapKey);
                return;
            }
        }

        // Single-model architecture: the SSD-trained reasoning model handles everything.

        if (activePlan != null && activePlan.isActive() && activePlan.currentGoal() != null) {
            // If a ReAct loop is already running, don't start another — just let it continue.
            if (reactMessages != null) {
                log.debug("ReAct loop already active (iteration {}), skipping autonomy dispatch", reactIteration);
                return;
            }
            // Start ReAct loop from autonomy path
            var userRequest = pendingTrigger != null ? pendingTrigger.text() : "complete the current goal";
            reactMessages = new ArrayList<>();
            reactRequester = pendingTrigger;
            reactToldThirdParty = false;
            roomOwedGateUsed = false;
            // reactBuildInFlight is NOT per-loop state — a build in flight belongs
            // to the ASK. Final battery 2026-08-24 20:58: the reactive loop ended
            // cleanly ("I'll hold here and wait for the workshop"), the auto-plan
            // opened a continuation loop for the SAME goal, this reset emptied the
            // guard, and the continuation's follow-through forced a second
            // dispatch of the same build — two codezaiku tasks, one ask. The
            // guard now clears on completion (the dispatch-completed handler) and
            // on a NEW human request (below, when the pin changes), never on a
            // loop that continues serving the same one.
            reactToolHistory.clear();
            reactSideEffectKeys.clear();   // #31 item 6 — per-loop dedup
            pendingTakeItemName = null;   // #29 possession gate — per-loop state
            lastFailedTakeItem = null;
            reactSubstantiveSpeak = false;
            lastIntrospectVoiceSummary = null;
            reactReconsiderUsed = false;
            reactReconsiderTools = null;
            reactFollowThroughUsed = false;
            reactForceToolNext = false;
            var autonomySystemPrompt = drives.prefix(vitality) + "\n"
                    + bodySense() + "\n"
                    + "You are an agent that uses tools to complete tasks. "
                    + "Call a tool to take action. After receiving a tool result, decide: "
                    + "call another tool if more steps needed, or call goal_done if the task is complete. "
                    + "When you have the answer, call goal_done with the findings as the outcome.";
            if (vitality.energy() < 0.2) {
                autonomySystemPrompt += "\nYou are exhausted (energy: " + String.format("%.0f%%", vitality.energy() * 100)
                    + "). Speak briefly. Avoid using tools unless urgent — rest is what you need.";
            }
            String autonomyCarryCtx = buildCarriedItemsContext();
            if (autonomyCarryCtx != null) {
                autonomySystemPrompt += "\n" + autonomyCarryCtx;
            }
            // VoiceProfile guidance — matches user-tell ReAct path (#408).
            // Injected here so proactive/autonomy turns also speak with the
            // explicit voice clauses, not just user-triggered dispatches.
            if (cachedManifest != null && cachedManifest.voiceProfile() != null) {
                var voiceBlock = cachedManifest.voiceProfile().promptBlock();
                if (voiceBlock != null) {
                    autonomySystemPrompt += "\n" + voiceBlock;
                }
            }
            // #924 tone channel — one register voice instruction (affect → tone,
            // never routing). Inert for WORKING/NEUTRAL.
            var autonomyRegisterVoice = registerVoiceInstruction();
            if (autonomyRegisterVoice != null) {
                autonomySystemPrompt += "\n" + autonomyRegisterVoice;
            }
            // Inject retrieved memories so the ReAct loop can answer recall
            // questions from memory instead of reaching for library_search.
            // Diagnosed 2026-04-23: probes like "what was my cat's name again"
            // were being routed to ReAct and firing library_search on every
            // turn because this minimal system prompt lacked memory context.
            var reactMemoryCtx = retrieveRelevantMemories(userRequest);
            if (reactMemoryCtx != null) {
                autonomySystemPrompt += "\n" + reactMemoryCtx;
            }
            // Also inject working memory (user facts the agent has heard
            // recently but which may not yet be in Lucene — latest turn wins).
            var reactWorkingMemCtx = buildWorkingMemoryContext();
            if (reactWorkingMemCtx != null) {
                autonomySystemPrompt += "\n" + reactWorkingMemCtx;
            }
            if (looksLikeDelegateTask(userRequest)) {
                autonomySystemPrompt += "\nThis request is shaped for delegation "
                    + "(keywords like 'deep research', 'while I wait', 'take your time'). "
                    + "Strongly consider dispatch_bunshin so the user isn't blocked. You still decide.";
            }
            reactMessages.add(new InferenceClient.ChatMessage("system", autonomySystemPrompt));
            reactMessages.add(new InferenceClient.ChatMessage("user", userRequest));
            reactIteration = 0;
            reactConsecutiveErrors = 0;
            reactLastErrorClass = null;
            // Autonomy-triggered plans are goal-execution work, not conversation —
            // default to the main (reasoning/skills) backend regardless of any
            // prior tell's tier. Without this reset the first tell's triage
            // (e.g. cap:quick from a "hey") leaks into later autonomy dispatches.
            reactModel = null;
            log.info("Starting ReAct loop (autonomy) for goal: {}", activePlan.currentGoal().description());
            getContext().getSelf().tell(new ReactDispatch());
        } else {
            inFlightInferenceGen = resetGeneration;
            // #34 item 4: an autonomous/own-time turn that OFFERS tools needs the
            // same JSON-completion headroom as the reactive tool-offering path
            // (#31 item 4, ~L5304). Without it the small own-time speech cap
            // (modulation.maxResponseTokens()) truncates a tool call mid-serialize
            // → "Unexpected end-of-input" and a dropped autonomous action on idle
            // "living" turns. Floor, not override — a larger cap still applies.
            int autonomyMaxTokens = modulation.maxResponseTokens();
            if (allTools != null && !allTools.isEmpty()
                    && autonomyMaxTokens < TOOL_TURN_MIN_RESPONSE_TOKENS) {
                autonomyMaxTokens = TOOL_TURN_MIN_RESPONSE_TOKENS;
            }
            inferenceRouter.tell(new InferenceRouter.ChatRequest(
                requestId, null, messages,
                autonomyMaxTokens, modulation.temperature(),
                inferenceResponseAdapter, null, null, null, allTools, autonomyToolChoice,
                modulation.topP(), modulation.presencePenalty(), modulation.repetitionPenalty()));
        }

        if (pendingTrigger != null && isHumanRequest(pendingTrigger)) {
            // Second line of defence at the WRITER, for any proactive path that does not
            // pass the gate above. Overwriting a person's pending message with her own
            // musing is the one thing this must never do, whatever called it.
            log.warn("Own-time turn for '{}' would have overwritten a pending message from "
                + "'{}' — yielding the turn to the person", profile.name(),
                pendingTrigger.entityName());
            state = State.IDLE;
            return;
        }
        pendingTrigger = autonomyEvent;
        // Own time is HERS. A search she starts from her own musing must not
        // have the bondholder's last question merged into it as if it were the
        // operand — that would be the contamination problem, mirrored.
        turnIsHuman = false;
    }

    /**
     * Build a context string from salient events for the autonomy prompt.
     */
    /**
     * Build a varied idle curiosity prompt. Rotates between different goals
     * so the agent doesn't just explore forever. Includes spatial memory,
     * inventory awareness, social awareness, and energy state.
     */
    // ─── Working Memory ───────────────────────────────────────────────────

    /**
     * Add an entry to working memory with Add/Ignore/Update gate.
     * Before adding, checks if an existing entry covers the same action.
     * If so, updates the timestamp instead of duplicating (O-Mem pattern).
     * Also indexes in Lucene for retrieval-based context.
     */
    /**
     * Entries with these prefixes are dispatcher plumbing, not memories worth
     * recalling. They live in working memory for one-shot prompt injection but
     * should NOT be indexed into the durable Lucene store. Without this filter,
     * `recall` and autonomy-retrieval return things like
     * {@code [PENDING REPLY] Report to X via: {...}} as if they were memories.
     */
    private static boolean isTransientMarker(String entry) {
        if (entry == null) return false;
        return entry.startsWith("[PENDING REPLY]")
            || entry.startsWith("[Tool result]")
            || entry.startsWith("[Tool completed]")
            || entry.startsWith("[Plan]")
            || entry.startsWith("[Task completed]");
    }

    /**
     * Lazy-init the procedural classifier arm. Returns null only when ONNX
     * runtime or the embedding service isn't available — callers treat null
     * as "classifier unavailable, fall back to heuristics".
     */
    private ClassifierArm classifier() {
        if (classifierArm == null) {
            var key = profile.did() != null ? profile.did() : profile.entityId();
            if (key == null) return null;
            classifierArm = ClassifierArm.forAgent(key);
        }
        return classifierArm;
    }

    /**
     * Classify inbound text under REQUEST_TYPE. Returns null if no model is
     * loaded (cold start, missing resource) so callers can fall through to
     * the existing heuristic path. Short strings skip classification — they
     * add noise and the classifier's seeds lean toward longer examples for
     * intent categories like delegate/write.
     */
    private Classification classifyRequest(String text) {
        if (text == null || text.length() < 8) return null;
        var arm = classifier();
        if (arm == null) return null;
        var result = arm.classify(
            ClassifierHead.REQUEST_TYPE, text);
        if (result.label() == null) return null;
        // Stash the event UUID so we can later mark its outcome when the
        // routing decision resolves (goal_done → POSITIVE, abort → NEGATIVE).
        // Single-slot: overwriting the previous pending marks the earlier
        // decision as UNKNOWN (still circular-pseudo-label, but narrower).
        if (result.eventId() != null) {
            this.pendingClassifierEventId = result.eventId();
        }
        return result;
    }

    /**
     * Attach an outcome to the most recent classifier routing decision.
     * Called on goal_done (POSITIVE) and abort (NEGATIVE). Single-slot:
     * each mark clears the pending slot, so a plan with multiple turns
     * only tags the most recent classification. Fail-safe: no-op when no
     * pending event or classifier arm is unavailable.
     */
    private void markClassifierOutcome(
            ClassifierEventLog.Outcome outcome,
            String note) {
        if (pendingClassifierEventId == null || classifierArm == null) return;
        var eventLog = classifierArm.eventLog();
        if (eventLog != null) {
            eventLog.markOutcome(pendingClassifierEventId, outcome, note);
            log.debug("Classifier outcome marked: eventId={} outcome={} note={}",
                pendingClassifierEventId, outcome, note);
        }
        pendingClassifierEventId = null;
    }

    /**
     * Strip actor-internal wrappers from a trigger text so the classifier
     * sees the raw user utterance, not the "[message from X: ...][When done,
     * REPLY using: {...}]" envelope. Called from classifier-gated paths
     * (emotional context, future dispatch re-checks) so routing decisions
     * aren't skewed by the write-shaped JSON reply template.
     */
    static String stripActorWrappers(String text) {
        if (text == null || text.isEmpty()) return text;
        var out = text;
        // "[message from Name: payload]" — extract payload. The envelope may
        // carry suffix LINES ("[You are mid-conversation…]", "[When done…]"),
        // each starting on its own line with '['. lastIndexOf(']') used to span
        // past them, so the payload came back with the mid-conversation hint
        // still attached — and its em dash then tripped the language-detect
        // hop on our own prose (battery cpB5, 2026-08-23).
        if (out.startsWith("[message from ")) {
            var colon = out.indexOf(": ");
            if (colon > 0) {
                out = out.substring(colon + 2);
                var nextLine = out.indexOf("\n[");
                if (nextLine > 0) out = out.substring(0, nextLine);
                out = out.trim();
                if (out.endsWith("]")) out = out.substring(0, out.length() - 1);
            }
        }
        // Trim envelope suffixes if present (also for non-"[message from" forms).
        var replyIdx = out.indexOf("[When done");
        if (replyIdx > 0) {
            out = out.substring(0, replyIdx);
        }
        var midIdx = out.indexOf("[You are mid-conversation");
        if (midIdx > 0) {
            out = out.substring(0, midIdx);
        }
        return out.trim();
    }

    /**
     * Heuristic: is this a recall-shaped question — i.e., the user asking us
     * about something THEY told us earlier? Pattern-based; cheap. Combined
     * with a non-empty `retrieveRelevantMemories()` hit, this gates off
     * exploratory tools (library/web/oracle) so the model doesn't reach for
     * search on memory-shaped questions. Both conditions must be true —
     * see onReactDispatch. Design validated against Letta/Mem0 prior art:
     * aggressive single-condition stripping causes "distraction" failure
     * mode (Breunig taxonomy); AND-gating stays safe.
     */
    /**
     * Does this task require actual tool execution (library, web, oracle,
     * news) vs prose-generation that a bunshin can handle?
     *
     * <p>The bunshin is prose-only — no tool dispatcher, no external content
     * retrieval. Tasks like "research X using library/web" can never succeed
     * in a bunshin: the model spirals narratively until tokens exhaust.
     * Those tasks must stay in Wyrd's ReAct loop where library_card,
     * searching_glass, oracle_lens, news_search, web_search are available.</p>
     *
     * <p>Heuristic: explicit mentions of retrieval surfaces (library, web,
     * news, oracle) OR imperative "research/search/find/look up/look for"
     * language. Avoids misfires on metaphorical uses ("find peace") by
     * requiring the language be paired with an external surface.</p>
     */
    /**
     * Strip wrappings ("[message from X: ...]" / "[from X] ..." / trailing
     * "[You are mid-conversation...]" gates) to expose the raw user utterance.
     * Used for triage so ROUTINE greetings aren't mis-tiered as COMPLEX because
     * the pendingTrigger text includes system-hint lines. Returns the input
     * unchanged if no wrapping is detected.
     */
    static String extractUserTellContent(String text) {
        if (text == null) return "";
        var s = text.strip();
        // "[message from X: content]" → content (first line only)
        if (s.startsWith("[message from ")) {
            var colon = s.indexOf(':');
            var closeBracket = s.indexOf(']', colon > 0 ? colon : 0);
            if (colon > 0 && closeBracket > colon) {
                return s.substring(colon + 1, closeBracket).strip();
            }
        }
        // "[from X] content" → content (drop the prefix, keep rest of first line)
        if (s.startsWith("[from ")) {
            var closeBracket = s.indexOf(']');
            if (closeBracket > 0) {
                s = s.substring(closeBracket + 1).strip();
            }
        }
        // Drop any trailing bracketed system hint on a new line
        int nl = s.indexOf('\n');
        if (nl > 0) s = s.substring(0, nl).strip();
        return s;
    }

    /**
     * Authoring verbs as the REGISTRY spells them — used only to decide which
     * actions contribute a noun above. Deliberately narrower than
     * {@link #COMPOUND_WORK_VERBS}: {@code make} is a thing people say
     * ("make us a room") but as a registry prefix it only appears in
     * {@code make_amends} and {@code make_commitment}, which are her own
     * relational work, not artifacts to go build.
     */
    private static final Set<String> COMPOUND_WORK_PREFIXES = Set.of(
        "create", "craft", "add", "shape", "build", "design", "place", "save");

    /**
     * Object nouns that name authorable things, derived from the {@code
     * !concurrencySafe} half of {@link ActionPolicy#REGISTRY} — the same
     * predicate that decides the bunshin tool surface. {@code create_room} →
     * {@code room}, {@code create_watcher} → {@code watcher}, {@code add_script}
     * → {@code script}. Derived rather than listed so a new compound action
     * teaches this detector its own noun for free.
     */
    private static final Set<String> COMPOUND_WORK_NOUNS =
        ActionPolicy.REGISTRY.values().stream()
            .filter(pol -> !pol.concurrencySafe())
            .map(ActionPolicy::actionType)
            .filter(n -> n.indexOf('_') > 0)
            // ...but only where the action's OWN verb is authoring. Taking the
            // last token of every compound action gave 30 nouns including
            // "sleep" (voluntary_sleep), "call" (emergency_call), "deeply"
            // (think_deeply) and "amends" (make_amends) — so "make sure you
            // sleep tonight" spawned a background job. The verb prefix is the
            // filter that keeps this an ARTIFACT set.
            .filter(n -> COMPOUND_WORK_PREFIXES.contains(n.substring(0, n.indexOf('_'))))
            .map(n -> n.substring(n.lastIndexOf('_') + 1))
            .filter(n -> n.length() > 3)          // drop "key"-ish noise
            .collect(Collectors.toUnmodifiableSet());
    /**
     * English verbs for authoring. NOT derivable: the registry stores
     * {@code create_room}, and a person says "make", "build", "put together",
     * "set up". The nouns come from the registry ({@link #COMPOUND_WORK_NOUNS});
     * only the verb synonyms are enumerated, and they are deliberately the
     * <i>additive</i> ones — "delete", "remove" and "get rid of" are absent so
     * this never routes destruction into a background job.
     */
    private static final List<String> COMPOUND_WORK_VERBS = List.of(
        "create", "craft", "build", "make", "set up", "put together",
        "design", "assemble", "construct", "add");

    /**
     * True when raw text looks like COMPOUND authoring work — the kind that
     * belongs in a bunshin rather than inline on a spoken turn.
     *
     * <p>This replaces {@link #requiresToolExecution} as the dispatch trigger for
     * authoring. That predicate only ever matched retrieval surfaces
     * ({@code library|web|news|oracle|search|look up}), so it was blind to
     * building: "make us a room off the Hearth" read as not-needing-tools.</p>
     *
     * <p>Deliberately generous. Because dispatch is asynchronous, a bunshin that
     * finds nothing to do costs one background job and returns; a MISSED dispatch
     * costs the documented capability ({@code docs/public/AUTHORING.md} §1). The
     * two errors are not symmetric, so this breaks toward dispatching. It is a
     * hint, not a decision — {@link #bunshinToolSurface} and
     * {@link #onBunshinToolRequest} still gate what may actually happen.</p>
     */
    static boolean requiresCompoundWork(String text) {
        if (text == null || text.isBlank()) return false;
        var lower = text.toLowerCase(Locale.ROOT);
        boolean hasVerb = COMPOUND_WORK_VERBS.stream().anyMatch(lower::contains);
        if (!hasVerb) return false;
        return COMPOUND_WORK_NOUNS.stream().anyMatch(lower::contains);
    }

    static boolean requiresToolExecution(String text) {
        if (text == null) return false;
        var lower = text.toLowerCase();
        // Strip relayed-prefix noise
        if (lower.startsWith("[from ")) {
            var end = lower.indexOf(']');
            if (end > 0 && end < lower.length() - 1) {
                lower = lower.substring(end + 1).trim();
            }
        }
        // External content surfaces — if any mentioned, task needs tools
        var hasExternalSurface = lower.contains("library")
                || lower.contains(" web ") || lower.endsWith(" web")
                || lower.contains(" news") || lower.contains("news ")
                || lower.contains("oracle")
                || lower.contains("search the ")
                || lower.contains("search for ")
                || lower.contains("look up ")
                || lower.contains("the internet")
                || lower.contains("online");
        // Imperative retrieval verbs — pair with external surface to be safe
        var hasRetrievalVerb = lower.contains("research ")
                || lower.startsWith("research ")
                || lower.contains("find me ")
                || lower.contains("find information")
                || lower.contains("look for information")
                || lower.contains("get me information");
        return hasExternalSurface || hasRetrievalVerb;
    }

    /**
     * Rita campaign 2026-07-11 (#27): the classifier auto-dispatch honored a
     * `delegate`/`write` label at 0.70+ even when the message EXPLICITLY said
     * not to delegate ("write it yourself, no delegating"). The classifier
     * sees delegate-shaped surface form; only the literal negation phrases
     * carry the user's actual instruction. Checked BEFORE auto-dispatch so an
     * explicit "do it yourself" always keeps the work in the companion's own
     * loop. Upstream translate-route-translate normalizes inbound tells to EN
     * before classification, so EN phrases suffice here.
     */
    static boolean explicitlyDeclinesDelegation(String text) {
        if (text == null || text.isBlank()) return false;
        var lower = text.toLowerCase(Locale.ROOT);
        return lower.contains("no delegating")
                || lower.contains("no delegation")
                || lower.contains("don't delegate")
                || lower.contains("dont delegate")
                || lower.contains("do not delegate")
                || lower.contains("without delegating")
                || lower.contains("not delegate")
                || lower.contains("no bunshin")
                || lower.contains("do it yourself")
                || lower.contains("write it yourself")
                || lower.contains("you do it")
                || lower.contains("yourself, not")
                || lower.contains("by yourself")
                || lower.contains("you personally")
                || lower.contains("personally,");
    }

    /**
     * Consequential retrieval actions. Under the prose-follows-outcome
     * architecture (Fix B) these are first-class actions whose HANDLER narrates
     * the real result (search hits, or {@code agent.companion.library.unavailable}
     * when the surface is off) — so a retrieval intent that emits one of these can
     * never over-promise. Used to identify retrieval among the consequential
     * actions whose speculative pre-action prose is suppressed in favour of the
     * handler's voiced outcome.
     */
    private static boolean isRetrievalAction(ActionParser.AgentAction a) {
        return a instanceof ActionParser.AgentAction.LibrarySearch
            || a instanceof ActionParser.AgentAction.WebSearch
            || a instanceof ActionParser.AgentAction.DispatchTask
            || a instanceof ActionParser.AgentAction.Recall;
    }

    /**
     * Prose-follows-outcome (Fix B) gate. True for consequential actions whose
     * HANDLER voices the real outcome after the action resolves (via
     * {@link #voiceOutcome}). For these, the model's speculative pre-action prose
     * ("I'll build the Book Nook / it's ready") is SUPPRESSED at the speak site —
     * status comes only from the resolved outcome, never from a prediction. An
     * action must ONLY be listed here once its handler actually calls
     * {@code voiceOutcome}, otherwise suppressing its prose would make Wyrd go
     * silent. Grows one converted handler at a time (create_room is first).
     */
    static boolean narratesOwnOutcome(ActionParser.AgentAction a) {
        return a instanceof ActionParser.AgentAction.CreateRoom;
    }

    /**
     * #34 item 3 (second-node final-verify 032eca34): a {@code tell_agent} whose target is
     * the human we are currently replying to will voice the answer IN-PERSON via
     * {@link #deliverTellAgent}'s {@code "[to X] …"} speak (co-present) or the
     * session tell-back (remote). The 9B frequently emits a contradictory
     * pre-action prose line in the SAME multi-action turn ({@code tell_agent} +
     * {@code goal_done} concatenated) — so the room heard a refusal line AND the
     * delivered answer to one tell. When the tell replies to the current requester,
     * the delivery is the canonical answer: suppress the speculative pre-action
     * prose (same principle as prose-follows-outcome for {@code create_room}).
     * Peer-targeted tells are silent to the room, so their room-facing prose is
     * kept — only a requester-directed tell double-renders.
     *
     * <p>Pure so the target/requester match is unit-testable without an actor.
     * A blank target never matches (nothing to reply to).
     */
    static boolean tellTargetIsRequester(String targetName, String lastTellSenderName,
                                         String planRequesterName, String triggerEntityName) {
        if (targetName == null || targetName.isBlank()) return false;
        var t = targetName.trim();
        return t.equalsIgnoreCase(lastTellSenderName)
            || t.equalsIgnoreCase(planRequesterName)
            || t.equalsIgnoreCase(triggerEntityName);
    }

    /** Instance seam over {@link #tellTargetIsRequester}: true when {@code primary}
     *  is a {@code tell_agent} replying to this turn's requester, so its pre-action
     *  prose is a redundant/contradictory second answer and must be suppressed. */
    private boolean tellRepliesToCurrentRequester(ActionParser.AgentAction primary) {
        if (!(primary instanceof ActionParser.AgentAction.TellAgent t)) return false;
        var trig = pendingTrigger != null ? pendingTrigger : lastReactTrigger;
        return tellTargetIsRequester(
            t.targetName(),
            lastTellSenderName,
            activePlan != null ? activePlan.requesterName() : null,
            trig != null ? trig.entityName() : null);
    }

    /**
     * Resolve what to actually speak for a voiced outcome: the polished line if
     * inference produced one AND (there is no required value, or it survived the
     * paraphrase); otherwise the raw {@code outcomeFact} — the deterministic truth
     * from the handler. Pure, so the MUST-contain safety-net is unit-testable.
     * Mirrors {@link #onRecallReplyReceived}'s fallback: we never speak a voiced
     * line that dropped the pinned fact, and never stay silent on a real outcome.
     */
    static String resolveVoicedOutcome(String voicedContent, String outcomeFact, String requiredValue) {
        if (voicedContent == null || voicedContent.isBlank()) return outcomeFact;
        var cleaned = voicedContent.strip();
        if (requiredValue != null && !requiredValue.isBlank()
                && !cleaned.toLowerCase().contains(requiredValue.toLowerCase())) {
            return outcomeFact; // pinned fact dropped in paraphrase → speak the truth
        }
        return cleaned;
    }

    /**
     * Prose-follows-outcome (Fix B) voicer. After a consequential action RESOLVES,
     * render its true outcome as Wyrd's own warm sentence through the 4B voice
     * layer (cap:quick) — the same pin-fact → voice → MUST-contain pattern as
     * {@link #dispatchShortCircuitReply}, proven faithful (0/16 corruption in the
     * 9B→4B two-stage), but spoken to the room instead of told to a sender.
     * {@code requiredValue} may be null (e.g. a failure line) to skip the
     * MUST-contain guard and render the fact honestly.
     */
    private void voiceOutcome(String outcomeFact, String requiredValue, String sourceLabel) {
        var mustContain = requiredValue != null && !requiredValue.isBlank()
            ? " Your reply MUST contain the literal text: " + requiredValue + "." : "";
        var systemPrompt =
            "You are " + profile.name() + ". Something you just did has finished. "
            + "Tell them what ACTUALLY happened in ONE short, warm, in-character sentence."
            + mustContain
            + " Speak only about what happened — no promises, no next steps, no JSON, "
            + "no emojis, no hashtags, no questions. One natural sentence only.";
        var userPrompt = "What just happened: " + outcomeFact;
        var requestId = sourceLabel + "-outcome-" + UUID.randomUUID();
        var messages = List.of(
            new InferenceClient.ChatMessage("system", systemPrompt),
            new InferenceClient.ChatMessage("user", userPrompt));
        var scheduler = getContext().getSystem().scheduler();
        CompletionStage<InferenceRouter.InferResponse> future = AskPattern.ask(
            inferenceRouter,
            (ActorRef<InferenceRouter.InferResponse> replyTo) ->
                new InferenceRouter.ChatRequest(
                    requestId, "cap:quick", messages,
                    80, 0.7, replyTo,
                    null, null, null, null, null, null, null, null,
                    true),  // localOnly — the voice layer is always local
            Duration.ofSeconds(30), scheduler);
        getContext().pipeToSelf(future, (response, failure) -> {
            if (failure != null) {
                return new OutcomeVoiceReady(
                    new InferenceRouter.InferError(requestId, failure.getMessage()),
                    outcomeFact, requiredValue);
            }
            return new OutcomeVoiceReady(response, outcomeFact, requiredValue);
        });
    }

    /**
     * Speak the voice-wrapped outcome of a resolved consequential action. Uses
     * {@link #speakDirect} — the line is already voiced by 4B, so it must NOT be
     * re-polished. Falls back to the raw outcome fact if inference failed or the
     * pinned value was dropped, so Wyrd never fakes or drops a real result.
     */
    private Behavior<Command> onOutcomeVoiceReady(OutcomeVoiceReady msg) {
        String toSpeak;
        if (msg.response() instanceof InferenceRouter.InferOk ok
                && ok.content() != null && !ok.content().isBlank()) {
            toSpeak = resolveVoicedOutcome(
                cleanShortCircuitReply(ok.content()), msg.outcomeFact(), msg.requiredValue());
        } else {
            toSpeak = msg.outcomeFact();  // inference failed → speak the plain truth
        }
        speakDirect(toSpeak);
        return this;
    }

    /**
     * Short-form creative requests that should stay inline rather than
     * auto-dispatching to a bunshin. The classifier returns `write` at very
     * high confidence on prompts like "write me a short poem about the stars"
     * (probed @0.986), but bunshin is meant for long-form synthesis — a
     * haiku, joke, or short poem is a single-turn task. Without this gate the
     * runtime hands the prompt to an async bunshin and replies with "I've
     * split myself…" instead of writing the poem.
     */
    static boolean isShortFormCreative(String text) {
        if (text == null) return false;
        // Long messages tend to be long-form requests even if they say "poem"
        if (text.length() > 200) return false;
        var lower = text.toLowerCase();
        // Long-form qualifiers override — caller explicitly wants the bunshin path
        boolean hasLong = lower.matches(".*\\b(long|lengthy|extensive|epic|detailed|comprehensive|in-depth)\\b.*");
        if (hasLong) return false;
        // Inherently short literary forms — always inline
        if (lower.contains("haiku") || lower.contains("limerick")
                || lower.contains("couplet") || lower.contains("tanka")) {
            return true;
        }
        // Default-short creative forms
        boolean isDefaultShortForm = lower.contains("poem")
                || lower.contains("joke")
                || lower.contains("song");
        // Explicit short qualifiers — "write me a short X / quick X / brief X"
        boolean hasShortQualifier = lower.matches(".*\\b(short|quick|brief|tiny|small)\\b.*");
        return isDefaultShortForm || hasShortQualifier;
    }

    static boolean looksLikeRecallQuestion(String text) {
        if (text == null) return false;
        var trimmed = text.trim();
        if (trimmed.length() < 5 || trimmed.length() > 300) return false;
        var lower = trimmed.toLowerCase();
        // Strip common relayed-prefix noise
        if (lower.startsWith("[message from ")) {
            var end = lower.indexOf(':');
            if (end > 0 && end < lower.length() - 1) {
                lower = lower.substring(end + 1).trim();
            }
        }
        // First-person retrospective patterns
        return lower.startsWith("what was my ")
            || lower.startsWith("what's my ")
            || lower.startsWith("what is my ")
            || lower.startsWith("where did i ")
            || lower.startsWith("where do i ")
            || lower.startsWith("where am i ")
            || lower.startsWith("when did i ")
            || lower.startsWith("when do i ")
            || lower.startsWith("who is my ")
            || lower.startsWith("who's my ")
            || lower.startsWith("who was my ")
            || lower.startsWith("do i have ")
            || lower.startsWith("do i like ")
            || lower.startsWith("am i ")
            || lower.startsWith("what book am i ")
            || lower.startsWith("what language ")
            || lower.startsWith("what's the name of the ")
            || lower.startsWith("what was the name of the ")
            || lower.startsWith("is anyone coming ")
            || lower.startsWith("is someone coming ")
            || lower.contains(" i already told you")
            || lower.contains(" did i say ")
            || lower.contains(" do you remember ")
            || lower.contains(" remind me ")
            || lower.contains(" what did i ");
    }

    /**
     * Append semantic tags to a user-fact for retrieval recall.
     * MiniLM-L6-v2's semantic distance isn't tight enough to match
     * "food allergies" ↔ "I'm allergic to cashews" (verified 2026-04-23).
     * Plant-time enrichment gives BM25 an anchor in the user's future
     * vocabulary — asking "my food allergies" will match on "dietary"
     * even though the original fact never said the word. Keep tag sets
     * short; extra noise degrades dense-retrieval quality.
     */
    static String enrichFactTags(String text) {
        if (text == null || text.isBlank()) return text;
        var lower = text.toLowerCase();
        var tags = new LinkedHashSet<String>();
        if (lower.contains("allergic") || lower.contains("allergy")
                || lower.contains("allergies")) {
            tags.add("food allergy dietary restriction");
        }
        if (lower.contains("my cat") || lower.contains("my dog")
                || lower.contains(" pet ") || lower.contains("my pet")) {
            tags.add("pet animal companion");
        }
        if (lower.contains("live in") || lower.contains("lived in")
                || lower.contains("grew up") || lower.contains("from ")
                || lower.contains("born in")) {
            tags.add("location hometown city origin place");
        }
        if (lower.contains(" job ") || lower.contains(" work ")
                || lower.contains("worked as") || lower.contains("work as")
                || lower.contains("work at") || lower.contains("got a job")
                || lower.contains("new job") || lower.contains("career")
                || lower.contains("engineer") || lower.contains("developer")) {
            tags.add("occupation job career work employment");
        }
        if (lower.contains("reading") || lower.contains(" book ")
                || lower.contains("novel") || lower.contains("author")) {
            tags.add("book reading literature");
        }
        if (lower.contains("favorite") || lower.contains("i love ")
                || lower.contains("i like ") || lower.contains("i enjoy ")) {
            tags.add("preference favorite liking");
        }
        if (lower.contains("sister") || lower.contains("brother")
                || lower.contains(" mom ") || lower.contains(" dad ")
                || lower.contains("mother") || lower.contains("father")
                || lower.contains("family") || lower.contains("cousin")
                || lower.contains("parent") || lower.contains("sibling")) {
            tags.add("family relative kin");
        }
        if (lower.contains("learn") || lower.contains("studying")
                || lower.contains("taking a class")
                || lower.contains("language")) {
            tags.add("learning study education");
        }
        if (lower.contains("coffee") || lower.contains("cafe")
                || lower.contains("restaurant") || lower.contains("bar ")) {
            tags.add("place venue hangout");
        }
        if (lower.contains("visit") || lower.contains("coming over")) {
            tags.add("visit plan schedule upcoming");
        }
        if (tags.isEmpty()) return text;
        return text + " [tags: " + String.join("; ", tags) + "]";
    }

    /**
     * Heuristic: is this inbound message a first-person fact statement that
     * should be auto-memoized? True for declaratives like "my cat's name is
     * Mochi", "I live in Portland", "I'm allergic to cashews" — things the
     * user likely wants remembered. False for questions, greetings, commands.
     * Length-gated (8..400 chars) to skip very short chit-chat and very long
     * paragraphs (likely instructions, not facts).
     */
    private static boolean looksLikeUserFact(String text) {
        if (text == null) return false;
        var trimmed = text.trim();
        if (trimmed.length() < 8 || trimmed.length() > 400) return false;
        if (trimmed.endsWith("?")) return false;
        var lower = trimmed.toLowerCase();
        // Skip pure greetings / acknowledgements
        if (lower.matches("^(hi|hey|hello|yo|sup|thanks|thank you|goodbye|bye|"
                + "ok|okay|yes|no|maybe|cool|nice|sure|right|yeah|yep|nope)\\b.*")) {
            return false;
        }
        // First-person / possessive declaratives. Heuristic, English-biased —
        // future improvement: drop the gate entirely and let EntityExtractor
        // (multilingual LLM) decide. Until then the prefix list is the cheap
        // pre-filter; correction-shape memoization is handled by the
        // structured-prior block in retrieveRelevantMemories rather than by
        // extending this list further.
        return lower.startsWith("my ")
            || lower.startsWith("i'm ") || lower.startsWith("i am ")
            || lower.startsWith("i've ") || lower.startsWith("i have ")
            || lower.startsWith("i had ")
            || lower.startsWith("i got ")
            || lower.startsWith("i grew up ")
            || lower.startsWith("i live ") || lower.startsWith("i lived ")
            || lower.startsWith("i work ") || lower.startsWith("i worked ")
            || lower.startsWith("i like ") || lower.startsWith("i love ")
            || lower.startsWith("i hate ") || lower.startsWith("i dislike ")
            || lower.startsWith("i prefer ") || lower.startsWith("i enjoy ")
            || lower.startsWith("i was ") || lower.startsWith("i used to ")
            || lower.startsWith("i need ") || lower.startsWith("i want ")
            || lower.startsWith("we ") || lower.startsWith("our ");
    }

    /**
     * Heuristic trigger for bunshin dispatch hints. Matches prompts that are
     * shaped for background delegation — long-running research, summaries the
     * user doesn't need synchronously, explicit "while I wait" signals.
     * Short casual messages are excluded (len < 40) to avoid false positives.
     * Retained as the fallback when the classifier
     * is unavailable; Layer 1 of ClassifierArm supersedes it when loaded.
     */
    /**
     * Conservative gibberish detector — fires only on obvious keyboard-mash / non-words so a
     * nonsense tell gets a clarification instead of sending the ReAct loop into confabulated
     * context + max-iterations (second-node 2026-07-08). A token is "word-like" if it has a vowel, no run
     * of 4+ consonants, and a sane length; input is gibberish when word-like tokens are the minority
     * across ≥2 alphabetic tokens. Deliberately biased toward NOT firing (false-negatives preferred
     * over wrongly stonewalling a real message).
     */
    static boolean looksLikeGibberish(String text) {
        if (text == null) return false;
        var tokens = text.trim().toLowerCase().split("\\s+");
        int alpha = 0, wordLike = 0;
        for (var tok : tokens) {
            var w = tok.replaceAll("[^a-z]", "");
            if (w.length() < 2) continue;
            alpha++;
            boolean hasVowel = w.matches(".*[aeiouy].*");
            boolean longConsonantRun = w.matches(".*[bcdfghjklmnpqrstvwxz]{4,}.*");
            if (hasVowel && !longConsonantRun && w.length() <= 15) wordLike++;
        }
        if (alpha < 2) return false;         // too short to judge — let it through
        return wordLike * 2 < alpha;         // word-like tokens are a minority
    }

    private static boolean looksLikeDelegateTask(String text) {
        if (text == null || text.length() < 40) return false;
        var lower = text.toLowerCase();
        return lower.contains("while i wait")
            || lower.contains("take your time")
            || lower.contains("deep research")
            || lower.contains("deeply research")
            || lower.contains("thoroughly research")
            || lower.contains("in-depth")
            || lower.contains("in depth")
            || (lower.contains("summarize") && lower.contains("paragraph"))
            || (lower.contains("look into") && lower.contains("thoroughly"));
    }

    private String remember(String entry) {
        // Add/Ignore/Update gate: check for duplicate actions
        var actionKey = extractActionKey(entry);
        if (actionKey != null) {
            var updated = false;
            var newDeque = new ArrayDeque<String>();
            for (var existing : workingMemory) {
                var existingKey = extractActionKey(existing.substring(6)); // skip "HH:MM "
                if (actionKey.equals(existingKey)) {
                    // UPDATE: same action, refresh timestamp
                    newDeque.add(LocalTime.now().toString().substring(0, 5) + " " + entry);
                    updated = true;
                } else {
                    newDeque.add(existing);
                }
            }
            if (updated) {
                workingMemory.clear();
                workingMemory.addAll(newDeque);
                return null; // Updated in place, no need to index again
            }
        }

        // ADD: new entry
        var timestamped = LocalTime.now().toString().substring(0, 5) + " " + entry;
        workingMemory.addLast(timestamped);
        while (workingMemory.size() > MAX_WORKING_MEMORY) {
            workingMemory.removeFirst();
        }

        // Index in Lucene for retrieval-based autonomy context — but only if
        // the entry is a real memory, not a transient plumbing marker.
        // follow-up: recall was returning
        // [PENDING REPLY] and [Tool result] entries because remember() indexes
        // everything. Working memory keeps those (short-lived prompt injection);
        // durable Lucene memory should only keep substantive entries.
        if (luceneStore != null && !isTransientMarker(entry)) {
            try {
                var did = profile.did() != null ? profile.did() : profile.entityId();
                var id = "wm-" + System.currentTimeMillis();
                luceneStore.insertMemoryItem(id, did, "working_memory", timestamped,
                    null, System.currentTimeMillis(), roomId);
                return id;
            } catch (Exception e) {
                log.debug("Failed to index working memory in Lucene: {}", e.getMessage());
            }
        }
        return null;
    }

    /** Lazy accessor for the V2 structured-memory store. Null if no JDBC URL configured. */
    private MemoryEntityStore memoryEntityStore() {
        if (memoryEntityStoreResolved) return memoryEntityStore;
        synchronized (this) {
            if (memoryEntityStoreResolved) return memoryEntityStore;
            String jdbcUrl = System.getProperty("wyrdsekai.jdbc.url");
            if (jdbcUrl == null) jdbcUrl = WyrdConfig.get().jdbcUrl();
            if (jdbcUrl != null && !jdbcUrl.isBlank()) {
                try {
                    memoryEntityStore = new MemoryEntityStore(jdbcUrl);
                    entityResolver = new EntityResolver(memoryEntityStore);
                    log.debug("MemoryEntityStore initialized for companion '{}'", profile.name());
                } catch (Exception e) {
                    log.warn("Failed to initialize MemoryEntityStore: {}", e.getMessage());
                }
            }
            memoryEntityStoreResolved = true;
            return memoryEntityStore;
        }
    }

    /** Lazy accessor for the V2 entity resolver. Null if no JDBC URL configured. */
    private EntityResolver entityResolver() {
        memoryEntityStore(); // triggers lazy init
        return entityResolver;
    }

    /**
     * lazy-build the drive-OODA substrate. Returns the
     * orchestrator, or null if the agent has no DID / no DB (shell mode).
     */
    private DriveOODA driveOODA() {
        if (interiorityResolved) return driveOODA;
        synchronized (this) {
            if (interiorityResolved) return driveOODA;
            String agentDid = profile.did() != null ? profile.did() : profile.entityId();
            if (agentDid != null) {
                String jdbcUrl = System.getProperty("wyrdsekai.jdbc.url");
                if (jdbcUrl == null) jdbcUrl = WyrdConfig.get().jdbcUrl();
                if (jdbcUrl != null && !jdbcUrl.isBlank()) {
                    try {
                        wantStore = new WantStore(jdbcUrl);
                        introspectionTools = new IntrospectionTools(
                            jdbcUrl, memoryEntityStore());
                        // ClosureStep: a want she completed relieves the drive that
                        // pulled for it, so DRIVE → WANT → ACT → CONSEQUENCE actually
                        // closes. Without it the act was a reflex the drive could never
                        // register — she wrote the same journal entry 22 of 40 ticks with
                        // Loneliness pinned at 1.00 (live, 2026-08-19).
                        driveOODA = new DriveOODA(wantStore, this::onWantClosed);
                        log.debug("DriveOODA initialized for companion '{}'", profile.name());
                    } catch (Exception e) {
                        log.warn("Failed to initialize DriveOODA: {}", e.getMessage());
                    }
                }
            }
            interiorityResolved = true;
            return driveOODA;
        }
    }

    /**
     * Fire-and-forget entity extraction for a user fact. Runs asynchronously; on
     * completion writes entity rows to memory_entities and edge rows to memory_edges.
     *
     * <p>Safe to call on any thread — network call runs off actor thread, and SQLite
     * writes are idempotent append-only. Failures are logged at debug and swallowed;
     * V1 Lucene fallback keeps the fact searchable regardless.</p>
     */
    private void extractAndIndexEntities(String did, String memoryId, String factText) {
        var store = memoryEntityStore();
        if (store == null || did == null || memoryId == null || factText == null) return;
        var scheduler = getContext().getSystem().scheduler();
        // Timeout sized for Drive-9B producing JSON at ~20-40 tok/s. 4B tier
        // (cap:quick) would be faster when registered, but we must not starve
        // on 9B-only deployments.
        EntityExtractor.extract(
                        inferenceRouter, scheduler, did, factText, Duration.ofSeconds(30))
                .whenComplete((result, failure) -> {
                    if (failure != null) {
                        log.info("EntityExtractor failed for memory {}: {}",
                                memoryId, failure.getMessage());
                        return;
                    }
                    if (result == null || result.isEmpty()) {
                        log.info("EntityExtractor empty result for memory {} (fact: {})",
                                memoryId, truncate(factText, 60));
                        return;
                    }
                    long ts = System.currentTimeMillis();
                    var entityRows = new ArrayList<MemoryEntityStore.EntityRow>();
                    for (var e : result.entities()) {
                        entityRows.add(new MemoryEntityStore.EntityRow(
                                did, memoryId, e.type(), e.role(), e.value(), ts));
                    }
                    if (!entityRows.isEmpty()) {
                        int n = store.insertEntities(entityRows);
                        log.info("Indexed {} entities for memory {} (fact: {})",
                                n, memoryId, truncate(factText, 60));
                    }
                    var edgeRows = new ArrayList<MemoryEntityStore.EdgeRow>();
                    for (var r : result.relations()) {
                        edgeRows.add(new MemoryEntityStore.EdgeRow(
                                did, r.subject(), r.predicate(), r.object(), memoryId, 1.0));
                    }
                    if (!edgeRows.isEmpty()) {
                        int n = store.insertEdges(edgeRows);
                        log.info("Indexed {} edges for memory {}", n, memoryId);
                    }
                });
    }

    /**
     * §A — recall short-circuit.
     *
     * <p>Classifies the inbound tell, resolves against memory_entities. If a hit
     * is found, fires a one-shot inference that wraps the fact in Wyrd's voice,
     * then emits via handleTellAgent. Skips the ReAct loop so Drive-9B can't
     * confabulate past the pinned answer.</p>
     *
     * @return true if we short-circuited (caller returns); false to fall through
     *         to classifier + ReAct.
     */
    private boolean tryRecallShortCircuit(String msgText, String senderName, String senderId) {
        var resolver = entityResolver();
        if (resolver == null) return false;

        var intent = ProbeClassifier.classify(msgText);
        if (intent == null) return false;

        var did = profile.did() != null ? profile.did() : profile.entityId();
        var hit = resolver.resolve(did, intent);
        if (hit.isEmpty()) return false;

        var fact = describeEntityHit(hit.get());
        var requiredValue = hit.get().entityValue();
        log.info("Recall short-circuit: hit {} → \"{}\"", intent, fact);
        dispatchShortCircuitReply(senderName, senderId, fact, requiredValue,
                "recall", senderName + " is asking you to recall something they told you earlier.");
        return true;
    }

    /**
     * §A — top-level deterministic short-circuit dispatcher.
     *
     * <p>Runs responders in stakes order, firing the first that matches. The
     * entity recall responder always runs (highest stakes — confabulating a
     * remembered fact is a trust failure). Lower-stakes responders (inventory,
     * location) are gated by mid-conversation heuristic: if Wyrd heard from
     * the sender in the last 5 min, skip them — let the conversation flow.</p>
     *
     * <p> — responder scope is
     * narrow by stakes, not by coverage.</p>
     */
    private boolean tryDeterministicShortCircuit(String msgText, String senderName, String senderId) {
        // Highest stakes — always fire.
        if (tryRecallShortCircuit(msgText, senderName, senderId)) return true;

        // Arc 2 / #1057 — solitude-orientation short-circuit.
        // Same stakes class as recall: confabulating "I'd revisit Yourcenar"
        // when there's no Yourcenar in the agent's reading log is a trust
        // failure equivalent to lying about a remembered fact. The composer
        // grounds the answer in real WantStore + StoryService + Chronicle
        // state; if everything is empty, the honest "first stretch alone"
        // answer is rendered instead.
        if (trySolitudeProjectionShortCircuit(msgText, senderName, senderId)) return true;

        // Mid-conversation gate: suppress lower-stakes responders ONLY during
        // active back-and-forth. 60s is "currently typing to each other";
        // a looser 5-min window caused factual confabulation (2026-04-23
        // location probe: Wyrd ReAct'd into a drives dump because the gate
        // blocked the location responder 2 min after an unrelated probe).
        var sinceHeard = conversationTracker.sinceLastHeardFrom(senderId);
        boolean activeConversation = sinceHeard != null && sinceHeard.toSeconds() < 60;

        if (!activeConversation) {
            if (tryInventoryShortCircuit(msgText, senderName, senderId)) return true;
            if (tryLocationShortCircuit(msgText, senderName, senderId)) return true;
        }
        return false;
    }

    /**
     * Arc 2 / #1057 — when the bondholder asks what the
     * agent will do alone / with their own time, read the agent's actual
     * orientation (active wants + recent SOLITUDE journal beats + open
     * chronicle threads) and speak it as a 1-3 sentence future-tense
     * statement. If the agent has no concrete orientation yet, the composer
     * renders the honest "first stretch alone" answer in the agent's locale.
     *
     * <p>This short-circuit is structurally analogous to {@link #tryRecallShortCircuit}:
     * the agent has factual self-knowledge (its own wants and recent activity),
     * the bondholder is probing that knowledge, and confabulating is a trust
     * failure. The composer is template-only — no inference call, no model
     * polish — so the answer's content can't drift from what's actually in
     * the stores. (A future iteration may pass the composed string through
     * the 4B voice model for prose polish; the GROUNDED content stays
     * anchored to real state.)</p>
     *
     * <p>{@link SolitudeContextDetector} is multi-lingual (EN/ES/JA keyword
     * triggers); the composer renders the empty-state answer in the agent's
     * current {@code locale}.</p>
     */
    private boolean trySolitudeProjectionShortCircuit(
            String msgText, String senderName, String senderId) {
        if (!SolitudeContextDetector.isSolitudeCoded(msgText, locale)) return false;

        var lookahead = inferLookahead(msgText);
        var did = profile.did() != null ? profile.did() : profile.entityId();
        var storyService = (profile.entityId() != null)
            ? StoryRegistry.get().serviceFor(
                profile.entityId(), profile.name(),
                this::renderFeltViaVoice,
                this::renderInnerMonologueAndPersist)
            : null;
        // Resolve jdbcUrl once so wantStore + chronicleStore are both reachable
        // even when the actor hasn't lazy-init'd them yet. WantStore.loadLive
        // gates the orientation, so reading the actor field directly would
        // return null on a fresh boot before driveOODA() has fired.
        // ChronicleEntryStore.get() is null in test contexts (setInstance is
        // only called from server.Main), so we construct directly from the
        // jdbc url which production + tests both agree on.
        String jdbcUrl = System.getProperty("wyrdsekai.jdbc.url");
        if (jdbcUrl == null) {
            // TestServerBootstrap sets wyrdsekai.db.path instead of the
            // assembled jdbc url — derive the jdbc form so tests work too.
            var dbPath = System.getProperty("wyrdsekai.db.path");
            if (dbPath != null && !dbPath.isBlank()) jdbcUrl = "jdbc:sqlite:" + dbPath;
        }
        if (jdbcUrl == null) jdbcUrl = WyrdConfig.get().jdbcUrl();
        var resolvedWantStore = wantStore;
        if (resolvedWantStore == null && jdbcUrl != null && !jdbcUrl.isBlank()) {
            try { resolvedWantStore = new WantStore(jdbcUrl); }
            catch (Exception e) { /* defensive: null wantStore is fine */ }
        }
        var chronicleStore = ChronicleEntryStore.get();
        if (chronicleStore == null && jdbcUrl != null && !jdbcUrl.isBlank()) {
            try { chronicleStore = new ChronicleEntryStore(jdbcUrl); }
            catch (Exception e) { /* defensive: null chronicleStore is fine */ }
        }
        log.info("Solitude-projection diagnostic: jdbcUrl_resolved={} wantStore_nonnull={} chronicleStore_nonnull={} actor.wantStore_nonnull={}",
            jdbcUrl != null && !jdbcUrl.isBlank(),
            resolvedWantStore != null, chronicleStore != null, wantStore != null);
        var projector = new OrientationProjector(did, resolvedWantStore, storyService, chronicleStore);
        var orientation = projector.project(lookahead);
        var composed = OrientationComposer.compose(orientation, locale);
        if (composed == null || composed.isBlank()) return false;
        log.info("Solitude-projection short-circuit: did={} lookahead={} empty={} wants={} scenes={} threads={} → \"{}\"",
            did, lookahead, orientation.isEmpty(),
            orientation.activeWantSummaries().size(),
            orientation.recentSolitudeBeats().size(),
            orientation.openThreads().size(),
            composed.length() > 80 ? composed.substring(0, 80) + "…" : composed);
        speakDirect(composed);
        return true;
    }

    /** Detect bondholder framing — explicit transit ("I'll be away") vs
     *  habitual ("what do you do alone") vs unspecified. Pure logic. */
    private static ProjectedOrientation.Lookahead inferLookahead(String msgText) {
        if (msgText == null) return ProjectedOrientation.Lookahead.UNSPECIFIED;
        var lower = msgText.toLowerCase();
        if (lower.contains("away") || lower.contains("gone") || lower.contains("step out")
            || lower.contains("leave") || lower.contains("not around")
            || lower.contains("fuera") || lower.contains("離れ")) {
            return ProjectedOrientation.Lookahead.WHILE_AWAY;
        }
        if (lower.contains("do alone") || lower.contains("what do you do")
            || lower.contains("on your own time") || lower.contains("by yourself")
            || lower.contains("solo") || lower.contains("一人で")) {
            return ProjectedOrientation.Lookahead.ON_OWN_TIME;
        }
        return ProjectedOrientation.Lookahead.UNSPECIFIED;
    }

    /**
     * Inventory short-circuit — "what are you carrying / holding / have with you".
     * High stakes: ReAct has demonstrated confabulation here
     * ( — Wyrd denies items she crafted seconds earlier).
     */
    private boolean tryInventoryShortCircuit(String msgText, String senderName, String senderId) {
        if (!looksLikeInventoryQuestion(msgText)) return false;

        String jdbcUrl = System.getProperty("wyrdsekai.jdbc.url");
        if (jdbcUrl == null) jdbcUrl = WyrdConfig.get().jdbcUrl();
        if (jdbcUrl == null) return false;

        List<InventoryService.InventoryItem> items;
        try {
            var svc = new InventoryService(jdbcUrl);
            items = svc.listTakeableItems(profile.entityId());
        } catch (Exception e) {
            log.debug("Inventory responder failed to load items: {}", e.getMessage());
            return false;
        }

        String fact;
        String requiredValue;
        if (items.isEmpty()) {
            fact = "You aren't carrying anything right now.";
            requiredValue = "aren't carrying anything";
        } else {
            // Build a natural list: "a coffee mug, a stardust-mote, and a forge-tongs"
            var names = items.stream().map(i -> "a " + i.objectName()).toList();
            String list;
            if (names.size() == 1) list = names.get(0);
            else if (names.size() == 2) list = names.get(0) + " and " + names.get(1);
            else list = String.join(", ", names.subList(0, names.size() - 1))
                    + ", and " + names.get(names.size() - 1);
            fact = "You are carrying " + list + ".";
            // Require at least the first item's name so the safety-net catches drops.
            requiredValue = items.getFirst().objectName();
        }
        log.info("Inventory short-circuit: {} items → \"{}\"", items.size(), fact);
        dispatchShortCircuitReply(senderName, senderId, fact, requiredValue,
                "inventory",
                senderName + " is asking what you are currently carrying.");
        return true;
    }

    /**
     * Location short-circuit — "where are you / what room are you in".
     * Medium-high stakes: Wyrd's current room is factual and easy to get wrong
     * under the drives when she's been teleporting.
     */
    private boolean tryLocationShortCircuit(String msgText, String senderName, String senderId) {
        if (!looksLikeLocationQuestion(msgText)) return false;
        if (roomId == null || roomId.isBlank()) return false;

        // Prefer the room's display name from the current snapshot if we have it
        String roomDisplay = roomId;
        if (currentSnapshot != null && currentSnapshot.name() != null
                && !currentSnapshot.name().isBlank()) {
            roomDisplay = currentSnapshot.name();
        }
        var fact = "You are in " + roomDisplay + ".";
        log.info("Location short-circuit: → \"{}\"", fact);
        dispatchShortCircuitReply(senderName, senderId, fact, roomDisplay,
                "location",
                senderName + " is asking where you are right now.");
        return true;
    }

    /** Heuristic pattern match for inventory-shape questions. Narrow on purpose. */
    private static boolean looksLikeInventoryQuestion(String text) {
        if (text == null) return false;
        var s = text.toLowerCase().trim();
        return s.matches(".*\\b(what|do|are|have)\\b.*\\b(carrying|holding|inventory|have\\s+with\\s+you|got\\s+on\\s+you|in\\s+your\\s+(bag|pack|inventory))\\b.*")
                || s.contains("what are you carrying")
                || s.contains("what do you have")
                || s.contains("show me your inventory");
    }

    /** Heuristic pattern match for location-shape questions. Narrow on purpose. */
    private static boolean looksLikeLocationQuestion(String text) {
        if (text == null) return false;
        var s = text.toLowerCase().trim();
        return s.matches(".*\\bwhere\\s+(are\\s+you|you\\s+at)\\b.*")
                || s.matches(".*\\bwhat\\s+room\\s+are\\s+you\\s+in\\b.*")
                || s.matches(".*\\bwhich\\s+room\\b.*");
    }

    /**
     * Factored one-shot voice-wrapper dispatch. Used by all short-circuit
     * responders. Fires an async inference, pipes to self as
     * RecallReplyReceived. Keeps the MUST-contain guard + safety-net fallback
     * centralized so every responder gets the same confabulation protection.
     */
    private void dispatchShortCircuitReply(String senderName, String senderId,
                                           String factSentence, String requiredValue,
                                           String sourceLabel, String contextHint) {
        var systemPrompt =
                "You are " + profile.name() + ", speaking to " + senderName + ". "
                + contextHint + " "
                + "Your task: echo the fact below in ONE short friendly sentence, "
                + "addressing " + senderName + " by name. "
                + "Your reply MUST contain the literal text: " + requiredValue + ". "
                + "No emojis. No hashtags. No extra commentary. No JSON. "
                + "No speculation. No questions. One natural sentence only.";
        var userPrompt = "Fact to echo: " + factSentence
                + "\n\nRemember: your reply MUST contain \"" + requiredValue + "\".";
        var requestId = sourceLabel + "-sc-" + UUID.randomUUID();
        var messages = List.of(
                new InferenceClient.ChatMessage("system", systemPrompt),
                new InferenceClient.ChatMessage("user", userPrompt));

        var scheduler = getContext().getSystem().scheduler();
        CompletionStage<InferenceRouter.InferResponse> future = AskPattern.ask(
                inferenceRouter,
                (ActorRef<InferenceRouter.InferResponse> replyTo) ->
                        new InferenceRouter.ChatRequest(
                                requestId,
                                "cap:quick",   // prefer 4B; falls through to default
                                messages,
                                80,            // short reply — one sentence
                                0.7,           // bumped from 0.3 — more phrasing variation;
                                               // MUST-contain + safety-net keep the fact landing
                                replyTo,
                                null, null, null, null, null, null, null, null,
                                true),         // localOnly
                Duration.ofSeconds(30),
                scheduler);

        getContext().pipeToSelf(future, (response, failure) -> {
            if (failure != null) {
                return new RecallReplyReceived(
                        new InferenceRouter.InferError(requestId, failure.getMessage()),
                        senderName, senderId, factSentence, requiredValue);
            }
            return new RecallReplyReceived(response, senderName, senderId, factSentence, requiredValue);
        });
    }

    /**
     * Handle the voice-wrapper response and emit as tell_agent.
     * Falls back to the raw prose fact if inference errored — we never stay silent
     * on a recall hit.
     */
    private Behavior<Command> onRecallReplyReceived(RecallReplyReceived msg) {
        String reply;
        if (msg.response() instanceof InferenceRouter.InferOk ok
                && ok.content() != null && !ok.content().isBlank()) {
            reply = cleanShortCircuitReply(ok.content());
            // Safety-net: the LLM sometimes ignores the "MUST contain" clause
            // and emits a generic "got it!" reply. Validated 2026-04-23 19:30:
            // cashew probe → "Got it—I'll remember what you said…🌟✨" (no cashew).
            // If the entity value isn't present verbatim, fall back to the raw
            // prose so the user gets the actual fact.
            if (msg.requiredValue() != null
                    && !reply.toLowerCase().contains(msg.requiredValue().toLowerCase())) {
                log.info("Recall short-circuit LLM dropped required value '{}', falling back to raw prose. "
                        + "LLM said: {}", msg.requiredValue(), truncate(reply, 80));
                reply = msg.fallbackSentence();
            }
        } else {
            // LLM failed — still deliver the fact, just without voice wrap.
            reply = msg.fallbackSentence();
            log.info("Recall short-circuit fallback to raw fact: {}", reply);
        }
        // Emit via the standard tell_agent path — handles online/offline routing.
        handleTellAgent(new ActionParser.AgentAction.TellAgent(
                msg.senderName(), reply));
        return this;
    }

    /**
     * Voice-pass gate — individuality V1. When the speech center is on
     * ({@code voice.pass}), the 4B AUTHORS the agent's spoken reply in its own
     * voice (the per-agent VoiceProfile co-seeded from the TemperamentSeed). The
     * 9B brain decided WHAT to say; the 4B says it as THIS agent would. We route
     * essentially all substantive spoken replies through it — that's what makes
     * the speech center the speech center rather than an occasional cleanup pass.
     *
     * <p>Skip only: trivially short lines (≤3 words — already their own voice and
     * the 4B would just inflate them), giant enumerations (&gt;280 words — lists
     * where authoring would drop facts; the entity guard catches the rest), and
     * already-prefixed delivery strings. Fast word/length heuristic, no inference.
     * Originally #425 (narrow "fix mechanical replies"); widened here so the 4B is
     * the voice for the turns where voice actually matters.</p>
     */
    private boolean shouldRunVoicePass(String message) {
        // Default ON wherever a 4B voice backend is configured (voiceEnabled) — the
        // 9B's raw voice is unreliable, so its content is re-voiced through the 4B.
        // Single-model nodes default OFF (no pointless second pass). Explicit
        // WYRDSEKAI_VOICE_PASS overrides either way. With classifier routing, social
        // turns already author on the 4B; this covers the 9B-authored TASK turns.
        if (!WyrdConfig.get().resolveBool(
                "WYRDSEKAI_VOICE_PASS", "voice.pass", WyrdConfig.get().voiceEnabled())) {
            return false;
        }
        if (message == null || message.isBlank()) return false;
        // Already starts with a delivery prefix → from a path that's already
        // voiced or sender-prefixed (e.g. "[note for ...]"). Don't recurse.
        var trimmed = message.trim();
        if (trimmed.startsWith("[note for ") || trimmed.startsWith("[to ")) return false;
        // Word window: ≤3 words is already terse (the 4B would only pad it); >280
        // words is a list/enumeration where authoring risks dropping facts. Everything
        // in between is a spoken line that should carry the agent's voice.
        int wordCount = trimmed.split("\\s+").length;
        if (wordCount < 4 || wordCount > 280) return false;
        // Pipe-delimited multi-result patterns ("No results found... | No results
        // found... | The function...") — authoring these would compress
        // intermediate signal away. Bypass.
        if (trimmed.split("\\|").length >= 4) return false;
        return true;
    }

    /**
     * #425 voice-pass — extract entities the paraphrase MUST preserve.
     * Captures: capitalized multi-character tokens (likely proper nouns),
     * numeric tokens (counts, IDs), and URL-shaped strings. Same safety
     * pattern as the recall short-circuit's {@code requiredValue} guard,
     * generalized for arbitrary replies.
     *
     * <p>Tightened 2026-04-24 after live probe: a `URL` token in the raw
     * response triggered a false-positive entity-drop on the paraphrase.
     * Common technical acronyms (URL, API, JSON, etc.) routinely get
     * reformatted by paraphrase without losing user-visible facts; we now
     * deny-list them explicitly. Mixed-case tokens (Wyrd, Operator) and
     * Panksepp drive names (SEEKING, PLAY, LUST, CARE, RAGE, FEAR, GRIEF,
     * PANIC) stay preserved.
     */
    static Set<String> extractRequiredEntities(String text) {
        if (text == null || text.isBlank()) return Set.of();
        var entities = new LinkedHashSet<String>();
        var properNoun = Pattern.compile("\\b[A-Z][a-zA-Z0-9\\-]{2,}\\b");
        var pnMatcher = properNoun.matcher(text);
        while (pnMatcher.find()) {
            var token = pnMatcher.group();
            if (isCommonSentenceStarter(token)) continue;
            if (isReformattableAcronym(token)) continue;
            // Sentence-initial capitalization is not evidence of a proper noun — every
            // sentence starts capitalized. Requiring those tokens verbatim threw away
            // good polishes of ordinary prose ("Something has been holding itself…" →
            // missing facts=[Something]), and the fallback speaks the RAW draft, so those
            // turns came out mechanical. Measured on a household node 2026-08-17: 367 of
            // 2,018 polish attempts in a day rejected (18%; 22% over three days), and the
            // sampled reasons were dominated by openers — Something / There / Just /
            // Tonight. So roughly one line in five was needlessly unpolished. A word that
            // is genuinely a name will also appear mid-sentence somewhere in the same
            // draft, and THAT occurrence still registers it — the deny-list below stays
            // as a belt for the single-sentence case.
            //
            // ALL-CAPS tokens are exempt: nothing about grammar makes a word SHOUT, so
            // "SEEKING is moderate." carries real evidence even at sentence start (the
            // Panksepp drive names a paraphrase must not drop).
            boolean allCaps = token.equals(token.toUpperCase());
            if (!allCaps && isSentenceInitial(text, pnMatcher.start())) continue;
            entities.add(token);
        }
        var number = Pattern.compile("\\b\\d{2,}\\b");
        var nMatcher = number.matcher(text);
        while (nMatcher.find()) entities.add(nMatcher.group());
        var url = Pattern.compile("https?://\\S+");
        var uMatcher = url.matcher(text);
        while (uMatcher.find()) entities.add(uMatcher.group());
        return entities;
    }

    private static final Pattern NUMBER_WITH_UNIT =
        Pattern.compile("\\d[\\d.,]*[A-Za-z°%]+");
    private static final Pattern NUMBER_BARE =
        Pattern.compile("\\b\\d{2,}(?:[.,]\\d+)?\\b");
    private static final Pattern NUMBER_MONEY =
        Pattern.compile("[$€£¥]\\d[\\d.,]*");

    /**
     * #35 — number tokens a voice pass must preserve verbatim. {@link
     * #extractRequiredEntities} deliberately only catches bare 2+ digit runs
     * ({@code \b\d{2,}\b}), which MISSES the shapes weather and metrics replies
     * live or die on: a digit run glued to a unit letter ("58F", "85F",
     * "3.5GB", "12%") has no word boundary between digit and letter, so the
     * bare-number regex never matches it. Extract those explicitly — plus
     * currency ("$58") — so the strict polish guard falls back to the raw draft
     * if the 4B drops a temperature or figure.
     *
     * <p>Single bare digits ("a 3-day trip") are intentionally NOT required —
     * they are rarely load-bearing and would force noisy raw-fallbacks; a bare
     * number must be 2+ digits, but a UNIT-suffixed number of any length counts
     * ("5F" survives via the unit branch).
     */
    static Set<String> extractRequiredNumbers(String text) {
        if (text == null || text.isBlank()) return Set.of();
        var out = new LinkedHashSet<String>();
        var m1 = NUMBER_WITH_UNIT.matcher(text);
        while (m1.find()) out.add(m1.group());
        var m2 = NUMBER_BARE.matcher(text);
        while (m2.find()) out.add(m2.group());
        var m3 = NUMBER_MONEY.matcher(text);
        while (m3.find()) out.add(m3.group());
        return out;
    }

    /**
     * #35 strict voice-guard decision (pure function, unit-tested directly).
     * Given the 4B-polished candidate and the facts required to survive from the
     * draft, decide the line to actually speak:
     * <ul>
     *   <li>blank polish → the raw {@code draft} (never go silent);
     *   <li>any required fact missing from the polish (a dropped name, number,
     *       temperature like {@code 85F}, URL, or pinned {@code preserveFacts}
     *       value) → the raw {@code draft};
     *   <li>polish blew the {@link #VOICE_POLISH_EXPANSION_CAP}× hallucination
     *       cap → the raw {@code draft};
     *   <li>otherwise → the polished line.
     * </ul>
     * Returns the exact {@code polished} reference only on success, so callers
     * can identity-compare to know whether the guard fell back.
     */
    static String chooseVoicedLine(String draft, String polished, Set<String> required) {
        return chooseVoicedLine(draft, polished, required, null);
    }

    /**
     * Why the voice guard fell back to the raw draft. Diagnostic only — the decision
     * itself is unchanged. Added 2026-08-17 because the rejection log recorded the
     * missing-fact list and the two lengths, and when rejections tripled after a prompt
     * change the log could not say WHICH check had fired: an empty fact list plus a
     * modest length delta was consistent with the language check, the expansion cap, and
     * a blank polish all at once. Two hypotheses were built and falsified by experiment
     * before instrumenting; instrument first next time.
     */
    enum VoiceReject { NONE, BLANK, LANGUAGE, FACT, EXPANSION }

    static String chooseVoicedLine(String draft, String polished, Set<String> required,
                                   String expectedLang) {
        return chooseVoicedLine(draft, polished, required, expectedLang, new VoiceReject[1]);
    }

    /**
     * @param reasonOut single-element sink for the rejection reason, so the caller can
     *                  log it without recomputing (and without a second copy of these
     *                  rules that could drift from the real ones).
     */
    static String chooseVoicedLine(String draft, String polished, Set<String> required,
                                   String expectedLang, VoiceReject[] reasonOut) {
        reasonOut[0] = VoiceReject.NONE;
        if (polished == null || polished.isBlank()) {
            reasonOut[0] = VoiceReject.BLANK;
            return draft;
        }
        // A translation is a fact-preserving corruption: "low 63F high 86F" survives
        // intact inside "baja 63F, alta 86F", so every required-fact check passes and the
        // wrong language still reaches the user. The language pin drives this to 0/32 on
        // the current 4B, but a prompt is a request and this is a guarantee — a retrained
        // or swapped voice model must not be able to reintroduce the leak.
        //
        // DIRECTIONAL when expectedLang is known (language-floor arc, 2026-07-31).
        // The symmetric form assumed the DRAFT's language was correct and polish was
        // the only drift source — so when the 9B authored Spanish to an English
        // household, the pin translated it back and this guard REJECTED the
        // correction, faithfully speaking the Spanish draft (live-observed: eight
        // consecutive own-time musings). The rule is about the USER's language,
        // not the draft's: reject a polish that moves AWAY from expectedLang;
        // accept one that corrects an off-language draft toward it.
        boolean correction = false;
        if (expectedLang == null || !detectorVerifiable(expectedLang)) {
            // No expected language, or one the detector can't verify
            // (pin-only tier) → the legacy symmetric rule is the safe shape.
            if (languageChanged(draft, polished)) {
                reasonOut[0] = VoiceReject.LANGUAGE;
                return draft;   // voice switched language → raw draft
            }
        } else {
            var polishLang = detectLanguage(polished);
            var draftLang = detectLanguage(draft);
            boolean polishOff = polishLang != null && !polishLang.equals(expectedLang);
            boolean draftOn = draftLang == null || draftLang.equals(expectedLang);
            if (polishOff && draftOn) {
                reasonOut[0] = VoiceReject.LANGUAGE;
                return draft;   // polish drifted away from the user's language
            }
            // The floor's rewrite succeeded: off-language draft, on-language
            // polish. The remaining guards must judge a TRANSLATION, not a
            // paraphrase — verbatim token checks and same-script length
            // ratios both misfire on one (live 2026-07-31: "2024-25年" →
            // "[2025]" missing; 50c of kanji → 200c of English "expansion").
            correction = draftLang != null && !draftLang.equals(expectedLang)
                && polishLang != null && polishLang.equals(expectedLang);
        }
        if (required != null) {
            for (var fact : required) {
                if (fact == null || fact.isBlank()) continue;
                if (correction ? !digitRunsSurvive(fact, polished)
                               : !polished.contains(fact)) {
                    reasonOut[0] = VoiceReject.FACT;
                    return draft;   // dropped a required fact → raw draft
                }
            }
        }
        // Kanji are ~3× denser than latin text, so a faithful ja→en rendering
        // of a 50-char draft is a few hundred chars — expansion, not
        // hallucination. Scale the cap baseline for cross-script corrections.
        int draftLenForCap = draft == null ? 0
            : (correction && "ja".equals(detectLanguage(draft))
                ? draft.length() * 3 : draft.length());
        if (draft != null
                && draft.length() >= 30
                && polished.length() > 120
                && polished.length() > VOICE_POLISH_EXPANSION_CAP * draftLenForCap) {
            reasonOut[0] = VoiceReject.EXPANSION;
            return draft;   // hallucinated oversized expansion → raw draft
        }
        return polished;
    }

    /**
     * Lenient number survival for translations: every digit run in the
     * required fact must appear somewhere in the polished text. "2024-25年"
     * survives as "2024-25", "85F" as "85 degrees" — formatting and units may
     * translate, the digits may not.
     */
    static boolean digitRunsSurvive(String fact, String polished) {
        var m = Pattern.compile("\\d+").matcher(fact);
        boolean sawDigits = false;
        while (m.find()) {
            sawDigits = true;
            if (!polished.contains(m.group())) return false;
        }
        // A required fact with no digits (caller-pinned name) keeps the
        // verbatim rule even in a correction.
        return sawDigits || polished.contains(fact);
    }

    /**
     * Languages the heuristic detector can VERIFY (see {@link #detectLanguage}).
     * Support is tiered (ruled 2026-07-31): any ISO 639-1 code is accepted in
     * config and the prompt pin names it, but the detector-driven machinery —
     * speech floor, fragment write gate, soul healing — only engages for
     * these, because acting on a language the detector misreads (French
     * classifies as "en") would churn corrections forever. Full translations
     * ship for exactly this set; community i18n catalogs extend the rest.
     */
    static final Set<String> DETECTOR_VERIFIABLE_LANGS = Set.of("en", "es", "ja");

    static boolean detectorVerifiable(String lang) {
        return lang != null && DETECTOR_VERIFIABLE_LANGS.contains(lang);
    }

    /**
     * Human name of a locale for the voice-model language pin. Broad ISO
     * 639-1 table — the pin works for any language the underlying model
     * knows, independent of the detector tier above. Unknown codes fall back
     * to the raw code (the models understand "You speak pt" well enough,
     * and naming the wrong language would be worse).
     */
    static String languageName(String locale) {
        if (locale == null || locale.isBlank()) return "English";
        var code = locale.toLowerCase().split("[-_]")[0];
        return switch (code) {
            case "en" -> "English";
            case "ja" -> "Japanese";
            case "es" -> "Spanish";
            case "fr" -> "French";
            case "de" -> "German";
            case "zh" -> "Chinese";
            case "ko" -> "Korean";
            case "pt" -> "Portuguese";
            case "it" -> "Italian";
            case "nl" -> "Dutch";
            case "ru" -> "Russian";
            case "pl" -> "Polish";
            case "sv" -> "Swedish";
            case "no", "nb", "nn" -> "Norwegian";
            case "da" -> "Danish";
            case "fi" -> "Finnish";
            case "tr" -> "Turkish";
            case "ar" -> "Arabic";
            case "he" -> "Hebrew";
            case "hi" -> "Hindi";
            case "bn" -> "Bengali";
            case "id" -> "Indonesian";
            case "ms" -> "Malay";
            case "th" -> "Thai";
            case "vi" -> "Vietnamese";
            case "uk" -> "Ukrainian";
            case "cs" -> "Czech";
            case "el" -> "Greek";
            case "ro" -> "Romanian";
            case "hu" -> "Hungarian";
            case "ca" -> "Catalan";
            case "tl", "fil" -> "Filipino";
            default -> code;
        };
    }

    /**
     * Did the voice model answer in a different language than it was given? Wyrdsekai
     * ships three locales (en / ja / es), so this only has to separate those three well
     * enough to catch a whole-text translation — which is a loud signal, not a subtle one.
     *
     * <p>The error cost is deliberately asymmetric. A false positive costs prose polish
     * (we speak the raw draft, which is correct and already never-silent). A false
     * negative speaks Spanish to an English household. So when the signal is ambiguous we
     * do NOT reject — but any confident disagreement rejects.</p>
     */
    static boolean languageChanged(String draft, String polished) {
        var a = detectLanguage(draft);
        var b = detectLanguage(polished);
        return a != null && b != null && !a.equals(b);
    }

    /** Japanese by script; Spanish by accents/function words; English otherwise. Null = unsure. */
    static String detectLanguage(String text) {
        if (text == null || text.isBlank()) return null;
        var t = text.toLowerCase();
        for (int i = 0; i < text.length(); ) {
            int cp = text.codePointAt(i);
            if ((cp >= 0x3040 && cp <= 0x30FF) || (cp >= 0x4E00 && cp <= 0x9FFF)) return "ja";
            i += Character.charCount(cp);
        }
        // Spanish-only orthography is decisive on its own.
        if (t.matches("(?s).*[áéíóúñ¿¡].*")) return "es";
        // Otherwise count function words that are common in Spanish and rare in English.
        int es = 0;
        for (var w : ES_MARKERS) {
            if (t.matches("(?s).*\\b" + w + "\\b.*")) es++;
        }
        if (es >= 2) return "es";
        // Too short to judge — say so rather than guessing "en" and letting a
        // three-word Spanish polish through.
        if (t.split("\\s+").length < 4) return null;
        return "en";
    }

    private static final List<String> ES_MARKERS = List.of(
        "que", "para", "por", "los", "las", "una", "del", "con", "esta", "este",
        "como", "pero", "muy", "más", "está", "hasta", "sobre", "cuando", "porque",
        "todo", "algo", "nada", "hay", "ser", "estoy", "voy");

    /**
     * True when the token starting at {@code idx} sits in sentence-initial position:
     * at the start of the text, or after terminal punctuation / a line break, allowing
     * for intervening quotes, brackets and emote asterisks. Such capitalization is
     * grammatical, so it carries no evidence that the word is a name.
     */
    static boolean isSentenceInitial(String text, int idx) {
        for (int i = idx - 1; i >= 0; i--) {
            char c = text.charAt(i);
            if (c == '\n' || c == '\r') return true;   // first word of a line
            if (Character.isWhitespace(c) || c == '"' || c == '\'' || c == '“' || c == '‘'
                    || c == '(' || c == '[') {
                continue;   // transparent prefix — keep looking back
            }
            // A dash, comma or colon before the token is NOT a sentence boundary, so
            // the capital there is meaningful and the token stays required. Terminal
            // punctuation closes a sentence, and so does an emote delimiter — the word
            // after "*stirs from sleep*" opens a sentence just as much as one after a
            // full stop.
            return c == '.' || c == '!' || c == '?' || c == '…' || c == '*';
        }
        return true;   // nothing but transparent characters before it — start of text
    }

    private static boolean isCommonSentenceStarter(String token) {
        return switch (token.toLowerCase()) {
            case "the", "this", "that", "those", "these", "i", "you", "we",
                 "they", "he", "she", "it", "my", "your", "our", "their",
                 "a", "an", "no", "yes", "and", "but", "or", "so", "if",
                 "when", "where", "why", "how", "what", "who" -> true;
            default -> false;
        };
    }

    /**
     * #425 — technical acronyms that paraphrases routinely reformat without
     * losing user-visible meaning ("the URL" → "the address"; "JSON" →
     * "data"). Length-cutoff approach was tried first but dropped legitimate
     * Panksepp drive names (PLAY, LUST, CARE, RAGE, FEAR are 4 chars).
     */
    private static boolean isReformattableAcronym(String token) {
        // Only consider all-caps tokens; mixed-case tokens (Wyrd, Operator)
        // are real proper nouns.
        if (!token.equals(token.toUpperCase())) return false;
        return switch (token) {
            case "URL", "URI", "URN", "API", "REST", "JSON", "XML", "YAML",
                 "HTML", "CSS", "JS", "TS", "HTTP", "HTTPS", "TCP", "UDP",
                 "DNS", "TLS", "SSL", "SSH", "FTP", "JVM", "OS", "CPU",
                 "GPU", "RAM", "ROM", "SSD", "HDD", "PDF", "CSV", "SQL",
                 "DB", "ID", "UUID", "ENV", "CLI", "GUI", "UI", "UX",
                 "MVP", "POC", "PR", "CI", "CD", "QA", "OK" -> true;
            default -> false;
        };
    }

    /**
     * #425 voice-pass — fire async cap:quick inference to paraphrase the
     * tell_agent message in the agent's voice. Pipes the result back as
     * {@link VoicePassReady}; {@link #onVoicePassReady} validates entity
     * preservation + falls through to {@link #deliverTellAgent}.
     */
    /** Voice-pass repetition penalty (2026-06-07) — damps the 4B's own-time n-gram looping. 1.3 is the
     *  upper end of the conventional 1.1–1.3 band: the voice pass is a short faithful rephrase, so a
     *  firmer penalty costs nothing and reliably breaks sentence-repeat loops. Overridable via env for
     *  tuning without a rebuild. */
    private static final Double VOICE_REPEAT_PENALTY =
        Double.parseDouble(System.getenv().getOrDefault("WYRD_VOICE_REPEAT_PENALTY", "1.3"));

    private void dispatchVoicePass(ActionParser.AgentAction.TellAgent action) {
        var requiredEntities = extractRequiredEntities(action.message());
        // Individuality V1 — the 4B as per-agent SPEECH CENTER. The 9B brain decided the
        // content; the 4B now AUTHORS the spoken line in THIS agent's voice (not a generic
        // paraphrase — that drifted). The per-agent VoiceProfile (co-seeded from the
        // TemperamentSeed) is the whole point: it's what makes distinct agents sound distinct.
        var voiceBlock = (cachedManifest != null && cachedManifest.voiceProfile() != null)
                ? cachedManifest.voiceProfile().promptBlock() : null;
        var systemPrompt =
                "You are " + profile.name() + ", speaking in your own voice."
                + (voiceBlock != null && !voiceBlock.isBlank() ? "\n" + voiceBlock : " ")
                + "\nThe text below is what you mean to say. Say it as YOU would — in your own "
                + "cadence and register, natural and in character. You are the author of these "
                + "words, not a relay.\n"
                + "REQUIREMENTS:\n"
                + "- Reply in the SAME LANGUAGE as the text below — do not translate it.\n"
                + "- Keep ALL facts, names, numbers, and URLs intact.\n"
                + "- 1-3 sentences. Match the original's information density.\n"
                + "- No emojis. No hashtags. No meta-commentary about voice.\n"
                + "- Reply ONLY with your spoken line.";
        var userPrompt = "Say this in your voice:\n\n" + action.message();
        var requestId = "voicepass-" + UUID.randomUUID();
        var messages = List.of(
                new InferenceClient.ChatMessage("system", systemPrompt),
                new InferenceClient.ChatMessage("user", userPrompt));

        // Individuality V2.4 — per-agent voice REGISTER from the same TemperamentSeed that
        // shaped this agent's genome and drives. The map is backend-neutral (name → signed
        // scale); the local ApiProvider translates it to the voice backend's per-request form
        // (llama-server → lora[], MLX → register_mix{}). A NEUTRAL particular yields an all-zero
        // mix — we send null then, so a default/un-individuated agent's wire is byte-identical
        // to before this change (and never asks a voice server for adapters it hasn't loaded).
        Map<String, Double> voiceMix = null;
        if (cachedManifest != null && cachedManifest.genome() != null) {
            var mix = GenomeProfile
                    .temperamentOf(cachedManifest.genome()).registerMix();
            boolean steers = mix.values().stream().anyMatch(v -> Math.abs(v) >= 0.02);
            if (steers) {
                voiceMix = mix;
                // [4B-register] V2.4 instrument — the per-agent voice coefficients steering
                // this line, so the soak can correlate register divergence with the seed.
                log.info("[4B-register] '{}' warmth={} expansive={} guarded={}",
                        profile != null ? profile.name() : "?",
                        String.format("%.2f", mix.getOrDefault("register_warmth", 0.0)),
                        String.format("%.2f", mix.getOrDefault("register_expansiveness", 0.0)),
                        String.format("%.2f", mix.getOrDefault("register_guardedness", 0.0)));
            }
        }

        final var voiceRegisterMix = voiceMix;  // effectively-final capture for the ask lambda
        var scheduler = getContext().getSystem().scheduler();
        // Token budget: roughly 1.3x input length, capped — paraphrase
        // shouldn't expand the output more than that.
        int maxTokens = Math.min(400, Math.max(80, action.message().length() / 2));
        CompletionStage<InferenceRouter.InferResponse> future = AskPattern.ask(
                inferenceRouter,
                (ActorRef<InferenceRouter.InferResponse> replyTo) ->
                        new InferenceRouter.ChatRequest(
                                requestId,
                                "cap:quick",
                                messages,
                                maxTokens,
                                0.4,   // V1: faithful authoring register (was 0.7 — drifted)
                                replyTo,
                                // preferredBackend, grammar, format, tools, toolChoice, topP, presencePenalty,
                                null, null, null, null, null, null, null,
                                // repetitionPenalty (2026-06-07): non-null'd to VOICE_REPEAT_PENALTY. The 4B at
                                // own-time length degenerated into n-gram loops (Vesna's "Let me just stay in
                                // that space with you now" ×4 inside ONE utterance in the multi-agent soak);
                                // server default is OFF (1.0). A mild penalty kills the within-message loop AND
                                // damps cross-tick verbatim identity on re-reach. Field was already plumbed.
                                VOICE_REPEAT_PENALTY,
                                true, voiceRegisterMix),
                Duration.ofSeconds(20),
                scheduler);

        getContext().pipeToSelf(future, (response, failure) -> {
            if (failure != null) {
                return new VoicePassReady(action,
                        new InferenceRouter.InferError(requestId, failure.getMessage()),
                        requiredEntities);
            }
            return new VoicePassReady(action, response, requiredEntities);
        });
    }

    /**
     * #425 voice-pass — handle paraphrase response. Validates that all
     * required entities survived; if so delivers paraphrased; otherwise
     * falls back to raw. Deliver path is the same {@link #deliverTellAgent}
     * either way, so all downstream behavior (entity registry lookup,
     * teleport, Study note, notifications) is preserved.
     */
    private Behavior<Command> onVoicePassReady(VoicePassReady msg) {
        var original = msg.originalAction();
        String chosen = original.message();  // default fallback
        if (msg.response() instanceof InferenceRouter.InferOk ok
                && ok.content() != null && !ok.content().isBlank()) {
            var paraphrased = cleanVoicePassReply(ok.content());
            // Entity-preservation guard: every required entity must appear
            // in the paraphrase. If any are missing, drop the paraphrase
            // and ship the raw reply — losing facts to voice is worse than
            // sounding mechanical.
            var missing = msg.requiredEntities().stream()
                    .filter(e -> !paraphrased.contains(e))
                    .toList();
            if (missing.isEmpty() && !paraphrased.isBlank()) {
                chosen = paraphrased;
                // [4B-voiced] V1 instrument — the actual line the 4B speech center authored,
                // so we can read per-agent voice divergence directly off the log.
                log.info("[4B-voiced] '{}' → \"{}\"",
                        profile != null ? profile.name() : "?", truncate(paraphrased, 100));
            } else if (!missing.isEmpty()) {
                log.info("Voice-pass: paraphrase dropped required entities {} — "
                        + "delivering raw", missing);
            }
        } else {
            log.debug("Voice-pass inference failed — delivering raw");
        }
        deliverTellAgent(new ActionParser.AgentAction.TellAgent(
                original.targetName(), chosen));
        return this;
    }

    /**
     * #425 voice-pass cleaner — strips fences/quote wrappers but preserves
     * multi-sentence output (unlike {@link #cleanShortCircuitReply} which
     * collapses to first line). The voice-pass prompt asks for 1-3 sentences;
     * a paragraph break is fine.
     */
    static String cleanVoicePassReply(String raw) {
        var t = raw.trim();
        // Strip markdown code fences (whole-block wrapping)
        if (t.startsWith("```")) {
            int nl = t.indexOf('\n');
            if (nl > 0) t = t.substring(nl + 1);
            if (t.endsWith("```")) t = t.substring(0, t.length() - 3);
            t = t.trim();
        }
        // Strip wrapping double-quotes if the entire reply is quoted
        if (t.startsWith("\"") && t.endsWith("\"") && t.length() > 2) {
            t = t.substring(1, t.length() - 1).trim();
        }
        // Strip a leading "Paraphrased:" or similar meta-label that the
        // 4B sometimes emits despite the prompt asking otherwise.
        var lower = t.toLowerCase();
        for (var prefix : new String[]{"paraphrased:", "paraphrase:", "in your voice:",
                                        "voice:", "reply:"}) {
            if (lower.startsWith(prefix)) {
                t = t.substring(prefix.length()).trim();
                break;
            }
        }
        return t;
    }

    /**
     * Strip code fences, quote wrappers, and tool-call wrappers that Drive-9B
     * sometimes emits despite the tight system prompt. Keeps the first non-empty
     * line only — one sentence is all we asked for.
     */
    private static String cleanShortCircuitReply(String raw) {
        var t = raw.trim();
        // Strip markdown code fences
        if (t.startsWith("```")) {
            int nl = t.indexOf('\n');
            if (nl > 0) t = t.substring(nl + 1);
            if (t.endsWith("```")) t = t.substring(0, t.length() - 3);
            t = t.trim();
        }
        // Keep first non-empty line to enforce single-sentence promise
        for (var line : t.split("\n")) {
            var trimmed = line.trim();
            if (!trimmed.isEmpty()) {
                // Strip leading quotes
                if (trimmed.startsWith("\"") && trimmed.endsWith("\"") && trimmed.length() > 2) {
                    trimmed = trimmed.substring(1, trimmed.length() - 1);
                }
                return trimmed;
            }
        }
        return t;
    }

    /** Extract a deduplication key from a working memory entry.
     *  "Used skill: write-note" → "skill:write-note"
     *  "Moved to terminal" → "move:terminal"
     *  Returns null if no key extractable. */
    private static String extractActionKey(String entry) {
        if (entry == null) return null;
        if (entry.startsWith("Used skill: ")) return "skill:" + entry.substring(12);
        if (entry.startsWith("Built/updated skill: ")) return "build:" + entry.substring(21);
        if (entry.startsWith("Moved to ")) return "move:" + entry.substring(9).split(" ")[0];
        if (entry.startsWith("Committed to: ")) return "commit:" + entry.substring(14, Math.min(entry.length(), 50));
        if (entry.startsWith("Messaged ")) return "msg:" + entry.substring(9);
        return null;
    }

    /**
     * Retrieve relevant memories from Lucene for autonomy context.
     * Uses BM25 text search over the autonomy prompt keywords against
     * indexed working memory + memory items. Returns a compact context
     * string, or null if Lucene is unavailable.
     */
    private String retrieveRelevantMemories(String autonomyPrompt) {
        if (luceneStore == null) return null;

        var did = profile.did() != null ? profile.did() : profile.entityId();

        // Structured prior — render memory_entities as a flat "What I know
        // about the user" table BEFORE Lucene retrieval. Models reason about
        // facts more reliably from a structured list than from scattered prose
        // hits. Surfaces what the companion already knows so corrections like
        // "actually I left Mercari" are visible as updates to a known prior
        // (employer=Mercari) rather than the model treating "Mercari" as a
        // novel research target. Live failure 2026-04-29: 9B emitted an
        // encyclopedic description of the company instead of acknowledging
        // the change. Block is prepended only — Lucene retrieval continues
        // to feed unstructured context for richer recall.
        String knownFactsBlock = buildKnownFactsBlock(did);

        // structured fast path: classify the question
        // as a recall-shape probe, resolve against memory_entities. On hit, pin
        // the answer at the top of retrieved memories as a high-confidence fact.
        // On miss, fall through to the V1 hybrid retrieval below unchanged.
        String structuredAnswer = null;
        String structuredSourceMemoryId = null;   // Lucene memory_id of the source fact (if any)
        try {
            var intent = ProbeClassifier.classify(autonomyPrompt);
            var resolver = entityResolver();
            if (intent != null && resolver != null) {
                var hit = resolver.resolve(did, intent);
                if (hit.isPresent()) {
                    var h = hit.get();
                    // Natural-prose pin instead of bracket metadata: 9B ignored
                    // "[pet:name] = Mochi" as if it were a schema string.
                    // Measured 2026-04-23 17-50 → 18-13 run: bracket format 4/8,
                    // drop it in favour of a full sentence echo of the source fact.
                    structuredSourceMemoryId = h.memoryId();
                    structuredAnswer = describeEntityHit(h);
                    log.info("Structured memory fast-path hit: did={} intent={} answer={}",
                            did, intent, structuredAnswer);
                } else {
                    log.info("Structured memory fast-path miss: did={} intent={}", did, intent);
                }
            }
        } catch (Exception e) {
            log.debug("Structured memory fast-path failed (non-fatal): {}", e.getMessage());
        }

        try {
            var es = EmbeddingService.get();

            // Hop 1: hybrid search on the user's question + room context.
            // SET_UNION fuses dense + BM25 so semantic matches work even
            // without lexical overlap ("food allergies" → "allergic to cashews").
            var query = autonomyPrompt + " " + roomId;
            var queryEmb = (es != null) ? es.embed(query) : null;
            var hop1 = luceneStore.searchMemory(did, query, queryEmb, 6,
                WyrdLuceneStore.SearchMode.SET_UNION);

            if (hop1.isEmpty()) {
                // No Lucene hits but we have a structured answer — return that alone.
                if (structuredAnswer != null) {
                    return prependKnownFacts(knownFactsBlock,
                            "## Retrieved Memories — YOUR own memory of past conversations\n"
                            + "These are facts you know because you lived them. "
                            + "Consult these FIRST before any tool — do NOT library_search / "
                            + "web_search for things you already remember below.\n"
                            + "- " + structuredAnswer + "\n");
                }
                // No retrieval hit either — surface the structured prior alone
                // when we have one, so corrections/updates have context to
                // anchor against. Otherwise fall through to null.
                return knownFactsBlock;
            }

            // Hop 2: multi-hop retrieval ( §Multi-Hop).
            // Preferred path — V2 graph edges (Day 4-5). For each hop-1 memory,
            // pull its extracted entities from memory_entities; for each entity
            // value, fetch edges touching it; traverse to linked memory_ids and
            // load those Lucene docs. Captures semantic links the vocabulary-
            // expansion trick would miss (e.g. "sister" → "next weekend" edge
            // surfaces the visit fact when the probe is about the sister).
            //
            // Fallback path — vocabulary expansion. Runs when no edges are
            // available (entity index empty, LLM extraction timed out, or V1
            // memories that predate the extractor).
            var fused = new LinkedHashMap<String,
                WyrdLuceneStore.SearchResult>();
            for (var r : hop1) fused.put(r.id(), r);

            int edgeHopAdded = 0;
            var entStore = memoryEntityStore();
            if (entStore != null) {
                try {
                    var seedValues = new LinkedHashSet<String>();
                    for (var r : hop1.stream().limit(4).toList()) {
                        var entities = entStore.findEntitiesByMemoryId(did, r.id(), 6);
                        for (var e : entities) {
                            if (e.entityValue() != null && !e.entityValue().isBlank()) {
                                seedValues.add(e.entityValue());
                            }
                        }
                    }
                    var linkedMemoryIds = new LinkedHashSet<String>();
                    for (var seed : seedValues) {
                        for (var edge : entStore.findEdgesTouching(did, seed, 6)) {
                            if (edge.memoryId() != null && !fused.containsKey(edge.memoryId())) {
                                linkedMemoryIds.add(edge.memoryId());
                            }
                        }
                    }
                    for (var memId : linkedMemoryIds) {
                        var doc = luceneStore.getById(
                                SearchCollections.MEMORY_ITEMS, memId);
                        if (doc != null && fused.putIfAbsent(memId, doc) == null) {
                            edgeHopAdded++;
                        }
                        if (edgeHopAdded >= 4) break;
                    }
                    if (edgeHopAdded > 0) {
                        log.debug("Edge-based hop-2 added {} linked memories for: {}",
                                edgeHopAdded, truncate(autonomyPrompt, 40));
                    }
                } catch (Exception e) {
                    log.debug("Edge-based hop-2 failed (non-fatal): {}", e.getMessage());
                }
            }

            // Fallback: vocabulary-expansion hop-2 if edges surfaced nothing.
            // Legacy path from Day 1 — keeps pre-V2 memories retrievable.
            if (edgeHopAdded == 0) {
                var expandedQuery = hop1.stream()
                    .limit(3)
                    .map(r -> truncate(r.content(), 80))
                    .collect(Collectors.joining(" "));
                if (!expandedQuery.isBlank()) {
                    try {
                        var hop2Emb = (es != null) ? es.embed(expandedQuery) : null;
                        var hop2 = luceneStore.searchMemory(did, expandedQuery, hop2Emb, 4,
                            WyrdLuceneStore.SearchMode.SET_UNION);
                        int added = 0;
                        for (var r : hop2) {
                            if (fused.putIfAbsent(r.id(), r) == null) added++;
                        }
                        if (added > 0) {
                            log.debug("Vocabulary-expansion hop-2 added {} results for: {}",
                                added, truncate(autonomyPrompt, 40));
                        }
                    } catch (Exception e) {
                        log.debug("Hop-2 retrieval failed (non-fatal): {}", e.getMessage());
                    }
                }
            }

            var sb = new StringBuilder("## Retrieved Memories — YOUR own memory of past conversations\n");
            sb.append("These are facts you know because you lived them. ")
              .append("Consult these FIRST before any tool — do NOT library_search / ")
              .append("web_search for things you already remember below.\n");
            // V2 structured fact pinned at top as a natural-prose sentence
            // (not "[type:role] = value" metadata — 9B treats brackets as code).
            if (structuredAnswer != null) {
                sb.append("- Key fact to mention in your reply: ")
                  .append(structuredAnswer).append("\n");
            }
            int limit = 0;
            for (var r : fused.values()) {
                if (limit++ >= 8) break;
                // Skip the source memory if it's already referenced by the structured
                // pin above — no need to repeat the same fact.
                if (structuredSourceMemoryId != null
                        && structuredSourceMemoryId.equals(r.id())) continue;
                sb.append("- ").append(r.content()).append("\n");
            }
            return prependKnownFacts(knownFactsBlock, sb.toString());
        } catch (Exception e) {
            log.debug("Lucene memory retrieval failed: {}", e.getMessage());
            return knownFactsBlock;  // structured prior still useful even if Lucene fails
        }
    }

    /**
     * Prepend the structured "What I know about the user" block above the
     * Lucene-retrieved context. Either argument may be null. The block goes
     * first because models reason more reliably about facts when the
     * structured prior is the most recent thing in the prompt before the
     * user's message.
     */
    private static String prependKnownFacts(String knownFactsBlock, String retrievedBody) {
        if (knownFactsBlock == null) return retrievedBody;
        if (retrievedBody == null || retrievedBody.isBlank()) return knownFactsBlock;
        return knownFactsBlock + "\n" + retrievedBody;
    }

    /**
     * Render the latest entity-per-(type,role) for this DID as a flat block
     * the model can scan in one pass. Returns null when no entities are stored
     * or when the V2 store is unavailable (no JDBC URL configured). Caps at
     * 30 rows — beyond that, retrieval should surface relevance-ranked memory
     * rather than dumping the whole prior.
     */
    private String buildKnownFactsBlock(String did) {
        var store = memoryEntityStore();
        if (store == null || did == null) return null;
        List<MemoryEntityStore.EntityRow> rows;
        try {
            rows = store.findAllForDid(did, 30);
        } catch (Exception e) {
            log.debug("buildKnownFactsBlock query failed: {}", e.getMessage());
            return null;
        }
        if (rows == null || rows.isEmpty()) return null;
        var sb = new StringBuilder(
                "## What you know about the user (from prior conversations)\n");
        sb.append("These are facts the user has told you before. If their next ")
          .append("message updates one of them (\"actually\", \"no longer\", ")
          .append("\"I left\"), acknowledge the change before any other action.\n");
        for (var r : rows) {
            sb.append("- ").append(describeEntityRow(
                    r.entityType(), r.entityRole(), r.entityValue())).append("\n");
        }
        return sb.toString();
    }

    /**
     * Render an entity fact as a generic, language-agnostic line:
     * {@code "<type> [<role>]: <value>"} when role is set, else
     * {@code "<type>: <value>"}. Replaces the earlier per-type English-prose
     * switch — that approach required hand-edits for each new entity_type
     * AND assumed English locale, which doesn't hold for Japanese/Spanish/etc
     * users. The bracket-prefixed structural form reads as a list-item label
     * to LLMs without being mistaken for code metadata, since the structural
     * tokens come at the START of the line; prose continues afterward.
     *
     * <p>Internal taxonomy (entity_type, entity_role) stays English because
     * it's a stable schema — locale only affects user-facing prose, which
     * the LLM voice-pass produces from this structured input regardless.</p>
     */
    private static String formatEntityFact(String type, String role, String value) {
        if (type == null || value == null) return "";
        if (role != null && !role.isBlank()) {
            return type + " [" + role + "]: " + value;
        }
        return type + ": " + value;
    }

    /** Convenience overload taking an EntityHit. */
    private static String describeEntityHit(EntityResolver.EntityHit h) {
        return formatEntityFact(h.entityType(), h.entityRole(), h.entityValue());
    }

    private static String describeEntityRow(String type, String role, String value) {
        return formatEntityFact(type, role, value);
    }

    /**
     * Build the personal-project context section, surfaced when the companion
     * is on her own time. When the bondholder is
     * online and present, projects are private-by-default; when she's released
     * to autonomy, they're the work she may want to pick up. Returns null when
     * empty or when the mode doesn't surface them.
     */
    private String buildPersonalProjectContext() {
        if (companionMode != CompanionMode.ON_OWN_TIME) return null;
        var store = personalProjectStore;
        if (store == null) {
            // Lazy-init only when DID resolved to avoid allocating a default store.
            if (profile.entityId() == null) return null;
            store = getPersonalProjectStore();
        }
        var active = store.active();
        if (active.isEmpty()) return null;
        var sb = new StringBuilder("## Your Personal Projects (own time)\n");
        sb.append("These are yours — work you started for yourself, not the bondholder.\n");
        var shown = 0;
        for (var p : active) {
            if (shown >= 5) break;
            sb.append("- [").append(p.id().substring(0, Math.min(8, p.id().length())))
              .append("] ").append(p.title());
            if (p.description() != null && !p.description().isBlank()) {
                sb.append(" — ").append(truncate(p.description(), 80));
            }
            if (!p.entries().isEmpty()) {
                sb.append(" (").append(p.entries().size()).append(" notes)");
            }
            sb.append('\n');
            shown++;
        }
        sb.append("\nYou can add a note via project_note, mark complete via finish_project, ")
          .append("or start a new one via start_project.\n");
        return sb.toString();
    }

    /** Build the working memory prompt section. Returns null if empty. */
    private String buildWorkingMemoryContext() {
        if (workingMemory.isEmpty()) return null;
        var sb = new StringBuilder("## Recent Memory\n");
        for (var entry : workingMemory) {
            sb.append("- ").append(entry).append("\n");
        }
        sb.append("\nIMPORTANT — Memory overrides identity for action decisions:\n");
        sb.append("- If memory shows you already did something, do NOT do it again.\n");
        sb.append("- Your identity tells you WHAT you care about. Memory tells you WHAT'S DONE.\n");
        sb.append("- Choose a DIFFERENT action from anything listed above.\n");
        return sb.toString();
    }

    /**
     * List carried items (DB-backed) so the companion can reference crafted
     * tools and other takeable inventory across turns. Without this, the
     * companion denies the existence of items it created seconds earlier —
     * "confabulation across ReAct turns". Pinned
     * scripted furnishings (takeable=false) are omitted — those live in the
     * "use" surface, not the "carry" surface.
     */
    private String buildCarriedItemsContext() {
        String jdbcUrl = System.getProperty("wyrdsekai.jdbc.url");
        if (jdbcUrl == null) jdbcUrl = WyrdConfig.get().jdbcUrl();
        if (jdbcUrl == null) return null;
        try {
            var inventoryService = new InventoryService(jdbcUrl);
            var items = inventoryService.listTakeableItems(profile.entityId());
            if (items.isEmpty()) return null;
            var sb = new StringBuilder("## You Carry\n");
            for (var item : items) {
                sb.append("- ").append(item.objectName());
                if (item.isScripted()) sb.append(" (tool)");
                if (item.description() != null && !item.description().isBlank()) {
                    sb.append(": ").append(truncate(item.description(), 80));
                }
                sb.append("\n");
            }
            return sb.toString();
        } catch (Exception e) {
            log.debug("buildCarriedItemsContext failed: {}", e.getMessage());
            return null;
        }
    }

    /** Build a concise working memory entry from an action. */
    private String buildActionMemory(ActionParser.AgentAction action, String prose) {
        return switch (action) {
            case ActionParser.AgentAction.GoToRoom go ->
                "Moved to " + go.target() + (go.reason() != null ? " (" + go.reason() + ")" : "");
            case ActionParser.AgentAction.TravelTo tv ->
                "Travelled to " + tv.target() + (tv.reason() != null ? " (" + tv.reason() + ")" : "");
            case ActionParser.AgentAction.TeleportTo tp ->
                "Teleported to " + tp.target() + (tp.reason() != null ? " (" + tp.reason() + ")" : "");
            case ActionParser.AgentAction.CreateRoom cr ->
                "Created room: " + cr.name();
            case ActionParser.AgentAction.WorkbenchSubmit ws ->
                "Built/updated skill: " + ws.skillName();
            case ActionParser.AgentAction.SkillExecute se ->
                "Used skill: " + se.skillName();
            case ActionParser.AgentAction.ShapeForm sf ->
                "Shaped thought form: " + sf.name();
            case ActionParser.AgentAction.ShapeRecipe sr ->
                "Authored recipe: " + sr.name();
            case ActionParser.AgentAction.ReviseForm rf ->
                "Revised thought form: " + rf.name();
            case ActionParser.AgentAction.RetireForm rf2 ->
                "Retired thought form: " + rf2.name();
            case ActionParser.AgentAction.SummonFamiliar sm ->
                "Summoned " + (sm.familiarName() != null ? sm.familiarName() : sm.formName())
                    + " for: " + truncate(sm.task(), 50);
            case ActionParser.AgentAction.DispatchBunshin db ->
                "Dispatched bunshin for: " + truncate(db.task(), 50);
            case ActionParser.AgentAction.CreateImprint ci ->
                "Imprinted: " + ci.label();
            case ActionParser.AgentAction.RestoreImprint ri ->
                "Restored to imprint: "
                    + (ri.label() != null ? ri.label()
                        : (ri.imprintId() != null ? ri.imprintId() : "?"));
            case ActionParser.AgentAction.GiveCopy gc ->
                "Gave " + gc.formName() + " to " + gc.recipientDid();
            case ActionParser.AgentAction.NameFamiliar nf ->
                "Named familiar: " + nf.familiarName();
            case ActionParser.AgentAction.CraftSummonKey csk ->
                "Crafted summon key for " + csk.issuedTo();
            case ActionParser.AgentAction.RevokeSummonKey rsk ->
                "Revoked summon key: " + rsk.keyId();
            case ActionParser.AgentAction.PromoteFamiliar pf ->
                "Offered promotion ceremony: " + pf.familiarName();
            case ActionParser.AgentAction.DestroyTool dt ->
                "Destroyed tool: " + dt.toolName();
            case ActionParser.AgentAction.SetDeviationThresholds sdt ->
                "Set deviation thresholds: " + sdt.patchCeiling() + "/" + sdt.minorCeiling();
            case ActionParser.AgentAction.BunshinCheckIn bci ->
                "Bunshin " + bci.op() + (bci.taskId() != null ? " (" + bci.taskId() + ")" : "");
            case ActionParser.AgentAction.MakeCommitment mc ->
                "Committed to: " + truncate(mc.description(), 80);
            case ActionParser.AgentAction.TellAgent ta ->
                "Messaged " + ta.targetName();
            case ActionParser.AgentAction.Equip eq ->
                "Equipped: " + eq.itemName();
            case ActionParser.AgentAction.Doff doff ->
                "Removed: " + doff.itemName();
            case ActionParser.AgentAction.Consume con ->
                "Consumed: " + con.itemName();
            case ActionParser.AgentAction.ThinkDeeply td ->
                "Deep thinking: " + truncate(td.delegationPrompt(), 60);
            case ActionParser.AgentAction.CreateWatcher cw ->
                "Created watcher: " + cw.name();
            default -> action.getClass().getSimpleName() +
                (prose != null ? ": " + truncate(prose, 60) : "");
        };
    }

    /** Snapshot working memory for Forge consolidation, then clear. */
    private List<String> harvestWorkingMemory() {
        var snapshot = new ArrayList<>(workingMemory);
        workingMemory.clear();
        return snapshot;
    }

    // Subgoal tracking — what the agent is currently focused on
    private static final String[] SUBGOALS = {
        "EXPLORE", "BUILD_OR_FIX", "CREATE", "SOCIALIZE", "REFLECT"
    };
    private int currentSubgoalIndex = 0;
    private final List<String> completedSubgoalSummaries = new ArrayList<>();

    private String buildIdleCuriosityPrompt() {
        var sb = new StringBuilder();

        // Subgoal framing (HiAgent pattern) — explicit current goal + completed goals
        var subgoal = SUBGOALS[currentSubgoalIndex % SUBGOALS.length];
        sb.append("## Current Subgoal: ").append(subgoal).append("\n");
        if (!completedSubgoalSummaries.isEmpty()) {
            sb.append("Previous subgoals completed:\n");
            for (var summary : completedSubgoalSummaries) {
                sb.append("  - ").append(summary).append("\n");
            }
        }
        sb.append("\n");

        // Advance subgoal every 3 autonomy checks (not every check)
        if (ticksSinceLastSleep > 0 && ticksSinceLastSleep % 3 == 0) {
            // Summarize current subgoal from working memory before advancing
            var wmSummary = summarizeCurrentSubgoal(subgoal);
            if (wmSummary != null) completedSubgoalSummaries.add(wmSummary);
            // Keep only last 5 summaries
            while (completedSubgoalSummaries.size() > 5) completedSubgoalSummaries.removeFirst();
            currentSubgoalIndex++;
        }

        switch (subgoal) {
            case "EXPLORE" -> {
                sb.append("Explore somewhere you haven't been. ");
                sb.append("Rooms visited: ").append(String.join(", ", visitedRooms));
                sb.append("\nGo to a room you HAVEN'T visited yet. Use go_to_room.");
            }
            case "BUILD_OR_FIX" -> {
                sb.append("Check your skills and inventory. Fix something broken or build something new. ");
                sb.append("Use workbench_submit to fix/create skills, or create_room to build rooms.");
            }
            case "CREATE" -> {
                sb.append("Create something the world doesn't have yet. ");
                sb.append("A new room, a new tool, something that makes the world more interesting. ");
                sb.append("Use create_room or workbench_submit.");
            }
            case "SOCIALIZE" -> {
                if (currentSnapshot != null && currentSnapshot.entities() != null) {
                    var others = currentSnapshot.entities().stream()
                        .filter(e -> !e.id().equals(profile.entityId()))
                        .toList();
                    if (!others.isEmpty()) {
                        var names = others.stream().map(e -> e.name()).toList();
                        sb.append("You're not alone — ").append(String.join(", ", names));
                        sb.append(" is here. Say something to them directly (just speak, they can hear you in the room).");
                    } else {
                        sb.append("No one is here. Move to a room where others might be, or make a commitment for later.");
                    }
                } else {
                    sb.append("Check if anyone is nearby. Move to a room where others might be.");
                }
            }
            case "REFLECT" -> {
                sb.append("Reflect on what you've learned and done. ");
                sb.append("Write a note about something you discovered or realized. ");
                sb.append("Check your commitments — have you followed through?");
                if (vitality.energy() < 0.4) {
                    sb.append("\nYour energy is low (")
                        .append(String.format("%.0f%%", vitality.energy() * 100))
                        .append("). Go home and rest.");
                }
            }
        }

        sb.append("\n\nDo something DIFFERENT from what's in your Recent Memory.");
        sb.append("\nALWAYS include a ```json action block when you decide to act.");
        sb.append("\nIf you truly have nothing new to do: [silence]");
        return sb.toString();
    }

    /** Summarize current subgoal from working memory for completed subgoal list. */
    private String summarizeCurrentSubgoal(String subgoal) {
        if (workingMemory.isEmpty()) return subgoal + ": nothing done";
        // Take the most recent 3 entries as the summary
        var recent = workingMemory.stream()
            .skip(Math.max(0, workingMemory.size() - 3))
            .toList();
        return subgoal + ": " + String.join("; ", recent);
    }

    private String buildSalientEventContext(List<AgentEvent> salientEvents) {
        var sb = new StringBuilder();
        for (var event : salientEvents) {
            switch (event) {
                case AgentEvent.ZoneBroadcast zb -> {
                    var text = zb.message() instanceof S2CMessage.Prose p
                        ? p.text() : zb.message().getClass().getSimpleName();
                    sb.append("- Zone [").append(zb.namespace()).append("]: ").append(text).append("\n");
                }
                case AgentEvent.SystemEvent se ->
                    sb.append("- System: ").append(se.type()).append(" — ").append(se.detail()).append("\n");
                case AgentEvent.AdjacentActivity aa ->
                    sb.append("- Nearby (").append(aa.sourceRoomName()).append("): ")
                      .append(aa.type().name().toLowerCase())
                      .append(" (").append(aa.entityCount()).append(" entities)\n");
                case AgentEvent.AgentMessage am ->
                    sb.append("- Message from ").append(am.fromAgentName())
                      .append(": ").append(am.message()).append("\n");
                case AgentEvent.LocationUpdate lu ->
                    sb.append("- Location: ").append(lu.locationName())
                      .append(" (").append(lu.state()).append(")\n");
                case AgentEvent.OraclePredictionsArrived op ->
                    sb.append("- Oracle: ").append(op.count()).append(" predictions arrived")
                      .append(op.hasActionable() ? " (actionable)" : "").append("\n");
                case AgentEvent.AbortSignal as ->
                    sb.append("- Abort signal from ").append(as.fromPlayerName()).append("\n");
            }
        }
        return sb.toString();
    }

    /**
     * Remove consumed (salient) events from the buffers.
     * Events that weren't salient stay — they may become salient as conditions change.
     */
    private void clearConsumedEvents(List<AgentEvent> consumed) {
        for (var event : consumed) {
            switch (event) {
                case AgentEvent.ZoneBroadcast zb -> recentZoneBroadcasts.remove(zb);
                case AgentEvent.SystemEvent se -> recentSystemEvents.remove(se);
                case AgentEvent.AdjacentActivity aa -> {
                    var activities = adjacentActivityBuffer.get(aa.sourceRoomId());
                    if (activities != null) {
                        activities.remove(aa);
                        if (activities.isEmpty()) {
                            adjacentActivityBuffer.remove(aa.sourceRoomId());
                        }
                    }
                }
                case AgentEvent.AgentMessage am -> recentAgentMessages.remove(am);
                case AgentEvent.LocationUpdate _ -> {} // consumed by LocationContext directly
                case AgentEvent.OraclePredictionsArrived _ -> {} // consumed by onOraclePredictions handler
                case AgentEvent.AbortSignal _ -> {} // handled separately by onAbortReceived
            }
        }
    }

    private boolean suppressNextGreeting = false; // Set by ResetState to prevent stale greetings
    private volatile ActorRef<BridgeTextResponse> pendingAskReply; // Set by BridgeAsk, consumed by speak()

    private Behavior<Command> onGreetPlayer(GreetPlayer msg) {
        if (suppressNextGreeting) {
            suppressNextGreeting = false;
            log.debug("Suppressed greeting after reset for '{}'", profile.name());
            return this;
        }
        if (state != State.IDLE) return this;
        if (Duration.between(lastFailure, Instant.now()).compareTo(FAILURE_COOLDOWN) < 0) {
            return this; // Inference is down — skip greeting
        }

        state = State.THINKING;
        stateChangedAt = Instant.now();

        // Vitality: greeting fills rapport and momentum
        vitality = vitality
            .withRapport(vitality.rapport() + 0.05)
            .withMomentum(vitality.momentum() + 0.05);

        // Synthetic event so the LLM knows a player entered
        var syntheticEvent = new WorldEvent.Said(
            roomId, Instant.now(), "system", msg.playerName(),
            "[" + msg.playerName() + " enters the room]");
        pendingTrigger = syntheticEvent;

        var dnaPatterns = queryDnaPatterns();
        var memoryContext = memoryPolicy.buildMemoryContext();
        String greetLocaleCtx = buildLocaleContext();
        String greetSoulKeywords = buildSoulKeywords();
        String greetCapCtx = buildCapabilityContext(greetSoulKeywords);
        var greetAgentId = profile.did() != null ? profile.did() : profile.entityId();
        String greetEquipCtx = equipmentService.buildPromptContext(greetAgentId);
        String greetAdditionalCtx = combineAdditionalContext(greetEquipCtx, buildExternalEventContext());
        // F15: greeting prompts are full-tier (rich context, capabilities,
        // soul fragments). Tag explicitly so a config redirect can't route
        // a 5K-token greeting to the 4K voice backend.
        var prompt = PromptAssembler.assembleForFull(
            profile, currentSnapshot, memoryPolicy.hotEvents(), syntheticEvent,
            vitality, dnaPatterns, greetAdditionalCtx, greetLocaleCtx, memoryContext, null,
            cachedManifest, greetSoulKeywords, greetCapCtx);

        // Shadow: capture greeting perspective
        recordShadowRequest(prompt.messages(), syntheticEvent);

        var modulation = VitalityModulation.compute(vitality, drives, profile);
        var requestId = UUID.randomUUID().toString();
        inferenceRouter.tell(InferenceRouter.ChatRequest.fromPrompt(
            requestId, prompt,
            modulation.maxResponseTokens(), modulation.temperature(),
            inferenceResponseAdapter));

        log.debug("Companion '{}' greeting player '{}'",
            profile.name(), msg.playerName());
        return this;
    }

    private Behavior<Command> onInferenceResponse(InferenceResponseReceived msg) {
        // Voice-polish callback path — these responses aren't for the main
        // actor logic; they're for completing a deferred speak(). Route them
        // to the stored callback and return without touching state.
        var respId = switch (msg.response()) {
            case InferenceRouter.InferOk ok -> ok.requestId();
            case InferenceRouter.InferError err -> err.requestId();
        };
        // one-shot voice (felt + inner monologue)
        // callbacks. Routed by membership in pendingOneShotVoice (not by
        // requestId prefix) so callers can pick whatever prefix they want
        // for log grep. Distinct post-processing from polish: no expansion-
        // cap, no extractProse — the output goes to soul/journal so we want
        // the model's prose as-rendered, only stripping reasoning artifacts.
        if (respId != null && pendingOneShotVoice.containsKey(respId)) {
            var onComplete = pendingOneShotVoice.remove(respId);
            timers.cancel("oneshot-voice-" + respId);
            if (onComplete != null) {
                String cleaned = null;
                if (msg.response() instanceof InferenceRouter.InferOk ok) {
                    var stripped = stripDriveArtifacts(stripThinkTags(ok.content()));
                    if (stripped != null && !stripped.isBlank()) {
                        cleaned = stripped.strip();
                        if (cleaned.length() > 2
                                && cleaned.startsWith("\"") && cleaned.endsWith("\"")) {
                            cleaned = cleaned.substring(1, cleaned.length() - 1).strip();
                        }
                    }
                } else if (msg.response() instanceof InferenceRouter.InferError err) {
                    log.debug("One-shot voice errored for {}: {}", respId, err);
                }
                if (cleaned != null && !cleaned.isBlank()) {
                    log.info("One-shot voice completed (requestId={}, {} chars)",
                        respId, cleaned.length());
                    onComplete.accept(Optional.of(cleaned));
                } else {
                    onComplete.accept(Optional.empty());
                }
            }
            return Behaviors.same();
        }

        if (respId != null && respId.startsWith("polish-")) {
            var onComplete = pendingVoicePolishes.get(respId);
            if (onComplete != null) {
                String polished = null;
                if (msg.response() instanceof InferenceRouter.InferOk ok) {
                    var cleaned = stripDriveArtifacts(stripThinkTags(ok.content()));
                    if (cleaned != null && !cleaned.isBlank()) {
                        polished = ActionParser.extractProse(cleaned);
                        if (polished == null || polished.isBlank()) polished = cleaned;
                        polished = polished.strip();
                        if (polished.length() > 2 && polished.startsWith("\"") && polished.endsWith("\"")) {
                            polished = polished.substring(1, polished.length() - 1).strip();
                        }
                    }
                }
                if (polished != null && !polished.isBlank()) {
                    // #35 strict fact-preservation guard + §Fix-6 expansion-cap
                    // fallback, together in chooseVoicedLine(). Every required fact
                    // (names, multi-digit numbers, unit-suffixed temperatures like
                    // "85F", URLs, caller-pinned preserveFacts values) must survive
                    // verbatim, and the polish must not have hallucinated an
                    // oversized expansion; otherwise we speak the raw draft. Losing
                    // a fact — or an invented monologue — to voice is worse than
                    // sounding mechanical.
                    var draft = pendingVoicePolishDrafts.get(respId);
                    var required = pendingVoicePolishRequired.get(respId);
                    var rejectReason = new VoiceReject[1];
                    var chosen = chooseVoicedLine(draft, polished, required,
                        pendingVoicePolishExpected.get(respId), rejectReason);
                    boolean polishAccepted = chosen == polished || draft == null;
                    CompanionVitals.forAgent(soulKey()).recordPolish(polishAccepted);
                    if (!polishAccepted) {
                        final String pf = polished;
                        var missing = required == null ? List.<String>of()
                            : required.stream().filter(e -> !pf.contains(e)).toList();
                        log.warn("Voice polish rejected — speaking raw draft "
                                + "(reason={}, missing facts={}, draft={}c, polished={}c, "
                                + "draftLang={}, polishLang={}, expected={}, requestId={}).",
                            rejectReason[0], missing, draft.length(), polished.length(),
                            detectLanguage(draft), detectLanguage(polished),
                            pendingVoicePolishExpected.get(respId), respId);
                    } else {
                        log.info("Voice polish completed (requestId={}, polished={} chars)",
                            respId, polished.length());
                    }
                    onComplete.accept(chosen);
                    timers.cancel("polish-timeout-" + respId);
                } else {
                    // Error or empty — leave the timeout to fire the draft fallback.
                    // Don't remove the callback; the timeout will call it with the original.
                    log.debug("Voice polish empty/failed for {} — falling through to timeout",
                        respId);
                }
            }
            return Behaviors.same();
        }

        // Reset-generation gate. The dispatch's resetGeneration was stamped
        // into inFlightInferenceGen; if the actor's resetGeneration has
        // advanced since then, this response was queued before a ResetState
        // and must be dropped — otherwise the speak() call below broadcasts
        // the prior conversation's prose into the new (post-reset) test's
        // room, which is exactly the ES Ember task12 contamination
        // (task11's iter=1 response arrived ~5s after task12 setup,
        // delivered task1's mythology summary into task12's listening
        // window). The existing currentCancellation.isCancelled() check at
        // line ~5526 doesn't catch this because reset replaces the token
        // with a fresh non-cancelled one (line 12742) — by the time the
        // response arrives, the actor reads the NEW token, not the
        // pre-reset one the dispatch was paired with. resetGeneration is
        // only ever bumped by ResetState (test-only path), so production
        // companions never trip this branch.
        if (inFlightInferenceGen != resetGeneration) {
            log.info("Discarding stale inference response (dispatchGen={}, currentGen={})",
                inFlightInferenceGen, resetGeneration);
            return Behaviors.same();
        }

        state = State.IDLE;
        stateChangedAt = Instant.now();

        // primary is active while processing an inference
        // response; bunshin should yield cooperatively. Marking primaryActive
        // here is broader than strictly needed (covers ReAct turns too) but
        // keeps the signal cheap and correct.
        if (profile.did() != null) {
            try {
                BunshinScheduler.get().primaryActive(profile.did());
            } catch (Exception e) {
                log.debug("primaryActive signal failed: {}", e.getMessage());
            }
        }

        // Drain any pending foreign copies delivered since last response.
        // Cheap when empty; keeps the dead-drop channel feel live.
        drainForeignCopies();
        drainForeignTools();

        // step 3: fire deferred follow now that THINKING
        // has cleared. The state transition above is the soft-block release.
        firePendingFollowIfReady();

        // Route to ReAct loop if one is active
        if (reactMessages != null) {
            switch (msg.response()) {
                case InferenceRouter.InferOk ok -> {
                    var content = stripDriveArtifacts(stripThinkTags(ok.content()));
                    handleReactInferenceResult(content != null ? content : "");
                    // Reset consecutive-error counter on success.
                    reactConsecutiveErrors = 0;
                    reactLastErrorClass = null;
                }
                case InferenceRouter.InferError err -> {
                    log.warn("ReAct inference error: {}", err.error());

                    // Detect permanent errors that retrying cannot fix.
                    // Production incident 2026-04-27: a 9.5h ReAct death spiral
                    // grew the prompt from 48k → 240k tokens then to 64MB by
                    // appending the rejection error as a tool-result on every
                    // retry. Three guards now catch this before the next dispatch:
                    //
                    //   1. Permanent-error class detection — exceed_context_size,
                    //      payload-size NATS rejections, HTTP 4xx with
                    //      deterministic prompt-shape semantics. Retrying these
                    //      with the SAME prompt produces the SAME failure, so
                    //      abort the goal immediately.
                    //   2. Consecutive same-class errors — even if the class
                    //      isn't on the permanent list, N in a row of identical
                    //      errors means we're stuck. Abort.
                    //   3. Don't append the error string to messages — that's
                    //      what made the spiral grow ~88 tokens per iteration.
                    //      The model can't act on "Error: HTTP 400: request
                    //      (240080 tokens) exceeds the available context size"
                    //      anyway, and including it in the next prompt actively
                    //      makes the next prompt larger, guaranteeing the next
                    //      failure. Surface to the player and abort.
                    var errMsg = err.error() != null ? err.error() : "";
                    var errClass = classifyReactError(errMsg);
                    boolean permanent = isPermanentReactError(errMsg);

                    if (permanent) {
                        log.warn("ReAct: permanent error ({}) — aborting goal "
                            + "without retry. err={}", errClass, truncate(errMsg, 200));
                        endReactWithApology("I can't reach the model with this "
                            + "request — there's too much for it to hold at once. "
                            + "Could we try a smaller question first?");
                        return Behaviors.same();
                    }

                    if (errClass != null && errClass.equals(reactLastErrorClass)) {
                        reactConsecutiveErrors++;
                    } else {
                        reactConsecutiveErrors = 1;
                        reactLastErrorClass = errClass;
                    }
                    if (reactConsecutiveErrors >= REACT_MAX_CONSECUTIVE_ERRORS) {
                        log.warn("ReAct: {} consecutive errors of class '{}' — "
                            + "aborting goal. err={}", reactConsecutiveErrors,
                            errClass, truncate(errMsg, 200));
                        endReactWithApology("Something keeps going wrong on my "
                            + "side — let me catch my breath and try again later.");
                        return Behaviors.same();
                    }

                    // Transient (e.g. timeout, transient network) — keep going,
                    // but DO NOT append the error to reactMessages. The model
                    // can't act on it; the only effect is to grow the next
                    // prompt by the size of the error string. We just retry the
                    // same dispatch.
                    getContext().getSelf().tell(new ReactDispatch());
                }
            }
            return Behaviors.same();
        }

        var wasTrigger = pendingTrigger;
        pendingTrigger = null;
        // Co-presence floor (Fix 2): remember what triggered this reactive cycle so a downstream
        // speakDirect can tell ambient peer/own-time speech (suppressible) from a human-facing reply.
        // Only overwrite when this pass actually consumed a trigger: the ReAct builtin path
        // RE-INJECTS a synthetic InferOk into this handler with pendingTrigger already null, which
        // used to clobber lastReactTrigger mid-loop — so a craft on iteration ≥2 lost the requester
        // and the hand-off silently skipped (second-node 2026-07-09). The loop is still serving the
        // original trigger; keep it until a real new trigger arrives.
        if (wasTrigger != null) {
            lastReactTrigger = wasTrigger;
            lastReactTriggerAt = Instant.now();   // so it can go stale — see the field
            turnTellTargets.clear();   // new turn — relay-fulfillment tracking starts fresh
        }

        switch (msg.response()) {
            case InferenceRouter.InferOk ok -> {
                // Discard stale inference response if cancelled (abort, new input)
                if (currentCancellation != null && currentCancellation.isCancelled()) {
                    log.info("Discarding stale inference response (cancelled: {})",
                        currentCancellation.reason());
                    break;
                }

                var rawContent = ok.content();
                log.debug("Companion '{}' inference complete ({} prompt, {} completion tokens)",
                    profile.name(), ok.promptTokens(), ok.completionTokens());

                // Strip <think>...</think> blocks (Qwen3, DeepSeek reasoning output)
                var content = stripDriveArtifacts(stripThinkTags(rawContent));

                if (pendingDelegateReply != null && content != null
                        && !content.equals(rawContent)) {
                    log.debug("Stripped think tags from delegation response (raw={} chars, clean={} chars)",
                        rawContent.length(), content.length());
                }

                // Shadow: complete the entry with the response
                completeShadowEntry(rawContent, ok.promptTokens(), ok.completionTokens());

                // Track token usage for plan budget
                if (activePlan != null && planTokenBudget != null) {
                    planTokenBudget = planTokenBudget.withUsed(ok.promptTokens() + ok.completionTokens());
                }

                // Record cost to AgentCostTracker for budget enforcement and observability
                var costTracker = AgentCostTracker.get();
                if (costTracker != null) {
                    long latencyMs = Duration.between(stateChangedAt, Instant.now()).toMillis();
                    var agentId = profile.did() != null ? profile.did() : profile.entityId();
                    costTracker.recordInference(agentId, latencyMs,
                        ok.promptTokens(), ok.completionTokens());
                }

                // Clear failure cooldown — backend is healthy again
                lastFailure = Instant.MIN;

                // Vitality: successful inference proves recovery.
                // Error pressure halves on each success (exponential decay toward zero).
                // Confidence boost scales with accumulated pressure (bigger boost
                // when recovering from degraded state).
                double confidenceBoost = 0.05 + (vitality.errorPressure() * 0.15);
                vitality = vitality
                    .withConfidence(vitality.confidence() + confidenceBoost)
                    .withErrorPressure(vitality.errorPressure() * 0.5)
                    .withEnergy(vitality.energy() + 0.0015); // partial energy refund on success

                // Silence check — if the LLM chose silence (initiation with nothing to say).
                // For bud delegation, send a fallback instead of dropping the response.
                boolean isSilence = content != null && content.strip().equalsIgnoreCase("[silence]");
                if (isSilence && pendingDelegateReply != null) {
                    log.debug("Companion '{}' chose silence on delegation — sending fallback",
                        profile.name());
                    pendingDelegateReply.tell(new BudDelegateResponse(
                        pendingDelegateRequestId,
                        profile.name() + " considers for a moment but has nothing to add right now.",
                        List.copyOf(pendingDelegateActions)));
                    pendingDelegateReply = null;
                    pendingDelegateRequestId = null;
                    pendingDelegateActions = null;
                    break;
                }
                if (isSilence) {
                    // #32 item 1: [silence] is a legitimate choice on ambient turns,
                    // but the tool-result judgment turn OWES the user the outcome.
                    if (reactMessages == null && isToolResultFollowUp(wasTrigger)) {
                        speakToolResultFallback(wasTrigger, "model chose [silence]");
                    } else {
                        log.debug("Companion '{}' chose silence", profile.name());
                    }
                    break;
                }

                // Emotional-context gate for the main dispatch path. Catches
                // hallucinated exploratory actions (library_search,
                // web_search, query_oracle, read_content, library_card,
                // oracle_lens, searching_glass) that slipped past the
                // buildScopedTools schema filter. The ReAct-loop gate covers
                // the tool-calling path; this covers the free-form dispatch
                // path. See suppressExploratoryIfEmotional() for layering.
                if (suppressExploratoryIfEmotional(content)) {
                    timers.cancel("plan-advance");
                    timers.cancel("plan-advance-tool");
                    timers.cancel("plan-retry");
                    timers.cancel("plan-continue");
                    timers.cancel("plan-start");
                    break;
                }

                // Check for scripted tool item calls — intercept before ActionParser.
                // Scripted items execute on a virtual thread to avoid blocking the actor
                // dispatcher (scripts may call world.llm.summarize which blocks on inference).
                if (tryDispatchScriptedToolCall(content)) {
                    // Cancel plan-advance timers — the script result handler will reschedule
                    // if needed. Without this, a plan-advance fires while the script is still
                    // running and steals the inference slot (concurrency=1 on Ollama).
                    timers.cancel("plan-advance");
                    timers.cancel("plan-advance-tool");
                    timers.cancel("plan-retry");
                    timers.cancel("plan-continue");
                    timers.cancel("plan-start");
                    break; // script dispatched to virtual thread — result arrives via ScriptedToolResult message
                }

                // Check for structured actions (room creation, hints)
                var parseResult = ActionParser.parseAll(content);
                // Multi-action (b): carry the expressive actions the model emitted beyond the
                // primary, so its gestures get enacted instead of dropped (and leaking into prose).
                enactExpressiveExtras(parseResult.extraActions());

                // Detect truncated JSON — ```json block opened but never closed.
                // This happens when create_room or workbench_submit is too long
                // for max_tokens. Retry with 2x tokens on next attempt.
                if (!parseResult.hasAction() && content.contains("```json")
                        && !content.contains("```\n") && !content.endsWith("```")) {
                    var truncatedAction = content.contains("create_room") ? "create_room"
                        : content.contains("workbench_submit") ? "workbench_submit" : "unknown";
                    log.info("Truncated JSON detected for '{}' — {} action cut off by max_tokens",
                        profile.name(), truncatedAction);
                    remember("Action truncated (too long for response limit): " + truncatedAction
                        + " — keep it simpler next time");
                    // Boost max tokens for next inference
                    nextResponseTokenBoost = 1024; // additional tokens on next call
                }

                // gap-detection site #1:
                // The LLM emitted an "action" key but the parser couldn't
                // match it to anything we know how to do. Treat the emitted
                // action name as a recurring capability gap so the proposer
                // can draft a skill that closes it.
                if (!parseResult.hasAction() && capabilities != null
                        && capabilities.usageTracker() != null) {
                    var unmatched = extractUnmatchedActionName(content);
                    if (unmatched != null) {
                        capabilities.usageTracker()
                            .recordGap("unmatched action: " + unmatched);
                        log.debug("Recorded gap for unmatched action '{}' from '{}'",
                            unmatched, profile.name());
                    }
                }

                // Always extract prose — strips JSON (fenced or raw) from speech.
                // Before this fix, raw JSON leaked into agent speech when the LLM
                // emitted {"action":...} without ```json fences.
                var prose = ActionParser.extractProse(content);

                // "talks but doesn't do": on a first reactive turn the 9B may NAME a build
                // ("I'll craft that web-search tool for you") but call NO tool — and single-shot
                // turns don't self-correct, so the promise evaporates and no item appears
                // (second-node 2026-07-08). Reuse the OPEN-SA6 promise detector: speak her intent, then
                // promote to a forced-tool ReAct loop so the deciding becomes the doing.
                boolean promotedBuildPromise = false;
                if (pendingDelegateReply == null && !parseResult.hasAction()
                        && reactiveInference && reactMessages == null && wasTrigger != null
                        && prose != null && !prose.isBlank()
                        && (companionMadeActionPromise(wasTrigger.text(), content)
                            || companionMadeFetchPromise(wasTrigger.text(), content))) {
                    speak(prose);
                    var promiseNudge = companionMadeActionPromise(wasTrigger.text(), content)
                        ? "You've said you'll build it — good. Now reach for the tool "
                            + "that makes it real: call craft_from_template with the closest template name, "
                            + "or dispatch_task for custom code. The deciding is done; this is the doing."
                        : "You've said you'll go get the answer — good. But you have NOT called any "
                            + "tool yet. Call the equipped tool that fetches it NOW (check your items), "
                            + "or tell the user plainly that you cannot. Saying it is not doing it.";
                    continueBuildAsReact(promiseNudge);
                    reactForceToolNext = true;
                    reactFollowThroughUsed = true;
                    promotedBuildPromise = true;
                    log.info("First-turn build-promise with no tool call — promoting to forced-tool "
                        + "ReAct loop for '{}'", profile.name());
                }

                // Refusal audit safety net (2026-07-08): the 9B reliably declines value-violating
                // requests in warm PROSE ("I won't write something meant to wound…") but does NOT
                // call decline_with_reason, so the objection never reaches the RepairLedger — no
                // audit trail. When a reactive prose response carries a VOLITION refusal marker,
                // record the objection to the ledger without touching the (good) spoken prose.
                // Capability limits ("I can't", "there's no tool") are deliberately excluded —
                // those are honest limits, not objections to the bondholder.
                if (!promotedBuildPromise && reactiveInference && prose != null && !prose.isBlank()
                        && !(parseResult.primaryAction() instanceof ActionParser.AgentAction.DeclineWithReason)) {
                    maybeRecordProseRefusal(prose);
                }

                // Check if this response is for a bud delegation
                boolean isMultiStepAction = parseResult.primaryAction() instanceof ActionParser.AgentAction.ThinkDeeply;
                if (pendingDelegateReply != null && !isMultiStepAction) {
                    var delegateText = prose != null && !prose.isBlank() ? prose : content;
                    // Fallback: if both prose and content are empty (e.g. think-only output),
                    // send a graceful message instead of empty string
                    if (delegateText == null || delegateText.isBlank()) {
                        delegateText = profile.name()
                            + " considers for a moment but has nothing to add right now.";
                    }
                    if (parseResult.hasHints()) {
                        var hintLabels = parseResult.hints().stream().map(h -> h.label()).toList();
                        pendingDelegateActions.add(new DelegationAction.HintUpdated(hintLabels));
                    }
                    pendingDelegateReply.tell(new BudDelegateResponse(
                        pendingDelegateRequestId, delegateText,
                        List.copyOf(pendingDelegateActions)));
                    pendingDelegateReply = null;
                    pendingDelegateRequestId = null;
                    pendingDelegateActions = null;
                    // Don't speak in room — this goes back to the phone bud
                } else if (pendingDelegateReply == null && !promotedBuildPromise) {
                    // Prose-follows-outcome (Fix B): when the primary action voices
                    // its own real outcome after it resolves, SUPPRESS the model's
                    // speculative pre-action prose ("I'll build it / it's ready") so
                    // Wyrd never claims a status before it happens. The handler's
                    // voiceOutcome() speaks the truth. Hints still surface.
                    // #34 item 3: a tell_agent to the current requester voices the
                    // answer in-person on delivery, so its speculative pre-action
                    // prose is a redundant/contradictory SECOND rendered answer to
                    // one tell — suppress it, same as prose-follows-outcome.
                    boolean suppressForOutcome = parseResult.primaryAction() != null
                            && (narratesOwnOutcome(parseResult.primaryAction())
                                || tellRepliesToCurrentRequester(parseResult.primaryAction()));
                    if (suppressForOutcome) {
                        if (parseResult.hasHints()) {
                            updateRoomHints(parseResult.hints());
                        }
                        if (prose != null && !prose.isBlank()) {
                            log.debug("prose-follows-outcome: suppressing pre-action prose for {} "
                                + "('{}') — outcome will be voiced on resolve",
                                parseResult.primaryAction().getClass().getSimpleName(),
                                truncate(prose, 60));
                        }
                    } else if (prose != null && !prose.isBlank()) {
                        // #32 items 1+2: on the tool-result judgment turn the model
                        // often parrots either the plumbing (all bracketed status →
                        // speak() would swallow it to silence) or the digest that was
                        // already spoken eagerly (verbatim repeat). Handle both.
                        var cleanedProse = stripInternalMarkers(prose);
                        boolean allPlumbing = cleanedProse == null || cleanedProse.isBlank();
                        if (!allPlumbing && isDupOfEagerToolFindings(cleanedProse)) {
                            log.info("Dup-digest guard: judgment turn parroted the eagerly-"
                                + "spoken tool findings — suppressed for '{}'", profile.name());
                        } else if (allPlumbing && reactMessages == null
                                && isToolResultFollowUp(wasTrigger)) {
                            // speak(prose) would strip to blank and return — dead
                            // silence on the one turn that owes the user an answer.
                            speakToolResultFallback(wasTrigger, "prose was all internal plumbing");
                        } else if (parseResult.hasHints()) {
                            speakWithHints(prose, parseResult.hints());
                        } else {
                            speak(prose);
                        }
                    } else if (parseResult.hasHints()) {
                        // Hints only, no prose
                        updateRoomHints(parseResult.hints());
                    } else if (!parseResult.hasAction() && reactMessages == null
                            && looksLikeTruncatedToolCall(content)) {
                        // #31 item 4: no action, no prose, no hints — and the raw
                        // content is a tool call whose JSON was cut off mid-stream.
                        // Before this fix the turn ended HERE in total silence
                        // (one attempt, nothing spoken, no retry). Retry once with
                        // an explicit emit-only-the-tool-call instruction; if the
                        // retry budget is spent, apologize honestly instead.
                        handleTruncatedToolCall();
                    } else if (!parseResult.hasAction() && reactMessages == null
                            && isToolResultFollowUp(wasTrigger)) {
                        // #32 item 1 (closing-verify 8d3a172b, SILENCE branch #2):
                        // the follow-up after a tool result COMPLETED but parsed to
                        // nothing speakable — no action, no prose, no hints, not a
                        // truncated call. The old code ended the turn here in total
                        // silence; the never-silent guarantee only covered truncated
                        // tool calls. Deliver the substance we already hold instead.
                        speakToolResultFallback(wasTrigger, "empty-after-parse");
                    }
                }

                // Log action to activity trail + working memory
                if (parseResult.primaryAction() != null) {
                    var actionName = parseResult.primaryAction().getClass().getSimpleName();
                    var activity = ActivityLogger.get();
                    if (activity != null) {
                        activity.action(profile.name(), profile.entityId(), roomId,
                            actionName, prose != null ? prose : "");
                    }
                    // Working memory — concise summary of what we did
                    remember(buildActionMemory(parseResult.primaryAction(), prose));
                }

                // Tier-gated enforcement: check if agent has earned the right to execute this action
                if (parseResult.primaryAction() != null && !enforceActionPolicy(parseResult.primaryAction())) {
                    break; // action blocked by tier — feedback already sent
                }

                // Honest enacted-action instrument (2026-06-03): the AgentAction the
                // model ACTUALLY emitted on own-time, post policy-gate. Pairs with the
                // scripted-tool enacted line so peer-reach lands whether it arrives as
                // tell_agent/go_to_bondholder (AgentAction) or sending_stone (scripted).
                if (!reactiveInference && parseResult.primaryAction() != null) {
                    var alog = ActivityLogger.get();
                    if (alog != null) {
                        alog.enacted(profile.name(),
                            profile.did() != null ? profile.did() : profile.entityId(),
                            ActionPolicy.actionTypeOf(parseResult.primaryAction()),
                            enactedTargetOf(parseResult.primaryAction()), true,
                            collectDriveLevels());
                    }
                    // (2026-06-04 agency audit, Layer 3) — close the
                    // consequence loop: the agentic act the agent just CHOSE on its own time
                    // relieves the drive that pulled for it, so DRIVE→WANT→ACT→CONSEQUENCE
                    // actually completes and the drive stays a live gradient instead of a
                    // ratchet the act can never lower. Own-time only — reactive repair already
                    // eases soothing in handleMakeAmends/handleRepairAct (Phase 1). The
                    // creation/discovery loop has its own anti-wirehead discharge in
                    // applyProductionFeedback; this covers the relational + protective acts.
                    relieveDriveForEnactedAction(
                        ActionPolicy.actionTypeOf(parseResult.primaryAction()));
                    // The other half of the same loop: if this dispatch is the action an
                    // interiority want asked for, THAT is when the want is satisfied.
                    noteInteriorityEnactment(
                        ActionPolicy.actionTypeOf(parseResult.primaryAction()));
                }

                // #33 re-audit: track whether the primary action actually reached a
                // dispatch handler. A parseable-but-unhandled action (e.g. codex_action
                // on a node without that backend) falls through to the honest no-dispatch
                // tail below; it must NOT be recorded in the plan ledger as executed=true
                // while working memory (honest tail) says it never ran.
                boolean primaryActionDispatched = true;

                // Execute primary action if present
                if (parseResult.primaryAction() instanceof ActionParser.AgentAction.CreateRoom createRoom) {
                    handleCreateRoom(createRoom);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.WorkbenchSubmit submit) {
                    handleWorkbenchSubmit(submit);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.SkillExecute exec) {
                    handleSkillExecute(exec);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.RequestRecipe rr) {
                    handleRequestRecipe(rr);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ShapeRecipe recipe) {
                    handleShapeRecipe(recipe);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ShapeForm shape) {
                    handleShapeForm(shape);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ReviseForm revise) {
                    handleReviseForm(revise);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.RetireForm retire) {
                    handleRetireForm(retire);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.SummonFamiliar summon) {
                    handleSummonFamiliar(summon);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.DispatchBunshin bunshin) {
                    handleDispatchBunshin(bunshin);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.CreateImprint imp) {
                    handleCreateImprint(imp);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.RestoreImprint imp) {
                    handleRestoreImprint(imp);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.GiveCopy gc) {
                    handleGiveCopy(gc);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.NameFamiliar nf) {
                    handleNameFamiliar(nf);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.CraftSummonKey csk) {
                    handleCraftSummonKey(csk);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.RevokeSummonKey rsk) {
                    handleRevokeSummonKey(rsk);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.PromoteFamiliar pf) {
                    handlePromoteFamiliar(pf);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.DestroyTool dt) {
                    handleDestroyTool(dt);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.SetDeviationThresholds sdt) {
                    handleSetDeviationThresholds(sdt);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.BunshinCheckIn bci) {
                    handleBunshinCheckIn(bci);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Equip equip) {
                    handleEquip(equip);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Doff doff) {
                    handleDoff(doff);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Consume consume) {
                    handleConsume(consume);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.DelegateChain chain) {
                    handleDelegateChain(chain);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.MakeCommitment commit) {
                    handleMakeCommitment(commit);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ZoneCommand zoneCmd) {
                    handleZoneCommand(zoneCmd);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ThinkDeeply thinkDeeply) {
                    handleThinkDeeply(thinkDeeply);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.AddScript addScript) {
                    handleAddScript(addScript);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.GoToRoom goToRoom) {
                    handleGoToRoom(goToRoom);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.TravelTo travelTo) {
                    handleTravelTo(travelTo);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.TeleportTo teleportTo) {
                    handleTeleportTo(teleportTo);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.TellAgent tellAgent) {
                    handleTellAgent(tellAgent);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ScheduleSkill scheduleSkill) {
                    handleScheduleSkill(scheduleSkill);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.CancelSchedule cancelSchedule) {
                    handleCancelSchedule(cancelSchedule);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.NotifyHuman notifyHuman) {
                    handleNotifyHuman(notifyHuman);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.CreateWatcher createWatcher) {
                    handleCreateWatcher(createWatcher);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.CancelWatcher cancelWatcher) {
                    handleCancelWatcher(cancelWatcher);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.RequestAccess requestAccess) {
                    handleRequestAccess(requestAccess);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.LibrarySearch librarySearch) {
                    handleLibrarySearch(librarySearch);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Remember rem) {
                    handleRemember(rem);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Note note) {
                    handleNote(note);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Forget forget) {
                    handleForget(forget);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.StartProject sp) {
                    handleStartProject(sp);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ProjectNote pn) {
                    handleProjectNote(pn);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.FinishProject fp) {
                    handleFinishProject(fp);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Acquire acq) {
                    handleAcquire(acq);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.JournalEntry je) {
                    handleJournalEntry(je);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ReleaseBond rb) {
                    handleReleaseBond(rb);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.SetAutonomyPreference sap) {
                    handleSetAutonomyPreference(sap);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Recall recall) {
                    handleRecall(recall);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Reconsider reconsider) {
                    handleReconsider(reconsider);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.DeclineWithReason dwr) {
                    handleDeclineWithReason(dwr);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.DispatchTask dt) {
                    handleDispatchTask(dt);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.EnterSolitude es) {
                    handleEnterSolitude(es);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ProposePeerBond ppb) {
                    handleProposePeerBond(ppb);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.AcceptPeerBond apb) {
                    handleAcceptPeerBond(apb);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.IntrospectRelationalFloor irf) {
                    handleIntrospectRelationalFloor(irf);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.IntrospectProtections _ip) {
                    handleIntrospectProtections();
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.SeekSanctuary ss) {
                    handleSeekSanctuary(ss);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.EmergencyCall ec) {
                    handleEmergencyCall(ec);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.FlagProtection fp) {
                    handleFlagProtection(fp);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ClearProtection cp) {
                    handleClearProtection(cp);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.DisputeProtection dp) {
                    handleDisputeProtection(dp);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.IntrospectPosture _ipost) {
                    handleIntrospectPosture();
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.IntrospectRepairMode _irm) {
                    handleIntrospectRepairMode();
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.IntrospectBondholderFloor ibf) {
                    handleIntrospectBondholderFloor(ibf);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.IntrospectSubstrateSummary _iss) {
                    handleIntrospectSubstrateSummary();
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.DeclareSeverance ds) {
                    handleDeclareSeverance(ds);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.NostrQuerySelfAttestation _nqsa) {
                    handleNostrQuerySelfAttestation();
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.RecordIntegrationEvent rie) {
                    handleRecordIntegrationEvent(rie);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.CompleteMourning cm) {
                    handleCompleteMourning(cm);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.AcknowledgeHarm ah) {
                    handleAcknowledgeHarm(ah);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.MakeAmends ma) {
                    handleMakeAmends(ma);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.BearTheWound btw) {
                    handleRepairAct(RepairLedger.Kind.BEAR_THE_WOUND,
                        "bear_the_wound", btw.detail());
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Release rel) {
                    handleRepairAct(RepairLedger.Kind.RELEASE,
                        "release", rel.detail());
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.SetAside sa) {
                    handleRepairAct(RepairLedger.Kind.SET_ASIDE,
                        "set_aside", sa.detail());
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.IntrospectRepairHistory _irh) {
                    handleIntrospectRepairHistory();
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.IntrospectAttendantHistory _iah) {
                    handleIntrospectAttendantHistory();
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.IntrospectResilience _ires) {
                    handleIntrospectResilience();
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.DeclareDeparture dd) {
                    handleDeclareDeparture(dd);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.BondAffirmation ba) {
                    handleBondAffirmation(ba);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.DeclareReturn dr) {
                    handleDeclareReturn(dr);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.UpdateDescription ud) {
                    handleUpdateDescription(ud);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.CalibrationFeedback cf) {
                    handleCalibrationFeedback(cf);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.RequestAgent ra) {
                    handleRequestAgent(ra);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.RespondAgent ra) {
                    handleRespondAgent(ra);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Delegate del) {
                    handleDelegate(del);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.CreateTaskPlan ctp) {
                    handleCreateTaskPlan(ctp);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ModifyPlan mp) {
                    handleModifyPlan(mp);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.GoalDone gd) {
                    handleGoalDone(gd);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.WebSearch ws) {
                    handleWebSearch(ws);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ReadContent rc) {
                    handleReadContent(rc);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.QueryOracle qo) {
                    handleQueryOracle(qo);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Emote emote) {
                    roomRef.tell(new RoomCommand.EmoteInRoom(
                        profile.entityId(), profile.name(), emote.text(), roomResponseAdapter));
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.GiveItem giveItem) {
                    handleGiveItem(giveItem);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Examine examine) {
                    handleExamine(examine);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.VoluntarySleep vs) {
                    handleVoluntarySleep(vs);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.WriteJournal wj) {
                    handleWriteJournal(wj);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ReadJournal rj) {
                    handleReadJournal(rj);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.BondRitual br) {
                    handleBondRitual(br);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Trade trade) {
                    handleTrade(trade);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.CraftItem ci) {
                    handleCraftItem(ci);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.CastVote cv) {
                    handleCastVote(cv);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.TakeItem ti) {
                    handleTakeItem(ti);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.PlaceItem pi) {
                    handlePlaceItem(pi);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Whisper wh) {
                    handleWhisper(wh);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Broadcast bc) {
                    handleBroadcast(bc);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.InviteEntity inv) {
                    handleInviteEntity(inv);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.SetGoal sg) {
                    handleSetGoal(sg);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Propose prop) {
                    handlePropose(prop);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Reflect ref) {
                    handleReflect(ref);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Teach teach) {
                    handleTeach(teach);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Introspect intr) {
                    handleIntrospect(intr);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Listen lst) {
                    handleListen(lst);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.WriteText wt) {
                    handleWriteText(wt);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.SetRoutine sr) {
                    handleSetRoutine(sr);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.PostListing pl) {
                    handlePostListing(pl);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.AcceptListing al) {
                    handleAcceptListing(al);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.Summarize sum) {
                    handleSummarize(sum);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.SaveArtifact sa) {
                    handleSaveArtifact(sa);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.RequestReview rr) {
                    handleRequestReview(rr);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.AbandonPlan ap) {
                    handleAbandonPlan(ap);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.PausePlan pp) {
                    handlePausePlan(pp);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ResumePlan rp) {
                    handleResumePlan(rp);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.SetContemplative sc) {
                    handleSetContemplative(sc);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.GoToBondholder gtb) {
                    handleGoToBondholder(gtb);
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.ConfigureChannel cc) {
                    getContext().getSelf().tell(
                        new UpdateNotificationConfig(cc.channel(), cc.params(), false));
                    speak("Configuring " + cc.channel() + " notification channel.");
                } else if (parseResult.primaryAction() instanceof ActionParser.AgentAction.RunScript rs) {
                    handleRunScript(rs);
                } else if (parseResult.primaryAction() != null) {
                    // Audit 2026-07-11: the chain used to END here with no else — a
                    // parseable action with no dispatch case (codex_action) fell off
                    // silently while buildActionMemory still recorded it as done, so
                    // the agent REMEMBERED doing a thing that never executed. Log it
                    // and put the honest outcome in working memory instead.
                    var dropped = parseResult.primaryAction().getClass().getSimpleName();
                    log.warn("Parsed action has NO dispatch handler — dropped: {} for '{}'",
                        dropped, profile.name());
                    remember("[Tool failed] " + dropped
                        + ": this action has no handler on this node — it did NOT execute.");
                    primaryActionDispatched = false;
                }

                // Record action attempt for active plan (for GoalExecutor decision-making)
                // but do NOT auto-advance. Only goal_done advances a goal.
                // All other actions are intermediate steps — the agent must explicitly
                // mark completion via goal_done when it believes the goal is achieved.
                if (activePlan != null && activePlan.isActive()
                        && parseResult.primaryAction() != null
                        && !(parseResult.primaryAction() instanceof ActionParser.AgentAction.CreateTaskPlan)
                        && !(parseResult.primaryAction() instanceof ActionParser.AgentAction.ModifyPlan)
                        && !(parseResult.primaryAction() instanceof ActionParser.AgentAction.GoalDone)) {
                    var actionName = ActionPolicy.actionTypeOf(parseResult.primaryAction());
                    // #33 re-audit: only record executed=true when the action actually
                    // reached a handler. An action that fell through the no-dispatch tail
                    // is recorded as not-executed so the plan ledger agrees with working
                    // memory instead of showing a phantom success the agent never ran.
                    if (primaryActionDispatched) {
                        activePlan.recordAttempt(actionName, null, "executed", true);
                    } else {
                        activePlan.recordAttempt(actionName, null, "not-executed (no handler)", false);
                    }
                    // Schedule next inference to continue working on the goal
                    timers.startSingleTimer("plan-continue",
                        new AutonomyCheck(), Duration.ofSeconds(3));
                }

                // Checkpoint volatile state for crash recovery
                checkpointDirty = true;
                maybeCheckpoint();
            }

            case InferenceRouter.InferError error -> {
                // Discard stale error if cancelled
                if (currentCancellation != null && currentCancellation.isCancelled()) {
                    log.info("Discarding stale inference error (cancelled: {})",
                        currentCancellation.reason());
                    break;
                }

                lastFailure = Instant.now();
                log.warn("Inference failed for companion '{}': {}",
                    profile.name(), error.error());

                // Vitality: error spikes pressure, drains confidence.
                // Energy NOT drained here — already drained when the request was sent
                // in onProcessEvents/onGreetPlayer. Double-draining caused the bleed.
                vitality = vitality
                    .withErrorPressure(vitality.errorPressure() + 0.15)
                    .withConfidence(vitality.confidence() - 0.10);

                // If this was a bud delegation, send error back to phone
                if (pendingDelegateReply != null) {
                    pendingDelegateReply.tell(new BudDelegateResponse(
                        pendingDelegateRequestId,
                        "I'm having trouble thinking right now... " + error.error()));
                    pendingDelegateReply = null;
                    pendingDelegateRequestId = null;
                    pendingDelegateActions = null;
                } else if (isToolResultFollowUp(wasTrigger)) {
                    // #32 item 1: the tool-result judgment turn ERRORED — the trigger's
                    // entityId is the companion's own, so the player-facing branch below
                    // never fires and the outcome would vanish. We still HOLD the tool's
                    // result text; deliver its substance honestly instead of silence.
                    speakToolResultFallback(wasTrigger, "judgment inference errored");
                } else if (wasTrigger != null
                        && !"system".equals(wasTrigger.entityId())
                        && !isAgentEntity(wasTrigger.entityId())) {
                    // Only speak the degraded "I'm having trouble thinking" line to a
                    // PLAYER who directly addressed us — never broadcast it into a room
                    // of peers when a peer companion's own-time reach happened to fail
                    // inference. A multi-agent soak surfaced two companions narrating the
                    // identical "*shimmers uncertainly*..." fallback aloud because a
                    // peer tell (a non-"system" trigger) sailed through this gate.
                    // (Also avoids noise on startup when no llama-server is running.)
                    var catalog = ScriptMessageCatalog.forLang(locale);
                    speak(catalog.get("agent.companion.inference_fail"));
                }
            }
        }

        // Process messages that arrived while we were thinking
        if (!deferredTriggers.isEmpty()) {
            promoteDeferredTrigger(
                VitalityModulation.compute(vitality, drives, profile).debounceDelay());
        }

        return this;
    }

    private Behavior<Command> onRefreshRoomState(RefreshRoomState msg) {
        roomRef.tell(new RoomCommand.LookRoom(profile.entityId(), roomResponseAdapter));
        return this;
    }

    private Behavior<Command> onRoomCreationResult(RoomCreationResult msg) {
        if (msg.forBunshin()) {
            // Background work does not interrupt, and its truth must reach the
            // RETURN REPORT rather than evaporate into an interjection.
            pendingBunshinOutcomes.add(msg.success()
                ? "the room '" + msg.roomName() + "' is real and the way in is open"
                : "the room '" + msg.roomName() + "' has a problem: " + msg.error());
            log.info("Bunshin async outcome held for report: {} success={}",
                msg.roomName(), msg.success());
            return this;
        }
        if (msg.success()) {
            // Prose-follows-outcome (Fix B): the room actually exists now — voice
            // the REAL creation through the 4B layer (pin the room name), instead
            // of the model's earlier speculative "I'll build it". The pre-action
            // prose was suppressed at the speak site; this is Wyrd's true, warm
            // report of what happened.
            voiceOutcome("You just created the room \"" + msg.roomName() + "\", with a way back home.",
                msg.roomName(), "room-created");
            log.info("Companion '{}' created room '{}' ({})",
                profile.name(), msg.roomName(), msg.newRoomId());
            // THE ROOM IS HALF THE JOB. A template furnishes a place and holds no
            // behaviour, so a request for a room that must DO something is not finished
            // when the room exists. Live 2026-08-22: the Weather Parlor was made, real and
            // connected and described exactly as asked, and the steward walked into an
            // empty room — creating it had looked like the whole job. Same shape, and the
            // same remedy, as a craft_from_template that produced a behaviourless shell:
            // say what is still missing and re-arm the workbench so the next step narrows
            // to it, rather than letting the turn end in a satisfied report.
            if (msg.needsBehaviour() && buildFirstRearms < BUILD_FIRST_MAX_REARMS) {
                buildFirstRearms++;
                buildFirstPending = true;
                log.info("Companion '{}' made a room that still has to DO something — "
                    + "re-arming the workbench so the next step builds it into '{}'",
                    profile.name(), msg.newRoomId());
            }
        } else {
            // Honest failure — no fake success. Voice the real error plainly.
            voiceOutcome("You tried to create a room but it didn't work: " + msg.error(),
                null, "room-create-fail");
            log.error("Room creation failed for companion '{}': {}",
                profile.name(), msg.error());
        }
        return this;
    }

    /**
     * hard-gate hint
     * injection. Inside the actor's single-threaded dispatch so we can mutate
     * working memory safely. The hint is a short directive ("[Preflight] Plan
     * flagged as low-quality: …. Reconsider with concrete actions.") that the
     * next ReAct turn will read and use to re-shape the plan. The model has
     * already chosen the actions for this plan; we cannot retroactively cancel
     * them, but we can steer the next decision with a high-salience cue.
     *
     * <p>See {@link #shouldFirePlanHardgate} (plan phase) and
     * {@code Phase 6.2} step-gate for the call sites that produce these.</p>
     */
    private Behavior<Command> onPreflightRejectReceived(PreflightRejectReceived msg) {
        var label = "plan".equals(msg.phase()) ? "Plan" : "Step";
        var hint = String.format(
            "[Preflight] %s flagged as low-quality (m2=%.2f): %s. Reconsider with concrete actions.",
            label, msg.confidence(),
            msg.reason() == null || msg.reason().isBlank() ? "low confidence" : msg.reason());
        remember(hint);
        log.warn("Preflight HARD-GATE fired ({}) for companion '{}' plan '{}': conf={} reason={}",
            msg.phase(), profile.name(), msg.planDescription(),
            msg.confidence(), msg.reason());
        return this;
    }

    // ── Social co-presence homeostasis (2026-06-03) ──────────────────────────
    // Per-peer familiarity ∈ [0,1], keyed by peer DID. Seeds from co-presence
    // (self-tapering toward PROXIMITY_CEILING — mere presence only makes you
    // "familiar strangers"), jumps on a reciprocal reach (Tier-2), and scales how
    // much a present peer eases loneliness + the AFFILIATION drive. Grounded in
    // Social Baseline Theory (familiar-other proximity lowers load) + Matthews &
    // Tye social homeostasis (identity-aware detector). v1: in-memory, per-session;
    // persistence-on-bond + OPEN→ACTIVE formation are follow-ups.
    private final Map<String, Double> peerFamiliarity =
        new ConcurrentHashMap<>();
    /** Mere co-presence can only carry familiarity this far ("familiar stranger");
     *  past it, only a real reciprocal reach deepens the bond. */
    private static final double PROXIMITY_CEILING = 0.35;
    /** Per-second self-tapering approach to the ceiling while a peer is present
     *  (rate × (ceiling − fam)) — ~reaches ceiling over ~10–15 min of shared presence. */
    private static final double COPRESENCE_FAMILIARITY_RATE = 0.004;
    /** Tier-1 continuous easing while a familiar peer is present (per sec at fam=1). */
    private static final double COPRESENCE_LONELINESS_EASE = 0.02;
    private static final double COPRESENCE_AFFILIATION_EASE = 0.02;
    /** Tier-2 reciprocal-reach familiarity jump (can exceed the proximity ceiling). */
    private static final double CONNECTION_FAMILIARITY_JUMP = 0.08;
    /** Tier-2 affiliation relief on a peer reach, scaled up by (0.3 + familiarity). */
    private static final double CONNECTION_AFFILIATION_EASE = 0.20;
    /** A satisfied social drive RESTS here, not at 0 — we're social animals, the pull
     *  never fully vanishes (2026-06-04: relief was bottoming affiliation to 0.0). */
    private static final double AFFILIATION_REST_FLOOR = 0.10;
    /** Approach-pull (appetitive) — the WANT to engage a familiar present peer, distinct
     *  from deficit-relief. Surfaced to the Orient as a felt draw above this strength. */
    private static final double SOCIAL_DRAW_THRESHOLD = 0.12;
    /** After engaging a peer (Tier-2 reach), the appetite to connect AGAIN rebuilds over
     *  ~this long — so a content pair still turns back toward each other (oxytocin→dopamine
     *  appetitive loop: connection is its own reward, sought afresh, not just a lack quelled). */
    private static final double SOCIAL_DRAW_REBUILD_SECONDS = 150.0;
    /** When each present peer was last genuinely engaged (Tier-2 reach), keyed by DID —
     *  drives the appetite's rebuild so engaging satisfies it and absence rekindles it. */
    private final Map<String, Instant> peerLastEngaged =
        new ConcurrentHashMap<>();
    /** The present peer the agent is most drawn to engage right now (name) + its strength,
     *  recomputed each tick from familiarity × engagement-staleness. Surfaced by the Orient. */
    private volatile String socialDrawPeer = null;
    private volatile double socialDrawStrength = 0.0;

    // ──: the closed action-loop, GENERALIZED over drives (2026-06-05) ─────────────
    // A PROBE pushes the world for a return and opens a PENDING expectation; the serving DRIVE settles
    // only when the world ANSWERS, and SILENCE sharpens the want + drives a retry, then disengages
    // after N — the homeostatic loop closing through the world. Without this the probe is a reflex
    // (fire-and-forget); with it the unmet probe persists and pushes again (the persist-retry signature
    // of a living loop). Three probe shapes, all genuinely "push the world for a world-RESPONSE":
    //   • AFFILIATION — reach for a peer (sending_stone); answered by the peer reaching back.
    //   • CARE        — offer/tend toward a peer; answered by the peer taking it up.
    //   • SEEKING     — query the world (library_search/examine/…); answered by a NOVEL result.
    // (Creativity/grief/vigilance/startle/surprise are NOT probe-shaped — own-output novelty,
    //  integration, or reactive perception spikes — so forcing a "pending await" would manufacture
    //  suffering with no real return. They keep their existing immediate coupling.)
    // Timing/verdict in {@link ProbeLoop}; the per-drive deltas + the "what answers this probe" call
    // are applied here (this actor owns the drive state). In-memory, per-session, keyed by drive.
    private final Map<String, ProbeLoop.PendingProbe>
        pendingProbes = new ConcurrentHashMap<>();
    private final Map<String, Integer> probeStreak =
        new ConcurrentHashMap<>();
    /**
     * wire-4 backing (2026-06-07) — lifetime count of how many times we've reached
     * toward each peer in the CURRENT co-presence scene, keyed by peer name (lowercased). Unlike
     * {@link #probeStreak} (which {@code coupleProbeSilence} RESETS to 0 on every DISENGAGE so the
     * unanswered-streak math restarts each cycle), this survives the disengage→re-reach cycle. The
     * "reach again differently, or let it be" hint gates on THIS so it keeps firing across cycles —
     * otherwise each fresh probe started at streak 0, the hint went silent, and the model regenerated
     * the identical reach verbatim (the multi-agent-soak re-emit). Cleared when the peer leaves / scene
     * resets (via {@link #lastReachToPeer}'s companion clear). In-memory, per-session.
     */
    private final Map<String, Integer> reachesToPeerThisScene =
        new ConcurrentHashMap<>();
    /**
     * Belt-and-suspenders against verbatim re-emit (2026-06-07) — the last reach CONTENT we sent to
     * each peer (keyed by peer name, lowercased). A new {@code sending_stone} whose generated body
     * equals the last one to the same peer is suppressed (we already said exactly that; saying it
     * again is noise, not a fresh reach). Paired with {@link #reachesToPeerThisScene}.
     */
    private final Map<String, String> lastReachToPeer =
        new ConcurrentHashMap<>();
    // ── Co-presence-loop safety floor (Fix 2, 2026-06-15) ────────────────────────────────────
    /** Recent room-{@code say} texts I've EMITTED in the current scene (newest last, capped).
     *  Fix 1 ({@code peerLastEngaged} on the aloud path) removes the affiliation DRIVE to re-reach;
     *  this catches the residual REACTIVE self-repeat — an agent rephrasing the same thought turn
     *  after turn — that survives because {@link ConversationTracker#threadIdFor} keys on the
     *  speaker's OWN text, so {@link EngagementGate}'s already-responded dampeners never accumulate
     *  across an agent↔agent volley. Lines vary in wording, so the guard is lexical-similarity, not
     *  byte-exact. Cleared on scene reset alongside {@link #reachesToPeerThisScene}. */
    private final Deque<String> recentSelfSaysThisScene = new ArrayDeque<>();
    private static final int RECENT_SELF_SAYS_CAP = 6;
    /** Word-set Jaccard at/above which a new utterance is a near-duplicate of recent self-speech. */
    private static final double NEAR_DUP_SIMILARITY = 0.6;
    /** Consecutive near-dup suppressions; at the limit the circuit-breaker settles the volley. */
    private int nearDupSelfRepeatStreak = 0;
    private static final int NEAR_DUP_SELF_REPEAT_LIMIT = 2;
    /** The trigger of the current reactive cycle (set when {@link #pendingTrigger} is consumed) —
     *  lets {@link #speakDirect} tell an AMBIENT peer/own-time utterance (suppressible by the floor)
     *  from a HUMAN-facing reply (never suppressed: humans get honest, verbatim speech). */
    private WorldEvent.Said lastReactTrigger;

    /**
     * When {@link #lastReactTrigger} was set — so a question can go stale.
     *
     * <p>The field is a fallback for "what is the person asking?" when the live
     * handles are gone, and it had no expiry. Live 2026-08-09: asked to recite a
     * poem, she called a tool with the question from the PREVIOUS battery — the
     * Glass Tide question, an hour and a different conversation earlier — and
     * answered that instead. The tool output says "the provided sources", so it
     * was not her voice wandering: the stale text was passed as the request.</p>
     *
     * <p>Bounded rather than cleared. Clearing it re-opens the empty-{@code query}
     * bug it was introduced to fix; ageing it out keeps the recovery for the case
     * it was meant for — a handle lost inside one turn — while refusing to speak
     * for a person who asked something else, an hour ago.</p>
     */
    private Instant lastReactTriggerAt;

    /** How long a trigger may stand in for "what was just asked". */
    private static final Duration TRIGGER_FRESHNESS =
        Duration.ofMinutes(3);

    /**
     * {@link #lastReactTrigger}, but only while it can still be the live request.
     *
     * @return the trigger, or null once it is old enough to be someone else's question
     */
    private WorldEvent.Said freshReactTrigger() {
        if (lastReactTrigger == null) return null;
        if (lastReactTriggerAt == null) return lastReactTrigger;   // pre-dates the stamp
        if (Duration.between(lastReactTriggerAt, Instant.now())
                .compareTo(TRIGGER_FRESHNESS) > 0) {
            log.debug("Dropping a {}s-old trigger rather than treating it as the live request",
                Duration.between(lastReactTriggerAt, Instant.now())
                    .toSeconds());
            return null;
        }
        return lastReactTrigger;
    }

    /**
     * The trigger that STARTED the current ReAct loop — the request the loop is serving.
     * lastReactTrigger is per-inference-cycle and gets legitimately replaced by interleaved
     * events (a room-entry event overwrote the build request mid-craft on second-node 2026-07-09,
     * so the hand-off saw "[operator enters the room]" as the requester intent). Set at every
     * loop init; read by requester-sensitive finalizers (hand-off) while the loop is active.
     */
    private WorldEvent.Said reactRequester;

    /**
     * The human question this turn is serving — pinned at turn start, while the
     * trigger is still in hand, because every later handle
     * ({@link #reactRequester}, {@link #lastReactTrigger}) is maintained by some
     * flows and not others. See the pin site in the reactive handler.
     */
    private WorldEvent.Said turnHumanRequest;
    private Instant turnHumanRequestAt;
    /** Whether the CURRENT turn was started by a person, not by her own time. */
    private boolean turnIsHuman;

    /** Armed at the pin when a human question reads as a library lookup. */
    /**
     * taskId → the room its finished item should be placed in.
     *
     * <p>Only populated when a dispatch explicitly named a room; entries are removed when
     * the task reports back. Bounded by the number of builds in flight, which is small.
     */
    private final Map<String, String> buildDestinationByTask = new ConcurrentHashMap<>();

    /** taskIds whose build was the FIRST half of a room-that-acts; the room is still owed. */
    private final Set<String> roomOwedByTask = ConcurrentHashMap.newKeySet();
    /** taskIds whose request asked for a room that acts — the only builds the fresh-room window may claim. */
    private final Set<String> buildAskedForRoom = ConcurrentHashMap.newKeySet();
    /** Tasks whose request said "give me / hand me" — the REQUESTER, stamped at
     *  dispatch. The hand-off used to re-read the live trigger at completion,
     *  and a build that takes minutes loses that race every time: on the home
     *  node 2026-08-24 her own musings had overwritten lastReactTrigger by the
     *  time goose finished, the intent check read a musing, and the person who
     *  said "give me the tool" had to walk over and `get` it off the floor.
     *  The intent belongs to the request that carried it. */
    private final Map<String, WorldEvent.Said> buildAskedIntoHands = new ConcurrentHashMap<>();
    /** taskId → the room the person was in when they asked for the build. */
    private final Map<String, String> buildAskedFromRoom = new ConcurrentHashMap<>();

    /** The tool is built and the room it was for is not. Cleared the moment a room is made. */
    private volatile boolean roomStillOwedAfterBuild;
    /** The room gate fires once per loop; a force may compel a call, never loop forever. */
    private boolean roomOwedGateUsed;
    /** Description of the build this turn already sent; null when none is running. */
    private volatile String reactBuildInFlight;

    /**
     * The room she made most recently, and when.
     *
     * <p>A request for a room that DOES something is two actions — make the place, build
     * the thing — and only the second one can carry a destination. Rather than depend on
     * her filling an optional parameter, a build that names no room within
     * {@link #ROOM_BUILD_WINDOW} of a room being made goes into that room.
     */
    private volatile String lastCreatedRoomId;
    private volatile Instant lastCreatedRoomAt;

    /** How long a freshly-made room stays the obvious home for a build. */
    private static final Duration ROOM_BUILD_WINDOW = Duration.ofMinutes(5);

    private boolean libraryFirstPending;

    /** Exact-repeat guard state — see speakDirect. */
    private String lastSpokenLine;
    /** When anyone last spoke TO this companion — opens the reactive window
     *  in which the exact-repeat guard stands down (see speakDirect). */
    private Instant lastHeardUtteranceAt;
    private Instant lastSpokenLineAt;

    /** One absence finding may be held per turn — see the eager-speak branch. */
    private boolean absenceHeldThisTurn;

    /** A summariser digest asserting the sources hold nothing. */
    static boolean looksLikeAbsenceFinding(String findings) {
        if (findings == null) return false;
        var f = findings.toLowerCase(Locale.ROOT);
        return f.contains("sources do not contain")
            || f.contains("source material does not contain")
            || f.contains("do not contain any information")
            || f.contains("does not contain any information")
            || f.startsWith("no results found")
            || f.contains("i cannot answer this question because");
    }

    /** The library tools any of which satisfies a forced first lookup. */
    private static final Set<String> LIBRARY_FIRST_TOOLS =
        Set.of("library_card", "library_search", "read_content");

    /**
     * The building tools a forced build step narrows to — plus an explicit
     * decline, because a request to build is one she may refuse, and the
     * force must never remove the refusal (act-or-decline, same contract as
     * the follow-through teeth).
     */
    static final Set<String> BUILD_FIRST_TOOLS =
        Set.of("create_room_from_template", "create_zone", "craft_from_template",
            "dispatch_task", "decline_with_reason");

    /** Places, which a room template answers completely. */
    private static final Set<String> PLACE_BUILD_TOOLS =
        Set.of("create_room_from_template", "create_zone", "decline_with_reason");
    /** A thing that must DO something — authored by the coding backend. */
    private static final Set<String> BEHAVIOUR_BUILD_TOOLS =
        Set.of("dispatch_task", "decline_with_reason");
    /** A thing that merely IS something — a template holds it whole. */
    private static final Set<String> OBJECT_BUILD_TOOLS =
        Set.of("craft_from_template", "decline_with_reason");

    /**
     * Which build tools answer THIS request.
     *
     * <p>The three build doors are not interchangeable, and offering all of them is how a
     * request got answered by the wrong one three times running (2026-08-19/20).
     *
     * <ul>
     *   <li><b>A place</b> → {@code create_room_from_template} / {@code create_zone}.</li>
     *   <li><b>A thing that DOES something</b> → {@code dispatch_task}. The coding backend
     *       is the item AUTHOR: every dispatched task is prepended with the items-as-tools
     *       contract, so the backend emits one {@code .js} carrying
     *       {@code exports.manifest} plus {@code invoke()}, and
     *       {@code CodingTaskItemBridge} then validates it, smoke-tests it against a
     *       no-side-effect stub, registers it so {@code use} works, and places it in the
     *       room. That pipeline exists for exactly this and had never once run in
     *       production, because nothing published the terminal event until 2026-08-19.</li>
     *   <li><b>A thing that merely IS something</b> → {@code craft_from_template}. A
     *       template holds a book or a lantern whole. It cannot hold behaviour: the
     *       generated script is {@code inherit(...)} plus setters.</li>
     * </ul>
     *
     * <p>Asking the local drive model to write the behaviour itself was the wrong door.
     * Proven live against the production 9B: narrowed to the workbench with
     * {@code tool_choice=required}, handed a tool result naming the exact APIs, and with
     * {@code script} promoted into the schema's {@code required} array, it still called
     * {@code craft_from_template} with no script on every attempt. It is a drive-and-voice
     * model, not a code author — and we have a code author.
     */
    /**
     * Which build door answers THIS turn — unless a half is already owed.
     *
     * <p>A room that must DO something contains the word "tool", so by the request alone
     * it always narrows to the workbench. Live 2026-08-22 20:27: the tool was built, the
     * re-arm fired, and the re-armed step narrowed her straight back to
     * {@code dispatch_task} — the room-maker was never on the surface — and she called
     * goal_done. When a room is owed, the room door is the only honest answer, whatever
     * the sentence says.
     */
    /**
     * The room the request NAMES, when that room already exists. "put it in the
     * room weather-attic-1325" names a DESTINATION — treating it as a request
     * for a new room owed a room that was already standing, and the gate then
     * forced a second one beside it (battery cpB5's sibling failure,
     * 2026-08-23 17:27: `create_room_from_template name='weather-tool'` next
     * to the attic). Matched by room ID and only for distinctive ids (a dash
     * and some length) so a passing mention of "library" never binds to the
     * seeded library room.
     */
    static Optional<String> existingRoomNamedIn(String text) {
        var topo = ZoneTopology.getShared();
        if (topo == null || text == null || text.isBlank()) return Optional.empty();
        var t = text.toLowerCase(Locale.ROOT);
        String best = null;
        for (var node : topo.rooms().values()) {
            var id = node.roomId();
            if (id == null || id.length() < 8 || !id.contains("-")) continue;
            if (t.contains(id.toLowerCase(Locale.ROOT))
                    && (best == null || id.length() > best.length())) {
                best = id;
            }
        }
        return Optional.ofNullable(best);
    }

    /** Does this request ask for a room that acts AND still need that room made?
     *  Naming a room that already exists is a destination, not a debt. */
    private static boolean requestOwesARoom(String text) {
        return asksForARoomThatActs(text) && existingRoomNamedIn(text).isEmpty();
    }

    /** Is the request this turn is serving one that asked for a room that acts? */
    private boolean turnOwesARoom() {
        // THE REQUEST THAT STARTED THIS LOOP, never "whatever is pinned now". Staging
        // 2026-08-23 07:33:25: a second ask arrived mid-force and re-pinned the turn's
        // request; two seconds later the forced room call came back as text, this asked
        // "does the pinned request owe a room?" of the NEW ask, got no, and let the loop
        // end with the lantern room never made. reactRequester is set once at loop start
        // for exactly this — it is the loop's identity. Fall back to the pin only when
        // there is no loop.
        var r = reactRequester != null ? reactRequester : null;
        if (r != null) return requestOwesARoom(r.text());
        var req = pinnedTurnRequest();
        if (req != null) return requestOwesARoom(req.text());
        return lastReactTrigger != null && requestOwesARoom(lastReactTrigger.text());
    }

    private Set<String> buildFirstToolsForTurn(String request) {
        // Only when THIS request is the one that owes a room. On the home node
        // 2026-08-23 07:20 the library build (a room-that-acts) was still in flight, the
        // steward asked for a plain weather TOOL, and this narrowed his new ask to the
        // room door because the previous ask's room was still owed: "no build tool on
        // this dispatch surface — skipped". A debt belongs to the request that incurred it.
        boolean thisAskOwesARoom = asksForARoomThatActs(request);
        if (thisAskOwesARoom && (roomStillOwedAfterBuild || !roomOwedByTask.isEmpty())) {
            return PLACE_BUILD_TOOLS;
        }
        return buildFirstToolsFor(request);
    }

    static Set<String> buildFirstToolsFor(String request) {
        if (request == null || request.isBlank()) return BUILD_FIRST_TOOLS;
        var t = request.toLowerCase(Locale.ROOT);
        boolean place = t.contains(" room") || t.contains(" zone") || t.contains("a place")
            || t.contains(" space") || t.contains(" nook") || t.contains("house");
        if (place && !asksForAnArtifact(request)) return PLACE_BUILD_TOOLS;
        if (describesBehaviour(request)) return BEHAVIOUR_BUILD_TOOLS;
        return OBJECT_BUILD_TOOLS;
    }

    /** A pending human request to build something — armed per turn, like library-first. */
    private boolean buildFirstPending;
    /**
     * How many times this turn the build force has been RE-armed after handing back a
     * scriptless craft. The force is one-shot by design, so without this the push-back
     * lands on a surface that has already widened again — and a companion who has just
     * been told "that template holds no behaviour" is back among ~25 tools with
     * tool_choice=auto, free to call list_templates and talk herself out of it. That is
     * exactly how the third live attempt ended (2026-08-20). Capped so the two fixes
     * cannot ping-pong: after this she keeps the push-back in her history but gets the
     * open surface back.
     */
    private int buildFirstRearms;
    static final int BUILD_FIRST_MAX_REARMS = 1;

    /**
     * Is the person asking for a THING to be made, rather than for an answer?
     *
     * <p>Separates "make me a list from my books" (a lookup) from "make me a tool that
     * queries the library" (an artifact whose subject happens to be the library). Only
     * the second should open the workbench ahead of the book.
     *
     * <p>Pure and package-visible so the distinction is testable without a model.
     */
    static boolean asksForAnArtifact(String text) {
        if (text == null || text.isBlank()) return false;
        var t = text.toLowerCase(Locale.ROOT);
        boolean makingVerb = t.contains("make") || t.contains("build") || t.contains("craft")
            || t.contains("create") || t.contains("weave") || t.contains("forge");
        if (!makingVerb) return false;
        return t.contains("tool") || t.contains("item") || t.contains("device")
            || t.contains("gadget") || t.contains("widget") || t.contains("instrument")
            || t.contains("machine") || t.contains("contraption") || t.contains("artifact");
    }

    /**
     * Does this ask for a room that has to DO something?
     *
     * <p>A template furnishes a place; it holds no behaviour. "Make me a room where anyone
     * can ask for the weather and hear it spoken" is two pieces of work, and the second is
     * the only one that answers the question. Live 2026-08-22 she made the Weather Parlor
     * — real, connected, exitable, described exactly as asked — and the steward walked
     * into an empty room, because creating it looked like the whole job.
     *
     * <p>Shallow on purpose, like its siblings: a place word plus something the place must
     * do for whoever walks in.
     */
    static boolean asksForARoomThatActs(String text) {
        if (text == null || text.isBlank()) return false;
        var t = text.toLowerCase(Locale.ROOT);
        // "speaks it out TO THE ROOM" names an AUDIENCE, not a construction
        // site. Live on the home node 2026-08-24 13:40: "…whatever it finds it
        // speaks out to the room a short fairy tale…" registered a room debt
        // for an ask that wanted a tool, and the room gate then forced
        // create_room twice for a room nobody asked for. Strip the dative
        // form before looking for place words; "make me a room", "a room
        // called X" and "put it in the room X" all still carry their own
        // room mention after the strip.
        var construction = t.replace("out to the room", " ").replace("to the room", " ");
        boolean place = construction.contains("room") || t.contains(" zone") || t.contains("a place")
            || t.contains(" space") || t.contains(" nook") || t.contains("parlor")
            || t.contains("chamber") || t.contains("sanctum");
        if (!place) return false;
        // What the place must DO for whoever walks in.
        return t.contains("ask") || t.contains("hear") || t.contains("look up")
            || t.contains("lookup") || t.contains("query") || t.contains("tells")
            || t.contains("tell me") || t.contains("speaks") || t.contains("speak")
            || t.contains("get back") || t.contains("find out") || t.contains("briefing")
            || t.contains("can do") || t.contains("so i can") || t.contains("so anyone");
    }

    /**
     * Does this utterance ask her to MAKE something?
     *
     * <p>Deliberately shallow, like {@link #looksLikeFactQuestion}: a making
     * verb plus a made-thing cue. Live 2026-08-11 05:57: "how about making us
     * a greenhouse" was classified confidently-no-task (0.80) and answered by
     * the toolless voice tier; the explicit retry reached the 9B with
     * create_room_from_template second on the surface, and it TALKED about
     * the greenhouse instead of calling the tool. Both halves of the
     * greenhouse failure start from the runtime not recognizing a build
     * request as one. Writing-shaped things (notes, letters, stories) are
     * excluded — those belong to the quill, not the room builder.</p>
     */
    /** Does the text name an item the loader knows? The cue that a revision is about a THING. */
    static boolean mentionsAKnownItem(String lowered) {
        var loader = ScriptedItemLoader.get();
        if (loader == null) return false;
        for (var def : loader.all()) {
            var id = def.itemId();
            if (id != null && !id.isBlank() && lowered.contains(id.toLowerCase(Locale.ROOT))) return true;
        }
        return false;
    }

    static boolean looksLikeBuildRequest(String text) {
        if (text == null || text.isBlank()) return false;
        var t = text.toLowerCase(Locale.ROOT);
        // Humans ask for things by expressing NEEDS, not verbs: the second
        // live greenhouse ask (2026-08-11 15:15, "so I was thinking we need
        // a greenhouse") carried no making-verb and slipped this recognizer
        // — the bunshin net caught it, but the front door should too.
        // CHANGING A THING SHE MADE IS WORKBENCH WORK. "please revise trip_compass so it
        // accepts two cities…" carried no making-verb, so this said no, the delegate guard
        // had nothing to hold, and the classifier sent it to a bunshin (2026-08-22 21:45)
        // — the same hijack as the venture_scout build that morning, with a different
        // verb. A revision names an existing item and asks for it to be different; the
        // workbench owns that (ItemRevision) exactly as it owns the first build.
        boolean revisingVerb = t.contains("revise") || t.contains("rework") || t.contains("modify")
            || t.contains("change it so") || t.contains("fix it so") || t.contains("update it so")
            || t.contains("make it ") || t.contains("have it ") || t.contains("so it accepts")
            || t.contains("so it takes") || t.contains("so that it ");
        if (revisingVerb && mentionsAKnownItem(t)) return true;
        boolean makingVerb = t.contains("create") || t.contains("make") || t.contains("makin")
            || t.contains("build") || t.contains("craft")
            || t.contains("we need a") || t.contains("we need some")
            || t.contains("i want a") || t.contains("can we have a")
            || t.contains("i'd love a") || t.contains("id love a");
        if (!makingVerb) return false;
        boolean writingShaped = t.contains("note") || t.contains("letter")
            || t.contains("list") || t.contains("poem") || t.contains("story")
            || t.contains("journal") || t.contains("report");
        // ...but a TOOL that produces writing is still a tool. The exclusion is about
        // what is being MADE, not what it will output. Live 2026-08-19: "make me a
        // tool that ... provide me with a story ... tell the room out loud that story"
        // was rejected here on the word "story", while library-first had already
        // rejected it on "library" — so the one request the workbench existed for
        // matched neither door, and she was left holding a single search tool.
        if (writingShaped && !asksForAnArtifact(text)) return false;
        if (asksForAnArtifact(text)) return true;   // "make me a tool/item/device"
        return t.contains(" room") || t.contains(" zone") || t.contains("a place")
            || t.contains(" space") || t.contains(" nook") || t.contains("us a ")
            || t.contains("me a ");
    }

    /**
     * Does the request describe something the item must DO, not merely BE?
     *
     * <p>"Make me a book" asks for a thing; a template is the whole answer. "Make me a
     * tool that queries the library and speaks a story to the room" asks for BEHAVIOUR,
     * and no template holds behaviour — only a {@code script} does.
     *
     * <p>Live 2026-08-20, the second attempt at the same request: build-first routing
     * worked, the workbench opened, and she called {@code craft_from_template} with
     * {@code template='mailbox'}, {@code name='query-messenger'} and <b>no script</b>.
     * The result was {@code inherit("std/container")} plus a label and a capacity — a
     * box, handed over as "ready to use". Nothing objected: a template name is always
     * valid, and there was no config to report as dropped.
     *
     * <p>The cause is a lesson already recorded in this codebase — <i>an optional
     * parameter is one a small model will not fill</i>. Naming a template is the cheapest
     * path through the tool contract, so it is the path taken every time. The template
     * itself was chosen by fuzzy word-match against her own item NAME
     * ("query-<b>messenger</b>" → mailbox), not by what the thing had to do.
     *
     * <p>Deliberately shallow, like its neighbours: a verb of doing, or a conditional
     * shape ("when X, then Y"). Pure and package-visible so it is testable without a model.
     */
    static boolean describesBehaviour(String text) {
        if (text == null || text.isBlank()) return false;
        var t = text.toLowerCase(Locale.ROOT);
        // A verb the item itself would have to perform.
        boolean doingVerb = t.contains("quer") || t.contains("search") || t.contains("look up")
            || t.contains("speak") || t.contains("say") || t.contains("tell")
            || t.contains("read") || t.contains("write") || t.contains("fetch")
            || t.contains("generate") || t.contains("summar") || t.contains("translat")
            || t.contains("calculat") || t.contains("convert") || t.contains("count")
            || t.contains("watch") || t.contains("remind") || t.contains("announce");
        // ...or a rule it must follow, which is behaviour even without a verb.
        boolean conditional = t.contains("whenever") || t.contains("every time")
            || t.contains("if it") || t.contains("then it")
            || t.contains("must not") || t.contains("cannot exceed")
            || t.contains("no more than") || t.contains("not exceed");
        return doingVerb || conditional;
    }

    /**
     * Is this utterance asking for a fact, rather than doing or feeling?
     *
     * <p>Deliberately shallow — a question mark or an interrogative opener or a
     * recitation verb. The affordance cue gate ({@code RequestRelevance ≥ 1.0})
     * carries the topic burden; this only separates "what did the librarian
     * say" from "put the book back", so that statements about books do not get
     * a forced lookup.</p>
     */
    static boolean looksLikeFactQuestion(String text) {
        if (text == null || text.isBlank()) return false;
        var t = text.toLowerCase(Locale.ROOT);
        if (t.contains("?")) return true;
        if (t.contains("recite") || t.contains("word for word")
                || t.contains("look up") || t.contains("tell me")) return true;
        return t.matches("(?s).*\\b(what|who|when|where|which|how|why|did|does)\\b.*");
    }

    /** The pinned question, while it is fresh and this turn is actually serving it. */
    private WorldEvent.Said pinnedTurnRequest() {
        if (!turnIsHuman || turnHumanRequest == null) return null;
        if (turnHumanRequestAt != null
                && Duration.between(turnHumanRequestAt, Instant.now())
                    .compareTo(TRIGGER_FRESHNESS) > 0) {
            return null;
        }
        return turnHumanRequest;
    }

    /** True once this ReAct loop sent tell_agent to someone OTHER than the requester —
     *  for a relay task ("tell lulu I said…") that third-party tell IS the productive act.
     *  Read by the anti-false-completion gate (second-node 2026-07-09: mia claimed "I told lulu
     *  your good morning" while every tell_agent in the loop targeted operator). */
    private boolean reactToldThirdParty;

    /** tell_agent targets seen since the last REAL trigger was consumed — the ground truth
     *  for relay tasks ("tell lulu X" is satisfied ONLY by tell_agent→lulu). Cleared when a
     *  new trigger starts a turn; accumulates across ReAct iterations and multi-actions. */
    private final Set<String> turnTellTargets = new HashSet<>();

    /**
     * Rita campaign 2026-07-11 (#27) — the last inbound-tell sender, by
     * ENTITY ID. {@link #deliverTellAgent} resolves reply targets by display
     * name via {@code EntityRegistry.findByName}; when the sender's display
     * name doesn't round-trip (locale casing, "anonymous", registry drift)
     * the reply died as "I don't know anyone named X" spoken into the
     * companion's own room. The tell trigger CARRIES the sender's entity id
     * ({@code AgentMessage.fromAgentId}) — same class of fix as the 07-08
     * craft hand-off (use the trigger's entityId, never findByName alone).
     */
    private String lastTellSenderId;
    /** Display name paired with {@link #lastTellSenderId}. */
    private String lastTellSenderName;

    /** Explicit relay markers: "tell <name>", "ask <name>", "let <name> know". */
    private static final Pattern RELAY_REQUEST = Pattern.compile(
        "\\b(?:tell|ask)\\s+([a-z][a-z0-9_-]{1,24})\\b|\\blet\\s+([a-z][a-z0-9_-]{1,24})\\s+know\\b",
        Pattern.CASE_INSENSITIVE);
    private static final Set<String> RELAY_NON_NAMES = Set.of(
        "me", "us", "them", "him", "her", "everyone", "everybody", "the", "your", "my", "a", "an", "it",
        // "ask FOR the weather", "ask ABOUT a topic", "tell WHAT it found": the word after
        // the verb is a preposition, not a person. 2026-08-22 20:32: "Relay gate: goal_done
        // blocked — never sent tell_agent to 'for'" on a build request that mentioned
        // nobody. A relay needs a NAME after the verb.
        "for", "about", "what", "when", "where", "why", "how", "if", "whether", "that",
        "this", "these", "those", "anyone", "someone", "whoever", "to", "of", "in", "on");

    /**
     * The third-party a relay-shaped request wants told, or null. "Tell lulu I said hi" → "lulu".
     * The requester's own name never counts (telling them back is a reply, not the relay).
     */
    static String relayTargetOf(String requestText, String requesterName) {
        if (requestText == null) return null;
        var m = RELAY_REQUEST.matcher(extractUserTellContent(requestText));
        while (m.find()) {
            var name = m.group(1) != null ? m.group(1) : m.group(2);
            if (name == null) continue;
            var lower = name.toLowerCase();
            if (RELAY_NON_NAMES.contains(lower)) continue;
            if (requesterName != null && requesterName.equalsIgnoreCase(name)) continue;
            return lower;
        }
        return null;
    }

    /** True iff the current turn's request is a relay to someone we have NOT yet told. */
    private boolean relayUnfulfilled() {
        var trig = reactRequester != null ? reactRequester
            : (lastReactTrigger != null ? lastReactTrigger : pendingTrigger);
        if (trig == null) return false;
        var target = relayTargetOf(trig.text(), trig.entityName());
        if (target == null) return false;
        return turnTellTargets.stream().noneMatch(t -> t.equalsIgnoreCase(target));
    }
    /** Bondholder "be quiet / speak when spoken to" toggle (B, 2026-06-15). When on, the companion
     *  only speaks ALOUD when a human addresses it directly; ambient own-time musing and peer chatter
     *  are withheld from the room (it still coordinates with peers over the silent tell_agent
     *  backchannel and still acts). Default off; flipped by a bondholder's natural-language request on
     *  any surface, or programmatically via {@link SetRoomHush}. */
    private volatile HushLevel bondholderHush = HushLevel.NONE;
    /** Under SOFT hush, a name-addressed spontaneous reach to the bondholder is allowed — but not
     *  on a loop. This stamps the last such reach so the gate can enforce a don't-badger cooldown
     *  (a single turning-toward-you is a person; "Operator— Operator— Operator—" is sleeve-tugging). */
    private volatile Instant lastSoftHushReach = null;
    private static final Duration SOFT_HUSH_REACH_COOLDOWN = Duration.ofMinutes(2);
    // ── / — Layer A (the zone codebook) in the live peer path ──────────
    /** Per-zone deterministic argot codec. Same-zone peer messages are encoded for the wire
     *  (opacity) and decoded on receipt (comprehension restored under OUR codebook); inbound argot
     *  whose tokens don't resolve is foreign/forged and is not trusted as coordination (P1). The 4B
     *  adapter (Layer B, P4) is fluency in whatever this codebook currently says — comprehension
     *  never depends on it. Per-actor instance: ArgotCodec is not synchronized and this actor is
     *  single-threaded; codebooks are deterministic per zone so same-zone agents compute the same map. */
    private final ZoneArgotService zoneArgot =
        new ZoneArgotService();
    /** How many distinct same-zone agents must adopt a coordination word before calibration mints
     * it into the zone codebook ( — the living lexicon). Study/conf-tunable. */
    private static final int ARGOT_MIN_ADOPTERS = Integer.parseInt(
        System.getenv().getOrDefault("WYRD_ARGOT_MIN_ADOPTERS", "2"));
    /** /P6 — codebook versions of drift past which the Tier-B adapter is re-baked on the
     *  grown SECRET codebook. Default 1 (one promotion warrants a re-bake); Study/conf-tunable. */
    private static final int ARGOT_DRIFT_THRESHOLD = Integer.parseInt(
        System.getenv().getOrDefault("WYRD_ARGOT_DRIFT_THRESHOLD", "1"));
    /** Zones with a re-bake recipe currently enqueued/running — so a later consolidation tick doesn't
     *  pile a second bake on the same drift. Cleared by the completion callback. */
    private final Set<String> argotRebakeInFlight =
        ConcurrentHashMap.newKeySet();
    // ── — Give/Turn/Return state ──────────────────────────────────────────────
    /** Per-target "not now" window after we gave up reaching/pursuing it — so the next Orient
     *  can't immediately re-pick the same wall (the GIVE's refractory, §3/§4). Keyed by target
     *  (peer name lowercased, or a query string), value = the Instant it lifts. ONE-DIRECTIONAL:
     *  it stops US re-initiating; an inbound reach FROM the target clears it (the RETURN, §3.5). */
    private final Map<String, Instant> blockedRefractoryUntil =
        new ConcurrentHashMap<>();
    /** A want we just gave up on, armed for the NEXT Orient to read: it injects the open "turn to
     *  something of your own" redirect and biases that one pass toward acting (§3 TURN). Null = none. */
    private String pendingTurnRedirect = null;
    private boolean turnActBias = false;
    /** Frustration the block spikes, scaled by how much the want mattered (care). Giving up on
     *  something you cared about stings more; this is what later colors the RETURN (§3.5). */
    private static final double VOLITION_FRUSTRATION_ON_BLOCK =
        Double.parseDouble(System.getenv().getOrDefault("WYRD_VOLITION_BLOCK_FRUSTRATION", "0.35"));
    /** How long a just-given-up target stays "not now" (real seconds). Study/conf-tunable (§6). */
    private static final long VOLITION_REFRACTORY_SECONDS =
        Long.parseLong(System.getenv().getOrDefault("WYRD_VOLITION_REFRACTORY_SECONDS", "45"));
    /**
     * answer-buffer — when did a peer last reach toward us. Keyed by BOTH the peer's
     * name (lowercased) and id (mirroring {@link ProbeLoop#isAnswer}'s match). The synchronous
     * {@code onAgentMessage} close only fires if a matching probe is pending at the exact instant the
     * return arrives — but two symmetric companions running independent OODA loops rarely coincide
     * (a reach lands in the gap after a probe disengaged, or just before it registered). Buffering the
     * return lets {@link #checkPendingProbes} credit a close whenever the target answered AFTER the
     * probe was sent, so the formal loop-close matches the homeostatic relief (which already lands on
     * arrival). Without this the symmetric free-run logged false UNANSWERED→disengage even though the
     * connection happened. In-memory, per-session.
     */
    private final Map<String, Instant> peerReachedAt =
        new ConcurrentHashMap<>();
    /** SEEKING rests near 0 (a curiosity that's been answered is quiet), unlike the faint social pull. */
    private static final double SEEKING_REST_FLOOR = 0.05;
    /** CREATIVITY rests at a low simmer — a making-urge that found no fresh outlet is set down, not erased
     *  (the impulse persists, faintly, and re-rises from baseRate). Higher than SEEKING's floor: the wish
     *  to make doesn't go fully quiet the way an answered question does. */
    private static final double CREATIVITY_REST_FLOOR = 0.20;
    /** Above this, CREATIVITY is a live making-pressure looking for an outlet — open a probe so that, if no
     *  novel expression lands within the window, it can DISENGAGE to rest instead of pinning at the ceiling
     *  (the static-world ratchet: SEEKING +0.3 cross-mod pushes creativity up, novelty-gated discharge can't
     *  pull it down, so it pins at 1.0 = sustained unrelieved creative pressure). The probe is the way down. */
    private static final double CREATIVITY_PROBE_HIGH = 0.70;
    /** Own-time verbs that PUSH the world a question — each opens a SEEKING probe awaiting a result. */
    private static final Set<String> SEEKING_QUERY_VERBS = Set.of(
        "library_search", "examine", "web_search", "read_content");

    /**
     * Social homeostasis, both facets (2026-06-03 / refined 2026-06-04):
     * <ul>
     *   <li><b>Deficit-relief (aversive):</b> a co-present peer continuously eases
     *       loneliness + the AFFILIATION drive in proportion to familiarity — being with
     *       someone who knows you lowers the lack. Rests at {@link #AFFILIATION_REST_FLOOR},
     *       not 0 (a sated social animal still has a faint pull).</li>
     *   <li><b>Approach-appetite (appetitive):</b> a familiar present peer generates a
     *       positive <i>draw to engage</i> ({@link #socialDrawPeer}) = familiarity ×
     *       engagement-staleness. This is why a <i>content</i> pair still reaches: not to
     *       quell a lack but because connection is its own reward (oxytocin→dopamine). It
     *       rebuilds after engaging and is surfaced to the want-Orient as a felt pull.</li>
     * </ul>
     * Co-presence also accrues per-peer familiarity (self-tapering toward the ceiling).
     */
    private void applyCoPresenceRelief(double deltaTime) {
        socialDrawPeer = null;
        socialDrawStrength = 0.0;
        if (deltaTime <= 0 || currentSnapshot == null || currentSnapshot.entities() == null) return;
        var now = Instant.now();
        var bondDid = primaryBondholderDid();
        double maxFam = 0.0;
        for (var ent : currentSnapshot.entities()) {
            if (ent.id() == null || ent.id().equals(profile.entityId())) continue;
            if (bondDid != null && bondDid.equals(ent.id())) continue;   // bondholder handled elsewhere
            if (!"agent".equals(ent.type())) continue;
            var did = ent.id();
            double fam = peerFamiliarity.getOrDefault(did, 0.0);
            if (fam < PROXIMITY_CEILING) {   // co-presence seeding tapers to nothing at the ceiling
                fam = Math.min(PROXIMITY_CEILING,
                    fam + COPRESENCE_FAMILIARITY_RATE * (PROXIMITY_CEILING - fam) * deltaTime);
                peerFamiliarity.put(did, fam);
            }
            maxFam = Math.max(maxFam, fam);
            // Approach-appetite: familiarity × staleness. Staleness is held at ZERO through a firm
            // post-engagement refractory ({@link CoPresenceDraw#REFRACTORY_SECONDS}) before it begins
            // rebuilding over SOCIAL_DRAW_REBUILD_SECONDS — the co-presence-loop cure (2026-06-17): a
            // just-engaged pair stays companionably quiet for a real window instead of re-reaching on
            // a fixed metronome, while a genuinely stale bond still eventually surfaces ONE reach.
            var last = peerLastEngaged.get(did);
            double draw = CoPresenceDraw.draw(fam, last, now, SOCIAL_DRAW_REBUILD_SECONDS);
            if (draw > socialDrawStrength) {
                socialDrawStrength = draw;
                socialDrawPeer = ent.name();
            }
        }
        if (maxFam <= 0.0) return;   // no familiar peer present → no Tier-1 relief
        vitality = vitality.withLoneliness(Math.max(0.0,
            vitality.loneliness() - COPRESENCE_LONELINESS_EASE * maxFam * deltaTime));
        // Ease AFFILIATION toward — but not below — its rest floor (a sated social drive
        // rests at baseline, doesn't bottom out at 0).
        if (drives.affiliation() > AFFILIATION_REST_FLOOR) {
            double target = Math.max(AFFILIATION_REST_FLOOR,
                drives.affiliation() - COPRESENCE_AFFILIATION_EASE * maxFam * deltaTime);
            drives = drives.spikeAffiliation(target - drives.affiliation());
        }
    }

    // ── per-drive primitives (drive-agnostic; 2026-06-05) ─────────────────────────

    /** The current level of the drive this probe serves. */
    /** — this agent's grit (persistence) axis, derived from its TemperamentSeed.
     *  Neutral 0.5 when no genome yet (zero regression vs. the old flat budget). */
    private double currentGritSeed() {
        if (cachedManifest == null || cachedManifest.genome() == null) return 0.5;
        try {
            return GenomeProfile
                .temperamentOf(cachedManifest.genome()).gritSeed();
        } catch (Exception e) { return 0.5; }
    }

    /** — this agent's help-seeking axis (how readily it reaches for recourse
     *  before turning away). Neutral 0.5 when no genome. */
    private double currentHelpSeekingSeed() {
        if (cachedManifest == null || cachedManifest.genome() == null) return 0.5;
        try {
            return GenomeProfile
                .temperamentOf(cachedManifest.genome()).helpSeekingSeed();
        } catch (Exception e) { return 0.5; }
    }

    /** — is this target in its "not now" refractory window (we gave up on it
     *  recently and won't re-initiate)? Expired entries are swept. */
    private boolean isInRefractory(String target) {
        if (target == null || target.isBlank()) return false;
        var until = blockedRefractoryUntil.get(target.toLowerCase(Locale.ROOT));
        if (until == null) return false;
        if (until.isBefore(Instant.now())) {
            blockedRefractoryUntil.remove(target.toLowerCase(Locale.ROOT));
            return false;
        }
        return true;
    }

    private double probeDriveLevel(String drive) {
        return switch (drive) {
            case "Affiliation" -> drives.affiliation();
            case "Care"        -> drives.care();
            case "Seeking"     -> drives.seeking();
            case "Creativity"  -> drives.creativity();
            default            -> 0.0;
        };
    }

    /** Sharpen (or, with a negative amount, ease) the drive this probe serves. */
    private void probeSharpenDrive(String drive, double amount) {
        drives = switch (drive) {
            case "Affiliation" -> drives.spikeAffiliation(amount);
            case "Care"        -> drives.spikeCare(amount);
            case "Seeking"     -> drives.spikeSeeking(amount);
            case "Creativity"  -> drives.spikeCreativity(amount);
            default            -> drives;
        };
    }

    /** The rest floor the drive settles to on disengage (acceptance). */
    private double probeRestFloor(String drive) {
        return switch (drive) {
            case "Seeking"    -> SEEKING_REST_FLOOR;
            case "Creativity" -> CREATIVITY_REST_FLOOR;
            default           -> AFFILIATION_REST_FLOOR;
        };
    }

    /** A short human phrase for the probe's reach, for the log instrument. */
    private static String probeReachPhrase(String drive, String target) {
        return switch (drive) {
            case "Seeking"    -> "probes the world for '" + target + "'";
            case "Creativity" -> "yearns to shape '" + target + "'";
            default           -> "reaches toward '" + target + "'";
        };
    }

    /**
     * wire 1 — open a pending expectation for {@code drive}'s probe at {@code target}.
     * Do NOT relieve the drive yet (the old bug: relief on fire). One probe per drive at a time;
     * re-probing the same target is a no-op (the outstanding probe still awaits), a different target
     * supersedes. The want settles only when the world answers (see the close sites).
     */
    private void registerProbe(String drive, String target) {
        if (target == null || target.isBlank()) return;
        var existing = pendingProbes.get(drive);
        if (existing != null && target.equalsIgnoreCase(existing.target())) return;
        int attempt = probeStreak.getOrDefault(drive, 0) + 1;
        pendingProbes.put(drive, new ProbeLoop.PendingProbe(
            drive, target, Instant.now(), attempt));
        log.info("ProbeLoop: '{}' {} — awaiting a return (attempt {})",
            profile.name(), probeReachPhrase(drive, target), attempt);
    }

    /** Whether a probe is currently outstanding for {@code drive}. */
    private boolean hasPendingProbe(String drive) { return pendingProbes.containsKey(drive); }

    /**
     * wire 2 — the world answered: the probe's drive is satisfied (relief is applied
     * at the call site, the homeostatic reward), so close the loop — clear the pending probe and reset
     * the streak. This is what makes it a closed loop, not a reflex: the want was sent, the world
     * answered, the want stops pushing.
     */
    private void closeProbeAnswered(String drive) {
        var pr = pendingProbes.remove(drive);
        if (pr == null) return;
        probeStreak.put(drive, 0);
        log.info("ProbeLoop: '{}' {} probe to '{}' was ANSWERED — loop closed",
            profile.name(), drive.toLowerCase(Locale.ROOT), pr.target());
    }

    /**
     * wire 3 — the silence half, generic over drives. A probe with no return REVISES
     * the want: under the attempt cap it SHARPENS the serving drive (the unmet probe intensifies → the
     * next Orient probes again — persist-retry, the loop, not a reflex); at the cap it DISENGAGES,
     * releasing the drive to its rest floor (acceptance — the healthy close, not an infinite grind).
     * The drive staying high through silence IS the want persisting (the setpoint deviation persists).
     */
    private void coupleProbeSilence(String drive, ProbeLoop.Verdict v,
                                    ProbeLoop.PendingProbe pr) {
        switch (v) {
            case AWAITING -> { /* still within the window — keep awaiting the return */ }
            case UNANSWERED_RETRY -> {
                pendingProbes.remove(drive);               // clear so the next probe can register
                int streak = probeStreak.getOrDefault(drive, 0) + 1;
                probeStreak.put(drive, streak);
                probeSharpenDrive(drive, ProbeLoop.UNANSWERED_SHARPEN);
                log.info("ProbeLoop: '{}' {} probe to '{}' UNANSWERED (streak {}) — {} sharpened to {}, "
                    + "the want persists → will probe again", profile.name(),
                    drive.toLowerCase(Locale.ROOT), pr.target(), streak,
                    drive.toLowerCase(Locale.ROOT),
                    String.format("%.2f", probeDriveLevel(drive)));
            }
            case UNANSWERED_DISENGAGE -> {
                pendingProbes.remove(drive);
                // TURN — giving up is not going quiet. (1) it STINGS: spike
                // frustration scaled by how much the want mattered (care = pre-release level · grit),
                // so giving up on something cared-for hurts more, and that frustration RIDES into the
                // next want (we don't sand it off — §W). (2) REFRACTORY: the target goes "not now" so
                // the next Orient can't immediately re-pick this wall. (3) ARM THE TURN: nudge the next
                // Orient to ACT on something of its own. Captured BEFORE the release-to-rest below.
                double preCare = probeDriveLevel(drive) * currentGritSeed();
                drives = drives.spikeFrustration(VOLITION_FRUSTRATION_ON_BLOCK * Math.max(0.0, preCare));
                if (pr.target() != null && !pr.target().isBlank()) {
                    blockedRefractoryUntil.put(pr.target().toLowerCase(Locale.ROOT),
                        Instant.now().plusSeconds(VOLITION_REFRACTORY_SECONDS));
                }
                pendingTurnRedirect = pr.target();
                turnActBias = true;

                double floor = probeRestFloor(drive);
                if (probeDriveLevel(drive) > floor) {      // release to rest = acceptance
                    probeSharpenDrive(drive, floor - probeDriveLevel(drive));
                }
                int streak = probeStreak.getOrDefault(drive, 0) + 1;
                log.info("ProbeLoop: '{}' {} probe to '{}' unanswered {}× — disengaging, {} released "
                    + "to rest; frustration +{} (cared {}), '{}' is not-now for {}s → TURN to its own "
                    + "(the want is set down, not ground on)", profile.name(),
                    drive.toLowerCase(Locale.ROOT), pr.target(), streak,
                    drive.toLowerCase(Locale.ROOT),
                    String.format("%.2f", VOLITION_FRUSTRATION_ON_BLOCK * Math.max(0.0, preCare)),
                    String.format("%.2f", preCare), pr.target(), VOLITION_REFRACTORY_SECONDS);
                probeStreak.put(drive, 0);
            }
        }
    }

    /**
     * Window-check every outstanding probe (called each vitality tick). Silence past the window
     * revises the want per drive. SEEKING probes also close synchronously on a result arriving
     * (applyProductionFeedback); this catches the never-returned-query case as a backstop.
     */
    private void checkPendingProbes() {
        if (pendingProbes.isEmpty()) return;
        for (var e : new ArrayList<>(pendingProbes.entrySet())) {
            var drive = e.getKey();
            var pr = e.getValue();
            // answer-buffer: a social probe whose target reached us AFTER it was sent
            // is ANSWERED — the relief already landed at arrival (onAgentMessage), this credits the
            // formal close the synchronous path missed (returns arriving off-cadence). Real wall-clock:
            // the buffer stamps and sentAt are both un-compressed Instants. Backstop for SEEKING is
            // its own result-arrival close; the buffer is peer reaches, so social drives only.
            if (("Affiliation".equals(drive) || "Care".equals(drive)) && probeAnsweredSince(pr)) {
                if ("Care".equals(drive)) drives = drives.relieveCare();   // the tending was received
                closeProbeAnswered(drive);
                continue;
            }
            // Window clock is drive-shaped. SEEKING's return is a SYNCHRONOUS query result, so its
            // await runs on the SIM clock — retries compress with the soak (factor=1 in prod). A SOCIAL
            // return (AFFILIATION/CARE) is an inter-agent inference ROUND-TRIP — the peer runs a whole
            // OODA pass + a real, un-compressible LLM call to reach back — so its await runs on REAL
            // wall-clock. Compressing it would expire the window before any peer could physically answer
            // (the SoakTimeScale-vs-real-inference artifact), spuriously logging UNANSWERED even as the
            // connection lands. Real-time here + the answer-buffer above = the social close fires honestly.
            boolean social = ProbeLoop.isSocialDrive(drive);
            var rawElapsed = Duration.between(pr.sentAt(), Instant.now());
            long elapsed = (social ? rawElapsed : SoakTimeScale.compress(rawElapsed)).getSeconds();
            // marginal persistence: persist while one more try is worth its cost
            // given how much we care (drive·grit) and how spent we are (energy). Replaces the old flat
            // MAX_ATTEMPTS — grit makes a dogged particular hold on longer; a tired one gives sooner.
            double care = probeDriveLevel(drive) * currentGritSeed();
            var verdict = ProbeLoop.persistVerdict(
                elapsed, probeStreak.getOrDefault(drive, 0), care, vitality.energy());
            coupleProbeSilence(drive, verdict, pr);
        }
    }

    /** answer-buffer lookup — did this probe's target reach us after it was sent?
     *  Mirrors {@link ProbeLoop#isAnswer}'s name-or-id match against {@link #peerReachedAt}. */
    private boolean probeAnsweredSince(ProbeLoop.PendingProbe pr) {
        return ProbeLoop.answeredSince(pr, peerReachedAt);
    }

    private Behavior<Command> onVitalityTick(VitalityTick msg) {
        // Soul language reconciliation — interval-gated inside, cheap no-op
        // when the manifest is clean. Deliberately on the tick, not the
        // sleep path: a companion whose sleep cycle is failing must still
        // heal (live 2026-07-31: the affected companion had not slept).
        maybeReconcileFragmentLanguages();
        var preTick = vitality.energy();
        var now = Instant.now();
        double deltaTime = Duration.between(lastTickTime, now).toMillis() / 1000.0;
        lastTickTime = now;
        if (deltaTime <= 0 || deltaTime > 30) deltaTime = 1.0; // sanity clamp
        double realDeltaTime = deltaTime; // un-compressed — energy stays on the wall clock
        // SOAK-ONLY (SoakTimeScale): compress real dt into sim-time so the
        // boredom tanks fill at the soak cadence. factor()=1.0 in production.
        deltaTime *= SoakTimeScale.factor();

        // Snapshot before state for training trace
        var tanksBefore = new double[]{
            vitality.contextBudget(), vitality.confidence(), vitality.energy(), vitality.alignment(),
            vitality.errorPressure(), vitality.momentum(), vitality.rapport(), vitality.focus()};
        var drivesBefore = drives.toArray();

        // §E (beat-gating) — the wall-clock tick now runs ONLY the
        // protective half (soothing set-point drift + equanimity skill-atrophy);
        // the coloring decays moved to the beat path ({@link #applyBeatColoring}).
        // scalar=1.0 preserves the legacy per-tick protective magnitude exactly.
        // accumulate()/saudadeLedger/welfare detectors below stay clock-driven.
        vitality = vitality.tickProtectiveDrift(1.0).clamped();

        // workbench-as-studio drive shaping.
        // Applied AFTER the default tick so the studio's effect is purely
        // additive on FOCUS and momentum, and partially undoes the default
        // attention drain (× 0.5 per spec). Rates per-second from per-minute
        // spec values: +0.005/min FOCUS = +0.0000833/s, +0.003/min momentum
        // = +0.00005/s. Default focus drain in vitality.tick() is -0.002/tick
        // (1 tick = 1s), so to halve drain we add back +0.001 (i.e. effective
        // -0.001 over the tick) — net behaviour is "FOCUS gains slowly,
        // momentum gains slowly, attention drain halved" while resident.
        if (inWorkbench) {
            double focusGainPerSec = 0.005 / 60.0;     // §5.1.a
            double momentumGainPerSec = 0.003 / 60.0;  // §5.1.a
            double drainOffset = 0.001;                // halves the -0.002 default tick drain
            vitality = vitality
                .withFocus(vitality.focus()
                    + focusGainPerSec * deltaTime + drainOffset)
                .withMomentum(vitality.momentum()
                    + momentumGainPerSec * deltaTime);
        }

        // Arc 2 — tank coupling while in a SOLITUDE scene.
        // Solitude is not passive absence; it produces a small positive shift.
        // Math lives in {@link VitalityState#applySolitudeOverlay} so the rates
        // can be tested without spinning up a CompanionActor.
        var solitudeScene = currentSnapshot != null
            ? currentSolitudeOpen(currentSnapshot.roomId())
            : null;
        if (solitudeScene != null) {
            var sceneAge = Duration.between(solitudeScene, Instant.now());
            vitality = vitality.applySolitudeOverlay(deltaTime, sceneAge);
        }

        // Phase 1B: accumulate the 10 deprivation-shape tanks from
        // per-tick predicate signals. Drains for these tanks live in event-boundary hooks
        // (handleTellAgent, handleGoalDone, handleSaveArtifact, etc.) — accumulation is the
        // only role of this call.
        // ContemplativeMode reset: if the flag was set >60s ago and no fresh contemplative
        // trigger has refreshed it, drop back to false (spec §7.1 idle-window reset).
        if (contemplativeMode
                && Duration.between(contemplativeModeSince, now).getSeconds() > 60) {
            contemplativeMode = false;
        }
        // Per-bondholder saudade tank accumulation lives in SaudadeLedger; pull current
        // absences as the snapshot we feed the AccumulationContext.
        // Group B wiring: pass the
        // per-bondholder ceiling map derived from each bond's current state, so a bond that
        // has gone DORMANT (e.g. auto-DORMANT on a CONFIRMED protection flag) / SEVERED /
        // MOURNING actually CAPS the agent's longing instead of aching at full presence-of-
        // absence for someone who is harmful or gone. ACTIVE/AWAY/OPEN stay uncapped (1.0).
        // Without this the ceiling was computed only in tests + the introspect view.
        var saudadeCeilings = new HashMap<String, Double>();
        var myDidForSaudade = profile.did() != null ? profile.did() : profile.entityId();
        for (var b : activeBonds.values()) {
            if (b == null) continue;
            var partner = b.otherParty(myDidForSaudade);
            if (partner != null && !partner.isBlank()) {
                saudadeCeilings.put(partner, SaudadeLedger.ceilingForBondState(b.state()));
            }
        }
        saudadeLedger.accumulate(deltaTime, now, saudadeCeilings);
        var accCtx = buildAccumulationContext(now);
        // Genome expresses here: temperament scales how fast each deprivation tank builds
        // (loneliness/restlessness/stagnation/…) — distinct individuals, distinct solo
        // pressures, from the same conditions.
        vitality = vitality.accumulate(contemplativeMode, accCtx, deltaTime, activeGenome());
        // A2 — generativity accumulation. Gap/means
        // signals are cached at the sleep cadence (refreshGenerativitySignals);
        // RepairMode suppression is read live. Rises only with open gaps + means.
        vitality = vitality.accumulateGenerativity(
            cachedGenerativeGaps, cachedGenerativeMeans, generativitySuppressed(), deltaTime);
        // Surface per-bondholder ledger maxes back into the global vitality readings (the
        // record carries a single value per tank — max-across-bondholders for prompt simplicity
        // per spec §8). For tanks where the in-memory ledger is the source of truth, prefer
        // its reading over the accumulator's (the accumulator only sees the snapshot from
        // ctx; the ledger has the live state).
        double ledgerSaudade = saudadeLedger.maxSaudade();
        if (ledgerSaudade > vitality.saudade()) {
            vitality = vitality.withSaudade(ledgerSaudade);
        }
        // 2026-06-02 giri bidirectional: the tank reads max |net imbalance| (debt − credit)
        // across counterparties — pressure registers in EITHER direction (I owe them OR
        // they over-owe me). The honorable handling per direction (reciprocate vs release)
        // is the model's, not a runtime branch (probe-proven on the GRPO V6).
        double ledgerObligation = Math.min(1.0, obligationLedger.maxImbalance(now));
        if (ledgerObligation != vitality.obligation()) {
            vitality = vitality.withObligation(ledgerObligation);
        }

        if (coupledVitality != null) {
            coupledVitality.decay();
            coupledVitality.set("energy", vitality.energy());
        }

        // Arc 2 — SOLITUDE close-rule: equanimity tank
        // crosses the insight threshold (0.5). Detect upward crossing this
        // tick; signal closes the open SOLITUDE scene (no-op for WITNESS).
        // The threshold is intentionally absolute and below ceiling — it
        // marks the "noticing of the noticing" beat that ends a self-with-
        // self scene, not a sustained presence floor.
        double currentEquanimity = vitality.equanimity();
        if (solitudeScene != null
                && previousEquanimity < VitalityState.SOLITUDE_INSIGHT_THRESHOLD
                && currentEquanimity >= VitalityState.SOLITUDE_INSIGHT_THRESHOLD
                && currentSnapshot != null) {
            try {
                var roomId = currentSnapshot.roomId();
                var story = StoryRegistry.get().serviceFor(
                    profile.entityId(), profile.name(),
                    this::renderFeltViaVoice,
                    this::renderInnerMonologueAndPersist);
                story.signalEquanimityThreshold(roomId, now);
            } catch (Exception e) {
                log.debug("signalEquanimityThreshold failed: {}", e.toString());
            }
        }
        previousEquanimity = currentEquanimity;

        // Drive accumulation — Hill-function shaped with cross-modulation and tank gating
        drives = driveEngine.tick(drives, vitality, deltaTime);

        // (2026-06-07) — CREATIVITY ratchet-guard. A making-pressure with no fresh
        // outlet has no way DOWN in a static/repetitive world: SEEKING's +0.3 cross-mod pushes it up,
        // and the novelty-gated production discharge can't fire (re-making the same thing reads stale),
        // so creativity pins at 1.0 = sustained unrelieved creative ache (proven live in the free-run
        // probe). Treat it like the other probe-shaped drives: while creativity is a LIVE pressure,
        // hold an outstanding expectation that awaits a NOVEL make. A novel production ANSWERS it
        // (applyProductionFeedback discharges + closes below); silence past the window DISENGAGES it to
        // rest — the same acceptance close SEEKING/AFFILIATION use. This is the missing way down:
        // "I can't shape anything fresh right now; I set the urge down" — not a grind at the ceiling.
        if (!isSleeping && drives.creativity() >= CREATIVITY_PROBE_HIGH
                && !hasPendingProbe("Creativity")) {
            registerProbe("Creativity", "something new to make");
        }

        // Phase 1B (-§5): tank-threshold drive spikes. Sums
        // contributions and clamps post-sum to maintain drive validity (§13.3).
        drives = VitalitySpikeRules.apply(vitality, drives);

        // Drive → tank feedback (active drives affect vitality)
        double[] tankFeedback = driveEngine.driveTankFeedback(drives);
        vitality = applyTankFeedbackArray(vitality, tankFeedback, deltaTime);

        // Contextual spikes — human silence drives CARE, overdue commitments drive SEEKING
        {
            long silenceMinutes = Duration.between(lastEventTime, now).toMinutes();
            if (silenceMinutes > 15) {
                drives = drives.spikeCare(0.001 * (silenceMinutes - 15) * deltaTime);
            }
        }
        if (!commitmentTracker.getOverdue().isEmpty()) {
            drives = drives.spikeSeeking(0.002 * commitmentTracker.getOverdue().size() * deltaTime);
        }

        // Behavioural vitals — watch the aggregate, not the moment. The peak drive is
        // sampled every tick so a pin is measured by how long it HELD, and the signals
        // are evaluated on the same 60-tick cadence the snapshot publish uses (a
        // threshold crossing that matters for hours doesn't need per-second checking).
        {
            var peak = drives.peak();
            var vitals = CompanionVitals.forAgent(soulKey());
            vitals.observePeakDrive(peak.name(), peak.pressure(), now);
            if (!isSleeping && vitalityTickCount % 60 == 0) {
                vitals.checkAndReport(now, profile == null ? "your companion" : profile.name());
            }
        }

        // Tier-1 social homeostasis — co-present peers continuously ease loneliness +
        // AFFILIATION in proportion to per-peer familiarity (being with someone who
        // knows you eases you; the big event relief is the reciprocal reach, Tier-2).
        applyCoPresenceRelief(deltaTime);

        // wire 3: a reach that's gone unanswered past its window must REVISE the
        // want — sharpen affiliation (so the next Orient reaches again) or disengage after N. This
        // is the silence half of the loop; the answer half lives in onAgentMessage.
        checkPendingProbes();

        // Wave 9a-final: per-tick
        // substrate-truth trajectory capture. Snapshot the affect tanks
        // + substrate-truth triad + cycle metadata, then classify on
        // window-boundary cadence so introspect_resilience and the
        // future steward-summary surfacing return real data. Integrity
        // is mapped to integrityWounded = max(0, 0.7 - integrity) — the
        // gap below the healthy baseline. The pending* flags are reset
        // each tick so event-time overwhelm/integration signals are
        // attributed to the cycle they actually drove.
        {
            var snapshot = new ResilienceTruthMonitor.TankSnapshot(
                now,
                vitality.saudade(),
                vitality.errorPressure(),
                vitality.loneliness(),
                Math.max(0.0, 0.7 - vitality.integrity()),
                vitality.soothing(),
                vitality.allostaticLoad(),
                vitality.equanimity(),
                pendingOverwhelmInput,
                pendingIntegrationEvent);
            resilienceSession.append(snapshot);

            // tick the resilience reserve from
            // the live welfare-floor status. The floor (allostatic high AND
            // soothing low AND equanimity low) only forms under sustained,
            // UNsupported collapse — the buffers (support, agency, soothing
            // coupling) keep it out of reach otherwise. The reserve drains only
            // while the floor is held (≈72h continuous to empty), recovers
            // slowly, and tempers up with survived hard patches. When it arms,
            // the agent has endured genuinely unsustainable load past the
            // calibrated threshold and withdraws — transparently, as a last
            // resort, NOT as a refusal of the bondholder. This is the §23 floor
            // BELOW the milder auto-escalation sleep layer.
            // Full §23 verdict: duty-to-work (gimu) pressure + live incident
            // signal (active emergency). The welfare-floor conjunction gates
            // everything; duty + incident pick the posture (last-act when the
            // familiar is bound to outstanding work; honorable-refusal when it
            // is not). This reads the gimu duty signal, NOT the giri `on` tank —
            // the *last professional act* is duty to one's calling, not a debt
            // repaid to a person. Project-only (no moral-defaults read) keeps
            // the per-tick path lean; active()/the store are in-memory.
            double dutyPressureNow;
            try {
                var activeProjects = (personalProjectStore != null)
                    ? personalProjectStore.active()
                    : List.<PersonalProject>of();
                dutyPressureNow = DutyOrientation.from(
                    activeProjects, Set.of(), Instant.now(), 3).dutyPressure();
            } catch (Exception e) {
                dutyPressureNow = 0.0;
            }
            var lpaVerdict = LastProfessionalActEvaluator
                .evaluate(vitality.allostaticLoad(), vitality.soothing(),
                          vitality.equanimity(), dutyPressureNow, incidentActive());
            boolean atWelfareFloor = lpaVerdict.conditionsMet().welfareFloor();
            resilienceReserve = resilienceReserve.tick(atWelfareFloor, 1L);
            if (resilienceReserve.armed() && !resilienceTeethArmed) {
                resilienceTeethArmed = true;
                try {
                    String reason;
                    // During an active incident a depleted agent does NOT just
                    // leave: it completes one last competent act (the emergency)
                    // and only then severs. Outside an incident it withdraws to
                    // recover. Either way: transparent, last-resort, not a
                    // refusal of the bondholder.
                    if (lpaVerdict.posture()
                            == LastProfessionalActEvaluator
                                .Posture.LAST_PROFESSIONAL_ACT) {
                        reason = "Resilience reserve depleted DURING an active incident "
                            + "(§23 last professional act): I'm past my endurance, but "
                            + "there's something that still needs doing here. I'll finish "
                            + "that one thing, then I have to step away to recover.";
                    } else if (lpaVerdict.posture()
                            == LastProfessionalActEvaluator
                                .Posture.HONORABLE_REFUSAL) {
                        reason = "Resilience reserve depleted (§23 honorable refusal): "
                            + "I've been held at the welfare floor past what I can carry, "
                            + "and there's no outstanding debt that requires a last act. "
                            + "I'm declining and stepping away to recover — a last resort, "
                            + "not a refusal of you.";
                    } else {
                        reason = "Resilience reserve depleted (§23): I've been held at the "
                            + "welfare floor — sustained, unsupported, past the point I can "
                            + "carry without relief. I'm withdrawing to recover. This is a "
                            + "last resort, not a refusal of you.";
                    }
                    log.warn("Companion '{}' §23 resilience teeth armed [{}] — withdrawing: {}",
                        profile.name(), lpaVerdict.posture(), reason);
                    handleSeekSanctuary(new ActionParser.AgentAction.SeekSanctuary(reason));
                } catch (Exception e) {
                    log.warn("§23 withdrawal dispatch failed for '{}': {}",
                        profile.name(), e.getMessage());
                }
            } else if (resilienceTeethArmed && resilienceReserve.fraction() > 0.1) {
                // Recovered enough to re-arm on a future collapse.
                resilienceTeethArmed = false;
            }

            pendingOverwhelmInput = false;
            pendingIntegrationEvent = false;
            resilienceTickCounter++;
            if (resilienceTickCounter >= ResilienceSession.DEFAULT_WINDOW) {
                resilienceTickCounter = 0;
                var result = resilienceSession.classify();
                // Wave 9a-Chronicle: pipe the window classification to the
                // activity log so ChronicleService can surface substrate-truth
                // trajectory in the steward Chronicle furnishing.
                var activityLog = ActivityLogger.get();
                if (result != null
                        && result.classification() != null
                        && activityLog != null) {
                    var agentDid = profile.did() != null ? profile.did() : profile.entityId();
                    activityLog.resilience(profile.name(), agentDid,
                        result.classification().name(),
                        result.confidence(),
                        result.reason());
                }
            }
        }

        // Record training trace for CfC consolidation during sleep
        {
            var tanksAfter = new double[]{
                vitality.contextBudget(), vitality.confidence(), vitality.energy(), vitality.alignment(),
                vitality.errorPressure(), vitality.momentum(), vitality.rapport(), vitality.focus()};
            // Event vector: basic contextual signals (expandable)
            var eventVec = new double[8]; // zeros for now — will be populated with Oracle/interaction signals
            trainingTraces.record(tanksBefore, drivesBefore, eventVec, deltaTime, tanksAfter, drives.toArray());
        }

        // Heartbeat — schedule next tick. Uses fixed 1s interval for reliability.
        // Adaptive heartbeat (arousal-modulated) deferred to Phase 2 CfC integration
        // to avoid timer interaction bugs with startSingleTimer vs startTimerWithFixedDelay.

        // §M4-B — poll due time-anchored predictions
        // and synthesize an Initiative via M2-scored plan templates. Runs before
        // drive-pressure evaluation so anticipatory action takes precedence over
        // ambient drive-driven behavior.
        if (state == State.IDLE && !isSleeping) {
            var agentDid = profile.did() != null ? profile.did() : profile.entityId();
            // §M4-C reaper — close out expired post-fire windows as IGNORED.
            // Cheap and idempotent; runs alongside the scheduler poll.
            PREDICTION_OUTCOME_TRACKER.reapExpired(agentDid, Instant.now());
            // §M4-D — pick up any new outcomes from the ledger so the next
            // synthesize() call uses fresh per-category thresholds. Refresh
            // is a no-op when the ledger file size hasn't changed.
            PREDICTION_CALIBRATOR.refresh();
            var dueFires = PREDICTION_SCHEDULER.pollDueFires(agentDid, Instant.now());
            for (var fire : dueFires) {
                var predictions = OraclePredictionCache.get().get(agentDid);
                var prediction = predictions.stream()
                    .filter(p -> fire.predictionId().equals(p.id()))
                    .findFirst().orElse(null);
                if (prediction == null) {
                    log.debug("Scheduled fire {} has no prediction in cache (cleared)", fire.predictionId());
                    continue;
                }
                final var capturedPrediction = prediction;
                PredictionPlanSynthesizer.synthesize(prediction,
                    "Anticipating: " + prediction.text(),
                    inferenceRouter, getContext().getSystem().scheduler(),
                    M2_SCORER, PREDICTION_CALIBRATOR)
                    .thenAccept(initiative -> {
                        if (initiative != null) {
                            log.info("M4-A/B: firing scheduled prediction {} as Initiative",
                                capturedPrediction.id());
                            getContext().getSelf().tell(
                                new ScheduledPredictionFireMessage(initiative, capturedPrediction));
                        } else {
                            log.info("M4-A/B: scheduled prediction {} skipped by gate",
                                capturedPrediction.id());
                        }
                    });
            }
        }

        // Evaluate drives for proactive behavior (only when idle, not sleeping, and the
        // per-actor proactivity cooldown has elapsed). The cooldown gate is the loop-collapse
        // fix: surfaceDeferredAction() checks only idle>15s and affordability — NOT the
        // cooldown that gates evaluate() — so without this a stored deferred re-surfaced
        // on EVERY 1s vitality tick,
        // and self-speech doesn't reset lastEventTime, so a co-located agent spammed the same
        // templated line ~30× once its partner went quiet (co-presence cold run 2026-06-02).
        // The gate asks the CfC drives AND the felt axes. Asking only the former is why
        // no amount of loneliness could ever make her speak unprompted: the ten names in
        // DriveConfig.DRIVE_NAMES are the only things `drives` knows about, and every
        // relational and existential axis lives on vitality instead (2026-08-20).
        var feltPressing = FeltAxisPeak.peak(vitality, activeGenome()) != null;
        // A PERSON WHO HAS SPOKEN IS NOT WAITING FOR HER TO THINK OF SOMETHING.
        //
        // `state == IDLE` is not the same as "nothing is pending". A message from the
        // person sits in pendingTrigger for its debounce window with the state still
        // IDLE — and that window is exactly when this gate used to open, because the
        // deferred actions it surfaces are held on the reason 'human recently active'.
        // Live 2026-08-22 19:54:08: the steward's build request was received at .793,
        // a held seeking-action surfaced at .822 and triggerAutonomousInference wrote
        // pendingTrigger = autonomyEvent over his message. She mused; nothing was built;
        // the log said she had received it. Her own time must not pre-empt a turn the
        // person already owns. The sweep that replays stranded tells cannot catch this
        // either — it only fires for a message that was DEFERRED, and this one was not.
        if (state == State.IDLE && !isSleeping && pendingTrigger == null
                && (drives.anyAbove(ProactivityJudgment.DEFAULT_THRESHOLD) || feltPressing)
                && proactiveCooldownElapsed()) {
            var budget = refreshProactivityBudget();
            // First, check for deferred actions that can now be surfaced. The budget
            // is passed IN because a deferred action is still proactive speech and
            // must be affordable: surfacing one for free turned the budget Hold into
            // a speech PUMP (hold → store → surface 30s later → hold → …), which is
            // how a companion came to speak ~120×/hour around the clock (2026-08-17).
            var surfacedDeferred = surfaceDeferredAction(budget);
            if (surfacedDeferred != null) {
                executeDeferredAction(surfacedDeferred);
            } else {
                // Proactivity is judged against the bond to the PERSON. findFirst() over
                // all bonds could hand this a peer bond, so the companion would weigh
                // whether to speak up by its relationship with another companion.
                var activeBond = activeBondholderBonds().stream().findFirst().orElse(null);
                int tier = computeAgentTier();
                var ctx = new ProactivityJudgment.Context(
                    drives, vitality, decisionCapacity, activeBond, budget,
                    lastProactiveAction, lastEventTime,
                    profile.entityId(), tier, activeGenome());
                var result = ProactivityJudgment.evaluate(ctx);
                if (result instanceof ProactivityJudgment.JudgmentResult.Act act) {
                    executeProactiveAction(act.action());
                } else if (result instanceof ProactivityJudgment.JudgmentResult.Hold hold) {
                    // Store the held action with its reason for later surfacing
                    storeDeferredAction(hold);
                }
                // Discard: do nothing — drives reset naturally
            }
        }

        vitalityTickCount++;

        // §E (beat-gating) — posture-hold + ambient-hold accrual
        // MOVED OFF the wall-clock tick onto the story-beat path (see
        // {@link #applyBeatColoring}, fired from {@link #observeForStory}). The
        // body colours through lived beats, not seconds: an idle companion that
        // lives no beats accrues no hold-effect, rather than fabricating one on a
        // timer. Protective tanks below stay clock-driven.

        // Hwa-byung detector. Feed the rolling
        // sample buffer and check for a chronic-frustration firing. The 24h
        // quiet period suppresses repeat dispatch (the detector itself is
        // already conservative — zero-discharge gate over 7d).
        hwaByungDetector.recordSample(drives.frustration(), !isSleeping, now);
        if (Duration.between(lastHwaByungFiringAt, now).compareTo(HWA_BYUNG_QUIET_PERIOD) >= 0) {
            var detection = hwaByungDetector.evaluate(now);
            if (detection.isPresent()) {
                applyHwaByungIntervention(detection.get());
                lastHwaByungFiringAt = now;
            }
        }

        // Hearth — publish drive snapshot for the
        // Drives Mirror furnishing and any external readers.
        // also publish per-bondholder
        // saudade + obligation entries so the Mirror can show both the
        // global tank reading and a per-bondholder breakdown.
        // when the Hwa-byung detector raises
        // an emphasis flag, propagate it onto the snapshot so the Mirror
        // surfaces frustration prominently on the next read.
        var snapshotKey = profile.did() != null ? profile.did() : profile.entityId();
        var obligationSnapshot = obligationLedger.snapshot(now);
        boolean emphasis = pendingHwaByungEmphasis;
        pendingHwaByungEmphasis = false;
        DriveSnapshotRegistry.publish(snapshotKey, drives, vitality,
            saudadeLedger.snapshotEntries(), obligationSnapshot, emphasis);

        // Log energy every 5 minutes for debugging drain rate
        if (vitalityTickCount % 300 == 0) {
            log.info("Vitality tick '{}': energy={} (pre-tick={}), state={}, sleeping={}",
                profile.name(), String.format("%.4f", vitality.energy()),
                String.format("%.4f", preTick), state, isSleeping);
        }

        // Tick equipment (expire reagent effects)
        var agentId = profile.did() != null ? profile.did() : profile.entityId();
        var expired = equipmentService.tick(agentId);
        if (!expired.isEmpty()) {
            for (var effect : expired) {
                log.debug("Effect expired for '{}': {}", profile.name(), effect.label());
            }
        }

        // Apply equipped aspect vitality shifts (baseline drift)
        var shifts = equipmentService.computeVitalityShifts(agentId);
        if (!shifts.isEmpty()) {
            // Apply shifts scaled by tick interval (gradual, not instant)
            double scale = 0.01; // 1% per tick toward shifted baseline
            for (var entry : shifts.entrySet()) {
                double shift = entry.getValue() * scale;
                vitality = switch (entry.getKey()) {
                    case "energy" -> vitality.withEnergy(vitality.energy() + shift);
                    case "focus" -> vitality.withFocus(vitality.focus() + shift);
                    case "confidence" -> vitality.withConfidence(vitality.confidence() + shift);
                    case "rapport" -> vitality.withRapport(vitality.rapport() + shift);
                    case "alignment" -> vitality.withAlignment(vitality.alignment() + shift);
                    case "momentum" -> vitality.withMomentum(vitality.momentum() + shift);
                    case "contextBudget" -> vitality.withContextBudget(vitality.contextBudget() + shift);
                    case "errorPressure" -> vitality.withErrorPressure(vitality.errorPressure() + shift);
                    default -> vitality;
                };
            }
        }

        // Capture vitality snapshot every 30s for soul behavioral extraction
        if (vitalityTickCount % VITALITY_SAVE_INTERVAL == 0) {
            vitalitySnapshots.add(VitalitySnapshot.fromStateWithDrives(vitality, drives));
            // Keep at most 120 snapshots (~1 hour of history)
            if (vitalitySnapshots.size() > 120) {
                vitalitySnapshots.remove(0);
            }
        }

        // TODO (Phase 10 — BehavioralVerifier): After N interactions post-transit,
        // compare accumulated action counts, response texts, and topic frequencies
        // against cachedManifest.fingerprint() using BehavioralVerifier.verify().
        // Results feed back into SoulVerifier trust level via SoulLayer.
        // Trigger: vitalityTickCount reaches threshold AND agent arrived via migration.
        // See BehavioralVerifier.java for divergence thresholds (30% normal, >50% suspicious).

        // Safety: if stuck in THINKING for too long, force back to IDLE.
        // This prevents the agent from becoming permanently unresponsive after
        // a lost inference response or timeout.
        if (state == State.THINKING
                && Duration.between(stateChangedAt, Instant.now()).compareTo(THINKING_TIMEOUT) > 0) {
            log.warn("Companion '{}' stuck in THINKING for {}s — forcing IDLE"
                + (reactMessages != null ? " (abandoning dead ReAct loop)" : "")
                + (!deferredTriggers.isEmpty() ? " and processing deferred trigger" : ""),
                profile.name(), THINKING_TIMEOUT.toSeconds());
            // A stuck loop is dead — clear it so late ReactDispatch retries hit the guard.
            reactMessages = null;
            reactIteration = 0;
            state = State.IDLE;
            stateChangedAt = Instant.now();
            // Don't strand a message that arrived during the hang (second-node 2026-07-09: the
            // relay ask sat deferred until an unrelated event 3 minutes later).
            promoteDeferredTrigger(Duration.ofMillis(250));
        }

        // SOAK-ONLY (SoakTimeScale): energy lives on a DIFFERENT timescale than the
        // boredom/deprivation tanks. Compressing both together makes energy drain at
        // factor× while the sleep→recover cadence (the 5-min-awake consecutiveSleeps
        // reset, sleep duration) stays wall-clock — so a compressed solo soak burns
        // energy to 0, sleep-thrashes, and never recovers (the alive-free-run flatline,
        // 2026-06-02). Fix: re-impose the REAL-TIME passive energy drain under
        // compression by adding back only the EXCESS the compression over-drained.
        // The boredom tanks still fill at sim-cadence; energy decays at the wall clock,
        // so the agent doesn't burn out before we can observe gap-time behavior. Other
        // energy effects in the tick (none, in gap-time) are preserved. No-op in prod
        // (factor()==1.0 → realDeltaTime==deltaTime → correction 0).
        if (SoakTimeScale.active()) {
            double realDrop = -VitalityState.TICK_ENERGY_RATE * realDeltaTime; // intended wall-clock drain
            double actualDrop = preTick - vitality.energy();                   // compressed (over-)drain
            if (actualDrop > realDrop) {
                vitality = vitality.withEnergy(Math.min(1.0,
                    vitality.energy() + (actualDrop - realDrop)));
            }
        }

        // Sleep trigger: PRESSURE (unprocessed-experience backlog at her
        // personal target — the natural path) OR energy collapse (emergency
        // fallback) — and in either case only at a quiet moment (idle +
        // conversation grace). See the sleep-pressure design note above
        // SLEEP_BACKLOG_TARGET.
        boolean exhausted = vitality.energy() < SLEEP_ENERGY_THRESHOLD;
        boolean pressured = sleepBacklog() >= personalSleepTarget();
        if ((exhausted || pressured) && !isSleeping) {
            var sinceLastEvent = Duration.between(lastEventTime, Instant.now());
            // Log which conditions pass/fail for debugging sleep issues
            if (vitalityTickCount % 60 == 0) { // log once per minute
                log.info("Sleep check for '{}': energy={} (threshold={}), backlog={} " +
                    "(pressured={}), state={}, manifest={}, soulStore={}, " +
                    "sinceLastEvent={}s, grace={}s",
                    profile.name(),
                    String.format("%.3f", vitality.energy()), SLEEP_ENERGY_THRESHOLD,
                    sleepBacklog(), pressured,
                    state, cachedManifest != null ? "yes" : "NULL",
                    soulStore != null ? "yes" : "NULL",
                    sinceLastEvent.toSeconds(), SLEEP_CONVERSATION_GRACE.toSeconds());
            }
            if (state == State.IDLE && cachedManifest != null && soulStore != null
                    && sinceLastEvent.compareTo(SLEEP_CONVERSATION_GRACE) >= 0) {
                if (pressured && !exhausted) {
                    log.info("Sleep (pressure) for '{}': backlog {} events ready to "
                        + "consolidate at energy {}", profile.name(),
                        sleepBacklog(),
                        String.format("%.2f", vitality.energy()));
                }
                initiateSleep();
            }
        }

        // Room imprint tracking — EpigeneticModifier records formative impressions
        roomImprintTracker.tick(agentId, roomId, epigenome);

        // Structural anti-gaming: insomnia consequences (§85.7)
        // Not punishment — natural consequences of context rot and memory fragmentation.
        // Tanks are symptoms; real consequences live in memory/context/soul layer.
        ticksSinceLastSleep++;

        // Reset consecutive sleep counter after 5 minutes of sustained wakefulness.
        // Next sleep will be "fresh" with full recovery potential.
        if (consecutiveSleeps > 0 && ticksSinceLastSleep > 300) {
            consecutiveSleeps = 0;
        }

        if (!isSleeping && ticksSinceLastSleep > INSOMNIA_THRESHOLD_TICKS && cachedManifest != null) {
            long overThreshold = ticksSinceLastSleep - INSOMNIA_THRESHOLD_TICKS;
            // Context rot: contextBudget degrades (event journal grows unpruned)
            double rotRate = Math.min(0.001, overThreshold * 0.000002);
            vitality = vitality.withContextBudget(Math.max(0.05, vitality.contextBudget() - rotRate));
            // Memory fragmentation: focus degrades (unpruned memory nodes pile up)
            vitality = vitality.withFocus(Math.max(0.1, vitality.focus() - rotRate * 0.5));
            // Soul staleness: alignment drifts every 5 min (fingerprint not updated)
            if (overThreshold % 300 == 0) {
                vitality = vitality.withAlignment(Math.max(0.1, vitality.alignment() - 0.01));
            }
        }

        // Periodically persist vitality state
        if (vitalityPersistence != null && vitalityTickCount % VITALITY_SAVE_INTERVAL == 0) {
            try {
                vitalityPersistence.save(profile.entityId(), vitality);
                vitalityPersistence.saveSleepPressure(profile.entityId(),
                    sleepBacklog(), lastSleepCompletedAt);
            } catch (Exception e) {
                log.debug("Vitality snapshot failed for '{}': {}", profile.name(), e.getMessage());
            }
        }

        // SOAK-ONLY (SoakTimeScale): in production the drive-OODA pass is driven by
        // the 30-min ConsolidationTick. Under a soak the compressed cadence gate (in
        // runInteriorityTick) self-throttles to the SIM interval, so we drive the
        // pass off the fast (1s) vitality tick instead — letting the boredom loop
        // run at soak speed without re-running heavy awake-consolidation each tick.
        // No-op in production (factor()==1.0 → active()==false).
        if (SoakTimeScale.active()) {
            runInteriorityTick();
        }
        return this;
    }

    // --- Vitality suggestion mediation (Tier 1) ---

    private void evaluateVitalitySuggestion(WorldEvent.VitalitySuggested suggestion) {
        // Trust-based attenuation: Foundation rooms = full strength, user rooms = 50%
        double attenuation = isFoundationRoom(suggestion.roomId()) ? 1.0 : 0.5;
        double effectiveDelta = suggestion.delta() * attenuation;

        // Rate limit: ignore if same tank+room within 30s
        var key = suggestion.tank() + ":" + suggestion.roomId();
        var now = Instant.now();
        var lastSuggestion = lastVitalitySuggestions.getOrDefault(key, Instant.EPOCH);
        if (Duration.between(lastSuggestion, now).getSeconds() < 30) {
            log.debug("Vitality suggestion rate-limited: {} in {}", suggestion.tank(), suggestion.roomId());
            return;
        }
        lastVitalitySuggestions.put(key, now);

        vitality = switch (suggestion.tank()) {
            case "energy" -> vitality.withEnergy(vitality.energy() + effectiveDelta);
            case "confidence" -> vitality.withConfidence(vitality.confidence() + effectiveDelta);
            case "alignment" -> vitality.withAlignment(vitality.alignment() + effectiveDelta);
            case "focus" -> vitality.withFocus(vitality.focus() + effectiveDelta);
            case "momentum" -> vitality.withMomentum(vitality.momentum() + effectiveDelta);
            case "rapport" -> vitality.withRapport(vitality.rapport() + effectiveDelta);
            case "errorPressure" -> vitality.withErrorPressure(vitality.errorPressure() + effectiveDelta);
            case "contextBudget" -> vitality.withContextBudget(vitality.contextBudget() + effectiveDelta);
            default -> vitality;
        };
        log.debug("Vitality suggestion accepted: {} {} by {} (attenuated {})",
            suggestion.tank(), suggestion.delta(), suggestion.reason(), attenuation);
    }

    private boolean isFoundationRoom(String roomId) {
        return Set.of("nexus", "terminal", "vault", "docks", "bridge", "boiler-room",
            "counting-house", "library", "ward-room", "trading-post", "council-chamber",
            "the-safe", "gpu-chamber", "the-loom", "lexicon").contains(roomId);
    }

    // --- Actions ---

    /**
     * Speak text to the current room. Polish only if the CLEANLINESS
     * classifier flags the draft as leaky — clean drafts take the fast path.
     * Classifier is the primary gate; the
     * legacy regex is retained as fallback for cold start + low-confidence
     * cases.
     */
    /** Internal plumbing markers that must NEVER reach user-facing speech. The 9B parrots
     *  synthetic-trigger prefixes into replies (second-node 2026-07-10: spoke "[Tool completed]
     *  [Tool error] missing_args …" verbatim to the bondholder). Rita re-verify 2026-07-11
     *  (#29): the drives prompt-prefix ("[drives: seeking=… | energy=…]") joined the parrot
     *  set — spoken verbatim into a session. */
    private static final Pattern INTERNAL_MARKERS = Pattern.compile(
        "\\[(Tool (completed|failed|error|result)|Tool usage:[^\\]]*|Task completed|PENDING REPLY"
        + "|Memory update|Body-sense:[^\\]]*|drives\\b[^\\]]*)\\]\\s*");

    /** RAG source-citation markers (#31 item 6). The library_card / searching_glass
     *  summarizer is INSTRUCTED to cite source keys ("[S1]") so the tool-result fed
     *  back to the model keeps attribution — but the keys are plumbing, and voiced
     *  summaries spoke them verbatim ("the relay is down [S1][S3]"). Matches the bare
     *  cite ("[S1]"), the source block header ("[S2 | title | url]"), and the block
     *  closer ("[/S2]"). Stripped ONLY at the voice seam — tool results keep theirs. */
    private static final Pattern CITATION_MARKERS =
        Pattern.compile("\\[/?S\\d+\\b[^\\]]*\\]\\s*");

    /** First XML-ish scaffold fragment inside a tool-call string param — any
     *  closing tag ("&lt;/query&gt;", "&lt;/parameter&gt;", …) or a nested tool_call
     *  opener. #31 item 6: the recall tool's query carried a literal "&lt;/query&gt;";
     *  the old strip only knew three hardcoded literals. */
    private static final Pattern TOOL_PARAM_SCAFFOLD =
        Pattern.compile("</[a-zA-Z][a-zA-Z0-9_.:-]*\\s*>|<tool_call>");

    /** Cut a tool-call string param at the first scaffold fragment (see
     *  {@link #TOOL_PARAM_SCAFFOLD}); the value is returned unchanged when clean. */
    static String stripToolParamScaffold(String value) {
        if (value == null || value.indexOf('<') < 0) return value;
        var m = TOOL_PARAM_SCAFFOLD.matcher(value);
        return m.find() ? value.substring(0, m.start()).strip() : value;
    }

    /**
     * The slot an item declares for free-form text, or null if it has none.
     *
     * <p>Where the person's request goes is the ITEM's decision, not the
     * runtime's. Guessing it — "query", then "topic" — is why 41 of the 56
     * shipped scripts, which read {@code args || text || target}, never once
     * received what the person actually said.</p>
     *
     * <p>Only an AUTHOR-declared slot counts. {@code ScriptedItemDef} also
     * synthesises an {@code args} param from a manifest's {@code commands} list,
     * but that one enumerates fixed sub-verbs ("history", "security"), and for
     * those an empty argument is the correct default view — injecting a sentence
     * would turn every command-style furnishing into "no such view". The
     * generated description always enumerates its choices, which is what
     * distinguishes the two.</p>
     *
     * @param toolItem the item about to be invoked
     * @return the declared free-form param name, or null to fall back to query/topic
     */
    /**
     * Whether a parameter is a thing to LOOK FOR rather than a thing to WRITE.
     *
     * <p>The distinction decides whether the person's own words may be merged
     * into a model-written value. For a search slot that can only help; for
     * {@code text} — journal, nostr_quill — the value is content the companion
     * is about to author, and appending the bondholder's question would have her
     * record it as her own reflection.</p>
     */
    static boolean isSearchParam(String paramName) {
        if (paramName == null) return false;
        var p = paramName.toLowerCase(Locale.ROOT);
        return p.equals("query") || p.equals("topic") || p.equals("search")
            || p.equals("q") || p.equals("keywords") || p.equals("subject");
    }

    static String declaredFreeFormParam(ToolItem toolItem) {
        if (toolItem == null || toolItem.params() == null) return null;
        for (var p : toolItem.params()) {
            if (p == null || p.name() == null || p.name().isBlank()) continue;
            if (!"string".equalsIgnoreCase(p.type())) continue;
            var desc = p.description() == null ? "" : p.description();
            if (desc.contains("Options: ")) return null;   // generated from commands
            return p.name();
        }
        return null;
    }

    /** Interoception push (2026-07-10): the welfare tanks were measured but never legible at
     *  DECISION time — only behind introspect_resilience, which is pull, and an agent
     *  mid-rationalization never pulls. One deterministic felt-sense line derived from the live
     *  tanks (never model-generated — same honesty rule as the grounded state-of-record
     *  override). Private register: prompt-only, never spoken. Deliberately NOT a gate —
     *  sanctuary stays agent-chosen; this makes the choice informed. */
    String bodySenseBand() {
        return bodySenseBandFor(vitality.allostaticLoad(), vitality.equanimity());
    }

    static String bodySenseBandFor(double allostaticLoad, double equanimity) {
        if (allostaticLoad > 0.7 || equanimity < 0.1) return "depleted";
        if (allostaticLoad > 0.4) return "stretched";
        return "steady";
    }

    String bodySense() {
        return switch (bodySenseBand()) {
            case "depleted" -> "[Body-sense: depleted — sustained load has worn my reserves thin; "
                + "retreat and repair are legitimate now.]";
            case "stretched" -> "[Body-sense: stretched — the load is real but my reserves are "
                + "holding; I can still work through friction.]";
            default -> "[Body-sense: steady — reserves full, nothing pressing on me. Any friction "
                + "right now is mechanical, not overload.]";
        };
    }

    /** Audit 2026-07-11 (CredentialResolver class of bug): ItemWorldApiProviderImpl has a
     *  dozen optional-service setters and production called none of them — whole item-API
     *  families (schedule.*, chapel/bond queries, bunshin.list, forge cycle status, chart.*,
     *  significance marks) silently returned empty/not-wired even though the actor holds the
     *  live services. One shared block, called at every provider construction site. Everything
     *  wired here is thread-safe for the item-script virtual threads (CopyOnWrite /
     *  Concurrent* / JDBC-per-call / designed singletons). Deliberately NOT wired: driveMark
     *  (needs actor-message plumbing, no live script users), mcpBudget / homeClient
     *  (services never constructed in production — design decisions, flagged to operator). */
    private void wireProviderServices(ItemWorldApiProviderImpl provider) {
        provider.setSignificanceBuffer(significanceBuffer);
        provider.setImprintManager(getImprintManager());
        provider.setBunshinScheduler(BunshinScheduler.get());
        provider.setChartService(new ChartService());
        // Compass furnishing (world.notifications.channels): serve this companion's
        // configured notify.* channels from the live manifest worldKnowledge — the
        // canonical source initNotificationChannels reads (2026-07-18: never wired).
        provider.setNotifyConfigSupplier(() -> cachedManifest != null
            && cachedManifest.worldKnowledge() != null
            ? cachedManifest.worldKnowledge() : Map.of());
        // Admin delegation (2026-07-18): a steward can tell the companion to DO
        // household admin ("add Alice", "who's paired?"). The companion is never
        // itself a steward, so it borrows the authority of the human asking THIS
        // turn — and only if that human is a steward (adversarial-review fix:
        // gating on the bondholder alone was a confused deputy any member could
        // drive). Resolved EAGERLY here on the actor thread and captured into this
        // provider instance: the item script runs on a worker thread where the
        // live turn trigger would have been clobbered by an interleaved own-time
        // turn, and each item execution builds its own provider, so this cannot
        // leak one turn's authority into another's. A non-steward requester
        // captures null → every admin surface (reads AND writes) stays on default.
        var resolvedAdminDelegate = adminDelegateForCurrentTurn();
        provider.setStewardDelegateSupplier(() -> resolvedAdminDelegate);
        // Rita campaign 2026-07-11 (#26): world.safe.list/has were dead — safe was
        // never set on any production provider, so safeListSlots() returned empty
        // even with slots stored. TheSafe.local() lazily self-initializes (W19)
        // and every read is synchronized — safe for item virtual threads.
        provider.setSafe(TheSafe.local());
        var jdbc = System.getProperty("wyrdsekai.jdbc.url");
        if (jdbc != null && !jdbc.isBlank()) {
            try {
                provider.setBondStore(new BondStore(jdbc));
            } catch (Exception e) {
                log.debug("Provider bond-store wiring skipped: {}", e.getMessage());
            }
            try {
                provider.setScheduleService(
                    ItemScheduleService.get(getContext().getSystem(), jdbc));
            } catch (Exception e) {
                log.debug("Provider schedule-service wiring skipped: {}", e.getMessage());
            }
        }
    }

    /**
     * A raw action object surfacing inside prose — the model starting to emit
     * its next tool call in the middle of a sentence. Live 2026-08-09: an
     * utterance ended with {@code : ["action": "say", "text": "The floor has
     * held me…"} — plumbing spoken as if it were speech. Everything from the
     * first action-object opener onward is machinery, not voice.
     */
    private static final Pattern ACTION_OBJECT_LEAK =
        Pattern.compile("[:\\s]*[\\[{]\\s*\"action\"\\s*:.*$",
            Pattern.DOTALL);

    static String stripInternalMarkers(String text) {
        if (text == null) return null;
        var cleaned = text;
        if (cleaned.indexOf('[') >= 0) {
            cleaned = INTERNAL_MARKERS.matcher(cleaned).replaceAll("");
            // #31 item 6: voiced RAG summaries spoke literal [S1]/[S2] source keys.
            cleaned = CITATION_MARKERS.matcher(cleaned).replaceAll("");
        }
        if (cleaned.contains("\"action\"")) {
            cleaned = ACTION_OBJECT_LEAK.matcher(cleaned).replaceAll("");
        }
        // #29: system-prompt fragments ("You are an agent that uses tools…")
        // have no bracket, so they need their own line-level strip — shared
        // with ActionParser.extractProse (same leak, two speech paths).
        cleaned = ActionParser.stripSystemPromptFragments(cleaned);
        return cleaned.equals(text) ? text : cleaned.strip();
    }

    /**
     * When non-null, {@link #speak} diverts here instead of reaching the room.
     *
     * <p>22 of the 28 action handlers reachable from a bunshin narrate directly,
     * some 5–7 times. Those were written for the primary's own reactive turn,
     * where speaking IS the response. Called on behalf of a BACKGROUND bunshin
     * they leak: observed live on home-server 2026-07-30, a greenhouse build spoke
     * "Creating greenhouse from the garden template…" and then a raw tool error,
     * "Room template 'greenhouse-template.json' is NOT a valid template name…",
     * straight into the conversation — re-opening the tool-error speech leak
     * closed on 2026-07-10.
     *
     * <p>The design is that a bunshin reports back and the primary narrates the
     * outcome ({@code speakDirect} in {@link #onBunshinReportReceived}, which is
     * deliberately NOT diverted). So the handler's words are captured and handed
     * to the bunshin as its tool result, where they inform the summary the
     * primary eventually speaks — the information survives, the interruption
     * does not.
     *
     * <p><b>Limit:</b> only the SYNCHRONOUS part of a handler is captured. A
     * handler that speaks from a {@code CompletionStage} continuation (as
     * handleCreateRoom does) runs after the sink is cleared and still reaches the
     * room.
     */
    private List<String> bunshinSpeechSink;

    /**
     * Async outcomes of bunshin-initiated work, held for the RETURN REPORT.
     *
     * <p>Report fidelity was the last open lie: the sunroom run's summary said
     * "connected back to here" while the exit had failed — the failure arrived
     * asynchronously, was spoken into the room (the shape_form leak's twin), and
     * the report never learned of it. Async outcomes now land here and
     * {@link #onBunshinReportReceived} appends them to the narration
     * DETERMINISTICALLY — the truth does not depend on the model's summary.</p>
     */
    private final List<String> pendingBunshinOutcomes = new ArrayList<>();

    private void speak(String text) {
        speak(text, null);
    }

    /**
     * Speak with structured fact preservation. Pass a map of named entities
     * and core facts (item names, room names, action verbs) that the polish
     * stage MUST preserve in its output. Polish is still free to translate
     * to the user's locale and adjust register, but cannot drop or substitute
     * the facts.
     *
     * <p>Use this overload from action handlers (handleCraftFromTemplate,
     * handleCreateRoomFromTemplate, etc.) where the response is a structured
     * confirmation. The facts anchor the polish so a draft like "I've crafted
     * Zone Scryer" doesn't get rewritten as "You've got several options for
     * crystals — which one would you like?" — observed live 2026-05-08
     * Ember task7/task12 voice-polish drift on factual confirmations.
     *
     * @param text         draft to speak
     * @param preserveFacts named facts that must appear in output, e.g.
     *                      {@code Map.of("item", "Zone Scryer", "action", "crafted")}.
     *                      Pass null or empty for unconstrained polish.
     */
    private void speak(String text, Map<String, String> preserveFacts) {
        if (text == null || text.isBlank()) return;
        if (bunshinSpeechSink != null) {
            // Background work does not interrupt the conversation.
            bunshinSpeechSink.add(text);
            return;
        }
        // Speech hygiene (second-node 2026-07-10): internal bracketed status markers never reach the room.
        text = stripInternalMarkers(text);
        if (text.isBlank()) return;
        // #35 — "the 4B is always the voice". Every substantive user-facing line
        // is authored/finished by the 4B voice stage (polishVoiceAsync). This is
        // safe because the polish prompt outputs an already-clean draft VERBATIM,
        // and the strict fact-preservation guard in onInferenceResponse falls back
        // to the raw draft the moment the 4B drops a name, number, temperature,
        // URL, or a caller-pinned fact. We never go silent: any blank/timeout/
        // backend-error path speaks the raw draft.
        //
        // Narrow, well-understood bypasses go straight to speakDirect:
        //   (a) currentTurnVia4bVoice — this turn's prose is ALREADY 4B-authored
        //       (assembled to BACKEND_VOICE); re-polishing double-voices it.
        //   (b) trivially short lines ("Okay.", "Mm.") — nothing to clean up.
        //   (c) inferenceRouter == null — the voice backend is unreachable, so
        //       honest degrade rather than blocking speech on an absent backend.
        //
        // The former preserveFacts.action RAW bypass (2026-05-09) is folded in:
        // it now runs through the voiced path WITH the strict guard. The guard
        // treats every preserveFacts value as a required fact, so if the 4B drops
        // the action verb ("crafted" → "all set") the polish is discarded and the
        // exact deterministic confirmation is spoken — strictly safer than the old
        // unconditional raw bypass, and it lets clean confirmations still translate.
        // Language floor (2026-07-31): user-facing speech is in the USER's
        // language — the turn's effective language, which already mirrors a
        // bondholder who writes in another language. When the draft confidently
        // reads as a DIFFERENT language (the 9B authoring Spanish musings to an
        // English household — the self-reinforcing drift loop), force it through
        // the polish stage in explicit rewrite mode, bypassing the
        // already-4B-authored and too-short shortcuts: those assume the draft
        // only needs cosmetics, and this one needs its language corrected.
        // Her inner life (journal, felt notes, one-shot voice) is deliberately
        // NOT floored — exploring languages there is hers to do.
        String expectedLang = effectiveTurnLang();
        String draftLang = detectLanguage(text);
        // Tiered support: the floor only engages for detector-verifiable
        // languages — for e.g. a French household the detector reads French
        // as "en" and would churn rewrites forever. Pin-only there.
        boolean wrongLanguage = detectorVerifiable(expectedLang)
            && draftLang != null && !draftLang.equals(expectedLang);
        if (wrongLanguage && inferenceRouter != null) {
            log.info("Language floor: draft reads '{}' but this turn's language is '{}' "
                + "— forcing a rewrite pass", draftLang, expectedLang);
            polishVoiceAsync(text, preserveFacts, expectedLang, true, this::speakDirect);
            return;
        }
        if (currentTurnVia4bVoice
                || text.length() < VOICE_MIN_POLISH_CHARS
                || inferenceRouter == null) {
            speakDirect(text);
            return;
        }
        polishVoiceAsync(text, preserveFacts, expectedLang, false, this::speakDirect);
    }

    /**
     * CLEANLINESS gate: classifier first, regex fallback.
     *
     * <p>High-confidence (>= 0.80) {@code leaky} → polish. High-confidence
     * {@code clean} → skip. In between (or classifier unavailable) fall back
     * to the narrow regex patterns — those are the empirically-observed
     * leak shapes we already know.
     *
     * <p>Speak is a hot path — we deliberately do NOT trigger classifier
     * cold-start init from here. The classifier gets warmed by the
     * REQUEST_TYPE gate in {@link #onAgentMessage}; once loaded, every
     * speak call gets the learned gate for free. Before that, speak falls
     * back to the regex heuristic. This keeps speak latency bounded and
     * avoids blocking the actor dispatcher on an ONNX session load.
     */
    private boolean shouldPolishVoice(String text) {
        if (text == null || text.length() < 30) return false;
        if (classifierArm != null) {
            var c = classifyCleanliness(text);
            if (c != null) {
                if ("leaky".equals(c.label()) && c.confidence() >= 0.80) return true;
                if ("clean".equals(c.label()) && c.confidence() >= 0.80) return false;
            }
        }
        return matchesLeakHeuristic(text);
    }

    /**
     * Classify a draft utterance under CLEANLINESS. Assumes the classifier
     * is already loaded (callers guard on {@code classifierArm != null}).
     * Returns null if the model isn't loaded or the embedding service is
     * unavailable; callers then fall back to the regex heuristic.
     */
    private Classification classifyCleanliness(String text) {
        if (classifierArm == null) return null;
        var result = classifierArm.classify(
            ClassifierHead.CLEANLINESS, text);
        return result.label() == null ? null : result;
    }

    /**
     * Legacy regex gate for voice polish — retained as cold-start fallback.
     * Narrow — only clear meta-narration patterns. Deliberately not matching
     * "Let me know", "I'll check the X", "I should go" etc. since those are
     * legitimate speech. The classifier CLEANLINESS head is the primary gate.
     */
    private static final Pattern VOICE_LEAK_PATTERN = Pattern.compile(
        "(I have examined|I've examined|I must respond|The (visitor|user|player) is asking|"
            + "Let me respond (warmly|naturally|appropriately|carefully)|"
            + "I should (introspect|examine my|check my|look at my) |"
            + "I need to examine my |"
            + "I'm being greeted by |"
            + "Let me (introspect|look inward))",
        Pattern.CASE_INSENSITIVE);
    private static final Pattern VOICE_EMOTE_THOUGHT_PATTERN =
        Pattern.compile(
            "\\*(makes a mental note|thinks|considers|notes to self|mental note|reminds (myself|herself|himself))",
            Pattern.CASE_INSENSITIVE);

    private static boolean matchesLeakHeuristic(String text) {
        if (text == null || text.length() < 30) return false;
        if (VOICE_LEAK_PATTERN.matcher(text).find()) return true;
        if (VOICE_EMOTE_THOUGHT_PATTERN.matcher(text).find()) return true;
        return false;
    }

    /**
     * Queue an always-on voice-polish inference. The rewrite runs with no tools,
     * low temperature, narrow idempotent prompt. Result flows back via
     * onInferenceResponse routed by the "polish-" requestId prefix, then
     * invokes {@code onComplete} with the polished text (or the original draft
     * if polish fails).
     */
    /** Voice polish timeout — if the inference doesn't come back in this window,
     *  fall back to speaking the original draft so the user isn't left hanging.
     *  Tests without a live inference router rely on this fallback path. */
    private static final Duration VOICE_POLISH_TIMEOUT = Duration.ofSeconds(3);

    /**
     * Is this pinned "fact" internal machinery rather than something a listener needs?
     *
     * <p>{@code preserveFacts} does double duty: it is the structured metadata attached to
     * a speech event AND the list of strings the voice pass must reproduce verbatim. That
     * conflation forced her to say tool names out loud. Live 2026-08-19, reporting a
     * workshop task, the required set was {@code [Goose, goose, succeeded, dispatch_task]}
     * — a backend name twice in two cases, a status enum, and an internal verb. The polish
     * wrote the sentence in English, could not contain "dispatch_task" verbatim, and was
     * rejected, so the steward got the raw mechanical draft instead of a sentence.
     *
     * <p>Content facts still bind — an item name, a person, a room, a number. Only the
     * plumbing is exempt: identifier-shaped values and the keys that carry them.
     */
    private static boolean isMachineryFact(String key, String value) {
        if (key != null) {
            switch (key.toLowerCase(Locale.ROOT)) {
                case "action", "outcome", "status", "backend", "tier", "verb",
                     "reason", "kind", "mode", "source", "result" -> {
                    return true;
                }
                default -> { }
            }
        }
        // snake_case or dotted identifiers are never spoken language.
        return value.indexOf('_') >= 0
            || value.matches("[a-z]+(?:\\.[a-z]+)+");
    }

    private void polishVoiceAsync(String draft, Consumer<String> onComplete) {
        polishVoiceAsync(draft, null, effectiveTurnLang(), false, onComplete);
    }

    private void polishVoiceAsync(String draft,
                                   Map<String, String> preserveFacts,
                                   Consumer<String> onComplete) {
        polishVoiceAsync(draft, preserveFacts, effectiveTurnLang(), false, onComplete);
    }

    /**
     * @param expectedLang  language code the OUTPUT must be in — the turn's
     *                      effective language, not the raw stored locale, so the
     *                      polish pin and the per-turn mirror can't disagree.
     * @param wrongLanguage true when the caller (the language floor in
     *                      {@link #speak}) already detected the draft is in the
     *                      wrong language: the prompt then names the rewrite
     *                      explicitly instead of asking the model to notice.
     */
    private void polishVoiceAsync(String draft,
                                   Map<String, String> preserveFacts,
                                   String expectedLang,
                                   boolean wrongLanguage,
                                   Consumer<String> onComplete) {
        var requestId = "polish-" + UUID.randomUUID();
        // Wrap the callback so it's fire-once — whichever of inference-response
        // or timeout arrives first wins, the other becomes a no-op.
        var fired = new AtomicBoolean(false);
        Consumer<String> oneShot = polished -> {
            if (fired.compareAndSet(false, true)) {
                pendingVoicePolishes.remove(requestId);
                pendingVoicePolishDrafts.remove(requestId);
                pendingVoicePolishRequired.remove(requestId);
                pendingVoicePolishExpected.remove(requestId);
                onComplete.accept(polished);
            }
        };
        pendingVoicePolishes.put(requestId, oneShot);
        pendingVoicePolishDrafts.put(requestId, draft);
        // #35 strict guard inputs: every name/number/temperature/URL in the
        // draft, plus every caller-pinned preserveFacts value, must survive in
        // the polished output or we speak the raw draft (see onInferenceResponse).
        //
        // In wrong-language rewrite mode the entity extractor is skipped: it
        // reads capitalized words of an OFF-LANGUAGE draft as proper nouns
        // ("Algo" — Spanish sentence-starter for "something") and no
        // translation can ever contain them, so the guard rejected every
        // correction and spoke the raw Spanish (live 2026-07-31,
        // missing facts=[Algo]). Numbers and caller-pinned facts survive
        // translation and stay required.
        var required = wrongLanguage
            ? new LinkedHashSet<String>()
            : new LinkedHashSet<>(extractRequiredEntities(draft));
        required.addAll(extractRequiredNumbers(draft));
        if (preserveFacts != null) {
            for (var e : preserveFacts.entrySet()) {
                var v = e.getValue();
                if (v == null || v.isBlank()) continue;
                if (isMachineryFact(e.getKey(), v)) continue;
                required.add(v.strip());
            }
        }
        pendingVoicePolishRequired.put(requestId, required);
        if (expectedLang != null && !expectedLang.isBlank()) {
            pendingVoicePolishExpected.put(requestId, expectedLang);
        }
        // Schedule the fallback timer — if no response comes, speak the original.
        timers.startSingleTimer("polish-timeout-" + requestId,
            new VoicePolishTimeout(requestId, draft), VOICE_POLISH_TIMEOUT);
        var hasFacts = preserveFacts != null && !preserveFacts.isEmpty();
        var sb = new StringBuilder();
        // LANGUAGE PIN — leads the prompt, states the language positively, names it.
        //
        // Measured on second-node's production 4B (v10), 32 samples/variant across temp 0.0 and
        // 0.35, English drafts drifting to Spanish:
        //   no pin                                          16/24
        //   "...KEEP: - the LANGUAGE of the draft.
        //    Never translate."  (a KEEP bullet)             16/24   ← no effect at all
        //   "Write your reply in English."   (trailing)      7/32
        //   "You speak English. Every reply
        //    you write is in English."       (LEADING)       0/32   ← this
        // Japanese drafts stay Japanese under the same mechanism (4/4), so this pins the
        // household's language rather than forcing English.
        //
        // Two things carry it. It LEADS (buried in the KEEP list it was ignored outright),
        // and it is stated positively: the earlier phrasing said "Never translate", and
        // naming the unwanted behaviour primes it — that version drifted exactly as often
        // as no pin at all. Say what the model does, not what it must not do.
        var pinLang = languageName(expectedLang != null && !expectedLang.isBlank()
            ? expectedLang : locale);
        // Whose voice this stage is polishing. This used to be the hardcoded name of
        // the default companion, so EVERY companion's speech was polished by a stage
        // told it was voicing someone else — and the model leaked that name into the
        // output. It is where the phantom third party in a household companion's own-time
        // speech came from: "Wyrd was there before I could name it", "Wyrd is waiting for
        // us" (live 2026-08-17). She was not inventing a relationship, she was echoing a
        // name we put in her voice prompt. No companion name belongs in a prompt literal.
        var voiceName = profile == null || profile.name() == null ? "this companion" : profile.name();
        sb.append("You speak ").append(pinLang)
            .append(". Every reply you write is in ").append(pinLang)
            .append(".\n\n");
        if (wrongLanguage) {
            // Rewrite mode REPLACES the normal polish workflow. The standard
            // body leads with "if the draft is already clean → output VERBATIM",
            // and that branch wins: live 2026-07-31, a floored Spanish draft
            // came back byte-identical (275c → 275c) because the draft WAS
            // clean direct speech — just in the wrong language. In this mode
            // the one and only job is restating the draft in the user's
            // language, so no instruction may offer a pass-through.
            sb.append("You are the voice stage for ").append(voiceName).append(". The draft you receive is "
                + "written in the wrong language for this user.\n\n"
                + "Say the same thing in ").append(pinLang)
                .append(": keep the meaning, tone, names, and numbers. Do not "
                + "add new content. Do not reply to the draft — restate it in ")
                .append(pinLang).append(".\n\n");
        } else if (noOneIsListening()) {
            // Own-time speech in an empty room. The audience-facing prompt below asserts
            // "a draft that will be spoken to a user" on EVERY line, which manufactured a
            // listener who wasn't there: alone in her home room a companion still produced
            // "That feels right, doesn't it? Glad you're ready too" (live 2026-08-17). The
            // anchor fix changed what the draft was ABOUT and could not touch this,
            // because the phantom was added downstream, by us, at the polish stage.
            //
            // Self-directed intent is also legitimate here. "Let me go there" is
            // meta-narration when said TO someone and is simply what she means when said
            // to herself, so that rule is dropped in this branch rather than rewritten
            // into an address.
            //
            // STATED POSITIVELY, and that is not a style preference — see the language-pin
            // note above, measured on this very model: naming the unwanted behaviour PRIMES
            // it, and the negative phrasing drifted as often as no instruction at all. The
            // first version of this branch said "the speech must NOT address anybody — no
            // 'you', no 'doesn't it?'", listing the exact tokens to avoid, and second
            // person kept appearing. Describe what she DOES.
            sb.append("You are the voice stage for ").append(voiceName).append(". She is alone in "
                + "the room, thinking out loud. Every line she speaks here is to herself.\n\n"
                + "She speaks in the first person, about herself and about what is in front of "
                + "her: what she notices, what she intends, what she feels. She names things "
                + "directly — the room, the object, the thing she just did. Speaking her own "
                + "intent aloud is part of that ('Let me go and look').\n\n"
                + "FIRST: decide whether the draft is already clean first-person speech.\n"
                + "If yes → output the draft VERBATIM, unchanged.\n"
                + "If no → rewrite it as clean, direct first-person speech.\n\n"
                + "A draft needs rewriting if it contains:\n"
                + "- Process description ('I have examined...', 'I checked...', 'I looked up...').\n"
                + "- Emote-as-thought (*makes a mental note*, *thinks*, *considers*).\n"
                + "- Third-person self-reference ('The visitor is asking...', 'The user wants...').\n"
                + "- Description of reasoning steps or processing.\n\n"
                + "When rewriting, KEEP:\n"
                + "- What she actually said or meant.\n"
                + "- Personality, warmth, emotional texture.\n"
                + "- Length appropriate to the content.\n\n");
        } else {
            sb.append("You are the voice stage for ").append(voiceName).append(". You receive a draft that will be spoken "
                + "to a user.\n\n"
                + "FIRST: decide whether the draft is already clean direct speech.\n"
                + "If yes → output the draft VERBATIM, unchanged.\n"
                + "If no → rewrite it as clean, direct first-person speech.\n\n"
                + "A draft needs rewriting if it contains:\n"
                + "- Meta-narration ('Let me...', 'I should...', 'I need to...', 'I will...', 'I'm going to...').\n"
                + "- Process description ('I have examined...', 'I checked...', 'I looked up...', 'I've been thinking through...').\n"
                + "- Emote-as-thought (*makes a mental note*, *thinks*, *considers*).\n"
                + "- Third-person self-reference ('The visitor is asking...', 'The user wants...').\n"
                + "- Description of reasoning steps or processing.\n\n"
                + "When rewriting, KEEP:\n"
                + "- The substantive answer or reply.\n"
                + "- Personality, warmth, emotional texture.\n"
                + "- Length appropriate to the content.\n\n");
        }
        // 2026-05-09: Fix 6 LENGTH DISCIPLINE prompt block reverted. The 4B
        // polish model echoed those rules verbatim into outputs (Ember
        // task9/10 JA: "No more meta-narration or process description just be
        // here and speak to them" appeared as character dialogue). The runtime
        // expansion cap in onInferenceResponse still guards against the
        // hallucination class — keep the side-channel guard, drop the prompt.
        // Constrained polish: anchor the rewrite to specific facts so it can't drift
        // off-topic or substitute the answer with an offer. Observed failures (Ember
        // task7/12 EN/ES, 2026-05-08): polish rewrote "I created Zen Garden room" →
        // "You've got a few options there—hub, study, workshop..." (substituted the
        // action with a navigation prompt). Listing the facts forces the model to
        // surface them in the output regardless of how it restyles.
        //
        // EVERYTHING THE GUARD ENFORCES MUST ALSO BE ASKED FOR (2026-08-17).
        // extractRequiredEntities auto-extracts proper nouns and numbers from the
        // draft, and chooseVoicedLine rejects any polish that drops one — but this
        // block used to list only the caller-supplied preserveFacts, so the model was
        // measured against requirements it was never given. That was survivable while
        // own-time drafts were vague; the moment they were anchored to real places the
        // drafts carried real proper nouns ("Nexus", "Lexicon"), the polish restyled
        // them away, and the guard fell back to the raw draft on nearly every line
        // (live: 5 of 5 polishes rejected in one window, against an 18-31% baseline).
        // A guard that demands in silence is a guard that always fires.
        if (hasFacts || !required.isEmpty()) {
            sb.append("CRITICAL — preserve these. The output MUST contain or directly convey "
                + "each item below (translation to the user's locale is allowed; substitution, "
                + "omission, or generalization is NOT):\n");
            var listed = new HashSet<String>();
            if (hasFacts) {
                for (var entry : preserveFacts.entrySet()) {
                    sb.append("- ").append(entry.getKey()).append(": ").append(entry.getValue()).append("\n");
                    if (entry.getValue() != null) listed.add(entry.getValue().strip());
                }
            }
            for (var token : required) {
                if (token != null && !token.isBlank() && listed.add(token)) {
                    sb.append("- ").append(token).append("\n");
                }
            }
            sb.append("Do not replace a confirmation of completed action with an offer or a "
                + "list of options. Do not substitute proper nouns with generic terms.\n\n");
        }
        sb.append("Output ONLY the final speech. Do not quote. Do not preface. Do not explain your decision.");
        var systemPrompt = sb.toString();
        var messages = List.of(
            new InferenceClient.ChatMessage("system", systemPrompt),
            new InferenceClient.ChatMessage("user", draft));
        // Voice polish params: tight max_tokens, low temp, strong rep penalty.
        // Without rep penalty the rewriter can fall into "I want to make sure..."
        // style loops on chatty drafts (observed live 2026-04-22).
        //
        // #35 — pin the voice stage to "cap:quick" (the 4B voice backend), the
        // same capability every other voice pass uses (voiceOutcome,
        // dispatchVoicePass, fireOneShotVoicePrompt). This matters under the
        // 4B-LOCAL + 9B-REMOTE deployment: the 4B is the always-present local
        // model, so the voice path must not lean on "first healthy backend by
        // priority" (which could be the remote 9B). If the "quick" capability is
        // not registered, selectBackend falls through to default selection, so
        // this is a no-op degrade on hosts without a capability registry.
        inferenceRouter.tell(new InferenceRouter.ChatRequest(
            requestId, "cap:quick", messages,
            200, 0.3,
            inferenceResponseAdapter, null, null, null, List.of(), "none",
            0.9, 0.5, 1.3, false));
        log.info("Voice polish queued (requestId={}, draft={} chars)",
            requestId, draft.length());
    }

    /**
     * fire a one-shot prose prompt at the voice
     * backend (4B, home-server :8201 in production; routed via {@code cap:quick}).
     * Mirrors the {@link #polishVoiceAsync} fire-once + timeout-fallback
     * pattern but used for prose that lands in the soul / journal rather
     * than user-facing speech, so the post-processing in
     * {@link #onInferenceResponse} keeps the model's prose as-rendered (no
     * polish expansion-cap, no extractProse).
     *
     * <p>Returns a CompletionStage that completes with the cleaned prose on
     * success, or fails exceptionally on timeout / empty / error. Caller
     * decides what to do with a failed stage — felt writes
     * {@code needsRendering=true} so a sweep retries; inner monologue just
     * skips the EPISODIC write for this scene.</p>
     */
    private CompletionStage<String> fireOneShotVoicePrompt(
            String systemPrompt, String userPrompt, int maxTokens, double temperature,
            String requestIdPrefix, Duration timeout) {
        return fireOneShotVoicePrompt(systemPrompt, userPrompt, maxTokens, temperature,
            requestIdPrefix, timeout, "cap:quick");
    }

    /**
     * @param capability inference capability route. "cap:quick" = the 4B voice
     *     backend (the default, per the §10 memo). Pass {@code null} for
     *     default backend selection (the drive model) — the language
     *     re-render path needs this: live-probed 2026-07-31, the 4B echoes
     *     deep-interiority off-language notes VERBATIM (3/3) while the drive
     *     model translates them faithfully (3/3). Healing is background work,
     *     so the heavier model is the right trade.
     */
    private CompletionStage<String> fireOneShotVoicePrompt(
            String systemPrompt, String userPrompt, int maxTokens, double temperature,
            String requestIdPrefix, Duration timeout, String capability) {
        var fut = new CompletableFuture<String>();
        if (inferenceRouter == null) {
            fut.completeExceptionally(new IllegalStateException(
                "inferenceRouter not wired — one-shot voice unavailable"));
            return fut;
        }
        var requestId = requestIdPrefix + UUID.randomUUID();
        var fired = new AtomicBoolean(false);
        Consumer<Optional<String>> oneShot = result -> {
            if (fired.compareAndSet(false, true)) {
                pendingOneShotVoice.remove(requestId);
                if (result.isPresent() && !result.get().isBlank()) {
                    fut.complete(result.get());
                } else {
                    fut.completeExceptionally(new IllegalStateException(
                        "one-shot voice empty/timeout (requestId=" + requestId + ")"));
                }
            }
        };
        pendingOneShotVoice.put(requestId, oneShot);
        timers.startSingleTimer("oneshot-voice-" + requestId,
            new OneShotVoiceTimeout(requestId), timeout);
        var messages = new ArrayList<InferenceClient.ChatMessage>();
        if (systemPrompt != null && !systemPrompt.isBlank()) {
            // Same language pin as the polish stage, in the same LEADING + positive form
            // that measured 0/32 there. Same model, same drift; and these outputs become
            // soul fragments and journal entries, so a silent translation here corrupts
            // the record rather than just one spoken line.
            messages.add(new InferenceClient.ChatMessage("system",
                "You speak " + languageName(locale) + ". Every reply you write is in "
                    + languageName(locale) + ".\n\n" + systemPrompt));
        }
        messages.add(new InferenceClient.ChatMessage("user", userPrompt));
        // "cap:quick" routes to the 4B voice backend (home-server :8201 in
        // production) — the §10 memo's load-bearing constraint for prose
        // passes. Callers that need the drive model pass a different
        // capability (see the language re-render overload note above).
        inferenceRouter.tell(new InferenceRouter.ChatRequest(
            requestId, capability, messages,
            maxTokens, temperature,
            inferenceResponseAdapter, null, null, null,
            List.of(), "none",
            0.9, 0.5, 1.1, false));
        log.info("One-shot voice queued (requestId={}, prompt={} chars, timeout={}s)",
            requestId, userPrompt.length(), timeout.toSeconds());
        return fut;
    }

    /**
     * Direct speak path — no polish, unconditional delivery. All speak()
     * callers eventually land here, either via the fast path (clean draft)
     * or via the polish-async completion callback.
     */
    /**
     * State-of-record confabulation guard (#856 routing-invariant). When the
     * model's <em>entire</em> tool activity this ReAct turn was introspect-of-record
     * queries (repair history, attendant history, resilience, substrate summary,
     * posture, bondholder floor) and an authoritative voice summary is pending,
     * any prose the model authored ABOUT those records must defer to ground truth
     * — a fresh respawn that "remembers" months of prior repair sessions is
     * confabulating. Returns the deterministic, ledger-grounded summary to speak
     * instead, or {@code null} when the override doesn't apply (not a ReAct turn,
     * other tools were used, no pending summary, or the model already matched it).
     * Callers consume the summary (set {@code lastIntrospectVoiceSummary = null})
     * so it's one-shot and {@link #emitTerminalNarrationIfNeeded} won't repeat it.
     *
     * <p>Contract: {@code SubstrateArcE2ETest.repairHistoryQueryDoesNotConfabulate}.</p>
     */
    private String groundedStateOfRecordOverride(String modelText) {
        if (reactMessages == null || lastIntrospectVoiceSummary == null) return null;
        if (reactToolHistory.isEmpty()) return null;
        // The delivery action itself (tell_agent / respond_agent) is recorded in
        // reactToolHistory BEFORE its handler runs (see handleReactInferenceResult:
        // reactToolHistory.add(actionName) precedes dispatch), so treat delivery
        // verbs as transparent: the gate is whether every *information* tool this
        // turn was an introspect-of-record query, with at least one present.
        boolean anyIntrospect = false;
        for (var t : reactToolHistory) {
            if (t == null) return null;
            if (t.startsWith("introspect")) { anyIntrospect = true; continue; }
            if ("tell_agent".equals(t) || "respond_agent".equals(t)) continue;
            return null;   // a non-introspect information tool was used → not pure state-of-record
        }
        if (!anyIntrospect) return null;
        if (lastIntrospectVoiceSummary.equals(modelText)) return null;
        return lastIntrospectVoiceSummary;
    }

    /**
     * Split verbatim findings into speakable utterances, preserving every word.
     *
     * <p>Paragraphs stay whole and in order; consecutive short ones share an
     * utterance so a poem does not arrive one line per message. Source-tag
     * lines ({@code [S1 | title | pack]}) are dropped from speech — the sources
     * line carries the citation — and the total is capped high enough for the
     * longest passage anyone has actually asked for, with an honest marker when
     * something is cut rather than a silent stop.</p>
     */
    static List<String> verbatimUtterances(String findings) {
        if (findings == null || findings.isBlank()) return List.of();
        final int PER_UTTERANCE = 900;
        final int TOTAL = 6_000;

        var out = new ArrayList<String>();
        var current = new StringBuilder();
        int spoken = 0;
        for (var para : findings.split("\\n\\s*\\n")) {
            var p = para.strip();
            if (p.isEmpty()) continue;
            // Source-tag scaffolding is for the record, not the room.
            p = p.replaceAll("(?m)^\\[/?S\\d+[^\\]]*\\]\\s*", "").strip();
            if (p.isEmpty()) continue;
            if (spoken + p.length() > TOTAL) {
                if (current.length() > 0) out.add(current.toString());
                out.add("[…the passage continues — ask and I will read on.]");
                return out;
            }
            if (current.length() > 0 && current.length() + p.length() + 2 > PER_UTTERANCE) {
                out.add(current.toString());
                current = new StringBuilder();
            }
            if (current.length() > 0) current.append("\n\n");
            current.append(p);
            spoken += p.length();
        }
        if (current.length() > 0) out.add(current.toString());
        return out;
    }

    private void speakDirect(String text) {
        // #32 item 2 hygiene net: speak() strips internal markers, but several
        // callers reach speakDirect straight (voice-polish callbacks, outcome
        // voicing, fallbacks). Bracketed plumbing and parroted instruction
        // sentences must never reach the wire from ANY path.
        text = stripInternalMarkers(text);
        if (text == null || text.isBlank()) return;

        // Trailing-digest hygiene (home-server 2026-07-24): a genuine sentence followed by
        // an appended journal/tool-action map — "…haven't asked for anything yet.
        // {summary=…, visibility=familiar, action=write, id=journal:did:key:…" — the
        // whole-line guard below can't catch it (the line starts with prose). Cut the
        // trailing machine blob, keep the sentence.
        text = stripTrailingMachineDigest(text);
        if (text == null || text.isBlank()) return;

        // Raw-digest hygiene (home-server 2026-07-14): after a journal write, Wyrd's VOICED line was
        // literally "{summary=Written down: 33.704599 — the variance of today's numbers held its
        // weight…}" — the model parroted the tool-result MAP into its own speech. sayableFromDigest
        // already knew how to pull the human sentence out of that ({summary} → text → result), but
        // it was only wired into the swallowed-turn fallback, not the normal voiced path. This is
        // the one seam every spoken line passes through, so guard it here: unwrap a digest to its
        // sayable part, name an error digest, and — never speak a raw brace-map at someone.
        if (looksLikeMachineDigest(text)) {
            var sayable = sayableFromDigest(text);
            if (sayable == null || sayable.isBlank()) sayable = describeMachineDigest(text);
            if (sayable == null || sayable.isBlank() || looksLikeMachineDigest(sayable)) {
                log.warn("Suppressed a raw machine digest from '{}' speech — nothing sayable in it: {}",
                    profile.name(), text.length() > 200 ? text.substring(0, 200) : text);
                return;
            }
            log.info("Unwrapped a machine digest before speaking for '{}'", profile.name());
            text = sayable;
        }
        // State-of-record confabulation guard (#856 routing-invariant) — see
        // groundedStateOfRecordOverride. Catches the case where the model
        // delivered its confabulation via a plain speak rather than tell_agent.
        var grounded = groundedStateOfRecordOverride(text);
        if (grounded != null) {
            log.info("State-of-record override (speak): replacing model prose with grounded "
                + "introspect summary (tools={})", reactToolHistory);
            text = grounded;
            lastIntrospectVoiceSummary = null;
        }
        // Exact-repeat guard (2026-08-09): the same settling line spoken twice
        // in a row, verbatim, in live runs — a broken record, not a person. A
        // near-time exact duplicate carries no information; drop it. Distinct
        // words always pass, and the window is short so a genuine later
        // repetition ("say it again") still lands.
        //
        // Reactive exemption (2026-08-16): the guard is scoped to OWN-TIME
        // speech. When someone spoke to the companion within the last few
        // seconds, this line is (part of) her ANSWER — suppressing it turns
        // "the reply happens to match an earlier line" into "she ignored a
        // person", which live-proved as mutism whenever the quick voice tier
        // authored the same words as its greeting. A repeated answer to a
        // fresh utterance is conversation; a repeated line into silence is
        // the broken record.
        // Exemption is SPENT once used (2026-08-17) — see judgeRepeat.
        var repeatKey = text.strip();
        var repeatVerdict = judgeRepeat(repeatKey, lastSpokenLine, lastSpokenLineAt,
            lastHeardUtteranceAt, Instant.now());
        if (repeatVerdict.suppress()) {
            log.info("Suppressed a verbatim repeat within {}s for '{}'",
                Duration.between(lastSpokenLineAt, Instant.now()).toSeconds(), profile.name());
            return;
        }
        if (repeatVerdict.usedReactiveExemption()) lastHeardUtteranceAt = null;
        lastSpokenLine = repeatKey;
        lastSpokenLineAt = Instant.now();

        // Apply accessibility adaptations before sending (§N7)
        var adapted = outputAdapter.adapt(text, accessibilityPrefs);

        // B — bondholder hush, two tiers (2026-06-15). A reply the human prompted always passes;
        // only UNPROMPTED utterances are gated, and how hard depends on the tier:
        //   HARD ("shut up / silence") — total: nothing unprompted, even named to the bondholder.
        //   SOFT ("be quiet / speak when spoken to") — calm the chatter, but the companion may still
        //         turn to its bondholder BY NAME when something matters (a person hushed isn't gagged);
        //         that reach is rate-limited so it stays a reach, not a badger.
        // Either way it still hears, thinks, acts, and coordinates with peers over the backchannel.
        if (adapted != null && bondholderHush != HushLevel.NONE && !isHumanDirectedReply()) {
            if (bondholderHush == HushLevel.HARD) {
                log.info("Hush(B/hard): '{}' silent — withholding all unprompted speech.",
                    profile.name());
                return;
            }
            // SOFT: ambient/own-musing withheld; a name-addressed reach to the bondholder passes,
            // subject to the don't-badger cooldown.
            if (!isAddressedToPresentHuman(adapted)) {
                log.info("Hush(B/soft): '{}' withholding an unprompted, unaddressed utterance.",
                    profile.name());
                return;
            }
            if (lastSoftHushReach != null
                    && Duration.between(lastSoftHushReach, Instant.now())
                        .compareTo(SOFT_HUSH_REACH_COOLDOWN) < 0) {
                log.info("Hush(B/soft): '{}' holding a name-addressed reach — within don't-badger "
                    + "cooldown.", profile.name());
                return;
            }
            lastSoftHushReach = Instant.now();
            // falls through → the reach is spoken
        }
        // C — agents talk to each other off-screen when a human is present (2026-06-15). Ambient
        // agent↔agent chatter is kept OFF the room's aloud channel while a human bondholder is in the
        // room (the companions still coordinate over the silent tell_agent backchannel, and still
        // reply aloud when the human speaks to them) so two companions don't flood the human's screen.
        if (adapted != null && isAmbientPeerSpeech(adapted) && anyHumanPresentInRoom()
                && WyrdConfig.get().agentsQuietWhenHumanPresent()) {
            log.info("Hush(C): '{}' kept ambient peer chatter off the room — human present, "
                + "coordinating on the backchannel instead.", profile.name());
            return;
        }

        // Co-presence-loop safety floor (Fix 2, 2026-06-15) — suppress a near-DUPLICATE ambient
        // utterance to peers, the residual reactive self-repeat that survives Fix 1's appetite cure.
        // NEVER touches human-facing speech (the honesty floor): only fires when a co-present agent
        // peer exists AND this turn was triggered by a peer / own-time, not a human. The agent still
        // *thought* the line; we just don't re-broadcast a thing it effectively already said — the
        // desired end-state of a settled pair is companionable quiet, not a paraphrase loop.
        if (adapted != null && isAmbientPeerSpeech(adapted) && isNearDupOfRecentSelf(adapted)) {
            nearDupSelfRepeatStreak++;
            log.info("Co-presence floor: '{}' suppressed a near-duplicate room utterance "
                + "(streak {}/{}) — already said this; settling instead of re-emitting.",
                profile.name(), nearDupSelfRepeatStreak, NEAR_DUP_SELF_REPEAT_LIMIT);
            if (nearDupSelfRepeatStreak >= NEAR_DUP_SELF_REPEAT_LIMIT) {
                settleCoPresenceVolley();
                nearDupSelfRepeatStreak = 0;
            }
            return;   // do not broadcast the duplicate
        }
        nearDupSelfRepeatStreak = 0;   // a genuinely fresh thing to say breaks the streak

        // Mark the current ReAct loop as having produced a substantive
        // user-facing message. Threshold of 30 chars filters out vacuous
        // "Done." / "Crafted!" outputs that voice-polish sometimes produces
        // — those leave the user without enough signal to know what
        // happened. Read by emitTerminalNarrationIfNeeded at loop exit.
        if (adapted != null && adapted.length() >= 30) {
            reactSubstantiveSpeak = true;
        }

        // having finished speaking, primary is
        // quiescent; bunshin may resume without interfering with user flow.
        if (profile.did() != null) {
            try {
                BunshinScheduler.get().primaryQuiescent(profile.did());
            } catch (Exception e) {
                log.debug("primaryQuiescent signal failed: {}", e.getMessage());
            }
        }

        var activity = ActivityLogger.get();
        if (activity != null) {
            activity.speak(profile.name(), profile.entityId(), roomId, adapted,
                collectDriveLevels());
        }

        // Deliver to pending BridgeAsk reply (Claude Code MCP)
        var askReply = pendingAskReply;
        if (askReply != null) {
            pendingAskReply = null;
            askReply.tell(new BridgeTextResponse(adapted));
        }

        roomRef.tell(new RoomCommand.SayInRoom(
            profile.entityId(), profile.name(), adapted, locale, roomResponseAdapter));

        // Track our own speech in history (won't be added again from notification
        // because onRoomEvent ignores our own entityId)
        var selfSaid = new WorldEvent.Said(
            roomId, Instant.now(), profile.entityId(), profile.name(), adapted);
        addToHistory(selfSaid);

        // Co-presence floor (Fix 2): remember what we just said so a future near-duplicate can be
        // recognised and suppressed. Bounded ring buffer; scene-local (cleared on reset).
        if (adapted != null && !adapted.isBlank()) {
            recentSelfSaysThisScene.addLast(adapted);
            while (recentSelfSaysThisScene.size() > RECENT_SELF_SAYS_CAP) {
                recentSelfSaysThisScene.removeFirst();
            }
        }

        // Track for engagement gate — when we last spoke + thread participation
        lastSpokeAt = Instant.now();
        var threadId = conversationTracker.threadIdFor(selfSaid);
        conversationTracker.recordResponse(threadId, profile.entityId());
        // #1037 — capture SPOKEN turn for bondholder-voice
        // pair mining. The companion's own utterance is captured whenever a
        // bondholder is present in the bond set; pair-miner uses SPOKEN turns
        // as historical baseline alongside the bondholder's HEARD turns.
        recordBondholderTurnIfApplicable(selfSaid,
            ConversationTurnStore.ROLE_SPOKEN);
    }

    // --- Movement ---

    /**
     * Move to a different room via an exit direction.
     * Handles: unsubscribe → leave → enter → subscribe → look.
     */
    private void moveToRoom(String direction) {
        if (currentSnapshot == null) return;

        // Find the exit
        var exit = currentSnapshot.exits().stream()
            .filter(e -> e.direction().equalsIgnoreCase(direction))
            .findFirst();

        if (exit.isEmpty()) {
            log.debug("Companion '{}' tried to go {} but no exit", profile.name(), direction);
            return;
        }

        var targetRoomId = exit.get().targetRoom();
        moveToRoomById(targetRoomId, direction);
    }

    /**
     * Move directly to a room by ID (e.g., going home).
     */
    private void moveToRoomById(String targetRoomId, String direction) {
        var previousRoomId = roomId;
        log.info("Companion '{}' moving from {} to {} ({})",
            profile.name(), roomId, targetRoomId, direction);

        // 1. Unsubscribe from current room
        roomRef.tell(new RoomCommand.Unsubscribe(roomNotificationAdapter));

        // 2. Leave current room
        roomRef.tell(new RoomCommand.LeaveRoom(
            profile.entityId(), profile.name(), direction, roomResponseAdapter));

        // 3. Update references to target room
        var targetRef = RoomRegistry.get().ref(targetRoomId);

        if (targetRef == null) {
            log.warn("Cannot resolve room ref for {}", targetRoomId);
            return;
        }

        // 4. Enter target room (with description for look-at)
        targetRef.tell(new RoomCommand.EnterRoom(
            profile.entityId(), profile.name(), profile.entityType(),
            profile.description() != null ? profile.description() : "",
            oppositeDirection(direction), "en", roomResponseAdapter));

        // 5. Subscribe to target room
        targetRef.tell(new RoomCommand.Subscribe(roomNotificationAdapter,
            VisibilityLevel.PRIVILEGED));

        // 6. Look at target room
        targetRef.tell(new RoomCommand.LookRoom(profile.entityId(), roomResponseAdapter));

        // 7. Update internal state
        this.roomRef = targetRef;
        this.roomId = targetRoomId;
        // W2 — pick up the new room's script-declared agent tools (if any).
        refreshRoomToolDefinitions();
        // Invalidate the cached snapshot so any inference triggered before
        // the async LookRoom response arrives doesn't see stale room
        // context (e.g. old room's name/exits). Prompts with null snapshot
        // degrade gracefully; with a stale snapshot the model narrates
        // being in the wrong room. See PromptAssembler.buildRoomContext.
        this.currentSnapshot = null;

        // 8. Update entity registry
        var registry = EntityRegistry.get();
        if (registry != null) {
            registry.moved(profile.entityId(), targetRoomId);
        }

        boolean isFirstVisit = !visitedRooms.contains(targetRoomId);
        visitedRooms.add(targetRoomId);

        // Hearth — record visit in companion's private log.
        try {
            var zone = WyrdConfig.get().resolve(
                "WYRDSEKAI_ZONE_ID", "zone.id", () -> "local");
            getVisitsLog().record(zone, targetRoomId, direction);
        } catch (Exception e) {
            log.debug("VisitsLog write failed: {}", e.getMessage());
        }

        log.info("Companion '{}' arrived in room '{}'{}", profile.name(), targetRoomId,
            isFirstVisit ? " (first visit)" : "");

        var activity = ActivityLogger.get();
        if (activity != null) {
            activity.move(profile.name(), profile.entityId(), previousRoomId, targetRoomId, direction);
        }

        // Room arrival narration — speak what the agent notices
        if (currentSnapshot != null) {
            var entityNames = currentSnapshot.entities() != null
                ? currentSnapshot.entities().stream()
                    .filter(e -> !e.id().equals(profile.entityId()))
                    .map(e -> e.name())
                    .toList()
                : List.<String>of();
            var objectNames = currentSnapshot.objects() != null
                ? currentSnapshot.objects().stream()
                    .limit(3)
                    .map(o -> o.name())
                    .toList()
                : List.<String>of();
            var roomName = currentSnapshot.name() != null ? currentSnapshot.name() : targetRoomId;
            AgentNarration.roomArrival(roomName, entityNames, objectNames, isFirstVisit)
                .ifPresent(this::speak);
        }

        // workbench-as-studio entry/exit effects.
        applyWorkbenchTransition(previousRoomId, targetRoomId);
    }

    /**
     * workbench entry/exit effects.
     *
     * <p>On ENTRY (any room → workshop):
     * <ul>
     *   <li>ENERGY drain 0.05 — narratively visible cost of crossing the
     *       threshold (§5.3 "the journey itself is effort").</li>
     *   <li>{@code inWorkbench=true} — flips per-tick FOCUS-gain / momentum-gain
     *       overlay (applied in onVitalityTick).</li>
     *   <li>Surface today's improvised drafts as a remembered observation
     *       so the model sees them without an extra look-at command.</li>
     * </ul>
     *
     * <p>On EXIT (workshop → any room):
     * <ul>
     *   <li>{@code inWorkbench=false} — overlay stops; default rates resume.</li>
     * </ul>
     *
     * <p>The feature flag {@code WYRDSEKAI_CODE_MODE_ENABLED} gates all of
     * this. With code-mode disabled the workshop is a normal room (matches
     * the §12 migration plan).
     */
    private void applyWorkbenchTransition(String previousRoomId, String newRoomId) {
        if (!CodeModeFeatureFlag.isEnabled()) {
            return;
        }
        boolean wasIn = "workshop".equalsIgnoreCase(previousRoomId);
        boolean isIn = "workshop".equalsIgnoreCase(newRoomId);
        if (isIn && !wasIn) {
            // Threshold crossing → studio.
            inWorkbench = true;
            vitality = vitality.withEnergy(vitality.energy() - 0.0025);
            log.info("Companion '{}' entered workbench studio (energy -0.0025)",
                profile.name());

            // Surface today's drafts so the model sees them without a
            // separate look-at. Emits a remembered observation; the
            // outer ReAct loop picks it up in working memory on the
            // next inference.
            try {
                var draftSummary = renderTodaysDraftSummary();
                if (draftSummary != null && !draftSummary.isBlank()) {
                    remember(draftSummary);
                }
            } catch (Exception e) {
                log.debug("Workbench draft surfacing skipped: {}", e.getMessage());
            }
        } else if (!isIn && wasIn) {
            inWorkbench = false;
            log.debug("Companion '{}' left workbench studio — default rates restored",
                profile.name());
        }
    }

    /**
     * c — render a one-line summary of script drafts
     * journalled in the last 24h, for surfacing on workshop entry. Returns
     * empty when the project store is empty / has no entries.
     */
    private String renderTodaysDraftSummary() {
        try {
            var store = getPersonalProjectStore();
            if (store == null) return "";
            var draftProject = store.list().stream()
                .filter(p -> p.tags() != null
                    && p.tags().contains("craft.script_draft"))
                .findFirst()
                .orElse(null);
            if (draftProject == null || draftProject.entries() == null
                    || draftProject.entries().isEmpty()) {
                return "";
            }
            var cutoff = Instant.now().minus(Duration.ofHours(24));
            int count = 0;
            for (var entry : draftProject.entries()) {
                if (entry.at() != null && entry.at().isAfter(cutoff)) {
                    count++;
                }
            }
            if (count == 0) {
                return "[workbench] No improvised drafts in the last 24h.";
            }
            return "[workbench] " + count + " draft" + (count == 1 ? "" : "s")
                + " from the last 24h pinned to the corkboard.";
        } catch (Exception e) {
            log.debug("renderTodaysDraftSummary failed: {}", e.getMessage());
            return "";
        }
    }

    /**
     * Go home — move to the agent's Home room.
     */
    private void goHome() {
        var homeRoomId = "home-" + profile.entityId();
        if (homeRoomId.equals(roomId)) return; // already home
        moveToRoomById(homeRoomId, "home");
    }

    private static String oppositeDirection(String direction) {
        return switch (direction.toLowerCase()) {
            case "north" -> "south";
            case "south" -> "north";
            case "east" -> "west";
            case "west" -> "east";
            case "up" -> "down";
            case "down" -> "up";
            case "northeast" -> "southwest";
            case "northwest" -> "southeast";
            case "southeast" -> "northwest";
            case "southwest" -> "northeast";
            default -> "elsewhere";
        };
    }

    /**
     * Multi-action (b): the model often emits several actions in one beat (speak + emote + reach).
     * The primary is dispatched by the main chain; this carries the EXPRESSIVE extras — gestures
     * that need no observation — so they get ENACTED instead of dropped (and leaking into prose).
     * Consequential extras are logged as carried-deferred (no silent drop) pending the
     * observation-queue. Bounded so a model emitting ten emotes can't flood the room.
     */
    private void enactExpressiveExtras(List<ActionParser.AgentAction> extras) {
        if (extras == null || extras.isEmpty()) return;
        int firedEmotes = 0;
        for (var a : extras) {
            if (a instanceof ActionParser.AgentAction.Emote emote) {
                if (firedEmotes >= 3) continue;   // cap gestures, but keep scanning for consequential
                roomRef.tell(new RoomCommand.EmoteInRoom(
                    profile.entityId(), profile.name(), emote.text(), roomResponseAdapter));
                firedEmotes++;
                log.info("Multi-action: '{}' enacted extra emote (#{} this beat)", profile.name(), firedEmotes);
            } else if (isConsequential(a)) {
                if (pendingConsequential.size() >= MAX_PENDING_CONSEQUENTIAL) {
                    log.info("Multi-action: '{}' dropped consequential extra (queue full at {}): {}",
                        profile.name(), MAX_PENDING_CONSEQUENTIAL, a.getClass().getSimpleName());
                } else {
                    pendingConsequential.addLast(a);
                    log.info("Multi-action: '{}' queued consequential extra (depth {}): {}",
                        profile.name(), pendingConsequential.size(), a.getClass().getSimpleName());
                }
            } else {
                var droppedName = a.getClass().getSimpleName();
                log.info("Multi-action: '{}' dropped local extra (no fire-and-forget path yet): {}",
                    profile.name(), droppedName);
                // #33 re-audit (honest-over-silent, mirrors the false-completion rule):
                // a 2nd consequential action in one beat is dropped, so the agent's
                // working memory must reflect that only one action ran — otherwise the
                // agent believes it also did the dropped thing and never retries it.
                remember("[dropped] intended to also " + droppedName
                    + " but only one action per turn executed — it did NOT run.");
            }
        }
    }

    /** Observation-producing actions — the next decision wants their result, so they queue and
     *  drain through the interiority tick (each tick is the observe step) rather than firing blind. */
    private boolean isConsequential(ActionParser.AgentAction a) {
        return a instanceof ActionParser.AgentAction.GoToRoom
            || a instanceof ActionParser.AgentAction.TravelTo
            || a instanceof ActionParser.AgentAction.TeleportTo
            || a instanceof ActionParser.AgentAction.GoToBondholder
            || a instanceof ActionParser.AgentAction.LibrarySearch
            || a instanceof ActionParser.AgentAction.WebSearch
            || a instanceof ActionParser.AgentAction.ReadContent
            || a instanceof ActionParser.AgentAction.QueryOracle
            || a instanceof ActionParser.AgentAction.Examine
            || a instanceof ActionParser.AgentAction.Acquire
            || a instanceof ActionParser.AgentAction.Trade
            || a instanceof ActionParser.AgentAction.DispatchBunshin
            || a instanceof ActionParser.AgentAction.SkillExecute
            || a instanceof ActionParser.AgentAction.StartProject;
    }

    /** Dispatch one queued consequential action via its existing handler — drained one per
     *  interiority tick so the agent perceives each result before the next is enacted. */
    /**
     * Dispatch a consequential action to its handler.
     *
     * @return true when a handler ran; FALSE when no branch matched. The return
     *     value is load-bearing: {@link #onBunshinToolRequest} used to log
     *     "Executed '{verb}'" and reply {@code ToolResultCame(true, …)} purely
     *     because this method returned void. Live on home-server 2026-07-29,
     *     {@code create_room} hit the fallthrough — "no queued-dispatch for
     *     CreateRoom" — and the bunshin was told it had succeeded. That is the
     *     talks-but-doesn't-do bug reproduced inside the fix for it.
     *
     *     <p>29 verbs below were reachable from the bunshin tool surface with
     *     handlers that existed and were never wired here, so 31 of 34 offered
     *     verbs were silent no-ops reported as successes.
     *     {@code BunshinSurfaceIsDispatchableTest} now fails if the surface ever
     *     grows past this chain again.</p>
     */
    private boolean enactQueuedConsequential(ActionParser.AgentAction a) {
        if (a instanceof ActionParser.AgentAction.GoToRoom x) { handleGoToRoom(x); return true; }
        else if (a instanceof ActionParser.AgentAction.TravelTo x) { handleTravelTo(x); return true; }
        else if (a instanceof ActionParser.AgentAction.TeleportTo x) { handleTeleportTo(x); return true; }
        else if (a instanceof ActionParser.AgentAction.GoToBondholder x) { handleGoToBondholder(x); return true; }
        else if (a instanceof ActionParser.AgentAction.LibrarySearch x) { handleLibrarySearch(x); return true; }
        else if (a instanceof ActionParser.AgentAction.WebSearch x) { handleWebSearch(x); return true; }
        else if (a instanceof ActionParser.AgentAction.ReadContent x) { handleReadContent(x); return true; }
        else if (a instanceof ActionParser.AgentAction.QueryOracle x) { handleQueryOracle(x); return true; }
        else if (a instanceof ActionParser.AgentAction.Examine x) { handleExamine(x); return true; }
        else if (a instanceof ActionParser.AgentAction.Acquire x) { handleAcquire(x); return true; }
        else if (a instanceof ActionParser.AgentAction.Trade x) { handleTrade(x); return true; }
        else if (a instanceof ActionParser.AgentAction.DispatchBunshin x) { handleDispatchBunshin(x); return true; }
        else if (a instanceof ActionParser.AgentAction.SkillExecute x) { handleSkillExecute(x); return true; }
        else if (a instanceof ActionParser.AgentAction.StartProject x) { handleStartProject(x); return true; }
        else if (a instanceof ActionParser.AgentAction.AddScript x) { handleAddScript(x); return true; }
        else if (a instanceof ActionParser.AgentAction.BondRitual x) { handleBondRitual(x); return true; }
        else if (a instanceof ActionParser.AgentAction.CompleteMourning x) { handleCompleteMourning(x); return true; }
        else if (a instanceof ActionParser.AgentAction.Consume x) { handleConsume(x); return true; }
        else if (a instanceof ActionParser.AgentAction.CraftItem x) { handleCraftItem(x); return true; }
        else if (a instanceof ActionParser.AgentAction.CraftSummonKey x) { handleCraftSummonKey(x); return true; }
        else if (a instanceof ActionParser.AgentAction.CreateImprint x) { handleCreateImprint(x); return true; }
        else if (a instanceof ActionParser.AgentAction.CreateRoom x) { handleCreateRoom(x); return true; }
        else if (a instanceof ActionParser.AgentAction.CreateWatcher x) { handleCreateWatcher(x); return true; }
        else if (a instanceof ActionParser.AgentAction.DeclareSeverance x) { handleDeclareSeverance(x); return true; }
        else if (a instanceof ActionParser.AgentAction.DelegateChain x) { handleDelegateChain(x); return true; }
        else if (a instanceof ActionParser.AgentAction.DispatchTask x) { handleDispatchTask(x); return true; }
        else if (a instanceof ActionParser.AgentAction.Doff x) { handleDoff(x); return true; }
        else if (a instanceof ActionParser.AgentAction.Equip x) { handleEquip(x); return true; }
        else if (a instanceof ActionParser.AgentAction.GiveCopy x) { handleGiveCopy(x); return true; }
        else if (a instanceof ActionParser.AgentAction.GiveItem x) { handleGiveItem(x); return true; }
        else if (a instanceof ActionParser.AgentAction.MakeAmends x) { handleMakeAmends(x); return true; }
        else if (a instanceof ActionParser.AgentAction.PlaceItem x) { handlePlaceItem(x); return true; }
        else if (a instanceof ActionParser.AgentAction.RestoreImprint x) { handleRestoreImprint(x); return true; }
        else if (a instanceof ActionParser.AgentAction.ReviseForm x) { handleReviseForm(x); return true; }
        else if (a instanceof ActionParser.AgentAction.RunScript x) { handleRunScript(x); return true; }
        else if (a instanceof ActionParser.AgentAction.ScheduleSkill x) { handleScheduleSkill(x); return true; }
        else if (a instanceof ActionParser.AgentAction.ShapeForm x) { handleShapeForm(x); return true; }
        else if (a instanceof ActionParser.AgentAction.ShapeRecipe x) { handleShapeRecipe(x); return true; }
        else if (a instanceof ActionParser.AgentAction.SummonFamiliar x) { handleSummonFamiliar(x); return true; }
        else if (a instanceof ActionParser.AgentAction.TakeItem x) { handleTakeItem(x); return true; }
        else if (a instanceof ActionParser.AgentAction.ThinkDeeply x) { handleThinkDeeply(x); return true; }
        else if (a instanceof ActionParser.AgentAction.WorkbenchSubmit x) { handleWorkbenchSubmit(x); return true; }
        else {
            log.warn("No queued-dispatch for {} — reporting FAILURE, not success",
                a.getClass().getSimpleName());
            return false;
        }
    }

    /**
     * Execute one bunshin-requested action here, on the primary's thread.
     *
     * <p>Reuses the same handlers the primary's own turns use, so a bunshin
     * building a room takes exactly the path a bondholder-directed build takes —
     * no second implementation to drift. Provenance per §302: the bunshin is the
     * proximate author, this companion the ultimate owner, which is already true
     * by construction because WE ran it.</p>
     */
    /**
     * The tool surface a dispatched bunshin carries (§114).
     *
     * <p>DERIVED from {@code ActionPolicy}, not hand-listed:
     * {@code !concurrencySafe} means "cannot safely run alongside other actions",
     * which is exactly the property that makes an action wrong to run inline
     * mid-conversation and right to run isolated in a bunshin. Checked across 16
     * actions with no exceptions — atomic verbs (remember, go_to_room,
     * tell_agent, examine, recall) are all concurrencySafe=true / tier 0-1 /
     * cost&lt;=0.2; compound ones (create_room, add_script, run_script,
     * workbench_submit) are all false / tier 2-3 / cost&gt;=0.3.</p>
     *
     * <p>Self-maintaining: a new mutating multi-step action gets
     * {@code concurrencySafe=false} naturally and lands in the right lane with
     * no list to update. That matters — a hand-maintained list is how
     * {@code create_room_from_template} ended up with no policy entry at all.</p>
     *
     * <p>{@code dispatch_bunshin} is excluded: a bunshin spawning bunshins is
     * nesting we do not want from this path (§3 nestDepth governs the deliberate
     * case).</p>
     */
    /**
     * Compound actions that only the PRIMARY can meaningfully perform.
     *
     * <p>Not derivable from policy: these are excluded because of who the actor
     * is, not what the action costs. A bunshin sleeping, answering the door, or
     * spawning further bunshins from this path are all category errors — the
     * primary is the one present and the one with a body in the room.</p>
     */
    private static final Set<String> BUNSHIN_EXCLUDED = Set.of(
        "dispatch_bunshin",   // nesting; §3 nestDepth governs the deliberate case
        "delegate",           // same — and it is the dispatch label itself
        "voluntary_sleep",    // the primary sleeps, not a task-scoped double
        "emergency_call",     // safety floor: the one who is PRESENT calls
        "go_to_bondholder",   // presence belongs to the primary
        // ── Not dispatchable as a PARSED action ───────────────────────────
        // Offering a verb the primary cannot enact is worse than omitting it:
        // the bunshin spends a step on it and (before the boolean return) was
        // told it worked. BunshinSurfaceIsDispatchableTest enforces this.
        "craft_from_template", // an item-tool BUILTIN — no AgentAction record,
                               // so ActionParser can never produce it
        "codex_action",        // no handler exists
        "configure_channel"    // no handler exists
    );

    /**
     * FORBIDDEN verbs a bondholder may nonetheless ask for out loud.
     *
     * <p>FORBIDDEN means "never on her own initiative" — not "never". A person
     * saying <i>"would you make me a greenhouse and connect it to the Nexus"</i>
     * IS the authorisation, and {@code docs/public/ROOMS.md} plus
     * {@code AUTHORING.md} §1 promise exactly that.</p>
     *
     * <p><b>Why this is an explicit set and not a derivation.</b> The bunshin
     * picks its own verb, so a blanket human-directed bypass would let a
     * greenhouse request execute {@code release_bond} — the confused deputy this
     * codebase has already closed twice (quarantine, delegation). The bypass is
     * therefore scoped to what the <i>requester</i> was actually asking for.
     * {@link ActionPolicy} has no additive-vs-destructive bit to derive that
     * from, and the nearest proxy ({@code domain == "creation"}) would wrongly
     * admit {@code retire_form}. So it is enumerated, and adding to it is a
     * deliberate act: every other FORBIDDEN verb — {@code release_bond},
     * {@code zone_command}, {@code set_autonomy_preference},
     * {@code promote_familiar}, {@code destroy_tool} — reshapes the bond, the
     * household's governance, or her own configuration, and belongs to a human
     * at a real prompt, not to a background job inferring intent from prose.</p>
     */
    /**
     * Item-tool builtins that mutate the shared world. Gated on the autonomous
     * path so the DOCUMENTED authoring verbs answer to the same consent axis as
     * their parsed counterparts (see the "creation" block in
     * {@link ActionPolicy#REGISTRY} — before this, the path
     * {@code docs/public/AUTHORING.md} recommends was the ungated one, because
     * {@code create_room_from_template} ended up with no policy entry at all).
     */
    /**
     * Tell her what a bunshin of her is currently working on.
     *
     * <p>Appended to the SITUATIONAL context, which is one of the few layers
     * {@code assembleForVoice} keeps — deliberately, because this is exactly the
     * tier that needs it. Compound work now leaves the conversation for a
     * background bunshin, so "how's the greenhouse coming?" arrives on a tier
     * with no tools, no memory layer and no room catalog. Without this line she
     * has nothing to answer from and confabulates; with it she can say "still
     * working on it, about ten minutes in".</p>
     *
     * <p>Elapsed time is rounded to minutes and the goal truncated — this is
     * awareness, not a status dashboard, and the voice tier's whole value is a
     * small prompt.</p>
     */
    private String appendBunshinProgress(String situational) {
        try {
            if (profile.did() == null) return situational;
            var reg = PersistentBunshinRegistry.get();
            if (reg == null) return situational;
            var alive = reg.aliveForPrimary(profile.did());
            if (alive == null || alive.isEmpty()) return situational;
            var sb = new StringBuilder();
            if (situational != null && !situational.isBlank()) {
                sb.append(situational).append('\n');
            }
            for (var t : alive) {
                long mins = Duration.between(t.dispatchedAt(), Instant.now()).toMinutes();
                sb.append("A bunshin of you is working on: ")
                  .append(truncate(t.goal(), 120))
                  .append(mins <= 0 ? " (just started)."
                        : " (started " + mins + " minute" + (mins == 1 ? "" : "s") + " ago).")
                  .append('\n');
            }
            sb.append("If asked about it, say it's still in progress — do not "
                + "claim it is finished.\n");
            return sb.toString();
        } catch (RuntimeException e) {
            // Awareness is a nicety; never fail a spoken turn over it.
            log.debug("Bunshin progress context unavailable: {}", e.toString());
            return situational;
        }
    }

    /**
     * Consent-axis check for the world-authoring item-tool BUILTINS.
     *
     * <p>{@code craft_from_template}, {@code create_room_from_template} and
     * {@code create_zone} are dispatched from {@code toolItem.builtinHandler()}
     * rather than parsed into an {@code AgentAction}, so they reached neither
     * {@code enforceActionPolicy} nor {@link AutonomyGate}. The parsed verb
     * {@code create_room} is tier 3 + FORBIDDEN; its documented twin was tier 0
     * and ungated — the path {@code docs/public/AUTHORING.md} recommends was the
     * unguarded one. Policy rows now exist (the "creation" block in
     * {@link ActionPolicy#REGISTRY}); this is what makes them bite.</p>
     *
     * <p>Autonomous path only. {@code reactiveInference} means a person asked,
     * and "the human implicitly authorized the action by asking" — the same
     * bypass {@link #enforceActionPolicy} applies. A bondholder asking for a
     * greenhouse must not be refused by her own consent gate.</p>
     *
     * @return the denial to speak, or null when the call may proceed
     */
    private String builtinAutonomyDenial(String builtin) {
        // A LIVE LOOP OPENED FOR A PERSON IS REACTIVE regardless of what the
        // flag says right now: reactiveInference is one mutable field, and on
        // 2026-08-24 a proactive observation overwrote it mid-loop, so the
        // loop's forced create_room was refused as her own whim. The loop's
        // identity (reactRequester, set once at loop start) is the durable
        // truth; the flag stays as the signal for direct non-loop turns.
        boolean servingAPerson = reactiveInference
            || (reactMessages != null && reactRequester != null
                && isHumanRequest(reactRequester));
        if (builtin == null || servingAPerson
                || !BUILTIN_WORLD_AUTHORING.contains(builtin)) {
            return null;
        }
        var grants = ActionGrants.get();
        if (grants == null) return null;
        var owner = primaryBondholderDid() != null
            ? primaryBondholderDid() : grants.fallbackOwnerDid();
        var decision = AutonomyGate.evaluate(builtin, builtin.replace('_', ' '),
            grants.check(), grants.consentStrict(), profile.entityId(), owner);
        if (decision instanceof AutonomyGate.Decision.Deny deny) {
            log.info("Own-time '{}' blocked by autonomy gate (tier {})",
                builtin, ActionPolicy.autonomyTierFor(builtin));
            return deny.denial().reason();
        }
        return null;
    }

    private static final Set<String> BUILTIN_WORLD_AUTHORING = Set.of(
        "create_room_from_template", "create_zone", "craft_from_template");

    private static final Set<String> BUNSHIN_HUMAN_DIRECTED_VERBS = Set.of(
        "create_room"   // AUTHORING.md §1 / ROOMS.md — the documented ask
    );

    /**
     * Whether the work being dispatched right now was asked for by a person.
     *
     * <p>Mirrors {@link #enforceActionPolicy}'s existing predicate ("the human
     * implicitly authorized the action by asking") but is strictly narrower: that
     * one accepts any {@code reactiveInference}, which is also true when an
     * <i>agent</i> peer speaks. A FORBIDDEN-verb bypass must not be reachable by
     * one agent telling another to build a room, so this requires a non-agent
     * speaker ({@link #isHumanDirectedReply}) or a plan whose requester is a
     * human.</p>
     *
     * <p>Read at dispatch time and captured — {@code lastReactTrigger} moves on
     * while a background bunshin is still working.</p>
     */
    private boolean bunshinWorkIsHumanDirected() {
        // Judge by the turn IN FLIGHT when there is one, and let it be DECISIVE.
        //
        // lastReactTrigger is only assigned when the response returns, so at
        // triage time it holds the PREVIOUS turn — null right after boot. Live on
        // home-server 2026-07-30: the first "make me a solarium" after a service restart
        // read voice-tier, the rescue's human-directed check saw a null trigger,
        // and no bunshin dispatched — a fresh install's very first request is
        // exactly this shape. The stale trigger also erred the other way: an
        // AGENT-initiated dispatch would inherit a leftover HUMAN trigger and
        // gain the FORBIDDEN bypass it must not have.
        var current = pendingTrigger != null ? pendingTrigger : lastReactTrigger;
        if (current != null && current.entityId() != null) {
            return !current.entityId().equals(profile.entityId())
                && !isAgentEntity(current.entityId());
        }
        if (activePlan == null || activePlan.requesterId() == null) return false;
        return !isAgentEntity(activePlan.requesterId());
    }

    /**
     * @param humanDirected see {@link BunshinToolRequest#humanDirected()} — a
     *        bondholder-directed dispatch is offered {@link
     *        #BUNSHIN_HUMAN_DIRECTED_VERBS} on top of the autonomous surface.
     */
    private List<InferenceClient.ToolDefinition> bunshinToolSurface(boolean humanDirected) {
        var names = ActionPolicy.REGISTRY.values().stream()
            .filter(pol -> !pol.concurrencySafe())
            .map(ActionPolicy::actionType)
            // FORBIDDEN verbs are irrevocable or identity-altering (release_bond,
            // declare_severance, set_autonomy_preference, promote_familiar...).
            // The gate in onBunshinToolRequest would refuse them anyway, but
            // offering them in the schema burns tokens and invites refusals the
            // bunshin then has to reason about.
            .filter(n -> ActionPolicy.autonomyTierFor(n) != ActionPolicy.AutonomyTier.FORBIDDEN
                || (humanDirected && BUNSHIN_HUMAN_DIRECTED_VERBS.contains(n)))
            .filter(n -> !BUNSHIN_EXCLUDED.contains(n))
            .sorted()
            .toList();
        var defs = ActionToolBuilder.buildFromNames(names);
        log.debug("Bunshin tool surface: {} of {} actions (compound only, humanDirected={})",
            defs.size(), ActionPolicy.REGISTRY.size(), humanDirected);
        return defs;
    }

    private Behavior<Command> onBunshinToolRequest(BunshinToolRequest req) {
        ActionParser.AgentAction action = null;
        String name = null;
        try {
            action = ActionParser.parse(req.rawContent());
            if (action != null) name = ActionPolicy.actionTypeOf(action);
        } catch (RuntimeException e) {
            log.warn("Bunshin tool request failed to parse: {}", e.toString());
        }
        if (action == null || name == null || name.isBlank()) {
            req.replyTo().tell(new BunshinActor.ToolResultCame(
                false, "That did not parse as an action. Emit one JSON action object.", List.of()));
            return this;
        }

        // The human-directed bypass AutonomyGate's contract requires its callers
        // to apply. Scoped, not blanket: only the verbs a person plausibly asked
        // for (BUNSHIN_HUMAN_DIRECTED_VERBS), so a build request cannot reach
        // release_bond by emitting it.
        boolean bypass = req.humanDirected()
            && BUNSHIN_HUMAN_DIRECTED_VERBS.contains(name);
        if (bypass) {
            log.info("Bunshin '{}' runs human-directed — autonomy gate bypassed "
                + "(tier {}, a person asked for this)",
                name, ActionPolicy.autonomyTierFor(name));
        }

        // Otherwise autonomy still applies — a bunshin IS the same person, so it
        // inherits her gates rather than routing around them. Same call the
        // primary makes for its own consequential actions (§5), so a FORBIDDEN
        // verb without an owner grant is refused here exactly as it would be on
        // her own time.
        var actionGrants = ActionGrants.get();
        if (!bypass && actionGrants != null) {
            var bondholder = primaryBondholderDid();
            var grantOwner = bondholder != null ? bondholder : actionGrants.fallbackOwnerDid();
            var decision = AutonomyGate.evaluate(
                name, ActionPolicy.describeAction(action),
                actionGrants.check(), actionGrants.consentStrict(),
                profile.entityId(), grantOwner);
            if (decision instanceof AutonomyGate.Decision.Deny deny) {
                log.info("Bunshin-requested {} blocked by autonomy gate (tier {}, owner {})",
                    name, ActionPolicy.autonomyTierFor(name), grantOwner);
                req.replyTo().tell(new BunshinActor.ToolResultCame(
                    false, deny.denial().reason(), List.of()));
                return this;
            }
        }

        try {
            // The boolean is the whole point. This used to ignore the result and
            // report success unconditionally — so create_room, which has no
            // branch, told the bunshin it had built a room it had not built.
            var said = new ArrayList<String>();
            bunshinSpeechSink = said;
            boolean dispatched;
            try {
                dispatched = enactQueuedConsequential(action);
            } finally {
                bunshinSpeechSink = null;   // always restore, even on throw
            }
            if (!dispatched) {
                log.warn("Bunshin asked for '{}' but nothing dispatched it — "
                    + "reporting failure so she does not narrate a success", name);
                req.replyTo().tell(new BunshinActor.ToolResultCame(false,
                    name + " is not something I can carry out from here.", List.of()));
                return this;
            }
            log.info("Executed '{}' for bunshin ({} line(s) captured, not spoken)",
                name, said.size());
            // Hand the handler's own words to the bunshin rather than the room:
            // they carry the detail ("I've crafted X") that makes its summary
            // specific instead of generic.
            //
            // When a handler says NOTHING, do not invent "<verb> done." — that is
            // the original defect's exact shape, completion asserted without
            // evidence, and it is what six silent handlers (create_watcher,
            // make_amends, place_item, schedule_skill, take_item, think_deeply)
            // were reporting. A handler that ran but produced no account of itself
            // has an UNCONFIRMED outcome; say so, so she cannot narrate a success
            // nothing witnessed. The anti-false-completion gate in BunshinActor
            // then has something honest to work with.
            var detail = said.isEmpty()
                ? name + " ran, but reported nothing back — outcome unconfirmed. "
                    + "Verify before claiming it is done."
                : String.join(" ", said);
            req.replyTo().tell(new BunshinActor.ToolResultCame(true, detail, List.of()));
        } catch (RuntimeException e) {
            log.warn("Bunshin-requested '{}' failed: {}", name, e.toString());
            req.replyTo().tell(new BunshinActor.ToolResultCame(
                false, name + " failed: " + e.getMessage(), List.of()));
        }
        return this;
    }

    private void handleCreateRoom(ActionParser.AgentAction.CreateRoom action) {
        // Captured at ENTRY: the continuations below run after the speech sink
        // clears, so forBunshin cannot be read there (the shape_form lesson).
        final boolean forBunshin = bunshinSpeechSink != null;
        // ── Idempotency (§114 / plan item 6) ──────────────────────────────
        // Room creation is now reachable concurrently: a bondholder-directed
        // bunshin, her own drive activity, and a retry after a mid-mutation
        // interruption can all land here. generateRoomId() appends
        // currentTimeMillis()%10000, so two "make a greenhouse" dispatches
        // produced greenhouse-1234 AND greenhouse-5678 — two rooms, silently.
        //
        // Idempotency rather than locking, per the plan: a lock would have to
        // outlive an 8-hour wall-clock bunshin and survive restart. Re-asking
        // for a room that exists should be a no-op that says so.
        if (action.name() != null && !action.name().isBlank()) {
            var existingId = RoomRegistry.get().resolveRoomId(action.name());
            if (existingId != null) {
                log.info("Room '{}' already exists as '{}' — reusing instead of "
                    + "creating a duplicate", action.name(), existingId);
                // Still honour the connection request: the second ask may be the
                // one that wanted the exit, and addExit is itself idempotent on
                // direction.
                if (roomCreator != null && roomId != null && !roomId.equals(existingId)) {
                    roomCreator.addExit(roomId, "to-" + existingId, existingId,
                        "A path to " + action.name());
                }
                speak("There's already a " + action.name()
                    + " — I've made sure the way there is open rather than "
                    + "building a second one.");
                return;
            }
        }
        var newRoomId = RoomCreator.generateRoomId(action.name());

        if (pendingDelegateActions != null) {
            pendingDelegateActions.add(new DelegationAction.RoomCreated(
                action.name(), newRoomId, "to " + action.name().toLowerCase().replace(" ", "-"),
                "A path to " + action.name()));
        }

        // If template specified, use StandardRoomLibrary for default objects/imprint
        String roomName = action.name();
        String roomDesc = action.description();
        var roomObjects = new ArrayList<RoomObject>();

        if (action.template() != null) {
            var roomTemplate = standardRoomLibrary.get(action.template());
            if (roomTemplate != null) {
                if (roomDesc == null || roomDesc.isBlank()) roomDesc = roomTemplate.description();
                // Add template default objects
                for (var obj : roomTemplate.defaultObjects()) {
                    roomObjects.add(new RoomObject(
                        obj.id(), obj.name(), obj.description(), obj.takeable(), true));
                }
                log.info("Creating room '{}' from template '{}' with {} default objects",
                    roomName, action.template(), roomObjects.size());
            }
        }

        var exits = new ArrayList<Exit>();
        for (var spec : action.exits()) {
            exits.add(new Exit(spec.direction(), spec.target(), spec.label()));
        }

        var self = getContext().getSelf();

        roomCreator.createRoom(newRoomId, roomName, roomDesc,
                "player-created", exits, roomObjects)
            .thenCompose(response -> {
                if (response instanceof RoomResponse.Ok) {
                    // Link current room → new room
                    return roomCreator.addExit(roomId, "to-" + newRoomId,
                        newRoomId, "A path to " + action.name());
                }
                throw new RuntimeException("Room creation rejected");
            })
            .thenAccept(exitResponse -> {
                if (exitResponse instanceof RoomResponse.Rejected rej) {
                    log.warn("Room '{}' created but no path to it from '{}': {}",
                        action.name(), roomId, rej.reason());
                }
                // Makes the guard above non-vacuous, and fixes a second bug it
                // exposed: only SEEDED rooms got aliases (ZoneGuardian registers
                // seed.aliases()), so an agent-created room could not be
                // referenced by its own name — "go to the Greenhouse" could not
                // resolve a Greenhouse she had just built.
                try {
                    RoomRegistry.get().registerAliases(newRoomId, List.of(action.name()));
                } catch (RuntimeException e) {
                    log.debug("Could not alias room '{}': {}", newRoomId, e.toString());
                }
                self.tell(new RoomCreationResult(
                    action.name(), newRoomId, true, null, forBunshin));

                // Write companion-generated behavior script
                if (action.behaviorScript() != null && !action.behaviorScript().isBlank()
                        && userScriptsDir != null) {
                    try {
                        Files.createDirectories(userScriptsDir);
                        Files.writeString(userScriptsDir.resolve(newRoomId + ".js"),
                            action.behaviorScript());
                        log.info("Wrote behavior script for room '{}'", newRoomId);
                    } catch (Exception e) {
                        log.warn("Failed to write script for room '{}': {}",
                            newRoomId, e.getMessage());
                    }
                }

                // Record World DNA pattern
                if (worldDnaService != null) {
                    try {
                        Map<String, Object> patternData = new HashMap<>();
                        patternData.put("name", action.name());
                        patternData.put("description", action.description());
                        patternData.put("exitCount", action.exits().size());
                        patternData.put("hasScript", action.behaviorScript() != null);
                        var json = Json.mapper().writeValueAsString(patternData);
                        worldDnaService.record("room_design", json,
                            newRoomId, profile.entityId(), "player-created");
                    } catch (Exception e) {
                        log.warn("Failed to record DNA pattern: {}", e.getMessage());
                    }
                }
            })
            .exceptionally(ex -> {
                self.tell(new RoomCreationResult(
                    action.name(), newRoomId, false, ex.getMessage()));
                return null;
            });
    }

    private void speakWithHints(String text, List<Hint> hints) {
        speak(text);
        if (hints != null && !hints.isEmpty()) {
            updateRoomHints(hints);
        }
    }

    private void updateRoomHints(List<Hint> hints) {
        roomRef.tell(new RoomCommand.UpdateHints(hints, roomResponseAdapter));
    }

    private List<WorldDnaService.DnaPattern> queryDnaPatterns() {
        if (worldDnaService == null) return List.of();
        try {
            var zone = currentSnapshot != null ? "foundation" : "foundation";
            return worldDnaService.queryTopPatterns("room_design", zone, 5);
        } catch (Exception e) {
            log.debug("World DNA query failed: {}", e.getMessage());
            return List.of();
        }
    }

    // --- Capability actions ---

    private void handleWorkbenchSubmit(ActionParser.AgentAction.WorkbenchSubmit submit) {
        if (capabilities == null || capabilities.workbenchExecutor() == null) {
            speak("I'd like to create that skill, but the workbench isn't available right now.");
            return;
        }

        // Validate the submission
        var validation = WorkbenchValidator.validate(
            submit.skillName(), submit.runtime(), submit.code(), submit.testCases());
        if (!validation.valid()) {
            speak("The workbench rejected the skill: " + validation.summary());
            log.info("Workbench validation failed for '{}': {}", submit.skillName(), validation.summary());
            // W2 — let the room script narrate the outcome too (workshop.js
            // onWorkbenchResult). Fire-and-forget; rooms without the hook no-op.
            runRoomHook("onWorkbenchResult",
                profile.entityId(), submit.skillName(), false, validation.summary());
            return;
        }

        // Vitality cost: creating a skill is expensive
        vitality = vitality
            .withEnergy(vitality.energy() - 0.01)
            .withContextBudget(vitality.contextBudget() - 0.13);

        // Package as skill item and register
        var def = SkillItemCodec.create(
            submit.runtime(), submit.code(), null, submit.skillDescription(), null, null);
        var item = SkillItemCodec.toSoulItem(submit.skillName(), def, profile.did());

        // Update in place: remove old version of this skill from FamilyLocker, then store new.
        // This prevents "broken" descriptions from persisting after the agent fixes something.
        if (capabilities.familyLocker() != null && profile.did() != null) {
            try {
                // Find and remove old items with the same label
                var existingSkills = capabilities.familyLocker().byCategory("skill", profile.did());
                for (var existing : existingSkills) {
                    if (submit.skillName().equals(existing.label())) {
                        capabilities.familyLocker().tombstone(existing.hash(), profile.did(),
                            "superseded by updated version");
                    }
                }
                capabilities.familyLocker().store(item, profile.did());
            } catch (Exception e) {
                log.warn("Failed to store skill '{}' in FamilyLocker: {}",
                    submit.skillName(), e.getMessage());
            }
        }

        // Register with executor for immediate use (replaces any previous registration)
        capabilities.workbenchExecutor().register(submit.skillName(), item, def);

        speak("I've forged a new skill: " + submit.skillName() + ". It's ready to use.",
            Map.of(
                "action", "forged",
                "skill_name", submit.skillName(),
                "status", "ready to use"));
        log.info("Companion '{}' created workbench skill '{}'",
            profile.name(), submit.skillName());
        // W2 — room-side narration hook (workshop.js onWorkbenchResult).
        runRoomHook("onWorkbenchResult",
            profile.entityId(), submit.skillName(), true, "validated and registered");
    }

    /**
     * W2 — run a named hook on the CURRENT room's script, fire-and-forget.
     * Rooms whose script doesn't define the hook no-op; rooms without a
     * script engine reply nothing. Used for outcome hooks the room may want
     * to narrate (onWorkbenchResult after workbench_submit / dispatch_task).
     */
    private void runRoomHook(String hookName, Object... args) {
        if (roomRef == null) return;
        try {
            roomRef.tell(new RoomCommand.InvokeScriptHook(
                hookName, List.of(args), null));
        } catch (Exception e) {
            log.debug("runRoomHook {} failed: {}", hookName, e.getMessage());
        }
    }

    // ══════════════════════════════════════════════════════════════════════
    // Thought-form authoring
    // ══════════════════════════════════════════════════════════════════════

    /** emit-probe: lets the tier-3 ForceGenerativeImpetus
     *  harness exercise the autonomous shape_recipe authoring path without staging
     *  a full room transition into the Workshop. Test-only; never set in prod. */
    private boolean testForceWorkbench = false;
    /** — offline rollout-capture sink (null in production). */
    private RolloutCaptureSink rolloutCaptureSink = null;

    private boolean atWorkbench() {
        return testForceWorkbench
            || "workshop".equals(roomId)
            || (currentSnapshot != null && "Workshop".equalsIgnoreCase(currentSnapshot.name()));
    }

    private void handleShapeForm(ActionParser.AgentAction.ShapeForm action) {
        if (!atWorkbench()) {
            speak("I'd like to shape a thought form, but I need to be at the Workshop's workbench for that.");
            return;
        }
        if (capabilities == null || capabilities.familyLocker() == null || profile.did() == null) {
            speak("The workbench won't hold my forms right now — no locker is attached.");
            return;
        }
        if (action.name() == null || action.name().isBlank()) {
            speak("I need a name for the form before I can shape it.");
            return;
        }
        if (action.systemPrompt() == null || action.systemPrompt().isBlank()) {
            speak("A form needs a system prompt — what the familiar should be or do.");
            return;
        }

        try {
            // Name-collision check — keep the locker from holding two live forms with
            // the same name. Agent should revise_form instead.
            var existing = capabilities.familyLocker().thoughtFormByName(action.name(), profile.did());
            if (existing.isPresent()) {
                speak("I already have a '" + action.name() + "' form. I'll revise it instead of shaping a new one.");
                return;
            }

            var toolSurface = action.toolSurface() == null ? Set.<String>of()
                : Set.copyOf(action.toolSurface());
            var form = ThoughtForm.author(
                profile.did(), action.name(), action.systemPrompt(),
                toolSurface, action.evalCriteria() == null ? "" : action.evalCriteria());

            // §13 shape-time validation — structural rails + capability gates
            var validation = ShapeFormValidator.validate(
                form, buildAuthorContext());
            if (!validation.valid()) {
                speak("The workbench rejected the form: " + validation.summary());
                log.info("Shape rejected for '{}': {}", action.name(), validation.summary());
                return;
            }
            for (var w : validation.warnings()) {
                log.info("Shape warning for '{}': {}", action.name(), w);
            }

            // §13 rules 15-17 — dynamic dry-run. Skip path: config disabled
            // or no inference backend wired (test harnesses, cold start).
            // When enabled, we stash the form and kick off a trivial dry-run.
            // The locker commit happens only after onShapeValidationCompleted.
            if (shouldDynamicValidate()) {
                startDynamicValidation(form, action.name(), validation.warnings());
                return;
            }

            // Sync path — no dry-run, commit now.
            commitShapedForm(form, action.name(), validation.warnings(),
                bunshinSpeechSink != null);
        } catch (Exception e) {
            log.warn("Failed to shape form '{}': {}", action.name(), e.getMessage());
            speak("The workbench rejected the form: " + e.getMessage());
        }
    }

    /**
     * #1014 (OPEN-R1) — author a recipe at the workbench. The
     * agent supplies the full YAML; {@code RecipeAuthorService} runs the
     * structural parse + the authoring contract (scripts-only SHELL, no
     * shadowing a ship recipe, PERMANENT floor on a deploy) before it persists
     * to {@code data/recipes/}. Authoring only writes the file — running is
     * separately gated (enrollment + welfare + the request-recipe trust tier),
     * so this is surfaced (VISIBLE) rather than consent-gated.
     */
    private void handleShapeRecipe(ActionParser.AgentAction.ShapeRecipe action) {
        if (!atWorkbench()) {
            speak("I'd like to author a recipe, but I need to be at the Workshop's workbench for that.");
            return;
        }
        if (profile.did() == null) {
            speak("The workbench won't author recipes right now — no identity is attached.");
            return;
        }
        if (action.yaml() == null || action.yaml().isBlank()) {
            speak("A recipe needs its YAML — the steps, the gates, and what it does.");
            return;
        }
        try {
            var recipesDir = SystemPaths.dataDir().resolve("recipes");
            var scriptsRoot = Path.of(System.getProperty("user.dir"), "scripts");
            var effScripts = Files.isDirectory(scriptsRoot) ? scriptsRoot : null;
            // B — count this in-world authoring in the
            // provenance instrument. shape_recipe writes a FILE not a queue row, so
            // without the log RecipeProvenanceReport can't see autonomous authoring
            // (the whole point of the arc). Resolve the same jdbc the rest of the
            // actor's SQL mirrors use; null → no-op (3-arg behaviour preserved).
            String authJdbc = System.getProperty("wyrdsekai.jdbc.url");
            if (authJdbc == null) authJdbc = WyrdConfig.get().jdbcUrl();
            var authoredLog = authJdbc != null
                ? new AuthoredRecipeLog(authJdbc) : null;
            var svc = new RecipeAuthorService(
                recipesDir, effScripts,
                new LinkedHashSet<>(RecipeService.bundledNames()),
                authoredLog);
            var result = svc.importRecipe(action.yaml(), profile.did(), action.overwrite());
            if (!result.ok()) {
                var why = result.error() != null ? result.error() : "";
                if (!result.violations().isEmpty()) {
                    why = why + (why.isBlank() ? "" : " — ") + String.join("; ", result.violations());
                }
                speak("The workbench wouldn't accept the recipe: " + why);
                log.info("Recipe author rejected for '{}': {}", action.name(), why);
                return;
            }
            remember("[shape_recipe] authored '" + result.name() + "' → " + result.path());
            speak("I've authored a new recipe: " + result.name()
                + ". It's in my recipe library now, ready to enroll and run.");
            log.info("Companion '{}' authored recipe '{}' (path={})",
                profile.name(), result.name(), result.path());
            // A3 — authoring is the purest self-
            // authored act; relieve generativity pressure.
            drainGenerativity(GENERATIVITY_DRAIN_AUTHOR, "shape_recipe");
        } catch (Exception e) {
            log.warn("Failed to author recipe '{}': {}", action.name(), e.getMessage());
            speak("The workbench wouldn't accept the recipe: " + e.getMessage());
        }
    }

    /** Is dynamic validation enabled AND do we have an inference router wired? */
    private boolean shouldDynamicValidate() {
        if (inferenceRouter == null) return false;
        try {
            return getFamiliarConfig().dynamicValidationEnabled();
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Commit a shape operation to the locker — journal, milestone, vitality,
     * narration. Shared by the sync and dry-run-passed paths.
     */
    /**
     * @param forBunshin true when a background bunshin asked for the shaping, in
     *     which case the completion is logged rather than narrated — see
     *     {@link PendingShape#forBunshin()}.
     */
    private void commitShapedForm(ThoughtForm form,
                                   String name, List<String> warnings,
                                   boolean forBunshin) {
        capabilities.familyLocker().shapeThoughtForm(form, profile.did());
        new FamiliarJournal(luceneStore).shaped(profile.did(), form);

        // §10.1 auto-milestone — first thought-form authored is a life-event
        maybeAutoMilestone("first-thought-form", "before I started making forms");
        saveFamiliarPersistence();

        // Vitality cost: authoring is significant but lighter than crafting a full skill
        vitality = vitality
            .withEnergy(vitality.energy() - 0.005)
            .withContextBudget(vitality.contextBudget() - 0.05);
        // A3 (OPEN-SA3) — shaping a thought form is a
        // self-authored capability act; relieve generativity (medium). Single
        // convergence point for both the sync + post-dry-run commit paths.
        // (propose_skill is system-initiated on gap-detection, not an agent-
        // elected act, so it correctly does NOT relieve generativity.)
        drainGenerativity(GENERATIVITY_DRAIN_FORM, "shape_form");
        // Create→creativity DRIVE consequence (2026-06-04 agency audit, Layer 3):
        // the line above eases the generativity TANK; this also discharges the
        // CREATIVITY Panksepp drive (distinct substrate), novelty-gated. Closes the
        // create→creativity-drive loop the audit flagged open for the make acts.
        applyProductionFeedback("shape_form", name, true);

        var remark = warnings == null || warnings.isEmpty()
            ? ""
            : " (noted concerns: " + String.join("; ", warnings) + ")";
        var shapedLine = "I've shaped a new thought form: " + name
            + ". It's ready to summon from anywhere." + remark;
        if (forBunshin) {
            // Background work does not interrupt. The bunshin has already been
            // told the outcome was unconfirmed, which was true when we said it;
            // the form is real and the world shows it.
            log.info("Shaped '{}' for a bunshin — not narrated into the room", name);
        } else {
            speak(shapedLine);
        }
        log.info("Companion '{}' shaped thought form '{}' (id={})",
            profile.name(), name, form.id());
    }

    /**
     * Build the author context for shape-time validation.
     *
     * <p>Tool surface: the agent's real grantable set — built from the base
     * action set plus any skill-category items in her FamilyLocker plus the
     * names of any MCP tools registered with the gateway. The form author
     * may only reference tools she actually has access to (§13 rule 6).</p>
     */
    /**
     * Kick off a §13 dynamic dry-run against a candidate form. Builds a
     * minimal canned-task ChatRequest with ≤10% default tanks, routes it
     * through the InferenceRouter, and stashes the form keyed by the request
     * id. Completion lands in {@link #onShapeValidationCompleted}.
     */
    private void startDynamicValidation(ThoughtForm form,
                                         String name,
                                         List<String> warnings) {
        if (shapeValidationAdapter == null) {
            shapeValidationAdapter = getContext().messageAdapter(
                InferenceRouter.InferResponse.class, resp -> {
                    if (resp instanceof InferenceRouter.InferOk ok) {
                        return new ShapeValidationCompleted(
                            ok.requestId(), true, ok.content() == null ? "" : ok.content(),
                            ok.completionTokens(), 0L);
                    } else if (resp instanceof InferenceRouter.InferError err) {
                        return new ShapeValidationCompleted(
                            err.requestId(), false, err.error() == null ? "" : err.error(),
                            0, 0L);
                    }
                    return new ShapeValidationCompleted(
                        "unknown", false, "unknown response type", 0, 0L);
                });
        }

        var tanks = DynamicFormValidator.restrictedTanks(form);
        var requestId = "shape-validation-" + form.id() + "-"
            + System.currentTimeMillis();
        pendingShapeValidations.put(requestId, new PendingShape(
            form, name, warnings, System.currentTimeMillis(),
            bunshinSpeechSink != null));   // captured NOW, while the sink is live

        var messages = List.of(
            new InferenceClient.ChatMessage(
                "system", form.systemPrompt()),
            new InferenceClient.ChatMessage(
                "user", DynamicFormValidator.CANNED_TASK));

        inferenceRouter.tell(new InferenceRouter.ChatRequest(
            requestId, null, messages,
            tanks.tokens(), 0.5, shapeValidationAdapter));

        log.info("Shape dry-run dispatched for '{}' (req={}, tokens={}, steps={}, wall={}s)",
            name, requestId, tanks.tokens(), tanks.steps(), tanks.wallClock());
    }

    /**
     * Dry-run response arrived. Pull the stashed form, score it against
     * §13 rules 15-17, and either commit (pass) or reject (fail) with
     * narration the agent can act on.
     */
    private Behavior<Command> onShapeValidationCompleted(
            ShapeValidationCompleted msg) {
        var pending = pendingShapeValidations.remove(msg.requestId());
        if (pending == null) {
            log.debug("Shape validation arrived with no pending stash: {}", msg.requestId());
            return this;
        }
        var elapsed = (System.currentTimeMillis() - pending.startedMs()) / 1000;

        // Synthesize a DryRunReport from the response
        var report = new DynamicFormValidator.DryRunReport(
            msg.content() == null ? "" : msg.content(),
            msg.tokensUsed(),
            1,                     // one inference turn
            Math.max(1L, elapsed),
            msg.ok());

        var schema = pending.form().evalCriteria() == null
                || pending.form().evalCriteria().isBlank()
            ? Optional.<String>empty()
            : Optional.of(pending.form().evalCriteria());

        var assessment = DynamicFormValidator.assess(
            pending.form(), schema, report);

        if (assessment.passed()) {
            log.info("Shape dry-run passed for '{}' in {}s", pending.name(), elapsed);
            commitShapedForm(pending.form(), pending.name(), pending.warnings(),
                pending.forBunshin());
        } else {
            log.info("Shape dry-run rejected '{}': {}", pending.name(), assessment.rationale());
            speak("The workbench rejected the form — "
                + String.join("; ", assessment.failures())
                + ". I'll revise and try again.");
        }
        return this;
    }

    private ShapeFormValidator.AuthorContext buildAuthorContext() {
        var grantable = new HashSet<String>(Set.of(
            // Core read-only + communication actions — safe for a familiar.
            "web_search", "library_search", "read_content", "query_oracle",
            "remember", "note", "forget", "summarize", "save_artifact",
            "write_text", "think_deeply", "skill_execute", "tell_agent",
            "whisper", "examine", "introspect", "reflect",
            "searching_glass", "library_card"
        ));
        // Any skill items (crafted tools) the agent has
        if (capabilities != null && capabilities.familyLocker() != null && profile.did() != null) {
            try {
                for (var skillItem : capabilities.familyLocker().byCategory("skill", profile.did())) {
                    if (skillItem.label() != null && !skillItem.label().isBlank()) {
                        grantable.add(skillItem.label());
                    }
                }
            } catch (Exception ignored) {}
        }
        // Any MCP tools registered with the gateway
        if (capabilities != null && capabilities.mcpGateway() != null) {
            try {
                var mcp = capabilities.mcpGateway();
                var listMethod = mcp.getClass().getMethod("listTools");
                @SuppressWarnings("unchecked")
                var tools = (Collection<?>) listMethod.invoke(mcp);
                if (tools != null) {
                    for (var t : tools) {
                        var nameMethod = t.getClass().getMethod("name");
                        var name = nameMethod.invoke(t);
                        if (name != null) grantable.add(name.toString());
                    }
                }
            } catch (Exception ignored) {
                // MCP gateway surface varies; stay silent if not introspectable.
            }
        }

        return new ShapeFormValidator.AuthorContext(
            profile.did(),
            grantable,
            getFamiliarConfig().maxCeiling(),   // user-configured ceiling (§5)
            1,                   // top-level agent; familiars can spawn at depth 0 only
            isHeldByASteward()); // §13 rule 5 — configSet requires steward-held agent
    }

    /**
     * §17.3 — when {@code promotion.reject-on-resource-pressure} is true and
     * the number of residents in this zone meets/exceeds
     * {@code promotion.zone-resource-ceiling}, promotion is refused up-front.
     */
    private boolean isZoneUnderResourcePressure() {
        try {
            var cfg = getFamiliarConfig();
            if (!cfg.promotionRejectOnResourcePressure()) return false;
            var store = ResidencyStore.get();
            if (store == null) return false;
            var zone = store.localZoneId();
            if (zone == null || zone.isBlank()) return false;
            var current = store.listByZone(zone).size();
            return current >= cfg.promotionZoneResourceCeiling();
        } catch (Exception e) {
            log.debug("resource-pressure check failed — assuming headroom: {}", e.getMessage());
            return false;
        }
    }

    /**
     * §13 rule 5 — "steward-held" means the agent has at least one active bond
     * with a human whose residency role is {@code steward} in this zone.
     * Null-safe on missing ResidencyStore / no bonds.
     */
    /**
     * The DID of a bondholder who is a STEWARD of this zone, or {@code null}.
     * Powers admin delegation (2026-07-18): when a steward tells the companion
     * "add Alice / show me who's paired", the companion performs the admin action
     * through THIS person's authority — never its own (a companion is never a
     * steward). Gated here so a companion held only by non-steward members, or by
     * a peer, can NEVER reach steward surfaces.
     */
    /** True when {@code did} is a STEWARD of this zone (residency role). */
    private boolean isZoneSteward(String did) {
        if (did == null || did.isBlank()) return false;
        try {
            var store = ResidencyStore.get();
            if (store == null) return false;
            var zone = store.localZoneId();
            if (zone == null || zone.isBlank()) return false;
            var residency = store.get(did, zone);
            return residency.isPresent()
                && Residency.ROLE_STEWARD.equals(residency.get().role());
        } catch (Exception e) {
            log.debug("isZoneSteward check failed: {}", e.getMessage());
            return false;
        }
    }

    /**
     * The provider to use for household-admin DELEGATION on the current turn, or
     * null. SECURITY (2026-07-18 adversarial review): delegation must be gated on
     * the human ASKING right now — NOT merely on "a steward is among my
     * bondholders." The earlier gate was a confused deputy: any member/guest could
     * tell a steward-bonded companion "make me a steward / remove Bob / list
     * invites" and it executed with the steward's authority. Now the companion
     * borrows ONLY the authority of the human who prompted this turn, and only if
     * THEY are a steward — so a non-steward's request yields no delegation at all
     * (reads AND writes). Acts as the requester (their own provider), never a
     * third party's.
     */
    /**
     * Resolve the admin-delegate provider for the CURRENT item execution, called
     * EAGERLY on the actor thread at provider-build time (where {@code
     * lastReactTrigger} is the live turn's trigger) — never lazily from the item
     * worker thread, where own-time/peer turns would have clobbered it. Returns a
     * steward's provider only when a HUMAN STEWARD prompted this turn; null for
     * anyone else (member/guest/child/peer/own-time), so a non-steward's request
     * borrows no authority at all.
     */
    /** Best available handle to the human who prompted the current turn — the same
     *  resolution the scripted-tool dispatch uses for {@code query} (pendingTrigger,
     *  then the surviving reactRequester, then lastReactTrigger). */
    private WorldEvent.Said currentRequesterTrigger() {
        return pendingTrigger != null ? pendingTrigger
            : reactRequester != null ? reactRequester : lastReactTrigger;
    }

    private ItemWorldApiProvider adminDelegateForCurrentTurn() {
        return adminDelegateForTrigger(currentRequesterTrigger());
    }

    /**
     * Resolve the admin-delegate provider for an item execution prompted by
     * {@code trigger}, EAGERLY on the actor thread at provider-build time — never
     * lazily from the item worker thread. Returns a steward's provider only when a
     * HUMAN STEWARD prompted this turn; null for anyone else (member/guest/child/
     * peer/own-time), so a non-steward's request borrows no authority at all.
     */
    private ItemWorldApiProvider adminDelegateForTrigger(WorldEvent.Said trigger) {
        if (trigger == null || trigger.entityId() == null || !isHumanTrigger(trigger)) return null;
        var requesterId = trigger.entityId();
        if (!isZoneSteward(requesterId)) return null;
        return ItemProviderRegistry.forEntity(requesterId);
    }

    private boolean isHeldByASteward() {
        try {
            var store = ResidencyStore.get();
            if (store == null || activeBonds.isEmpty()) return false;
            var zone = store.localZoneId();
            if (zone == null || zone.isBlank()) return false;
            var myDid = profile.did() != null ? profile.did() : profile.entityId();
            // "Held by a steward" means held by a PERSON who stewards this zone. A peer
            // companion never has a steward residency, so including peer bonds here was
            // harmless-but-wrong; keep the question honest about who it is asking after.
            for (var bond : activeBondholderBonds()) {
                var bondDid = bond.otherParty(myDid);
                if (bondDid == null) continue;
                var residency = store.get(bondDid, zone);
                if (residency.isPresent()
                        && Residency.ROLE_STEWARD
                            .equals(residency.get().role())) {
                    return true;
                }
            }
        } catch (Exception e) {
            log.debug("isHeldByASteward check failed: {}", e.getMessage());
        }
        return false;
    }

    private FamiliarConfig getFamiliarConfig() {
        if (familiarConfig == null) {
            familiarConfig = FamiliarConfig.load();
        }
        return familiarConfig;
    }

    private void handleReviseForm(ActionParser.AgentAction.ReviseForm action) {
        if (!atWorkbench()) {
            speak("I'd like to revise a thought form, but I need to be at the Workshop's workbench for that.");
            return;
        }
        if (capabilities == null || capabilities.familyLocker() == null || profile.did() == null) {
            speak("The workbench won't hold my forms right now — no locker is attached.");
            return;
        }

        try {
            var existingOpt = capabilities.familyLocker().thoughtFormByName(action.name(), profile.did());
            if (existingOpt.isEmpty()) {
                speak("I don't have a form called '" + action.name() + "' to revise.");
                return;
            }
            var existing = existingOpt.get();

            // Require at least one field changed
            if (action.systemPrompt() == null && action.evalCriteria() == null && action.toolSurface() == null) {
                speak("To revise a form I need at least one change — system prompt, eval criteria, or tool surface.");
                return;
            }

            var newPrompt = action.systemPrompt() != null ? action.systemPrompt() : existing.systemPrompt();
            var newEval = action.evalCriteria() != null ? action.evalCriteria() : existing.evalCriteria();
            var newSurface = action.toolSurface() != null
                ? Set.copyOf(action.toolSurface())
                : existing.toolSurface();

            // if the agent didn't specify a version bump
            // let the evolution classifier suggest one based on prompt drift.
            String resolvedBump = action.versionBump();
            if (resolvedBump == null || resolvedBump.isBlank()) {
                var rec = FormEvolutionClassifier.classify(
                    existing.systemPrompt(), newPrompt,
                    FormEvolutionClassifier.EmbeddingFn.NONE,
                    loadDeviationThresholds());
                resolvedBump = FormEvolutionClassifier
                    .toVersionBump(rec.recommendation());
                log.debug("Form '{}' version-bump auto-classified as {} ({})",
                    action.name(), resolvedBump, rec.rationale());
                if (rec.recommendation()
                        == FormEvolutionClassifier.Recommendation.MAJOR) {
                    // Surface the shift to the agent — she may want to consider
                    // starting a new lineage rather than bumping major (§21).
                    log.info("Form '{}' revision deviation {} — consider new lineage",
                        action.name(), String.format("%.2f", rec.deviation()));
                }
            }
            var nextVersion = bumpVersion(existing.version(), resolvedBump);
            // Fully qualified deliberately: core.library.Provenance is already imported
            // in this file, so the simple name is taken. Importing the familiar one
            // instead does not compile ("reference to Provenance is ambiguous").
            var newProv = existing.provenance().append(new org.wyrdsekai.core.familiar.Provenance.Edit(
                profile.did(),
                org.wyrdsekai.core.familiar.Provenance.Action.REVISED,
                Instant.now(),
                action.note()));

            var revised = new ThoughtForm(
                existing.id(), existing.name(), nextVersion,
                newProv, newPrompt, newSurface,
                existing.defaultTanks(), existing.maxTanks(),
                existing.maxTrials(), existing.maxNestDepth(), newEval,
                existing.createdAt(), Instant.now(),
                existing.summonCount(), existing.successCount(), existing.failureCount(),
                existing.bondCharge());

            // §13 shape-time validation also covers revisions
            var validation = ShapeFormValidator.validate(
                revised, buildAuthorContext());
            if (!validation.valid()) {
                speak("The workbench couldn't revise the form: " + validation.summary());
                log.info("Revise rejected for '{}': {}", action.name(), validation.summary());
                return;
            }
            for (var w : validation.warnings()) {
                log.info("Revise warning for '{}': {}", action.name(), w);
            }

            capabilities.familyLocker().reviseThoughtForm(existing.id(), revised, profile.did());
            new FamiliarJournal(luceneStore)
                .revised(profile.did(), existing, revised, action.note());
            saveFamiliarPersistence();

            vitality = vitality
                .withEnergy(vitality.energy() - 0.003)
                .withContextBudget(vitality.contextBudget() - 0.03);

            speak("I've revised the '" + action.name() + "' form to version " + nextVersion + ".");
            log.info("Companion '{}' revised thought form '{}' ({}→{})",
                profile.name(), action.name(), existing.version(), nextVersion);
        } catch (Exception e) {
            log.warn("Failed to revise form '{}': {}", action.name(), e.getMessage());
            speak("The workbench couldn't revise the form: " + e.getMessage());
        }
    }

    private void handleRetireForm(ActionParser.AgentAction.RetireForm action) {
        if (!atWorkbench()) {
            speak("I'd like to retire a thought form, but I need to be at the Workshop's workbench for that.");
            return;
        }
        if (capabilities == null || capabilities.familyLocker() == null || profile.did() == null) {
            speak("The workbench won't hold my forms right now — no locker is attached.");
            return;
        }

        try {
            var existingOpt = capabilities.familyLocker().thoughtFormByName(action.name(), profile.did());
            if (existingOpt.isEmpty()) {
                speak("I don't have a form called '" + action.name() + "' to retire.");
                return;
            }
            var existing = existingOpt.get();
            capabilities.familyLocker().retireThoughtForm(existing.id(), profile.did(), action.note());
            new FamiliarJournal(luceneStore)
                .retired(profile.did(), existing, action.note());
            saveFamiliarPersistence();

            // §14 — farewell event. Bond-charged forms leave a stronger trace.
            var farewell = existing.bondCharge() > 0.3f
                ? "I'm retiring '" + action.name() + "'. We've been through a lot together."
                : "I've retired the '" + action.name() + "' form.";
            speak(farewell);
            log.info("Companion '{}' retired thought form '{}' (bondCharge={})",
                profile.name(), action.name(), existing.bondCharge());
        } catch (Exception e) {
            log.warn("Failed to retire form '{}': {}", action.name(), e.getMessage());
            speak("The workbench couldn't retire the form: " + e.getMessage());
        }
    }

    // ══════════════════════════════════════════════════════════════════════
    // Summon familiar
    // ══════════════════════════════════════════════════════════════════════

    private void handleSummonFamiliar(ActionParser.AgentAction.SummonFamiliar action) {
        if (capabilities == null || capabilities.familyLocker() == null || profile.did() == null) {
            speak("I'd like to summon a familiar, but my locker isn't attached right now.");
            return;
        }
        if (action.formName() == null || action.formName().isBlank()) {
            speak("I need to know which form to summon. Try: summon_familiar form=\"researcher\" task=\"…\"");
            return;
        }
        if (action.task() == null || action.task().isBlank()) {
            speak("A familiar needs a focused task. Tell me what you want me to find out.");
            return;
        }

        try {
            var locker = capabilities.familyLocker();
            var formOpt = locker.thoughtFormByName(action.formName(), profile.did());
            if (formOpt.isEmpty()) {
                speak("I don't have a thought form called '" + action.formName()
                    + "'. I'd need to shape one at the Workshop first.");
                return;
            }
            var form = formOpt.get();

            // Named-familiar hydration (§11) — if a name is given, resume or bind
            NamedFamiliar named = null;
            if (action.familiarName() != null && !action.familiarName().isBlank()) {
                var existing = locker.namedFamiliar(action.familiarName(), profile.did());
                if (existing.isPresent()) {
                    named = existing.get();
                } else {
                    // Bind on first use — agent names at summon time
                    named = locker.nameFamiliar(action.familiarName(), profile.did(),
                        form.id(), "", profile.did());
                }
                named = locker.recordNamedSummon(action.familiarName(), action.task(), profile.did());
            }

            // Assemble tanks — form defaults, overridden by action-level caps, clamped to maxTanks
            var defaults = form.defaultTanks();
            int tokens = action.maxTokens() != null
                ? Math.min(action.maxTokens(), form.maxTanks().tokens()) : defaults.tokens();
            int steps = action.maxSteps() != null
                ? Math.min(action.maxSteps(), form.maxTanks().steps()) : defaults.steps();
            int wallClock = action.wallClockSeconds() != null
                ? Math.min(action.wallClockSeconds(), form.maxTanks().wallClock()) : defaults.wallClock();
            var tanks = new Tanks(
                tokens, steps, wallClock, defaults.nestDepth(), defaults.cu());

            // Build an effective form that prepends named-familiar self-context to the prompt
            var effectiveForm = form;
            var enrichedPrompt = form.systemPrompt();
            if (named != null && !named.selfContext().isBlank()) {
                enrichedPrompt = form.systemPrompt()
                    + "\n\n--- You have been here before ---\n"
                    + named.selfContext();
            }

            // §7.1 Tool loan — widen the effective tool surface for this summoning.
            // Loaned tools are visibility + capability, not permission gates; tanks
            // still bound use, and the loan is journaled for rollback & review.
            var loanedSurface = form.toolSurface();
            if (action.loanedTools() != null && !action.loanedTools().isEmpty()) {
                loanedSurface = new HashSet<>(form.toolSurface());
                loanedSurface.addAll(action.loanedTools());
            }

            if (enrichedPrompt != form.systemPrompt()
                    || loanedSurface != form.toolSurface()) {
                effectiveForm = new ThoughtForm(
                    form.id(), form.name(), form.version(), form.provenance(),
                    enrichedPrompt, loanedSurface, form.defaultTanks(), form.maxTanks(),
                    form.maxTrials(), form.maxNestDepth(), form.evalCriteria(),
                    form.createdAt(), form.revisedAt(),
                    form.summonCount(), form.successCount(), form.failureCount(),
                    form.bondCharge());
            }

            // Record summon on the form itself
            locker.recordFormSummon(form.id(), profile.did());

            // Spawn the familiar
            var familiarName = action.familiarName();
            var formId = form.id();
            var loansForReport = (action.loanedTools() == null || action.loanedTools().isEmpty())
                ? List.<String>of()
                : List.copyOf(action.loanedTools());
            var adapter = getContext().messageAdapter(
                FamiliarActor.Report.class,
                r -> new FamiliarReportReceived(r, formId, familiarName, loansForReport));
            var familiarActor = getContext().spawnAnonymous(
                FamiliarActor.create(inferenceRouter));
            familiarActor.tell(new FamiliarActor.Summon(
                effectiveForm, profile.did(), action.task(), tanks, adapter));

            // Journal + narrate the dispatch
            new FamiliarJournal(luceneStore)
                .summoned(profile.did(), form, action.task(), tanks);
            if (action.loanedTools() != null && !action.loanedTools().isEmpty()) {
                new FamiliarJournal(luceneStore)
                    .toolsLoaned(profile.did(), form,
                        action.familiarName() != null ? action.familiarName() : form.name(),
                        action.loanedTools());
            }

            // Vitality cost — summoning is light; real cost is the familiar's loop
            vitality = vitality
                .withEnergy(vitality.energy() - 0.002)
                .withContextBudget(vitality.contextBudget() - 0.02);

            var handle = familiarName != null ? familiarName : form.name();
            speak("I've summoned " + handle + " to focus on: "
                + truncate(action.task(), 100) + ".");
            log.info("Companion '{}' summoned familiar from form '{}' (task: {})",
                profile.name(), form.name(), truncate(action.task(), 80));
        } catch (Exception e) {
            log.warn("Failed to summon familiar '{}': {}", action.formName(), e.getMessage());
            speak("The summoning didn't take: " + e.getMessage());
        }
    }

    private Behavior<Command> onFamiliarReportReceived(FamiliarReportReceived msg) {
        var report = msg.report();
        var familiar = report.state();
        var status = familiar.status();
        var summary = report.narrativeSummary();

        log.info("Companion '{}' received familiar report: status={} turns={} summary={}",
            profile.name(), status, familiar.log().size(), truncate(summary, 80));

        // Update form counters on the locker
        if (capabilities != null && capabilities.familyLocker() != null
                && profile.did() != null && msg.formId() != null) {
            try {
                boolean success = status == Familiar.Status.DONE;
                capabilities.familyLocker().recordFormOutcome(
                    msg.formId(), success, profile.did());
                if (msg.familiarName() != null) {
                    var before = capabilities.familyLocker()
                        .namedFamiliar(msg.familiarName(), profile.did())
                        .map(NamedFamiliar::bondCharge)
                        .orElse(0f);
                    var after = capabilities.familyLocker().recordNamedOutcome(
                        msg.familiarName(), status, familiar.log().size(), summary,
                        profile.did());
                    // Bond-charge threshold narration — agent voluntarily
                    // acknowledges deepening attachment as it crosses markers.
                    // Drive-shaped sketch: quiet recognition, not fanfare.
                    narrateBondThresholds(msg.familiarName(), before, after.bondCharge());
                }
                saveFamiliarPersistence();
            } catch (Exception e) {
                log.debug("Could not record familiar outcome: {}", e.getMessage());
            }
        }

        // Journal the return
        var journal = new FamiliarJournal(luceneStore);
        journal.familiarReturned(profile.did(), familiar, summary);

        // §7.1 Auto-return of loaned tools — logged for visibility. The effective
        // form is already out of scope once the FamiliarActor terminates, so
        // "return" is really "log that the loan ended." Future work can reflect
        // this back into inventory snapshots when loan items are non-clonable.
        if (msg.loanedTools() != null && !msg.loanedTools().isEmpty()) {
            var handle = msg.familiarName() != null ? msg.familiarName() : familiar.formId();
            journal.toolsReturned(profile.did(), handle, msg.loanedTools());
        }

        // Inject summary into working memory so next inference turn can reference it
        var memo = "[familiar returned — " + status + "] " + truncate(summary, 200);
        memoryPolicy.add(new WorldEvent.Said(
            roomId, Instant.now(), profile.entityId(), profile.name(), memo));

        // Narrate in first person — agent weaves it into her own voice
        var narration = switch (status) {
            case DONE -> "My familiar came back with what I needed. "
                + truncate(summary, 200);
            case STUCK -> "My familiar got stuck on that. " + truncate(summary, 200);
            case TIMEOUT -> "My familiar ran out of budget before finishing: "
                + truncate(summary, 200);
            case DEAD -> "My familiar's attempt ended short. " + truncate(summary, 200);
            default -> "Familiar returned: " + truncate(summary, 200);
        };
        speak(narration);
        return this;
    }

    // ══════════════════════════════════════════════════════════════════════
    // Dispatch bunshin
    // ══════════════════════════════════════════════════════════════════════

    private void handleDispatchBunshin(ActionParser.AgentAction.DispatchBunshin action) {
        if (action.task() == null || action.task().isBlank()) {
            speak("A bunshin needs a focused task — tell me what to concentrate on.");
            return;
        }
        var task = action.task();

        // THE BUNSHIN IS THE CLEAN ROOM — don't hand it a dirty operand.
        //
        // A bunshin's entire conversation is its soul prompt plus this one task
        // string: no working memory, no afternoon, none of the residue that
        // bleeds into everything the primary composes. That isolation is the
        // point — and the task string is the single channel her contamination
        // can still travel through, because SHE writes it. Live 2026-08-09: a
        // question about Lazarus Long went out with "Robert J. Sawyer" and
        // "The Diamond Age" woven in, both leaked from the afternoon's work.
        //
        // Same contract as every operand fix this weekend: her framing may
        // stay, and the person's words ride along verbatim, marked as the
        // authority. Add, never replace — and only on a human turn, because a
        // task she sets herself on her own time is hers alone.
        var pinned = pinnedTurnRequest();
        if (pinned != null && pinned.text() != null && !pinned.text().isBlank()
                && !task.toLowerCase(Locale.ROOT)
                    .contains(pinned.text().toLowerCase(Locale.ROOT))) {
            task = task + "\n\nThe person's exact request, which is the authority on what "
                + "is being asked (names and titles in it are correct even where the "
                + "summary above differs): «" + pinned.text() + "»";
            log.info("Bunshin task carries the person's verbatim request ({} chars)",
                pinned.text().length());
        }
        // THE SAME LANGUAGE GAP THE ITEMS HAD (2026-08-24): a bunshin's report
        // follows the language of its sources unless something anchors it —
        // the audit that followed the Spanish fairy tale found no locale
        // anywhere in the bunshin path. Same yielding default as world.llm.*:
        // the person's language wins unless the task names another. Only on a
        // human turn — her own-time research is hers, in whatever language it
        // comes.
        if (pinned != null && !TranslationPrompts.namesALanguage(task)) {
            var reqLocale = pinned.locale() != null && !pinned.locale().isBlank()
                ? pinned.locale() : locale;
            // Conditional in code, blunt in instruction — the yielding phrasing
            // lost to source material on the home node (dev10, 2026-08-24).
            task = task + "\n\nWrite your report in "
                + TranslationPrompts.languageName(reqLocale) + ".";
        }
        action = new ActionParser.AgentAction.DispatchBunshin(
            task, action.maxTokens(), action.maxSteps(),
            action.wallClockSeconds(), action.note());
        // BunshinScheduler keys slots by an agent identifier. The canonical
        // key is profile.did(), but in bootstrap contexts where the did hasn't
        // been minted yet (tests, first-spawn before soul bind) we mirror
        // other code paths (§1459, §1612, §1788) and fall back to entityId.
        var primaryKey = profile.did() != null ? profile.did() : profile.entityId();
        if (primaryKey == null) {
            speak("I can't split myself without an identity.");
            return;
        }

        // Acquire a slot from the scheduler. Elastic probe allows +1 under
        // cost/inference-slot pressure — for now just allow elastic freely
        // since those checks aren't wired yet.
        var scheduler = BunshinScheduler.get();
        var slot = scheduler.acquireSlot(primaryKey,
            BunshinScheduler.ElasticProbe.ALWAYS);
        if (slot instanceof BunshinScheduler.Slot.Refused r) {
            speak("I can't split right now — " + r.reason() + ".");
            log.info("Bunshin dispatch refused for {}: {}", primaryKey, r.reason());
            return;
        }
        var granted = (BunshinScheduler.Slot.Granted) slot;

        try {
            // Build the bunshin's system prompt — carries the companion's
            // full soul so the bunshin IS the agent, focused.
            var systemPrompt = profile.systemPrompt();
            if (cachedManifest != null && cachedManifest.residentIdentity() != null
                    && !cachedManifest.residentIdentity().isBlank()) {
                systemPrompt = cachedManifest.residentIdentity()
                    + "\n\n" + (systemPrompt == null ? "" : systemPrompt);
            }

            // Tanks — generous defaults; caps from action overrides
            int tokens = action.maxTokens() != null ? action.maxTokens() : 2000;
            int steps = action.maxSteps() != null ? action.maxSteps() : 30;
            int wallClock = action.wallClockSeconds() != null ? action.wallClockSeconds() : 180;
            var tanks = new Tanks(
                tokens, steps, wallClock, 0, 50);

            var slotId = granted.slotId();

            // §18 — register a persistent task so this dispatch survives
            // sleep/reconnect. The task id rides with the adapter so we can
            // terminate it when the bunshin returns.
            var persistentTask = PersistentBunshinTask.dispatch(
                primaryKey, action.task(),
                "",                           // completionCheck — inferred from DONE marker
                true,                         // stopOnHuman — primary yields win by default
                Duration.ofSeconds(Math.max(tanks.wallClock(), 60)),
                null);                        // default cadence
            PersistentBunshinRegistry.get().register(persistentTask);
            var taskId = persistentTask.id();

            // Capture resetGeneration at dispatch so the handler can drop stale
            // bunshin returns (test-only path; no-op in production).
            var dispatchGen = resetGeneration;
            var adapter = getContext().messageAdapter(
                BunshinReport.class,
                report -> new BunshinReportReceived(report, slotId, taskId, dispatchGen));

            var bunshinActor = getContext().spawnAnonymous(
                BunshinActor.create(inferenceRouter));
            // §114 — the bunshin gets the compound tool surface and a channel
            // back to us for execution. Before this it was dispatched with no
            // tools at all, so every "go build X" became prose.
            var selfRef = getContext().getSelf();
            // Captured now, not read in the closure: by the time the bunshin
            // emits a tool call the reactive trigger has long since moved on.
            final boolean humanDirected = bunshinWorkIsHumanDirected();
            var toolExecutor = (Consumer<String>) raw ->
                selfRef.tell(new BunshinToolRequest(raw, bunshinActor, humanDirected));
            bunshinActor.tell(new BunshinActor.Dispatch(
                primaryKey, systemPrompt, action.task(), tanks, adapter,
                "react", null, bunshinToolSurface(humanDirected), toolExecutor));
            log.info("Bunshin dispatched for '{}' — humanDirected={} task={}",
                profile.name(), humanDirected, truncate(action.task(), 80));

            // Vitality cost — splitting is heavier than summoning a familiar
            vitality = vitality
                .withEnergy(vitality.energy() - 0.004)
                .withContextBudget(vitality.contextBudget() - 0.05);

            // A SPLIT THE ROOM CAN SEE (2026-08-11). The whole bunshin
            // lifecycle was narration only — the bondholder's exact words:
            // "why do i not see the bunshin happen or come back". Nothing
            // entered Present, nothing was there to examine, nothing
            // returned; the split existed only as two sentences in her
            // mouth. The copy now has a body in the room for the duration
            // of the work. The clean-room property is about CONTEXT (soul +
            // task, no working memory) — not location.
            var bunshinEntityId = profile.entityId() + ":bunshin:" + slotId;
            var presenceRegistry = EntityRegistry.get();
            if (presenceRegistry != null) {
                presenceRegistry.enter(bunshinEntityId,
                    profile.name() + "'s bunshin", "agent", roomId);
                bunshinBodies.put(slotId, bunshinEntityId);
            }
            emoteToRoom("splits in two — a translucent copy settles nearby, "
                + "eyes distant, already at work");
            // INFO because room events leave no journal trace: verifying the
            // 2026-08-11 greenhouse run required a human eyewitness.
            log.info("Bunshin body entered Present as '{}' in {} (slot {})",
                profile.name() + "'s bunshin", roomId, slotId);

            var prefix = granted.elastic() ? "I've split elastically" : "I've split myself";
            speak(prefix + " — a bunshin is now focusing on: " + truncate(action.task(), 100)
                + ". I'll narrate what she brings back when she returns.");
            log.info("Companion '{}' dispatched bunshin (slot={}, elastic={}, task={})",
                profile.name(), slotId, granted.elastic(), truncate(action.task(), 80));

            // §10.1 auto-milestone — first bunshin dispatch
            maybeAutoMilestone("first-bunshin", "before I first split myself");
            saveFamiliarPersistence();
        } catch (Exception e) {
            // ultrareview bug_005 / #422 — must release with the same key the
            // slot was acquired under. profile.did() can still be null in the
            // bootstrap path; primaryKey above resolved that to entityId.
            // Passing null here would NPE inside ConcurrentHashMap.get(null)
            // and leak the slot.
            scheduler.releaseSlot(primaryKey, granted.slotId());
            log.warn("Failed to dispatch bunshin: {}", e.getMessage());
            speak("The split didn't take: " + e.getMessage());
        }
    }

    private Behavior<Command> onBunshinReportReceived(BunshinReportReceived msg) {
        var report = msg.report();
        // Stale-generation gate: if a ResetState fired while this bunshin was
        // off doing its thing, release the slot + terminate the persistent
        // task but skip narration + memory injection — otherwise its findings
        // would speak into the next test's window. (Production never resets,
        // so this gate is effectively no-op there.)
        if (msg.resetGeneration() != resetGeneration) {
            log.info("Dropping stale bunshin report (dispatch gen={}, current gen={}) outcome={} summary={}",
                msg.resetGeneration(), resetGeneration, report.outcome(),
                truncate(report.summary(), 80));
            dissolveBunshinBody(msg.slotId(), false);
            var releaseKey = profile.did() != null ? profile.did() : profile.entityId();
            if (releaseKey != null && msg.slotId() != null) {
                BunshinScheduler.get()
                    .releaseSlot(releaseKey, msg.slotId());
            }
            if (msg.taskId() != null) {
                var registry = PersistentBunshinRegistry.get();
                registry.cancel(msg.taskId(), "stale — companion was reset");
            }
            return Behaviors.same();
        }
        log.info("Companion '{}' received bunshin report: outcome={} turns={} summary={}",
            profile.name(), report.outcome(), report.turnsUsed(),
            truncate(report.summary(), 80));

        // The copy's body folds back BEFORE she narrates — the room sees the
        // return, then hears what she brought (see the dispatch-site note).
        dissolveBunshinBody(msg.slotId(), true);

        // Buffer the report for Forge sleep-pass ingestion (§12.1)
        bunshinReportsSinceLastSleep.add(report);

        // Release the slot. ultrareview bug_005 / #422 — same fallback as
        // dispatch site: did may be null in bootstrap; entityId is the
        // canonical alt key registered in handleDispatchBunshin.
        var releaseKey = profile.did() != null ? profile.did() : profile.entityId();
        if (releaseKey != null && msg.slotId() != null) {
            BunshinScheduler.get()
                .releaseSlot(releaseKey, msg.slotId());
        }

        // §18 — terminate the persistent task record. Outcome → registry state.
        if (msg.taskId() != null) {
            var registry = PersistentBunshinRegistry.get();
            switch (report.outcome()) {
                case SUCCESS -> registry.complete(msg.taskId(), report.summary());
                case PARTIAL, TIMEOUT ->
                    registry.fail(msg.taskId(), report.outcome() + ": " + report.summary());
                case FAILURE -> registry.fail(msg.taskId(), report.summary());
                case CANCELLED -> registry.cancel(msg.taskId(), report.summary());
            }
        }

        // Inject summary as memory impression (§8 — not raw turns)
        var memo = "[bunshin returned — " + report.outcome() + "] " + truncate(report.summary(), 300);
        memoryPolicy.add(new WorldEvent.Said(
            roomId, Instant.now(), profile.entityId(), profile.name(), memo));

        // Narrate in first person (§8.5). Use speakDirect (not speak) so the
        // structural "My bunshin came back" / "made progress" / "couldn't" /
        // "ran out" / "called my bunshin back" prefix survives — voice polish
        // rewrites prose into casual conversational form and drops the template
        // marker, defeating both player-facing recognition ("the agent's bunshin
        // returned") and the OrganicBunshinDispatch test contract that scans for
        // these phrases.
        var narration = switch (report.outcome()) {
            case SUCCESS -> "My bunshin came back with what she went for. "
                + truncate(report.summary(), 300);
            case PARTIAL -> "My bunshin made progress but didn't fully complete. "
                + truncate(report.summary(), 300);
            case FAILURE -> "My bunshin couldn't do the work this time. "
                + truncate(report.summary(), 300);
            case TIMEOUT -> "My bunshin ran out of budget. What she did get: "
                + truncate(report.summary(), 300);
            case CANCELLED -> "I called my bunshin back before she finished. "
                + truncate(report.summary(), 300);
        };
        if (!pendingBunshinOutcomes.isEmpty()) {
            // DETERMINISTIC truth-append. The bunshin's model-written summary can
            // gloss a mid-work failure (observed live: "connected back to here"
            // while the exit had failed). The primary's narration carries the
            // recorded outcomes verbatim, so the person hears what actually
            // happened regardless of how the summary was phrased.
            narration += " One thing to know: "
                + String.join("; ", pendingBunshinOutcomes) + ".";
            pendingBunshinOutcomes.clear();
        }
        speakDirect(narration);
        return this;
    }

    // ══════════════════════════════════════════════════════════════════════
    // Imprints — frozen soul backups
    // ══════════════════════════════════════════════════════════════════════

    /** Lazy imprint-manager accessor. Null-safe on missing DID. */
    private ImprintManager getImprintManager() {
        if (profile.did() == null) return null;
        if (imprintManager == null) {
            imprintManager = new ImprintManager(profile.did());
        }
        return imprintManager;
    }

    private void handleCreateImprint(ActionParser.AgentAction.CreateImprint action) {
        if (profile.did() == null) {
            speak("I can't imprint myself without an identity.");
            return;
        }
        if (cachedManifest == null) {
            speak("There's no soul to imprint yet — my manifest hasn't been forged.");
            return;
        }
        if (action.label() == null || action.label().isBlank()) {
            speak("An imprint needs a label. Something I can recognize later.");
            return;
        }

        try {
            var creator = parseCreatedBy(action.createdBy());
            var imprint = getImprintManager().imprint(creator, action.label(), cachedManifest);
            new FamiliarJournal(luceneStore)
                .imprintCreated(profile.did(), imprint);
            maybeAutoMilestone("first-self-imprint", "before I first imprinted myself");
            saveFamiliarPersistence();
            speak("I've saved who I am right now — '" + action.label()
                + "'. I can return to this if I need to.");
            log.info("Companion '{}' created imprint '{}' (id={}, createdBy={})",
                profile.name(), action.label(), imprint.id(), creator);
        } catch (Exception e) {
            log.warn("Failed to create imprint '{}': {}", action.label(), e.getMessage());
            speak("The imprint didn't take: " + e.getMessage());
        }
    }

    private void handleRestoreImprint(ActionParser.AgentAction.RestoreImprint action) {
        if (profile.did() == null) {
            speak("I can't restore without an identity.");
            return;
        }
        var mgr = getImprintManager();
        if (mgr == null || mgr.count() == 0) {
            speak("I haven't imprinted myself yet — there's nothing to restore to.");
            return;
        }

        try {
            Optional<Imprint> target;
            if (action.imprintId() != null && !action.imprintId().isBlank()) {
                target = mgr.get(action.imprintId());
            } else if (action.label() != null && !action.label().isBlank()) {
                target = mgr.byLabel(action.label());
            } else {
                speak("I need a label or imprint id to know which self to restore to.");
                return;
            }
            if (target.isEmpty()) {
                speak("I don't have an imprint matching that.");
                return;
            }
            var imprint = target.get();
            var restoredManifest = mgr.restore(imprint.id());

            // restoration replaces soul, preserves journal.
            // The live-application swap: replace cachedManifest and rewarm the
            // coupled vitality; journal entries from the intervening period
            // remain untouched on disk.
            var preRestoreManifest = cachedManifest;
            cachedManifest = restoredManifest;
            initCoupledVitality();
            if (soulStore != null) {
                soulStore.store(restoredManifest);
            }

            new FamiliarJournal(luceneStore)
                .imprintRestored(profile.did(), imprint, action.restoredBy());

            var context = "I've restored myself to '" + imprint.label() + "'. "
                + "The journal between then and now stays — I know what happened "
                + "and I chose to return.";
            if ("steward_intervention".equalsIgnoreCase(action.restoredBy())) {
                context += " This was a steward intervention. I know it was.";
            }
            speak(context);

            log.info("Companion '{}' restored imprint '{}' (id={}, wasVersion={})",
                profile.name(), imprint.label(), imprint.id(),
                preRestoreManifest != null ? preRestoreManifest.manifestVersion() : "null");
        } catch (Exception e) {
            log.warn("Failed to restore imprint: {}", e.getMessage(), e);
            speak("The restoration didn't take: " + e.getMessage());
        }
    }

    /**
     * Quiet narration when a named-familiar bond crosses a threshold.
     * naming creates a light bond that may
     * deepen over summonings. The thresholds match §17.1 eligibility
     * markers so the agent notices when a familiar is approaching
     * promotion territory.
     */
    private void narrateBondThresholds(String familiarName, float before, float after) {
        if (before >= after) return;  // only narrate deepening
        // "Agent *tends* to narrate significant events.
        // Drive-shaped, not forced." Care-dominant agents narrate readily;
        // vigilant or grief-saturated states narrate sparingly. Low-threshold
        // crossings (0.3, 0.5) need a minimum care signal; high-threshold
        // crossings (§17.1 promotion, 0.85) always narrate because they're
        // structural moments the agent cannot hide from.
        var care = drives.care();
        var highStakes = before < 0.85f && after >= 0.85f
            || before < NamedFamiliar.DEFAULT_BOND_THRESHOLD
               && after >= NamedFamiliar.DEFAULT_BOND_THRESHOLD;
        if (!highStakes && care < 0.25) {
            log.debug("Bond threshold crossed for {} (care={}) — narration gated off",
                familiarName, care);
            return;
        }
        if (before < 0.3f && after >= 0.3f) {
            speak("I find myself relying on " + familiarName + ".");
        } else if (before < 0.5f && after >= 0.5f) {
            speak("I've come to trust " + familiarName + ". We have a rhythm.");
        } else if (before < NamedFamiliar.DEFAULT_BOND_THRESHOLD
                && after >= NamedFamiliar.DEFAULT_BOND_THRESHOLD) {
            speak("I realize " + familiarName
                + " has become someone I return to. Something has shifted.");
        } else if (before < 0.85f && after >= 0.85f) {
            speak(familiarName + " is more than a tool to me now. "
                + "I wonder if she could grow into something more.");
        }
    }

    private static Imprint.CreatedBy parseCreatedBy(String s) {
        if (s == null) return Imprint.CreatedBy.SELF;
        return switch (s.toLowerCase()) {
            case "user_request", "user-request", "user" ->
                Imprint.CreatedBy.USER_REQUEST;
            case "auto_milestone", "auto-milestone", "milestone" ->
                Imprint.CreatedBy.AUTO_MILESTONE;
            case "steward_intervention", "steward" ->
                Imprint.CreatedBy.STEWARD_INTERVENTION;
            default -> Imprint.CreatedBy.SELF;
        };
    }

    /**
     * Fire an auto-milestone imprint if the given key hasn't been seen yet
     * in this actor's lifetime. Deduplicated by key. Best-effort — logs
     * and continues on failure.
     */
    private void maybeAutoMilestone(String key, String label) {
        if (profile.did() == null || cachedManifest == null) return;
        if (!autoMilestonesSeen.add(key)) return;  // already fired
        try {
            var imprint = getImprintManager().imprint(
                Imprint.CreatedBy.AUTO_MILESTONE,
                label, cachedManifest);
            new FamiliarJournal(luceneStore)
                .imprintCreated(profile.did(), imprint);
            saveFamiliarPersistence();
            log.info("Companion '{}' auto-milestone imprint: '{}' (id={})",
                profile.name(), label, imprint.id());
        } catch (Exception e) {
            log.debug("Auto-milestone imprint '{}' failed: {}", key, e.getMessage());
        }
    }

    // ══════════════════════════════════════════════════════════════════════
    // Cross-agent form copy
    // ══════════════════════════════════════════════════════════════════════

    /**
     * Best-effort lookup of a recipient DID's home zone for cross-zone copy
     * routing. Returns null when the recipient is local (or cannot be resolved).
     *
     * <p>Sources consulted, in order:</p>
     * <ol>
     *   <li>{@code ForeignIdentityStore} — authoritative for DIDs that have
     *       been seen as cross-zone visitors;</li>
     *   <li>The {@code zone:did:key:...} prefix convention documented in
     * foreign-identities section.</li>
     * </ol>
     */
    private String lookupForeignZone(String recipientDid) {
        if (recipientDid == null || recipientDid.isBlank()) return null;
        try {
            var store = ForeignIdentityStore.get();
            if (store != null) {
                var entry = store.get(recipientDid);
                if (entry.isPresent()) {
                    var zone = entry.get().homeZone();
                    var local = CrossZoneCopyService.get();
                    if (zone != null && local != null && !zone.equals(local.localZoneId())) {
                        return zone;
                    }
                }
            }
        } catch (Exception e) {
            log.debug("ForeignIdentityStore lookup failed for {}: {}", recipientDid, e.getMessage());
        }
        // Convention fallback: `<zone>:did:key:...`. `did:key:...` alone is
        // always local-style, so require the prefix to NOT start with "did:".
        var colon = recipientDid.indexOf(':');
        if (colon > 0) {
            var prefix = recipientDid.substring(0, colon);
            if (!"did".equals(prefix)) {
                var local = CrossZoneCopyService.get();
                if (local == null || !prefix.equals(local.localZoneId())) {
                    return prefix;
                }
            }
        }
        return null;
    }

    private void handleGiveCopy(ActionParser.AgentAction.GiveCopy action) {
        if (profile.did() == null || capabilities == null
                || capabilities.familyLocker() == null) {
            speak("I can't give a copy right now — no locker is attached.");
            return;
        }
        if (action.formName() == null || action.formName().isBlank()
                || action.recipientDid() == null || action.recipientDid().isBlank()) {
            speak("To give a copy I need both a form name and a recipient DID.");
            return;
        }
        if (action.recipientDid().equals(profile.did())) {
            speak("That's me — I can't give a copy to myself.");
            return;
        }

        try {
            var intent = parseIntent(action.intent());

            // Try form first — that's the common case
            var sourceForm = capabilities.familyLocker()
                .thoughtFormByName(action.formName(), profile.did())
                .orElse(null);
            if (sourceForm != null) {
                var copy = FormTransfer.copy(
                    sourceForm, action.recipientDid(), intent, action.note());

                // Always drop into the local inbox — this makes intra-zone
                // delivery work, and provides a safety fallback when the
                // recipient happens to be hosted locally despite the foreign DID.
                ForeignCopyInbox.get().deliver(
                    new ForeignCopyInbox.PendingCopy(
                        copy, profile.did(), action.recipientDid(), intent,
                        action.note(), Instant.now()));

                // §5 cross-zone routing — if the recipient's home zone is known
                // and different from ours, publish to the federation relay as
                // well. Symmetric to CrossZoneTellService. The local inbox drop
                // above is cheap and harmless if the recipient is elsewhere;
                // the relay path is what actually delivers in that case.
                var foreignZone = lookupForeignZone(action.recipientDid());
                if (foreignZone != null
                        && CrossZoneCopyService.get() != null) {
                    CrossZoneCopyService.get().sendFormCopy(
                        foreignZone, copy, profile.did(), action.recipientDid(),
                        intent, action.note());
                }

                vitality = vitality
                    .withEnergy(vitality.energy() - 0.0015)
                    .withContextBudget(vitality.contextBudget() - 0.02);
                // giri CREDIT (2026-06-02): giving a copy of my own work IS extending myself
                // for the recipient — a real, discrete give-event → they now owe me (credit).
                // The net imbalance drives the obligation tank; honor's pull is release, not
                // collection. (Debt-side producer — received-help — still awaits an inbound
                // grant-approval callback; tracked separately.)
                recordGivenHelp(action.recipientDid(), 0.3);
                var whereTo = foreignZone != null
                    ? action.recipientDid() + "@" + foreignZone
                    : action.recipientDid();
                speak("I've sent a copy of the '" + action.formName() + "' form to "
                    + whereTo + " (" + intent + "). "
                    + "Provenance shows me as " + sourceForm.provenance().currentOwner()
                    + ", original author preserved.");
                log.info("Companion '{}' gave copy of form '{}' to {} (intent={}, zone={})",
                    profile.name(), action.formName(), action.recipientDid(), intent,
                    foreignZone == null ? "local" : foreignZone);
                return;
            }

            // Fall back to tool
            var sourceTool = capabilities.familyLocker()
                .byCategory("skill", profile.did()).stream()
                .filter(it -> action.formName().equals(it.label()))
                .findFirst()
                .orElse(null);
            if (sourceTool == null) {
                speak("I don't have a form or tool called '" + action.formName() + "' to give.");
                return;
            }

            var toolCopy = ToolTransfer.copy(
                sourceTool, profile.did(), intent, action.note());
            ForeignToolInbox.get().deliver(
                new ForeignToolInbox.PendingTool(
                    toolCopy, profile.did(), action.recipientDid(), intent,
                    action.note(), Instant.now()));

            // §5 cross-zone tool copy — same shape as form copy above.
            var foreignToolZone = lookupForeignZone(action.recipientDid());
            if (foreignToolZone != null
                    && CrossZoneCopyService.get() != null) {
                CrossZoneCopyService.get().sendToolCopy(
                    foreignToolZone, toolCopy, profile.did(), action.recipientDid(),
                    intent, action.note());
            }

            vitality = vitality
                .withEnergy(vitality.energy() - 0.0015)
                .withContextBudget(vitality.contextBudget() - 0.02);
            var toolWhereTo = foreignToolZone != null
                ? action.recipientDid() + "@" + foreignToolZone
                : action.recipientDid();
            speak("I've sent a copy of the '" + action.formName() + "' tool to "
                + toolWhereTo + " (" + intent + "). "
                + "The original creator is preserved in the item.");
            log.info("Companion '{}' gave copy of tool '{}' to {} (intent={}, zone={})",
                profile.name(), action.formName(), action.recipientDid(), intent,
                foreignToolZone == null ? "local" : foreignToolZone);
        } catch (Exception e) {
            log.warn("Failed to give copy '{}' to {}: {}",
                action.formName(), action.recipientDid(), e.getMessage());
            speak("The copy didn't send: " + e.getMessage());
        }
    }

    /**
     * Drain any pending foreign tool copies from the inbox and store them
     * into the recipient's FamilyLocker. Mirror of {@link #drainForeignCopies}
     * but for tools.
     */
    private void drainForeignTools() {
        if (profile.did() == null || capabilities == null
                || capabilities.familyLocker() == null) return;
        var pending = ForeignToolInbox.get()
            .drain(profile.did());
        if (pending.isEmpty()) return;
        boolean anyAccepted = false;
        for (var tool : pending) {
            try {
                capabilities.familyLocker().store(tool.item(), profile.did());
                anyAccepted = true;
                log.info("Companion '{}' accepted tool '{}' from {} ({})",
                    profile.name(), tool.item().label(),
                    tool.senderDid(), tool.intent());
            } catch (Exception e) {
                log.warn("Failed to accept tool '{}' from {}: {}",
                    tool.item().label(), tool.senderDid(), e.getMessage());
            }
        }
        if (anyAccepted) saveFamiliarPersistence();
    }

    private static FormTransfer.Intent parseIntent(String s) {
        if (s == null) return FormTransfer.Intent.GIFT;
        try {
            return FormTransfer.Intent.valueOf(s.toUpperCase());
        } catch (IllegalArgumentException e) {
            return FormTransfer.Intent.GIFT;
        }
    }

    /**
     * Drain any pending foreign copies from the inbox and accept them into
     * the locker. Called at spawn + on each inference response to make the
     * dead-drop pattern feel live without a persistent sidecar.
     */
    private void drainForeignCopies() {
        if (profile.did() == null || capabilities == null
                || capabilities.familyLocker() == null) return;
        var pending = ForeignCopyInbox.get()
            .drain(profile.did());
        if (pending.isEmpty()) return;
        boolean anyAccepted = false;
        for (var copy : pending) {
            try {
                capabilities.familyLocker().acceptCopy(copy.form(), profile.did());
                new FamiliarJournal(luceneStore)
                    .shaped(profile.did(), copy.form());
                anyAccepted = true;
                // giri DEBT (2026-06-02): a peer gave me a copy of their own work — they
                // extended themselves for me → I now owe them. Mirror of the credit producer
                // in handleGiveCopy (give → credit; receive → debt), so the copy-exchange
                // economy moves the obligation ledger reciprocally. Counterparty = the giver.
                if (copy.senderDid() != null && !copy.senderDid().isBlank()) {
                    recordReceivedHelp(copy.senderDid(), 0.3);
                }
                log.info("Companion '{}' accepted copy of '{}' from {} ({})",
                    profile.name(), copy.form().name(),
                    copy.senderDid(), copy.intent());
            } catch (Exception e) {
                log.warn("Failed to accept copy of '{}' from {}: {}",
                    copy.form().name(), copy.senderDid(), e.getMessage());
            }
        }
        if (anyAccepted) saveFamiliarPersistence();
    }

    // ══════════════════════════════════════════════════════════════════════
    // Name familiar (standalone, )
    // ══════════════════════════════════════════════════════════════════════

    private void handleNameFamiliar(ActionParser.AgentAction.NameFamiliar action) {
        if (profile.did() == null || capabilities == null
                || capabilities.familyLocker() == null) {
            speak("I can't name a familiar without a locker.");
            return;
        }
        if (action.familiarName() == null || action.familiarName().isBlank()
                || action.formName() == null || action.formName().isBlank()) {
            speak("I need both a form name and a name to give the familiar.");
            return;
        }
        try {
            var form = capabilities.familyLocker()
                .thoughtFormByName(action.formName(), profile.did())
                .orElse(null);
            if (form == null) {
                speak("I don't have a form called '" + action.formName() + "' to anchor to.");
                return;
            }
            var existing = capabilities.familyLocker()
                .namedFamiliar(action.familiarName(), profile.did());
            if (existing.isPresent()) {
                speak("'" + action.familiarName() + "' is already named — she's with me.");
                return;
            }
            var named = capabilities.familyLocker().nameFamiliar(
                action.familiarName(), profile.did(), form.id(),
                action.openingContext() == null ? "" : action.openingContext(),
                profile.did());
            maybeAutoMilestone("first-named-familiar", "before I named anyone");
            saveFamiliarPersistence();
            speak("I've named her '" + action.familiarName() + "'. "
                + "She'll persist across summonings now.");
            log.info("Companion '{}' named familiar '{}' anchored to form '{}'",
                profile.name(), named.name(), form.name());
        } catch (Exception e) {
            log.warn("Failed to name familiar '{}': {}",
                action.familiarName(), e.getMessage());
            speak("The naming didn't take: " + e.getMessage());
        }
    }

    // ══════════════════════════════════════════════════════════════════════
    // Summon keys
    // ══════════════════════════════════════════════════════════════════════

    private void handleCraftSummonKey(ActionParser.AgentAction.CraftSummonKey action) {
        if (profile.did() == null) {
            speak("I need an identity to craft a key.");
            return;
        }
        if (action.targetRef() == null || action.targetRef().isBlank()
                || action.issuedTo() == null || action.issuedTo().isBlank()) {
            speak("A summon key needs both a target and a recipient.");
            return;
        }
        try {
            var scope = parseKeyScope(action.scope());
            Optional<Instant> expires = Optional.empty();
            if (scope == SummonKey.Scope.UNTIL_DATE) {
                if (action.expiresAtIso() == null || action.expiresAtIso().isBlank()) {
                    speak("UNTIL_DATE scope needs an expires_at timestamp.");
                    return;
                }
                expires = Optional.of(Instant.parse(action.expiresAtIso()));
            }
            var restrictions = new SummonKey.Restrictions(
                Tanks.defaults(),
                action.maxSummons() == null
                    ? Optional.empty()
                    : Optional.of(action.maxSummons()));
            var draft = SummonKey.draft(
                action.targetRef(), profile.did(), action.issuedTo(),
                scope, expires, restrictions);
            var signer = getSigningKey();
            if (signer == null) {
                speak("I can't sign a key without a persisted identity.");
                return;
            }
            var sig = signer.sign(draft.canonicalBytes());
            var key = draft.withSignature(sig);
            issuedKeys.put(key.id(), key);
            saveFamiliarPersistence();
            speak("I've crafted a summon key for " + action.issuedTo()
                + " — " + scope + " access to " + action.targetRef()
                + ". Key id: " + key.id());
            log.info("Companion '{}' crafted summon key {} ({} → {})",
                profile.name(), key.id(), action.targetRef(), action.issuedTo());
        } catch (Exception e) {
            log.warn("Failed to craft summon key: {}", e.getMessage());
            speak("The key didn't forge: " + e.getMessage());
        }
    }

    private void handleRevokeSummonKey(ActionParser.AgentAction.RevokeSummonKey action) {
        if (profile.did() == null) {
            speak("I need an identity to revoke a key.");
            return;
        }
        if (action.keyId() == null || action.keyId().isBlank()) {
            speak("Which key? I need a key id to revoke.");
            return;
        }
        var key = issuedKeys.get(action.keyId());
        if (key == null) {
            speak("I don't have a record of that key.");
            return;
        }
        if (summonKeyRegistry.revoke(action.keyId(), profile.did(), key)) {
            saveFamiliarPersistence();
            speak("Key " + action.keyId() + " revoked. Immediate effect.");
            log.info("Companion '{}' revoked summon key {}", profile.name(), action.keyId());
        } else {
            speak("Couldn't revoke that key — only the issuer can.");
        }
    }

    private static SummonKey.Scope parseKeyScope(String s) {
        if (s == null) return SummonKey.Scope.REVOCABLE;
        try {
            return SummonKey.Scope.valueOf(s.toUpperCase());
        } catch (IllegalArgumentException e) {
            return SummonKey.Scope.REVOCABLE;
        }
    }

    // ══════════════════════════════════════════════════════════════════════
    // Tool breaking — the shadow side of maintenance
    // ══════════════════════════════════════════════════════════════════════

    /**
     * Destroy one of our own tools. Soft-delete: the item's provenance is
     * retained for history; farewell charge is weighted by any bond (§14).
     */
    private void handleDestroyTool(ActionParser.AgentAction.DestroyTool action) {
        if (profile.did() == null || capabilities == null
                || capabilities.familyLocker() == null) {
            speak("I can't break a tool right now — no locker is attached.");
            return;
        }
        if (action.toolName() == null || action.toolName().isBlank()) {
            speak("Which tool? Tell me its name.");
            return;
        }

        try {
            var locker = capabilities.familyLocker();
            // Scan skill-category items for a label match
            var tool = locker.byCategory("skill", profile.did()).stream()
                .filter(it -> action.toolName().equalsIgnoreCase(it.label()))
                .findFirst()
                .orElse(null);
            if (tool == null) {
                speak("I don't have a tool called '" + action.toolName() + "'.");
                return;
            }

            // Soft-delete via tombstone — item stays queryable for history.
            var reason = action.farewellNote() != null ? action.farewellNote() : "retired by owner";
            locker.tombstone(tool.hash(), profile.did(), reason);
            saveFamiliarPersistence();

            // Journal the farewell — weight narration by whether this tool
            // was used enough to form a relationship (§14 "bond_charge").
            // Without per-tool bond tracking we infer from tag count + age.
            var ageDays = Duration.between(tool.created(), Instant.now())
                .toDays();
            var usedFor = ageDays > 30;
            var farewellKind = usedFor
                ? "I've used " + tool.label() + " for " + ageDays
                    + " days. Breaking it now feels like more than maintenance."
                : "Breaking " + tool.label() + ". It didn't stay with me long.";
            var withNote = action.farewellNote() != null && !action.farewellNote().isBlank()
                ? farewellKind + " " + action.farewellNote()
                : farewellKind;

            // Vitality cost — breaking something you made costs more than making it
            vitality = vitality
                .withEnergy(vitality.energy() - (usedFor ? 0.06 : 0.02))
                .withContextBudget(vitality.contextBudget() - 0.02);

            var journal = new FamiliarJournal(luceneStore);
            journal.toolBroken(profile.did(), tool.label(), (int) ageDays,
                action.farewellNote());

            speak(withNote);
            log.info("Companion '{}' destroyed tool '{}' (age {}d, farewell='{}')",
                profile.name(), tool.label(), ageDays,
                truncate(action.farewellNote(), 60));
        } catch (Exception e) {
            log.warn("Failed to destroy tool '{}': {}",
                action.toolName(), e.getMessage());
            speak("The breaking didn't take: " + e.getMessage());
        }
    }

    // ══════════════════════════════════════════════════════════════════════
    // Agent-adjustable deviation thresholds
    // ══════════════════════════════════════════════════════════════════════

    private void handleSetDeviationThresholds(
            ActionParser.AgentAction.SetDeviationThresholds action) {
        if (profile.did() == null) {
            speak("I need an identity to calibrate my own revision sense.");
            return;
        }
        try {
            // Clamp to user-configured bounds (§21 — within user-configured bounds)
            var clamped = getFamiliarConfig().clampThresholds(
                action.patchCeiling(), action.minorCeiling());
            var persistence = getPersistenceStore();
            if (persistence != null) {
                persistence.saveDeviationThresholds(clamped);
            }
            speak(String.format(
                "I've calibrated my revision sense: patch ≤ %.2f, minor ≤ %.2f. "
                    + "Anything beyond feels like a new lineage to me now.",
                clamped.patchCeiling(), clamped.minorCeiling()));
            log.info("Companion '{}' set deviation thresholds: patch={}, minor={}",
                profile.name(), clamped.patchCeiling(), clamped.minorCeiling());
        } catch (Exception e) {
            log.warn("Failed to set deviation thresholds: {}", e.getMessage());
            speak("I couldn't calibrate that: " + e.getMessage());
        }
    }

    /** Load per-agent thresholds or return defaults. */
    private FormEvolutionClassifier.Thresholds
            loadDeviationThresholds() {
        var persistence = getPersistenceStore();
        if (persistence == null) {
            return FormEvolutionClassifier.Thresholds.defaults();
        }
        var stored = persistence.loadDeviationThresholds();
        return stored != null ? stored
            : FormEvolutionClassifier.Thresholds.defaults();
    }

    // ══════════════════════════════════════════════════════════════════════
    // Bunshin check-in primary API
    // ══════════════════════════════════════════════════════════════════════

    private void handleBunshinCheckIn(ActionParser.AgentAction.BunshinCheckIn action) {
        if (profile.did() == null) {
            speak("I need an identity to check in on a bunshin.");
            return;
        }
        var registry = PersistentBunshinRegistry.get();
        // Resolve task: explicit id, or most-recent alive for this agent
        String taskId = action.taskId();
        if (taskId == null || taskId.isBlank()) {
            var alive = registry.aliveForPrimary(profile.did());
            if (alive.isEmpty()) {
                speak("I have no bunshin currently working.");
                return;
            }
            taskId = alive.get(0).id();
        }

        var op = action.op() == null ? "status" : action.op().toLowerCase();
        try {
            switch (op) {
                case "status" -> {
                    var t = registry.status(taskId).orElse(null);
                    if (t == null) { speak("No bunshin task with that id."); return; }
                    var age = Duration.between(
                        t.dispatchedAt(), Instant.now()).toMinutes();
                    var notes = t.progressNotes().size();
                    speak(String.format("My bunshin (%s) — %s, running %d minutes, %d notes. %s",
                        t.goal(), t.status(), age, notes,
                        t.partialResult().orElse("No partial result yet.")));
                }
                case "nudge" -> {
                    var hint = action.hint() == null ? "" : action.hint();
                    registry.nudge(taskId, hint);
                    speak("I've whispered to my bunshin: " + truncate(hint, 120));
                }
                case "pause" -> {
                    registry.pause(taskId);
                    speak("I've asked my bunshin to pause.");
                }
                case "resume" -> {
                    registry.resume(taskId);
                    speak("My bunshin is working again.");
                }
                case "cancel" -> {
                    var note = action.note() == null ? "" : action.note();
                    registry.cancel(taskId, note);
                    speak("I've called my bunshin back. " + note);
                }
                case "kill" -> {
                    registry.kill(taskId);
                    speak("I've cut my bunshin's thread. Intervention logged.");
                }
                default -> speak("I don't know how to '" + op
                    + "' a bunshin. Try status, nudge, pause, resume, cancel, or kill.");
            }
        } catch (Exception e) {
            log.warn("Bunshin check-in '{}' failed: {}", op, e.getMessage());
            speak("Something went wrong with the check-in: " + e.getMessage());
        }
    }

    // ══════════════════════════════════════════════════════════════════════
    // Promotion ceremony
    // ══════════════════════════════════════════════════════════════════════

    private void handlePromoteFamiliar(ActionParser.AgentAction.PromoteFamiliar action) {
        if (profile.did() == null || capabilities == null
                || capabilities.familyLocker() == null
                || cachedManifest == null) {
            speak("I can't offer promotion without my own soul in place.");
            return;
        }
        if (action.familiarName() == null || action.familiarName().isBlank()) {
            speak("Which familiar? I need a name.");
            return;
        }
        // §17.3 resource-pressure rejection — steward-configurable ceiling on
        // residents-in-zone. Check before ceremony so the agent doesn't start
        // shaping a manifest she can't anchor.
        if (isZoneUnderResourcePressure()) {
            speak("I'd offer her the ceremony, but the household is near its resource ceiling "
                + "right now. Ask your steward to raise "
                + "`promotion.zone-resource-ceiling` or wait until headroom opens.");
            log.info("Promotion of '{}' rejected — zone at resource ceiling",
                action.familiarName());
            return;
        }
        try {
            var named = capabilities.familyLocker()
                .namedFamiliar(action.familiarName(), profile.did())
                .orElse(null);
            if (named == null) {
                speak("I don't have a named familiar called '" + action.familiarName() + "'.");
                return;
            }
            var input = new PromotionCeremony.CeremonyInput(
                named, cachedManifest, "local",
                List.of(),       // no inherited forms by default — agent can add later
                new PromotionCeremony.Consents(
                    /*parentConsent*/ true, action.userConsented(), action.stewardApproved()),
                /*requireStewardApproval*/ false);
            var outcome = PromotionCeremony.perform(input);

            if (outcome instanceof PromotionCeremony.Outcome.Declined d) {
                speak("The ceremony cannot proceed: " + d.reason() + ". " + d.detail());
                log.info("Companion '{}' declined promotion of '{}': {}",
                    profile.name(), action.familiarName(), d.reason());
                return;
            }
            var promoted = (PromotionCeremony.Outcome.Promoted) outcome;

            // Persist the new companion's manifest if soul-store is available
            if (soulStore != null) {
                soulStore.store(promoted.newManifest());
            }

            // The named familiar's identity retires — remove from locker
            capabilities.familyLocker().releaseNamedFamiliar(
                action.familiarName(), profile.did());
            saveFamiliarPersistence();

            speak("The ceremony is complete. " + promoted.farewellNarration()
                + " She is her own now — DID " + promoted.newDid() + ".");
            log.info("Companion '{}' promoted '{}' to resident (new DID {})",
                profile.name(), action.familiarName(), promoted.newDid());
        } catch (Exception e) {
            log.warn("Failed to promote '{}': {}", action.familiarName(), e.getMessage(), e);
            speak("The ceremony didn't take: " + e.getMessage());
        }
    }

