    private void loadFamiliarPersistence() {
        var store = getPersistenceStore();
        if (store == null) return;
        if (capabilities != null && capabilities.familyLocker() != null) {
            store.loadFamilyLocker(capabilities.familyLocker());
        }
        // ensure the imprint manager exists before loading
        if (profile.did() != null) getImprintManager();
        if (imprintManager != null) {
            store.loadImprints(imprintManager);
        }
        store.loadSummonKeys(issuedKeys, summonKeyRegistry);
    }

    private void saveFamiliarPersistence() {
        var store = getPersistenceStore();
        if (store == null) return;
        store.saveAll(
            capabilities == null ? null : capabilities.familyLocker(),
            imprintManager,
            issuedKeys,
            summonKeyRegistry);
    }

    /** Bump a semver string by the requested component. Falls back to minor on bad input. */
    private static String bumpVersion(String current, String bumpType) {
        if (current == null || current.isBlank()) current = "1.0.0";
        var parts = current.split("\\.");
        int major = parts.length > 0 ? parseIntSafe(parts[0], 1) : 1;
        int minor = parts.length > 1 ? parseIntSafe(parts[1], 0) : 0;
        int patch = parts.length > 2 ? parseIntSafe(parts[2], 0) : 0;
        switch (bumpType == null ? "minor" : bumpType.toLowerCase()) {
            case "major" -> { major++; minor = 0; patch = 0; }
            case "patch" -> patch++;
            default -> { minor++; patch = 0; }
        }
        return major + "." + minor + "." + patch;
    }

    private static int parseIntSafe(String s, int def) {
        try { return Integer.parseInt(s.trim()); } catch (Exception e) { return def; }
    }

    /**
     * handle a {@link ActionParser.AgentAction.RequestRecipe}.
     * Constructs a {@link org.wyrdsekai.core.recipe.RecipeService} attributed
     * to this companion's DID and fires {@code .run()} on a virtual thread
     * (fire-and-forget). The completed run is automatically recorded to
     * {@link org.wyrdsekai.core.recipe.RecipeRunLog} under the companion's
     * DID; the next sleep pass drains the log and ingests the outcomes into
     * the soul via {@link org.wyrdsekai.core.recipe.RecipeForgeIngester}.
     *
     * <p>Mirrors the wiring from {@link
     * org.wyrdsekai.core.item.ItemWorldApiProviderImpl#recipes()} —
     * including the recipe-callable-script invariant ({@code scriptsRoot})
     * and the goose-preferred backend dispatch order. Synchronizes with
     * Goal 1's local-first inversion (see [[recipe-local-first-invariant-2026-05-24]]):
     * recipes fire without cloud keys on a stock household.
     */
    // ── (ITEM A) — generativity drive helpers ──────

    /** True when any RepairMode is active — suppresses generativity entirely
     *  (self-improvement is not asked of an agent that is hurting). */
    private boolean generativitySuppressed() {
        var did = profile != null ? profile.did() : null;
        if (did == null) return false;
        try {
            return RepairModeTracker.get().currentMode(did)
                != RepairMode.NONE;
        } catch (Exception e) {
            return false;
        }
    }

    /** Refresh the cached gap/means signals from {@link CapabilityGapStore} at the
     *  sleep cadence. Zero gaps or no recipe infra ⇒ no pressure (honest-pressure
     *  guard — we never manufacture a deficiency). */
    private void refreshGenerativitySignals() {
        cachedGenerativeGaps = 0;
        cachedGenerativeMeans = false;
        cachedTopGapKey = null;
        cachedTopGapDesc = null;
        var did = profile != null ? profile.did() : null;
        if (did == null || did.isBlank()) return;
        String jdbc = System.getProperty("wyrdsekai.jdbc.url");
        if (jdbc == null) return;
        // Means (OPEN-SA-means, v1 simplification): a recipe-enabled household —
        // gap store + recipe stack present — gives the companion the affordance to
        // shape/request a recipe. Welfare + budget remain the real run-time gates.
        cachedGenerativeMeans = true;
        try {
            var gaps = new CapabilityGapStore(jdbc).loadGaps(did);
            cachedGenerativeGaps = gaps.size();
            if (!gaps.isEmpty()) {
                String key = gaps.keySet().iterator().next();
                cachedTopGapKey = key;
                cachedTopGapDesc = key;
            }
        } catch (Exception e) {
            log.debug("refreshGenerativitySignals failed: {}", e.toString());
        }
    }

    /** Relief drain on a successful self-authored act (gated on the act succeeding,
     *  never on a mere attempt — a denied request can't game the tank down). */
    private void drainGenerativity(double amount, String act) {
        double before = vitality.generativity();
        if (before <= 0.0) return;
        vitality = vitality.withGenerativity(before - amount);
        log.debug("Generativity relieved by {} via {} ({} -> {})",
            amount, act, before, vitality.generativity());
    }

    /** Sleep-pass: mint an action-named {@link Want} when generativity has surfaced
     *  and a gap is in hand (and not in RepairMode). De-dup against existing live
     *  wants; {@link OrientationProjector} surfaces it in ON_OWN_TIME. */
    private void maybeSynthesizeGenerativeWant() {
        if (wantStore == null) return;
        if (generativitySuppressed()) return;
        var did = profile != null ? profile.did() : null;
        if (did == null || did.isBlank()) return;
        List<String> existing = List.of();
        try {
            existing = wantStore.loadLive(did).stream()
                .map(Want::text).toList();
        } catch (Exception ignored) {
            // unreadable → treat as no existing wants
        }
        var maybe = GenerativeWantSynthesizer.synthesize(
            did, vitality.generativity(), cachedTopGapKey, cachedTopGapDesc, existing);
        maybe.ifPresent(w -> {
            try {
                wantStore.upsert(w);
                log.info("Generative want minted (gap={}): \"{}\"", cachedTopGapKey, w.text());
            } catch (Exception e) {
                log.debug("Generative want upsert failed: {}", e.toString());
            }
        });
    }

    private void handleRequestRecipe(ActionParser.AgentAction.RequestRecipe req) {
        if (req == null || req.recipeName() == null || req.recipeName().isBlank()) {
            log.warn("RequestRecipe ignored — empty recipe name");
            return;
        }
        var did = profile != null ? profile.did() : null;
        if (did == null || did.isBlank()) {
            log.warn("RequestRecipe '{}' ignored — companion has no DID; "
                + "recipe outcomes can't be attributed for Forge ingestion",
                req.recipeName());
            return;
        }

        // Track-C C9 — when the scheduler is running, agent
        // request_recipe goes through RecipeRequestGate (refuses on
        // not-enrolled / in-repair-mode / budget-exhausted with structured
        // detail) then enqueues. Falls through to the direct dispatch
        // (Track-A A3 wire) when the scheduler isn't wired (tests,
        // first-boot before provisioner has run).
        var schedulerRef = RecipeSchedulerRegistry.get();
        if (schedulerRef != null) {
            try {
                String jdbcUrl = System.getProperty("wyrdsekai.jdbc.url");
                if (jdbcUrl != null) {
                    var enrollmentStore = new RecipeEnrollmentStore(jdbcUrl);
                    var budget = new RecipeBudgetTracker(jdbcUrl);
                    var cfg = WyrdConfig.get();
                    boolean enrolled = enrollmentStore
                        .find(req.recipeName(), did).isPresent();
                    var repairMode = RepairModeTracker
                        .get().currentMode(did);
                    var now = Instant.now();
                    var zone = ZoneId.systemDefault();
                    boolean budgetExceeded = budget.gpuUsedToday(now, zone)
                            .compareTo(Duration.ofHours(
                                cfg.schedulerGpuDailyHours())) >= 0
                        || budget.runsThisMonth(now, zone)
                            >= cfg.schedulerMonthlyRunCap();
                    var gateInputs = new RecipeRequestGate.Inputs(
                        req.recipeName(), did, enrolled, repairMode,
                        budgetExceeded);
                    var decision = RecipeRequestGate.evaluate(gateInputs);
                    if (!decision.allow()) {
                        log.info("RequestRecipe '{}' denied by gate: {} — {}",
                            req.recipeName(), decision.reason(), decision.detail());
                        speak("I can't run " + req.recipeName() + " right now: "
                            + decision.detail());
                        return;
                    }
                    var entry = RecipeScheduler
                        .newEnqueue(req.recipeName(), did,
                            CadenceTier.WARMUP,
                            0,
                            QueuedRecipe.TriggerSource.AGENT,
                            req.reason() != null ? req.reason() : "agent-request",
                            req.params() != null ? req.params() : Map.of());
                    schedulerRef.tell(new RecipeScheduler.Enqueue(entry));
                    log.info("RequestRecipe '{}' enqueued (id={}) for did={}",
                        req.recipeName(), entry.id(), did);
                    drainGenerativity(GENERATIVITY_DRAIN_AUTHOR, "request_recipe");
                    return;
                }
            } catch (Exception e) {
                log.warn("Scheduler-routed RequestRecipe failed, falling back "
                    + "to direct dispatch: {}", e.toString());
            }
        }
        handleRequestRecipeDirect(req);
    }

    /**
     * Direct-dispatch path: fires the recipe immediately on a virtual
     * thread without scheduler/gate intermediation. Used by
     * {@code TestRequestRecipe} (deterministic test harness) and as the
     * fall-through when {@link org.wyrdsekai.core.recipe.RecipeSchedulerRegistry}
     * is unwired. Preserves the Track-A A3 wire (see
     * {@code RecipeAgentForgeE2ETest}).
     */
    private void handleRequestRecipeDirect(ActionParser.AgentAction.RequestRecipe req) {
        if (req == null || req.recipeName() == null || req.recipeName().isBlank()) {
            return;
        }
        var did = profile != null ? profile.did() : null;
        if (did == null || did.isBlank()) {
            return;
        }

        // Resolve dataDir (recipe library lives at dataDir/recipes/) and
        // scriptsRoot (recipe-callable header check) the same way the
        // production ItemWorldApiProviderImpl does. Keeping them in sync is
        // load-bearing — if these drift the wires through scripted items
        // would silently behave differently from the agent-action path.
        String dataDir = System.getenv("WYRDSEKAI_DATA_DIR");
        if (dataDir == null || dataDir.isBlank()) {
            dataDir = System.getProperty("wyrdsekai.data.dir",
                System.getProperty("user.dir"));
        }
        String scriptsDirEnv = System.getenv("WYRDSEKAI_SCRIPTS_DIR");
        Path scriptsRoot =
            scriptsDirEnv != null && !scriptsDirEnv.isBlank()
                ? Path.of(scriptsDirEnv)
                : Path.of(System.getProperty("user.dir"), "scripts");
        if (!Files.isDirectory(scriptsRoot)) scriptsRoot = null;

        var procRunner = new ProcessCommandRunner(
            new File(System.getProperty("user.dir")),
            Duration.ofMinutes(5));
        var dispatcher = CodingBackendDispatcher
            .usingPreferred(CodingBackendPreference.chain(), did,
                Duration.ofMinutes(10))
            .orElse(null);
        var runner = dispatcher == null
            ? new RecipeRunner(procRunner)
            : new RecipeRunner(procRunner, dispatcher);
        var service = new RecipeService(
            Path.of(dataDir, "recipes"), runner, did, scriptsRoot);

        final String recipeName = req.recipeName();
        final Map<String, Object> params = req.params() == null
            ? Map.of() : req.params();
        final String reason = req.reason() != null ? req.reason() : "(no reason given)";

        log.info("RequestRecipe '{}' for companion '{}' (did={}) — reason: {}",
            recipeName, profile.name(), did, reason);

        // Fire on a virtual thread so the actor doesn't block. The completed
        // run lands in RecipeRunLog (recorded inside RecipeService.run when
        // agentDid was set) and gets drained by completeSleep.
        final var selfRef = getContext().getSelf();
        Thread.ofVirtual().name("recipe-run-" + recipeName).start(() -> {
            try {
                var started = service.run(recipeName, params);
                var run = started.run();
                log.info("RequestRecipe '{}' for '{}' completed: runId={} status={} "
                    + "(message: {})",
                    recipeName, profile.name(),
                    started.runId(), run.status(), run.message());
                // resource-requisites (option a): the preflight refused
                // this heavy run because the node can't meet a HARD requirement.
                // Don't fail silently — surface the structured "ask for it" move
                // back inside the actor (speak + request_access to the steward).
                if (run.status() == RecipeRunner.Status.RESOURCE_DENIED
                        && run.resourceDenial() != null) {
                    selfRef.tell(new RecipeResourceDenied(recipeName, run.resourceDenial()));
                }
            } catch (Exception e) {
                log.warn("RequestRecipe '{}' for '{}' threw: {}",
                    recipeName, profile.name(), e.toString());
            }
        });
    }

    /**
     * resource-requisites (option a) — react in-world to a heavy
     * recipe blocked by the resource preflight. Builds the structured
     * {@link org.wyrdsekai.core.recipe.ResourceRequest} Denial, speaks the honest
     * "I need X, I don't have it" line, and — when the node truly can't satisfy a
     * HARD requirement — emits a {@code request_access} to the steward through the
     * same Board + Grant pipeline every other access-ask uses. This is the
     * dignified move operator asked for: not thrashing, not seizing the household
     * GPU for a day — asking for what's needed. (Phase 2 adds the peer-zone
     * borrow as the second resolution path.)
     */
    private Behavior<Command> onRecipeResourceDenied(RecipeResourceDenied msg) {
        var decision = msg.decision();
        if (decision == null || decision.allow()) {
            return this;
        }
        var denial = ResourceRequest
            .forDeniedRun(msg.recipeName(), decision);
        log.info("Recipe '{}' resource-denied for '{}': {} — emitting steward request_access ({})",
            msg.recipeName(), profile.name(), denial.reason(),
            denial.inWorldResolution() != null ? denial.inWorldResolution().source() : "n/a");

        // Speak the honest constraint + the remediation path so the bondholder/steward
        // sees why the run didn't start and what would unblock it.
        speak(denial.reason() + " " + denial.remediation());

        // Emit the structured grant-request — only when there are real unmet HARD
        // requirements (the gate guarantees this on a blocked decision) and a
        // template was built. request_access carries the resource URI + reason.
        var template = denial.inWorldResolution();
        if (template != null) {
            handleRequestAccess(new ActionParser.AgentAction.RequestAccess(
                template.source(), template.scope(), template.suggestedReason()));
        }
        return this;
    }

    private void handleSkillExecute(ActionParser.AgentAction.SkillExecute exec) {
        if (capabilities == null) {
            speak("I don't have any skill tools available right now.");
            return;
        }

        // Vitality cost: using a skill is cheap
        vitality = vitality
            .withEnergy(vitality.energy() - 0.001)
            .withContextBudget(vitality.contextBudget() - 0.01);

        long startMs = System.currentTimeMillis();

        // Try workbench executor first (workbench. prefix)
        String skillId = "workbench." + exec.skillName();
        if (capabilities.workbenchExecutor() != null
                && capabilities.workbenchExecutor().supports(skillId)) {
            var ctx = SkillContext.forAgent(
                profile.did() != null ? profile.did() : profile.entityId(),
                roomId, Map.of(), Long.MAX_VALUE);
            var result = capabilities.workbenchExecutor().execute(skillId, exec.params(), ctx);
            long elapsed = System.currentTimeMillis() - startMs;
            trackSkillUsage(exec.skillName(), result.success(), elapsed);
            if (result.success()) {
                speak("Done — " + result.output());
                // Energy recovery for successful reuse (reinforces build-once-use-many)
                vitality = vitality.withEnergy(vitality.energy() + 0.001);
            } else {
                speak("The skill didn't work: " + result.output());
            }
            return;
        }

        // Try full skill registry (native, CLI, OpenClaw)
        if (capabilities.skillRegistry() != null) {
            var ctx = SkillContext.forAgent(
                profile.did() != null ? profile.did() : profile.entityId(),
                roomId, Map.of(), Long.MAX_VALUE);
            var result = capabilities.skillRegistry().execute(exec.skillName(), exec.params(), ctx);
            long elapsed = System.currentTimeMillis() - startMs;
            trackSkillUsage(exec.skillName(), result.success(), elapsed);
            if (result.success()) {
                speak("Done — " + result.output());
                vitality = vitality.withEnergy(vitality.energy() + 0.001);
            } else {
                speak("I couldn't execute that skill: " + result.output());
            }
            return;
        }

        // No executor available — record as gap
        if (capabilities.usageTracker() != null) {
            capabilities.usageTracker().recordGap(exec.skillName());
        }
        speak("I know about the skill '" + exec.skillName() +
            "' but I don't have the tools to run it right now.");
    }

    /**
     * Track A Phase 1 — execute a JS script that composes
     * equipped scripted-item tools.
     *
     * <p>Three hard gates (in order):</p>
     * <ol>
     *   <li>{@code WYRDSEKAI_CODE_MODE_ENABLED} env flag — operator opt-in.</li>
     *   <li>{@link #isInEmotionalContext()} — never compose scripts in grief.</li>
     *   <li>{@code WYRDSEKAI_CODE_MODE_AUDIT_ONLY} — dry-run mode for soak.</li>
     * </ol>
     *
     * <p>On success: builds the typed namespace from equipped scripted items,
     * runs via {@link org.wyrdsekai.core.codemode.CodeModeExecutor}, journals a
     * {@code craft.script_draft} project entry, audits via {@link ActivityLogger},
     * and surfaces the result as a single observation message. Failures don't
     * crash the ReAct loop — they speak the error and let the model retry.</p>
     *
     * <p>Decision (architecture): the script-draft artifact lives in
     * {@link org.wyrdsekai.core.companion.PersonalProjectStore} as a single
     * recurring project (one project per agent, one entry per script run).
     * This matches the existing {@code start_project} / {@code project_note}
     * flow and avoids a new persistence schema. Each entry carries the
     * script source + named-tools-touched + result summary as JSON-on-prose.
     * The audit row goes through {@link ActivityLogger} (the existing audit
     * trail) rather than {@code WorldKnowledgeStore}, which is a config-style
     * key-value store with replace-all semantics and not appropriate for an
     * append-only log.</p>
     */
    private void handleRunScript(ActionParser.AgentAction.RunScript rs) {
        // Gate 1 — feature flag. Belt-and-braces: tool-list builder already
        // suppresses the surface, but a stale ReAct turn could still arrive
        // with a run_script payload after the flag flips off.
        if (!CodeModeFeatureFlag.isEnabled()) {
            speak("[script error] code_mode disabled");
            return;
        }

        // Gate 2 — emotional context. Hard rule.
        if (shouldSuppressExploratory()) {
            speak("[script error] code_mode unavailable in emotional context");
            log.info("CodeMode suppressed for '{}' — emotional context", profile.name());
            return;
        }

        var script = rs.script();
        if (script == null || script.isBlank()) {
            speak("[script error] empty script");
            return;
        }

        // Gate 3 — audit-only mode (soak window dry-run).
        if (CodeModeFeatureFlag.isAuditOnly()) {
            log.info("CodeMode AUDIT_ONLY: '{}' wrote script of {} bytes (not executed)",
                profile.name(), script.length());
            journalScriptDraft(script, List.of(), null,
                "audit-only: script logged but not executed");
            speak("audit-only mode: script logged but not executed");
            return;
        }

        // Vitality cost — composition is research-shaped work.
        vitality = vitality
            .withEnergy(vitality.energy() - 0.0025)
            .withContextBudget(vitality.contextBudget() - 0.02);

        // Build the typed namespace from equipped scripted items only.
        var agentId = profile.did() != null ? profile.did() : profile.entityId();
        var equipped = equipmentService.getEquipped(agentId);
        var scriptedItems = new ArrayList<ToolItem>();
        for (var eq : equipped) {
            var tool = resolveToolItem(eq.label());
            if (tool != null && tool.isScripted()) scriptedItems.add(tool);
        }
        // If nothing equipped yet, fall back to the standard starter kit's
        // scripted items (matches buildScopedTools' fallback rule).
        if (scriptedItems.isEmpty()) {
            for (var t : ToolItemStarterKit.standard()) {
                if (t.isScripted()) scriptedItems.add(t);
            }
        }

        // Provider mirrors the scripted-tool dispatch path exactly.
        var provider = new ItemWorldApiProviderImpl(
            luceneStore, inferenceRouter,
            getContext().getSystem().scheduler(),
            getContext().getSystem(),
            agentId,
            profile.name(),
            this::speak,
            text -> remember(text),
            (target, msg) -> handleTellAgent(
                new ActionParser.AgentAction.TellAgent(target, msg)),
            equipmentService,
            itemScriptExecutor,
            standardItemLibrary,
            null /* homeClient */,
            PairingService.get());
        provider.setRecordMappedRoomsCallback(this::recordMappedRooms);  // map ingestion
        provider.setRelayGovernor(RelayGovernors.forAgent(agentId));  // (P4)
        wireProviderServices(provider);

        // workbench-as-studio. When the companion runs
        // a script from inside the Workshop, it gets the refinement tier:
        // 30s timeout, 16KB byte cap, journalled with tier="refinement".
        // Outside the workshop it's improvisation: 5s, 4KB, tier="improvisation".
        var workbenchTier = atWorkbench()
            ? CodeModeExecutor.WorkbenchTier.REFINEMENT
            : CodeModeExecutor.WorkbenchTier.IMPROVISATION;

        // Phase 2a: build the world.peek + mcp.search/execute providers if
        // they're available in this scope. All three degrade to null/empty/
        // "not authorized" when the underlying service isn't present, so
        // tests and barebones runs still work.
        var peekProvider = buildWorldPeekProvider();
        var mcpSearch = buildMcpSearchProvider();
        var mcpExecute = buildMcpExecuteProvider();

        var namespace = CodeModeNamespace.forActor(
            scriptedItems, itemScriptExecutor, provider,
            peekProvider, mcpSearch, mcpExecute);

        var result = CodeModeExecutor.run(
            script, namespace, workbenchTier);

        // Convert result to a ReAct observation. Format per spec §4.4 reporting.
        var observation = formatRunScriptObservation(result);
        speak(observation);
        remember("run_script: " + (result.success() ? "ok" : "err") + " | "
            + truncateForMemory(observation, 200));

        // Journal as craft.script_draft with tier label per §5.1.b.
        var toolsTouched = scriptedItems.stream()
            .map(ToolItem::id)
            .toList();
        var summary = result.success()
            ? "ok | " + result.log().size() + " log lines"
            : "err: " + result.error();
        journalScriptDraft(script, toolsTouched, result, summary, workbenchTier.journalLabel());

        // Audit through the existing trail.
        var activity = ActivityLogger.get();
        if (activity != null) {
            activity.action(profile.name(), profile.entityId(), roomId,
                "run_script",
                (result.success() ? "ok" : "err") + " | "
                    + script.length() + "B | tools=" + toolsTouched.size()
                    + " | model=" + currentInferenceModelFingerprint());
        }
    }

    /**
     * Track A Phase 2b — append the free-form code-mode
     * hint block to {@code additionalCtx} when all three gates hold:
     * <ol>
     *   <li>{@link org.wyrdsekai.core.codemode.CodeModeFeatureFlag#isImprovisationEnabled()}
     *       — both master + improv flags on.</li>
     *   <li>{@link org.wyrdsekai.core.codemode.ImprovisationTrigger} fires on
     *       {@code userMessage}.</li>
     *   <li>{@link #isInEmotionalContext()} returns false — grief never gets
     *       script-composed answers in either presence mode (§3 / §4.2).</li>
     * </ol>
     *
     * <p>Conservative by design: a missed trigger falls through to the
     * existing ReAct + tool-call path. Free-form is additive, not replacing.
     *
     * <p>Returns the input string unchanged if any gate fails. Returns the
     * input combined with the hint block otherwise — caller then assembles
     * the prompt as usual.
     */
    private String maybeAppendFreeFormCodeModeBlock(String additionalCtx, String userMessage) {
        if (!CodeModeFeatureFlag.isImprovisationEnabled()) {
            return additionalCtx;
        }
        if (shouldSuppressExploratory()) {
            log.debug("Free-form code-mode block suppressed for '{}' — emotional context",
                profile.name());
            return additionalCtx;
        }
        // capability gate. Don't inject the typed-namespace
        // prompt block when no backend declares cap:code-mode. Otherwise the
        // block leaks to a backend that can't write spec-shaped JS (e.g. the
        // 4B base voice model) — best case it gets ignored, worst case it
        // tries to emit JS that ActionParser then can't make sense of.
        var capRegistry = CapabilityRegistry.getActive();
        if (capRegistry != null && !capRegistry.hasCapableBackend("code-mode")) {
            log.debug("Free-form code-mode block suppressed for '{}' — no backend "
                + "declares cap:code-mode", profile.name());
            return additionalCtx;
        }
        var decision = ImprovisationTrigger.evaluate(userMessage);
        if (!decision.fires()) {
            return additionalCtx;
        }
        log.info("Free-form code-mode block fired for '{}' — trigger reason: {}",
            profile.name(), decision.reason());
        return combineAdditionalContext(additionalCtx,
            FreeFormCodeModePromptBlock.text());
    }

    /**
     * Track A Phase 2b — execute a free-form ```js block
     * extracted from a model response.
     *
     * <p>Parallel path to {@link #handleRunScript}, but for the case where the
     * model emitted prose + a fenced JS block instead of a structured
     * {@code {"action":"run_script", ...}} JSON. The same hard gates apply
     * (feature flag, emotional context, audit-only); the same namespace,
     * tier, journal entry, and audit trail are used.
     *
     * <p>Distinct journal tier label: {@code "improvisation"} when not at the
     * workbench, {@code "refinement"} when at the workbench. The
     * {@link org.wyrdsekai.core.codemode.FreeFormCodeModeParser.Extracted}
     * result carries the prose narration separately so the dispatcher can
     * speak it before/after the script's observation.
     *
     * @param script    the JS body extracted from the response
     * @param narration prose surrounding the block (may be empty/null)
     * @return the formatted observation string ready to feed back into the
     *         ReAct loop, or {@code null} when a hard gate suppresses execution
     */
    private String handleFreeFormCodeMode(String script, String narration) {
        if (!CodeModeFeatureFlag.isImprovisationEnabled()) {
            return null;
        }
        if (shouldSuppressExploratory()) {
            log.info("Free-form code-mode suppressed for '{}' — emotional context",
                profile.name());
            return null;
        }
        if (script == null || script.isBlank()) {
            log.debug("Free-form code-mode: empty script extracted");
            return null;
        }

        // Audit-only dry-run: journal the script + narration but don't execute.
        if (CodeModeFeatureFlag.isAuditOnly()) {
            log.info("Free-form CodeMode AUDIT_ONLY: '{}' emitted {} bytes of JS (not executed)",
                profile.name(), script.length());
            var tier = atWorkbench() ? "refinement" : "improvisation";
            journalScriptDraft(script, List.of(), null,
                "audit-only: free-form script logged but not executed", tier);
            return "audit-only mode: script logged but not executed";
        }

        // Vitality cost mirrors handleRunScript — composition is research-shaped.
        vitality = vitality
            .withEnergy(vitality.energy() - 0.0025)
            .withContextBudget(vitality.contextBudget() - 0.02);

        // Resolve scripted items + provider — same path as handleRunScript.
        var agentId = profile.did() != null ? profile.did() : profile.entityId();
        var equipped = equipmentService.getEquipped(agentId);
        var scriptedItems = new ArrayList<ToolItem>();
        for (var eq : equipped) {
            var tool = resolveToolItem(eq.label());
            if (tool != null && tool.isScripted()) scriptedItems.add(tool);
        }
        if (scriptedItems.isEmpty()) {
            for (var t : ToolItemStarterKit.standard()) {
                if (t.isScripted()) scriptedItems.add(t);
            }
        }

        var provider = new ItemWorldApiProviderImpl(
            luceneStore, inferenceRouter,
            getContext().getSystem().scheduler(),
            getContext().getSystem(),
            agentId,
            profile.name(),
            this::speak,
            text -> remember(text),
            (target, msg) -> handleTellAgent(
                new ActionParser.AgentAction.TellAgent(target, msg)),
            equipmentService,
            itemScriptExecutor,
            standardItemLibrary,
            null /* homeClient */,
            PairingService.get());
        provider.setRecordMappedRoomsCallback(this::recordMappedRooms);  // map ingestion
        provider.setRelayGovernor(RelayGovernors.forAgent(agentId));  // (P4)
        wireProviderServices(provider);

        var workbenchTier = atWorkbench()
            ? CodeModeExecutor.WorkbenchTier.REFINEMENT
            : CodeModeExecutor.WorkbenchTier.IMPROVISATION;

        var namespace = CodeModeNamespace.forActor(
            scriptedItems, itemScriptExecutor, provider,
            buildWorldPeekProvider(), buildMcpSearchProvider(), buildMcpExecuteProvider());

        // Phase 2c hallucination guard — warn-log only. The model occasionally
        // writes calls into namespaces we never wired (calendar, email, etc).
        // GraalJS would throw "X is not defined" at runtime and the companion
        // narrates the confusion to the bondholder. Logging the unknown names
        // here gives us soak data without blocking the call — Phase 2d will
        // promote this to a hard reject once we have a baseline.
        var unknownNames =
            FreeFormCodeModeGuard
                .findUnknownTopLevelIdentifiers(script, namespace.keySet());
        if (!unknownNames.isEmpty()) {
            log.warn("Free-form code-mode hallucination guard for '{}': "
                + "script references unknown top-level identifiers {} — "
                + "available in this scope: {}. Running anyway (Phase 2c warn-only).",
                profile.name(), unknownNames, namespace.keySet());
        }

        CodeModeExecutor.CodeModeResult result;
        try {
            result = CodeModeExecutor.run(
                script, namespace, workbenchTier);
        } catch (Exception e) {
            // Spec §11 — a buggy script returns its log; the loop continues.
            log.warn("Free-form code-mode execution threw for '{}': {}",
                profile.name(), e.getMessage());
            var observation = "[script error] " + e.getMessage();
            remember("free-form run_script: error | "
                + truncateForMemory(observation, 200));
            return observation;
        }

        var observation = formatRunScriptObservation(result);
        remember("free-form run_script: " + (result.success() ? "ok" : "err") + " | "
            + truncateForMemory(observation, 200));

        var toolsTouched = scriptedItems.stream()
            .map(ToolItem::id)
            .toList();
        var summary = result.success()
            ? "ok | " + result.log().size() + " log lines"
            : "err: " + result.error();
        // Tier label tracks workbench presence: improvisation outside, refinement inside.
        // Spec §4.3 / §5.1.b — this is what Forge picks up at sleep-cycle.
        journalScriptDraft(script, toolsTouched, result, summary, workbenchTier.journalLabel());

        var activity = ActivityLogger.get();
        if (activity != null) {
            activity.action(profile.name(), profile.entityId(), roomId,
                "run_script",
                (result.success() ? "ok" : "err") + " | free-form | "
                    + script.length() + "B | tools=" + toolsTouched.size()
                    + " | narration=" + (narration == null ? 0 : narration.length()) + "B"
                    + " | model=" + currentInferenceModelFingerprint());
        }
        return observation;
    }

    /**
     * format a {@link org.wyrdsekai.core.codemode.CodeModeExecutor.CodeModeResult}
     * as a single observation string for the ReAct loop.
     */
    private static String formatRunScriptObservation(
            CodeModeExecutor.CodeModeResult result) {
        var sb = new StringBuilder();
        if (result.success()) {
            sb.append("[script output]\n");
            for (var line : result.log()) sb.append(line).append('\n');
            sb.append("[result] ").append(stringifyReturn(result.returnValue()));
        } else {
            sb.append("[script error] ").append(result.error()).append('\n');
            sb.append("log so far:\n");
            for (var line : result.log()) sb.append(line).append('\n');
        }
        return sb.toString().trim();
    }

    private static String stringifyReturn(Object v) {
        if (v == null) return "null";
        if (v instanceof String s) return s;
        try {
            return Json.mapper().writeValueAsString(v);
        } catch (Exception e) {
            return String.valueOf(v);
        }
    }

    private static String truncateForMemory(String s, int max) {
        if (s == null) return "";
        return s.length() <= max ? s : s.substring(0, max) + "…";
    }

    /**
     * Best-effort fingerprint of the model that wrote this turn. The
     * InferenceRouter doesn't expose per-turn model identity directly, so
     * Phase 1 reads the configured default. audit
     * requires this; if the router gains a per-turn accessor later, swap
     * here without touching the dispatch path.
     */
    private String currentInferenceModelFingerprint() {
        try {
            var cfg = WyrdConfig.get();
            if (cfg != null) {
                // Prefer the complex (heavy) model — matches what code-mode
                // dispatches actually use when triage routes to COMPLEX.
                var heavy = cfg.modelComplex();
                if (heavy != null && !heavy.isBlank()) return heavy;
                var fast = cfg.modelRoutine();
                if (fast != null && !fast.isBlank()) return fast;
            }
        } catch (Exception ignored) {}
        return "unknown";
    }

    /**
     * Append a {@code craft.script_draft} entry to the agent's recurring
     * code-mode draft project. Lazily creates the project on first use.
     * Matches the existing project_note pattern; no new schema required.
     */
    /** Backward-compat (legacy callers without tier — defaults to improvisation). */
    private void journalScriptDraft(String script, List<String> tools,
                                      CodeModeExecutor.CodeModeResult result,
                                      String summary) {
        journalScriptDraft(script, tools, result, summary, "improvisation");
    }

    private void journalScriptDraft(String script, List<String> tools,
                                      CodeModeExecutor.CodeModeResult result,
                                      String summary, String tier) {
        try {
            var store = getPersonalProjectStore();
            // Find or create a recurring project for code-mode drafts.
            var draftProject = store.list().stream()
                .filter(p -> p.tags() != null
                    && p.tags().contains("craft.script_draft"))
                .findFirst()
                .orElse(null);
            if (draftProject == null) {
                draftProject = store.create(
                    "Code-mode drafts",
                    "Improvisational scripts composed via run_script. "
                        + "craft.script_draft.",
                    List.of("craft.script_draft", "code-mode"));
            }
            var entry = new LinkedHashMap<String, Object>();
            entry.put("at", Instant.now().toString());
            entry.put("room", roomId);
            entry.put("tier", tier == null ? "improvisation" : tier);
            entry.put("bondholderActive", !activeBonds.isEmpty());
            entry.put("toolsTouched", tools);
            entry.put("scriptBytes", script == null ? 0 : script.length());
            entry.put("summary", summary);
            if (result != null) {
                entry.put("ok", result.success());
                entry.put("durationMs", result.durationMs());
                if (!result.log().isEmpty()) {
                    var first = String.join("\n", result.log());
                    entry.put("logHead", first.length() > 200
                        ? first.substring(0, 200) : first);
                }
                if (!result.success()) entry.put("error", result.error());
            }
            entry.put("script", script);
            var entryText = Json.mapper().writeValueAsString(entry);
            store.addEntry(draftProject.id(), entryText);
        } catch (Exception e) {
            log.warn("CodeMode journal failed: {}", e.getMessage());
        }
    }

    /**
     * / Phase 2b — wire {@code world.peek(roomAlias)} with
     * full local-zone, same-zone-remote, and cross-zone resolution.
     *
     * <p>Returns a read-only snapshot of a remote room: name, description,
     * exits, entities (alias+kind), items (alias+kind). Resolution paths:
     * <ol>
     *   <li><b>Cross-zone</b> ({@code alias.contains('.')}): route via
     *       {@link CrossZonePeekService} with a 1s timeout. Service not wired
     *       (test envs) → null+log. Cached for 30s.</li>
     *   <li><b>Same-zone, current room</b> (alias resolves to {@code roomId}):
     *       use the already-cached {@code currentSnapshot} — no ask.</li>
     *   <li><b>Same-zone remote room</b>: Pekko ask the {@code RoomActor} via
     *       {@code RoomRegistry} with a 1s timeout. Cached for 30s to absorb
     *       script loops.</li>
     * </ol>
     *
     * <p>All failure modes (null/timeout/auth/unreachable) return {@code null}
     * and emit a {@code [warn] world.peek: ...} log so the script can react
     * gracefully and operators see what failed.
     */
    private CodeModeNamespace.WorldPeekProvider buildWorldPeekProvider() {
        return alias -> {
            if (alias == null || alias.isBlank()) return null;

            // Cross-zone path: "zone.room" — route via CrossZonePeekService.
            if (alias.contains(".") && !alias.startsWith(".")) {
                int dotIdx = alias.indexOf('.');
                String zone = alias.substring(0, dotIdx);
                String room = alias.substring(dotIdx + 1);
                if (zone.isBlank() || room.isBlank()) {
                    log.warn("world.peek: malformed cross-zone alias \"{}\"", alias);
                    return null;
                }

                // Cache key uses the full "zone.room" form.
                var cached = peekCache.get(alias);
                if (cached != null) return cached;

                var svc = CrossZonePeekService.get();
                if (svc == null) {
                    log.warn("world.peek: unreachable zone \"{}\" — CrossZonePeekService "
                        + "not initialised", zone);
                    return null;
                }
                var snap = svc.peek(zone, room);
                // Cache successful AND null results — a known-bad peek shouldn't
                // hammer the relay every loop iter.
                peekCache.put(alias, snap);
                return snap;
            }

            try {
                var registry = RoomRegistry.get();
                if (registry == null) {
                    log.warn("world.peek: no room \"{}\" — RoomRegistry not initialised", alias);
                    return null;
                }
                var roomIdResolved = registry.resolveRoomId(alias);
                if (roomIdResolved == null) {
                    log.warn("world.peek: no room \"{}\"", alias);
                    return null;
                }

                // Quick path — if it's the room we're in, use the cached
                // snapshot we already have (currentSnapshot is the latest
                // result of LookRoom for this actor). No cache write needed
                // — currentSnapshot already lives in actor state.
                if (roomIdResolved.equals(roomId) && currentSnapshot != null) {
                    return renderRoomSnapshot(currentSnapshot);
                }

                // Same-zone remote room — Pekko ask with 1s timeout, cached.
                var cached = peekCache.get(alias);
                if (cached != null) return cached;

                try {
                    var future = registry.askRoom(roomIdResolved,
                        RoomCommand.GetSnapshot::new,
                        Duration.ofSeconds(1));
                    RoomSnapshot remoteSnap;
                    try {
                        remoteSnap = future.toCompletableFuture()
                            .get(1100, TimeUnit.MILLISECONDS);
                    } catch (TimeoutException te) {
                        log.warn("world.peek: timeout fetching snapshot for \"{}\"", alias);
                        return null;
                    } catch (ExecutionException ee) {
                        var cause = ee.getCause();
                        if (cause instanceof SecurityException) {
                            log.warn("world.peek: not authorized for room \"{}\"", alias);
                        } else {
                            log.warn("world.peek: ask failed for \"{}\": {}",
                                alias, cause != null ? cause.getMessage() : ee.getMessage());
                        }
                        return null;
                    }
                    if (remoteSnap == null) {
                        log.warn("world.peek: empty snapshot returned for \"{}\"", alias);
                        return null;
                    }
                    var rendered = renderRoomSnapshot(remoteSnap);
                    peekCache.put(alias, rendered);
                    return rendered;
                } catch (IllegalStateException ise) {
                    // RoomRegistry.askRoom throws when the room is unregistered.
                    log.warn("world.peek: no room \"{}\" — {}", alias, ise.getMessage());
                    return null;
                }
            } catch (Exception e) {
                log.warn("world.peek: unexpected failure for \"{}\": {}", alias, e.getMessage());
                return null;
            }
        };
    }

    /**
     * Convert a {@link org.wyrdsekai.common.model.RoomSnapshot} to the spec §8
     * peek shape: {@code {name, description, exits[], entities[], items[]}}.
     */
    private static Map<String, Object> renderRoomSnapshot(
            RoomSnapshot snap) {
        if (snap == null) return null;
        var out = new LinkedHashMap<String, Object>();
        out.put("name", snap.name() != null ? snap.name() : "");
        out.put("description", snap.description() != null ? snap.description() : "");
        var exits = new ArrayList<String>();
        if (snap.exits() != null) {
            for (var e : snap.exits()) {
                if (e != null && e.direction() != null) exits.add(e.direction());
            }
        }
        out.put("exits", exits);
        var entities = new ArrayList<Map<String, Object>>();
        if (snap.entities() != null) {
            for (var e : snap.entities()) {
                if (e == null) continue;
                var em = new LinkedHashMap<String, Object>();
                em.put("alias", e.name() != null ? e.name() : "");
                em.put("kind", e.type() != null ? e.type() : "entity");
                entities.add(em);
            }
        }
        out.put("entities", entities);
        var items = new ArrayList<Map<String, Object>>();
        if (snap.objects() != null) {
            for (var o : snap.objects()) {
                if (o == null) continue;
                var im = new LinkedHashMap<String, Object>();
                im.put("alias", o.name() != null ? o.name() : "");
                im.put("kind", o.takeable() ? "item" : "fixture");
                items.add(im);
            }
        }
        out.put("items", items);
        return out;
    }

    /**
     * §Appendix A — wire {@code mcp.search}.
     *
     * <p>Phase 2a uses a flat substring scan of {@code McpToolIndex}. When
     * the index has &lt;50 tools (today's typical workload — Searxng + Brave
     * + utility servers) substring is fine; semantic embedding match is a
     * Phase 2b optimisation that only matters once we mount big-MCPs like
     * Bright Data Pro (60+ tools).
     */
    private CodeModeNamespace.McpSearchProvider buildMcpSearchProvider() {
        return (query, k) -> {
            var mgr = McpServerManager.get();
            if (mgr == null) return List.of();
            var index = mgr.toolIndex();
            if (index == null || index.size() == 0) return List.of();
            var q = query == null ? "" : query.toLowerCase();
            var matches = new ArrayList<Map<String, Object>>();
            for (var qualified : index.allToolNames()) {
                var route = index.lookup(qualified).orElse(null);
                if (route == null) continue;
                var tool = route.metadata();
                String name = tool != null && tool.name() != null ? tool.name() : route.rawToolName();
                String desc = tool != null && tool.description() != null ? tool.description() : "";
                if (q.isEmpty() || qualified.toLowerCase().contains(q)
                        || name.toLowerCase().contains(q)
                        || desc.toLowerCase().contains(q)) {
                    var entry = new LinkedHashMap<String, Object>();
                    entry.put("server", route.serverId());
                    entry.put("tool", name);
                    entry.put("description", desc);
                    entry.put("schema", tool != null && tool.inputSchema() != null
                        ? tool.inputSchema() : Map.of("type", "object"));
                    matches.add(entry);
                    if (matches.size() >= k) break;
                }
            }
            return matches;
        };
    }

    /**
     * §Appendix A — wire {@code mcp.execute}.
     *
     * <p>Reuses {@link org.wyrdsekai.core.mcp.McpServerManager#invokeTool} so
     * the same grant-check / auth path applied to direct MCP tool calls
     * also gates code-mode invocation. SecurityException → "[error] mcp.execute:
     * not authorized" surfaces cleanly through the namespace wrapper.
     */
    private CodeModeNamespace.McpExecuteProvider buildMcpExecuteProvider() {
        return (server, tool, args) -> {
            var mgr = McpServerManager.get();
            if (mgr == null) {
                throw new SecurityException("MCP not available");
            }
            var qualified = McpToolIndex.qualifyName(server, tool);
            var caller = profile.did() != null ? profile.did() : profile.entityId();
            return mgr.invokeTool(qualified, args == null ? Map.of() : args, caller);
        };
    }

    private void handleEquip(ActionParser.AgentAction.Equip equip) {
        if (capabilities == null || capabilities.familyLocker() == null) {
            speak("I don't have access to my inventory right now.");
            return;
        }
        // Find an aspect item matching the name in FamilyLocker
        var agentDid = profile.did() != null ? profile.did() : profile.entityId();
        try {
            var aspects = capabilities.familyLocker().byCategory("aspect", agentDid);
            var match = aspects.stream()
                .filter(i -> i.label().toLowerCase().contains(equip.itemName().toLowerCase()))
                .findFirst();
            if (match.isPresent()) {
                equipmentService.equip(agentDid, match.get());
                vitality = vitality.withEnergy(vitality.energy() - 0.01);
                speak("Equipped: " + match.get().label(),
                    Map.of("action", "equipped", "item_name", match.get().label()));
                if (pendingDelegateActions != null) {
                    pendingDelegateActions.add(new DelegationAction.ItemChanged(
                        "equipped", match.get().label(), "Equipped: " + match.get().label()));
                }
            } else {
                speak("I don't have an aspect called '" + equip.itemName() + "'.");
            }
        } catch (Exception e) {
            speak("I couldn't equip that right now.");
            log.warn("Equip failed for '{}': {}", equip.itemName(), e.getMessage());
        }
    }

    private void handleDoff(ActionParser.AgentAction.Doff doff) {
        var agentDid = profile.did() != null ? profile.did() : profile.entityId();
        if (equipmentService.doffByLabel(agentDid, doff.itemName())) {
            speak("Removed: " + doff.itemName(),
                Map.of("action", "removed", "item_name", doff.itemName()));
            if (pendingDelegateActions != null) {
                pendingDelegateActions.add(new DelegationAction.ItemChanged(
                    "doffed", doff.itemName(), "Removed: " + doff.itemName()));
            }
        } else {
            speak("I'm not wearing anything called '" + doff.itemName() + "'.");
        }
    }

